#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27

// Define I2C address of ADS1115
#define ADS1115_ADDRESS 0x48

// Define ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Define debounce time for flame sensor
#define DEBOUNCE_TIME_MS 50

// Define buzzer activation time
#define BUZZER_TIME_SEC 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int configure_ads1115();
int read_flame_sensor();
int read_temperature_sensor();
void activate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    // Configure ADS1115 for single-ended AIN0, 4.096V range, 128 SPS, single-shot mode
    unsigned char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x40; // Start single conversion
    config[2] = 0x83; // MSB: 11000011 (Single-shot, AIN0, +/-4.096V, 128 SPS)

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115\n");
        return 1;
    }
    return 0;
}

// Function to read flame sensor
int read_flame_sensor() {
    int flame_detected = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(DEBOUNCE_TIME_MS * 1000); // Debounce
    return flame_detected;
}

// Function to read temperature sensor
int read_temperature_sensor() {
    unsigned char data[2];
    int16_t adc_value;

    // Read conversion register
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1; // Indicate error
    }

    // Combine the two bytes to form the 16-bit ADC value
    adc_value = (data[0] << 8) | data[1];

    // Convert ADC value to temperature (assuming 10mV/°C and 4.096V range)
    float voltage = (float)adc_value * 4.096 / 32768.0;
    float temperature = voltage * 100; // °C

    return (int)temperature;
}

// Function to activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(BUZZER_TIME_SEC * 1000000); // Wait for 2 seconds
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Function to log event
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        int temperature_reading = read_temperature_sensor();

        if (flame_detected == 0) {
            log_event("Flame detected!");
        } else if (temperature_reading > 60) {
            log_event("Temperature: " + temperature_reading + " °C");
        }

        if (flame_detected == 0 && temperature_reading > 60) {
            log_event("Fire detected!");
            activate_buzzer();
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

