#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 10000000 // 10 MHz
#define ADC_CHANNEL 0
#define CURRENT_THRESHOLD 1.0 // Amperes
#define FAN_GPIO 18
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL 1 // Seconds

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(int channel, int speed);
int read_adc(int channel);
float adc_to_current(int adc_value);
void control_fan(float current);
void log_data(float current);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(int channel, int speed) {
    int fd = wiringPiSPISetup(channel, speed);
    if (fd == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI data transfer failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Convert ADC value to current (Amperes)
float adc_to_current(int adc_value) {
    // Assuming 0-3.3V range corresponds to 0-10A
    // 10A / 3.3V = 3.03A/ADC unit
    return (float)adc_value * 3.03 / 4095.0; // 4095 is 2^12 - 1
}

// Control the cooling fan
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        digitalWrite(FAN_GPIO, HIGH); // Turn fan ON
    } else {
        digitalWrite(FAN_GPIO, LOW);  // Turn fan OFF
    }
}

// Log data to file
void log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    digitalWrite(FAN_GPIO, LOW); // Ensure fan is OFF
    wiringPiSetupGpio(); // Reset GPIO to default state
    pinMode(FAN_GPIO, INPUT); // Set GPIO pin to input mode
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set FAN_GPIO as output
    pinMode(FAN_GPIO, OUTPUT);
    digitalWrite(FAN_GPIO, LOW); // Initially turn the fan OFF

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            delay(SAMPLE_INTERVAL * 1000); // Wait before retrying
            continue;
        }

        // Check for sensor absent condition
        if (adc_value == 0 || adc_value == 4095) {
            fprintf(stderr, "Sensor absent condition detected.\n");
            log_data(0.0); // Log sensor absent value
            control_fan(0.0); // Ensure fan is OFF
        } else {
            float current = adc_to_current(adc_value);
            log_data(current);
            control_fan(current);
        }

        delay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

