#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x48 // ADS1115 default address
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CO_LOG_FILE "co_log.txt"
#define READ_DELAY_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int address);
int read_adc(int handle, int channel);
float convert_to_ppm(int raw_value);
int log_ppm_value(float ppm_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read ADC value from ADS1115
int read_adc(int handle, int channel) {
    // Configuration register value for single-ended mode, 128 SPS, +/- 4.096V range
    uint16_t config = 0x4003; // Single-ended AIN0, 128 SPS, +/- 4.096V
    uint8_t config_bytes[3];
    config_bytes[0] = (config >> 8) & 0xFF;
    config_bytes[1] = config & 0xFF;
    config_bytes[2] = 0x83; // Start single conversion

    // Write configuration to the device
    if (i2cWriteDevice(handle, (char *)config_bytes, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    uint8_t read_buffer[2];
    if (i2cReadDevice(handle, (char *)read_buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    int16_t raw_value = (read_buffer[0] << 8) | read_buffer[1];
    return raw_value;
}

// Convert raw resistance value to CO concentration in ppm
float convert_to_ppm(int raw_value) {
    // Logarithmic calibration curve parameters (example values)
    float a = 0.01;  // Slope
    float b = 100.0; // Intercept
    float c = 0.5;   // Offset

    // Apply the logarithmic equation
    float ppm = a * (raw_value - c) + b;
    return ppm;
}

// Log CO concentration to file
int log_ppm_value(float ppm_value) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

