// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE0 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0

// Define temperature range
#define MIN_TEMP 20.0
#define MAX_TEMP 40.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
float read_temperature();
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CE0, PI_OUTPUT);
    gpioWrite(MCP3008_CE0, 1); // Deselect MCP3008 initially

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CE0, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CE0, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Read temperature from MCP3008 and convert to Celsius
float read_temperature() {
    int adc_value = read_mcp3008(MCP3008_CHANNEL);
    if (adc_value < 0) {
        return -1.0; // Indicate error
    }

    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value * 3.3 / 1024.0;

    // Convert voltage to temperature (linear approximation)
    float temperature = (voltage - 0.5) * 100.0; // Assuming 0.5V = 20°C, 3.3V = 40°C

    // Clamp temperature to valid range
    if (temperature < MIN_TEMP) {
        temperature = MIN_TEMP;
    } else if (temperature > MAX_TEMP) {
        temperature = MAX_TEMP;
    }

    return temperature;
}

// Log data to CSV file
int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlameDetected,Temperature\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);

        // Read temperature
        float temperature = read_temperature();

        // Log data
        if (temperature >= 0) {
            log_data(flame_detected, temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close log file
    fclose(log_file);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

