#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MICS4514_ADDR 0x73
#define CO_REG 0x01 // Example register address for CO
#define NO2_REG 0x03 // Example register address for NO2
#define CO_SCALE 0.1  // Example scaling factor for CO
#define NO2_SCALE 0.01 // Example scaling factor for NO2
#define ALERT_THRESHOLD 25.0 // ppm
#define LOG_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *co_log_file = NULL;
FILE *alert_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *ox, int *red);
float convert_ox_to_ppm(int ox_value);
void log_co_data(float co_ppm);
void check_alert_threshold(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int *ox, int *red) {
    char buf[4];
    int result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 4);

    if (result != 4) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    *ox = (buf[0] << 8) | buf[1];
    *red = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to convert OX value to CO ppm
float convert_ox_to_ppm(int ox_value) {
    return ox_value * CO_SCALE;
}

// Function to log CO data to a file
void log_co_data(float co_ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(co_log_file, "%s, %.2f ppm\n", timestamp, co_ppm);
    fflush(co_log_file); // Ensure data is written immediately
}

// Function to check alert threshold and log alerts
void check_alert_threshold(float co_ppm) {
    if (co_ppm >= ALERT_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(alert_log_file, "%s, CO ppm exceeded threshold: %.2f ppm\n", timestamp, co_ppm);
        fflush(alert_log_file);
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (co_log_file != NULL) {
        fclose(co_log_file);
    }
    if (alert_log_file != NULL) {
        fclose(alert_log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log files
    co_log_file = fopen("co_log.txt", "a");
    if (co_log_file == NULL) {
        fprintf(stderr, "Failed to open co_log.txt\n");
        cleanup();
        return 1;
    }

    alert_log_file = fopen("alert_log.txt", "a");
    if (alert_log_file == NULL) {
        fprintf(stderr, "Failed to open alert_log.txt\n");
        cleanup();
        return 1;
    }

    int ox, red;
    float co_ppm;

    printf("Starting data logging...\n");

    while (!terminate) {
        if (read_sensor_data(&ox, &red) == 0) {
            co_ppm = convert_ox_to_ppm(ox);
            log_co_data(co_ppm);
            check_alert_threshold(co_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(LOG_INTERVAL * 1000); // Delay for 5 seconds
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

