#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MCP3008_CS1 8
#define MCP3008_CS2 9
#define LED_PIN 27

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define LED on time
#define LED_ON_TIME 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS1, 0); // Select MCP3008 on CE0
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS1, 1); // Deselect MCP3008 on CE0

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(LED_ON_TIME * 1000); // Wait for 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MCP3008_CS1, PI_OUTPUT);
    gpioSetMode(MCP3008_CS2, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int mic1_samples[100];
    int mic2_samples[100];
    int sample_count = 0;
    struct timespec start_time, current_time;
    double mic1_rms, mic2_rms;

    clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (!terminate) {
        // Read samples from microphones
        mic1_samples[sample_count] = read_mcp3008(0);
        mic2_samples[sample_count] = read_mcp3008(1);

        sample_count++;

        // Check for sampling rate violation
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
        if (elapsed_time > 0.1) {
            fprintf(stderr, "Error: Sampling rate exceeded 100ms window. Discarding samples.\n");
            sample_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        // Calculate RMS levels
        if (sample_count >= 100) {
            mic1_rms = calculate_rms(mic1_samples, 100);
            mic2_rms = calculate_rms(mic2_samples, 100);

            // Log data
            log_data(mic1_rms, mic2_rms);

            // Control LED
            control_led(mic1_rms, mic2_rms);

            // Reset sample count and start time
            sample_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        gpioDelay(1); // Sample every 1 ms
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

