// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x40; // Single-ended A0, 4.096V, 128 SPS
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    char read_reg[1];
    read_reg[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, read_reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

// Convert raw ADC value to current
float convert_to_current(int16_t raw_value) {
    float voltage = (float)raw_value * 4.096 / 32768.0; // 4.096V range, 16-bit ADC
    float current = (voltage - ZERO_CURRENT_OFFSET) / SENSITIVITY;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer.buffer[current_buffer.head] = current;
    current_buffer.head = (current_buffer.head + 1) % BUFFER_SIZE;
    if (current_buffer.count < BUFFER_SIZE) {
        current_buffer.count++;
    }
}

// Calculate average of current readings in the buffer
float calculate_average() {
    if (current_buffer.count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < current_buffer.count; i++) {
        sum += current_buffer.buffer[i];
    }
    return sum / current_buffer.count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD_A) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

