    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        if (read_ads1115(&raw_value) == 0) {
            current = convert_to_current(raw_value);
            add_to_buffer(current);
            average_current = calculate_average();
            control_led(average_current);
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 100ms (10Hz sampling)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

