#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x12

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_data(int i2c_handle, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_data(FILE *fp, unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// TCS34725 initialization function
int tcs34725_init(int i2c_handle) {
    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set integration time (ATIME) - 2.4ms * 256
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set gain (AGAIN) - 4x gain
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (sensor_id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// TCS34725 data reading function
int tcs34725_read_data(int i2c_handle, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    int result;

    result = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading clear data\n");
        return -1;
    }
    *clear = (unsigned int)result;

    result = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading red data\n");
        return -1;
    }
    *red = (unsigned int)result;

    result = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading green data\n");
        return -1;
    }
    *green = (unsigned int)result;

    result = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading blue data\n");
        return -1;
    }
    *blue = (unsigned int)result;

    return 0;
}

// Data logging function
int log_data(FILE *fp, unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    unsigned int clear, red, green, blue;
    int consecutive_errors = 0;

    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            // Log data
            if (log_data(log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            consecutive_errors = 0; // Reset error count
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            consecutive_errors++;
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive errors, exiting.\n");
                break;
            }
        }

        // Wait for 1 second using a non-blocking sleep
        struct timespec sleep_time;
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

