#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CE0_GPIO 8

// Define MCP3008 channel assignments
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1

// Global variables for SPI file descriptor and program termination flag
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int log_data(int moisture1, int moisture2);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data (optional, but good practice)
typedef struct {
    int moisture1;
    int moisture2;
} sensor_data_t;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_fd);
        return -1;
    }
    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_fd, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log data to a CSV file
int log_data(int moisture1, int moisture2) {
    FILE *fp = fopen("moisture_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Write data to file
    fprintf(fp, "%s,%d,%d\n", timestamp, moisture1, moisture2);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

