#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0_PIN 8
#define SPI_SCLK_PIN 11
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9
#define MOTOR_DISABLE_PIN 17

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define current threshold
#define CURRENT_THRESHOLD 10.0

// Define MCP3008 channel for MLX91211
#define MLX91211_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_amps(int adc_value);
void log_current(float current);
void motor_shutdown(void);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int count = 0;
    while (count < 3) {
        char tx_buf[3];
        char rx_buf[3];

        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
        tx_buf[2] = 0x00;

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI communication failed (attempt %d). Retrying...\n", count + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            count++;
        }
    }
    fprintf(stderr, "SPI communication failed after 3 attempts. Aborting.\n");
    return -1; // Indicate failure
}

// Function to convert ADC reading to amperes
float adc_to_amps(int adc_value) {
    // Assuming 0V = 0A, 3.3V = 10A (10.0A threshold)
    // 10A / (3.3V - 0V) = 3.0303A/ADC unit
    // 10A = 3.0303 * ADC_Value
    return (float)adc_value * 3.0303;
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to shutdown the motor
void motor_shutdown(void) {
    gpioWrite(MOTOR_DISABLE_PIN, 0); // Set GPIO low to disable motor
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Motor Shutdown due to over-current!\n", timestamp);
    fflush(log_file);
    gpioDelay(1000); // Wait 1 second
    gpioWrite(MOTOR_DISABLE_PIN, 1); // Set GPIO high to re-enable motor
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SPI_CE0_PIN, PI_OUTPUT);
    gpioSetMode(SPI_SCLK_PIN, PI_OUTPUT);
    gpioSetMode(SPI_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(SPI_MISO_PIN, PI_INPUT);
    gpioSetMode(MOTOR_DISABLE_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MLX91211_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to amperes
        float current = adc_to_amps(adc_value);

        // Log current value
        log_current(current);

        // Check for over-current condition
        if (current > CURRENT_THRESHOLD) {
            motor_shutdown();
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

