void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read pressure from the MLX90817 sensor
int read_pressure(int i2c_handle, float *pressure) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert the raw data to pressure in kPa (example conversion)
            int raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure * 0.1; // Example scaling
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries - 1);
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read pressure after multiple retries.\n");
    return -1; // Failure
}

// Function to log pressure data to a CSV file
int log_pressure(FILE *log_file, float pressure) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (fprintf(log_file, "%s,%.2f\n", buf, pressure) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

