// Function to read from ADS1115 ADC
int read_ads1115(int i2c_handle, int channel) {
    char config[3];
    char data[2];
    int retries = 3;
    int result;

    // Configure the ADC for single-ended read
    config[0] = 0x01; // Configuration register address
    config[1] = 0x83; // Single-ended AIN0, 4.096V, 128 SPS, Disable comparator
