#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define GPIO pin for motor shutdown
#define SHUTDOWN_PIN 27

// Define current threshold for shutdown
#define CURRENT_THRESHOLD 10.0 // Amperes

// Define log file name
#define LOG_FILE "current_log.txt"

// Global variables
FILE *log_file = NULL;
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void shutdown_motor();
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI data read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to convert ADC value to current (Amperes)
float adc_to_current(int adc_value) {
    // Assuming 0V = 0A and 3.3V = 10A (1000mA)
    // 1000mA / 3.3V = 303.03 A/V
    // Current = (ADC Value / 1023) * 303.03
    return ((float)adc_value / 1023.0) * 303.03;
}

// Function to log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f A\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to shut down the motor
void shutdown_motor() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s, OVERCURRENT: Shutting down motor!\n", timestamp);
    fprintf(log_file, "%s, OVERCURRENT: Shutting down motor!\n", timestamp);
    fflush(log_file);

    digitalWrite(SHUTDOWN_PIN, HIGH); // Set GPIO HIGH to shut down motor
    program_running = 0; // Stop the program
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin for motor shutdown as output
    pinMode(SHUTDOWN_PIN, OUTPUT);
    digitalWrite(SHUTDOWN_PIN, LOW); // Initially keep motor running

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 100ms.\n");
            delay(100);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            shutdown_motor();
            break; // Exit loop after shutdown
        }

        delay(100); // Sample every 100ms
    }

    // Cleanup
    digitalWrite(SHUTDOWN_PIN, LOW); // Ensure motor is off
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program terminated.\n");
    return 0;
}

