    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to log data to file
void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the alarm based on voltage
void control_alarm(float voltage) {
    if (voltage > ALARM_THRESHOLD) {
        gpioWrite(ALARM_PIN, 1); // Turn alarm on
    } else {
        gpioWrite(ALARM_PIN, 0); // Turn alarm off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("co_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue; // Skip to next iteration
            }
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = convert_to_voltage(adc_value);

        // Log data
        log_data(voltage);

        // Control alarm
        control_alarm(voltage);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(ALARM_PIN, 0); // Turn off alarm
    gpioTerminate();

    return 0;
}

