#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060 // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

#define SENSOR_MIN_VOLTAGE 0.01 // 10mV
#define SENSOR_MAX_VOLTAGE 4.096 // 4.096V
#define SENSOR_MIN_PRESSURE 0.001 // 1 kPa
#define SENSOR_MAX_PRESSURE 100.0 // 100 kPa

#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_pressure(float *pressure);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configures the ADS1115 ADC
int configure_ads1115() {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    int result = i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads the pressure data from the ADS1115
int read_pressure(float *pressure) {
    uint8_t buffer[2];
    int16_t raw_value;
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion data: %d\n", result);
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];

    // Convert raw value to voltage (assuming +/- 4.096V range)
    float voltage = (float)raw_value * 4.096 / 32768.0;

    // Convert voltage to pressure (assuming linear relationship)
    *pressure = (voltage - SENSOR_MIN_VOLTAGE) / (SENSOR_MAX_VOLTAGE - SENSOR_MIN_VOLTAGE) * (SENSOR_MAX_PRESSURE - SENSOR_MIN_PRESSURE) + SENSOR_MIN_PRESSURE;

    return 0;
}

// Validates the pressure reading
int validate_pressure(float pressure) {
    if (pressure < SENSOR_MIN_PRESSURE || pressure > SENSOR_MAX_PRESSURE) {
        fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Logs the pressure reading to a file
int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float pressure;
    int read_result, validation_result, logging_result;

    // Main loop
    while (!terminate) {
        // Read pressure
        read_result = read_pressure(&pressure);
        if (read_result == 0) {
            // Validate pressure
            validation_result = validate_pressure(pressure);
            if (validation_result == 0) {
                // Log pressure
                logging_result = log_pressure(pressure);
                if (logging_result != 0) {
                    fprintf(stderr, "Failed to log pressure\n");
                }
            } else {
                fprintf(stderr, "Pressure validation failed\n");
            }
        } else {
            fprintf(stderr, "Pressure reading failed\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

