#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define GPIO_CE 8
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float adc_to_celsius(int adc_value);
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }
    rewind(log_file);

    // Set GPIO_CE as output
    gpioSetMode(GPIO_CE, PI_OUTPUT);
    gpioWrite(GPIO_CE, 1); // Deactivate chip select initially

    return 0;
}

// Function to read from MCP3208
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(GPIO_CE, 0); // Activate chip select
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(GPIO_CE, 1); // Deactivate chip select

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to log temperature data
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(GPIO_CE, 1); // Deactivate chip select
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < -40.0 || temperature > 125.0) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        } else {
            log_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 1 second (microseconds)
    }

    cleanup();
    printf("Temperature monitoring stopped.\n");

    return 0;
}

