#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define ADC_MAX 1023.0
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi(int spi_channel, int spi_speed);
int read_mcp3008(int spi_handle, int channel);
float adc_to_flow_rate(int adc_value, float vref, float flow_min, float flow_max);
int validate_flow_rate(float flow_rate);
int log_flow_rate(float flow_rate, FILE *log_file);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI device
int open_spi(int spi_channel, int spi_speed) {
    int handle = spiOpen(spi_channel, spi_speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to flow rate
float adc_to_flow_rate(int adc_value, float vref, float flow_min, float flow_max) {
    float flow_rate = flow_min + (float)adc_value / ADC_MAX * (flow_max - flow_min);
    return flow_rate;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
        fprintf(stderr, "Flow rate out of range: %.2f\n", flow_rate);
        return -1;
    }
    return 0;
}

// Log flow rate to file
int log_flow_rate(float flow_rate, FILE *log_file) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
