#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICP_10125_ADDR 0x68
#define MEASURE_CMD 0x06 // High precision measurement command
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

// Calibration data (replace with actual values from your sensor)
// These are example values and will need to be calibrated for your specific sensor.
#define P_TCO_OFFSET 100.0
#define P_TCO_SCALE 0.1
#define T_CO_OFFSET 25.0
#define T_CO_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold raw sensor data
typedef struct {
    int pressure_msb;
    int pressure_lsb;
    int temperature_msb;
    int temperature_lsb;
    int pressure_crc;
    int temperature_crc;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_temperature(int raw_temperature);
float calculate_pressure(int raw_pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP_10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ICP-10125
int read_sensor_data(sensor_data_t *data) {
    char cmd[1] = {MEASURE_CMD};
    char buffer[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion (adjust as needed based on sensor datasheet)
    gpioDelay(100); // 100 ms delay

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Assign data to the struct
    data->pressure_msb = buffer[0];
    data->pressure_lsb = buffer[1];
    data->temperature_msb = buffer[2];
    data->temperature_lsb = buffer[3];
    data->pressure_crc = buffer[4];
    data->temperature_crc = buffer[5];

    return 0;
}

// Calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature) {
    return T_CO_OFFSET + raw_temperature * T_CO_SCALE;
}

// Calculate pressure in Pascals
float calculate_pressure(int raw_pressure) {
    return P_TCO_OFFSET + raw_pressure * P_TCO_SCALE;
}

// Log data to CSV file
int log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Display data on the console
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert raw data to temperature and pressure
            float raw_pressure = (sensor_data.pressure_msb << 8) | sensor_data.pressure_lsb;
            float raw_temperature = (sensor_data.temperature_msb << 8) | sensor_data.temperature_lsb;

            float temperature = calculate_temperature(raw_temperature);
            float pressure = calculate_pressure(raw_pressure);

            // Log data
            log_data(temperature, pressure);

            // Display data
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            // Attempt to re-initialize I2C after an error
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

