int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Sample audio from both microphones
AudioSample sample_audio(int gain_left, int gain_right) {
    AudioSample sample;
    int left_adc = read_mcp3008(MCP3008_CHANNEL_LEFT);
    int right_adc = read_mcp3008(MCP3008_CHANNEL_RIGHT);

    if (left_adc < 0 || right_adc < 0) {
        fprintf(stderr, "Error reading ADC values\n");
        sample.left = 0; // Set to zero to avoid further calculations with bad data
        sample.right = 0;
        return sample;
    }

    // Convert ADC value to signed 16-bit integer
    sample.left = (int16_t)((float)left_adc / 1023.0 * gain_left * 32768.0);
    sample.right = (int16_t)((float)right_adc / 1023.0 * gain_right * 32768.0);

    return sample;
}

// Apply noise cancellation algorithm
AudioSample subtract_noise(AudioSample left_sample, AudioSample right_sample) {
    AudioSample output_sample;
    output_sample.left = left_sample.left - right_sample.left;
    output_sample.right = left_sample.right - right_sample.right;
    return output_sample;
}

// Print audio data to CSV format
void print_csv(AudioSample output_sample) {
    printf("%d,%d\n", output_sample.left, output_sample.right);
}

// Cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for gain
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain_left> <gain_right>\n", argv[0]);
        return 1;
    }

    GAIN_LEFT = atoi(argv[1]);
    GAIN_RIGHT = atoi(argv[2]);

    if (GAIN_LEFT <= 0 || GAIN_RIGHT <= 0) {
        fprintf(stderr, "Gain values must be positive integers\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        AudioSample left_sample = sample_audio(GAIN_LEFT, GAIN_RIGHT);
        AudioSample right_sample = sample_audio(GAIN_LEFT, GAIN_RIGHT);
        AudioSample output_sample = subtract_noise(left_sample, right_sample);
        print_csv(output_sample);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

