#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define ADC_CHANNEL 0
#define ADC_START_BIT 0x01
#define ADC_SINGLE_ENDED 0x80
#define ADC_DUMMY_BYTE 0x00
#define ADC_READ_COMMAND 0x01
#define ADC_READ_LENGTH 3
#define ADC_READ_TIMEOUT_US 100000 // 100ms timeout
#define MAX_RETRIES 3
#define MIN_ADC_VALUE 0
#define MAX_ADC_VALUE 1023
#define MIN_TEMP 20.0
#define MAX_TEMP 30.0
#define DEFAULT_AMBIENT_TEMP 25.0
#define LOG_FILE "flame_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float compensate_voltage(int raw_adc, float ambient_temp);
void control_buzzer(int flame_detected);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count;

    // Construct SPI message
    tx_buffer[0] = ADC_START_BIT;
    tx_buffer[1] = (ADC_SINGLE_ENDED | (channel & 0x07)) << 4;
    tx_buffer[2] = ADC_DUMMY_BYTE;

    count = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (count != ADC_READ_LENGTH) {
        fprintf(stderr, "SPI transfer failed: %d\n", count);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to compensate voltage with temperature
float compensate_voltage(int raw_adc, float ambient_temp) {
    float voltage = (float)raw_adc / 1023.0 * 3.3;
    return voltage * (1.0 - (ambient_temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP));
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    if (flame_detected) {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer ON
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    }
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.2f,%.2f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is OFF initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Read ambient temperature from file
    float ambient_temp = DEFAULT_AMBIENT_TEMP;
    FILE *temp_file = fopen("ambient_temp.txt", "r");
    if (temp_file != NULL) {
        if (fscanf(temp_file, "%f", &ambient_temp) != 1) {
            fprintf(stderr, "Invalid temperature in ambient_temp.txt, using default\n");
        }
        fclose(temp_file);
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_adc = -1;
        for (int i = 0; i < MAX_RETRIES; i++) {
            raw_adc = read_adc(ADC_CHANNEL);
            if (raw_adc >= MIN_ADC_VALUE && raw_adc <= MAX_ADC_VALUE) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "ADC read failed, retry %d\n", i + 1);
                gpioDelay(10000); // Wait 10ms before retrying
            }
        }

        if (raw_adc == -1) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            log_data(-1, -1.0, -1.0, -1.0, -1); // Log error values
            gpioDelay(500000); // Wait 500ms before next attempt
            continue;
        }

        float voltage = (float)raw_adc / 1023.0 * 3.3;
        float compensated_voltage = compensate_voltage(raw_adc, ambient_temp);
        int flame_detected = (compensated_voltage < 0.5); // Simple threshold
        control_buzzer(flame_detected);
        log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

        gpioDelay(500000); // Sample every 500ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    fclose(log_file);
    gpioTerminate();

    return 0;
}

