#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0

// Define GPIO pins for SPI0 CE0
#define SPI_CE0_PIN 24

// Define GPIO pins for SPI0 MOSI, MISO, SCLK
#define SPI_MOSI_PIN 19
#define SPI_MISO_PIN 21
#define SPI_SCLK_PIN 23

// Define sensor calibration parameters
#define V_SUPPLY 5.0 // Voltage supply to the sensor
#define MAX_VOLTAGE 3.3 // Maximum voltage the MCP3008 can read (V)
#define MAX_AIRFLOW 20.0 // Maximum airflow (LPM)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_airflow(int adc_value);
int log_airflow_data(float airflow);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int ce_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
} spi_config_t;

// Initialize SPI interface
int initialize_spi() {
    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .ce_pin = SPI_CE0_PIN,
        .mosi_pin = SPI_MOSI_PIN,
        .miso_pin = SPI_MISO_PIN,
        .sclk_pin = SPI_SCLK_PIN
    };

    spi_handle = spiOpen(spi_config.ce_pin, spi_config.baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }

    return 0;
}

// Read analog value from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to Liters Per Minute
float convert_to_airflow(int adc_value) {
    // Convert ADC value to voltage (assuming 10-bit ADC and VREF = 3.3V)
    float voltage = (float)adc_value * (V_SUPPLY / 1024.0);

    // Convert voltage to airflow (linear relationship)
    float airflow = (voltage / V_SUPPLY) * MAX_AIRFLOW;

    return airflow;
}

// Log airflow data to CSV file
int log_airflow_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Check if the file exists and write the header if it doesn't
    FILE *fp = fopen("airflow_log.csv", "r");
    if (fp == NULL) {
        log_file = fopen("airflow_log.csv", "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening airflow_log.csv for writing\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Airflow (LPM)\n");
    } else {
        fclose(fp);
        log_file = fopen("airflow_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening airflow_log.csv for appending\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, airflow);
    fclose(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008\n");
            cleanup();
            return 1;
        }

        // Convert to airflow
        float airflow = convert_to_airflow(adc_value);

        // Log airflow data
        if (log_airflow_data(airflow) != 0) {
            fprintf(stderr, "Error logging airflow data\n");
            cleanup();
            return 1;
        }

        // Wait 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

