#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration parameters
int spi_channel = 0;
int adc_channel = 0;
int min_calibration_value = 0;
int max_calibration_value = 1023;
int moisture_threshold = 30;
int logging_interval = 60;
char *email_recipient = NULL;
char *msmtp_config_path = NULL;

int spi_handle;

// Function prototypes
int read_adc(int channel);
float calculate_moisture_percentage(int adc_value, int min_value, int max_value);
void log_data(float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int min_value, int max_value) {
    float percentage = 100.0 * (adc_value - min_value) / (float)(max_value - min_value);
    if (percentage < 0.0) percentage = 0.0;
    if (percentage > 100.0) percentage = 100.0;
    return percentage;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for logging!\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Function to send email alert
void send_email_alert(float moisture_percentage) {
    char command[256];
    char body[256];

    snprintf(body, sizeof(body), "Subject: Plant Moisture Alert\n\nThe moisture level of the plant is below the threshold (%.2f%%).", moisture_percentage);

    snprintf(command, sizeof(command), "echo '%s' | msmtp %s", body, email_recipient);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error sending email!\n");
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", status);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:i:r:e:o:")) != -1) {
        switch (opt) {
            case 'c':
                spi_channel = atoi(optarg);
                break;
            case 'a':
                adc_channel = atoi(optarg);
                break;
            case 'm':
                min_calibration_value = atoi(optarg);
                break;
            case 'M':
                max_calibration_value = atoi(optarg);
                break;
            case 't':
                moisture_threshold = atoi(optarg);
                break;
