// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // Channel connected to MLX90823

// Define GPIO pins for SPI0 CE0
#define SPI_CE0_PIN 8

// Define sensor parameters
#define V_SUPPLY 3.3
#define P_MIN 0.0
#define P_MAX 100.0
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_pressure(int adc_value);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud_rate;
    int ce_pin;
} spi_config_t;

// Structure to hold sensor configuration
typedef struct {
    float min_pressure;
    float max_pressure;
    float min_adc;
    float max_adc;
} sensor_config_t;

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .baud_rate = SPI_BAUD,
        .ce_pin = SPI_CE0_PIN
    };

    spi_handle = spiOpen(spi_config.channel, spi_config.baud_rate, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to pressure (kPa)
float adc_to_pressure(int adc_value) {
    float pressure = P_MIN + (float)(adc_value - ADC_MIN) * (P_MAX - P_MIN) / (ADC_MAX - ADC_MIN);
    return pressure;
}

