#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  // 1 MHz
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define BUFFER_SIZE 20

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd;
int socket_fd;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int state);
void log_data(int moisture_level, int pump_state);
void send_data_to_server(int moisture_level, int pump_state);
void timer_interrupt_handler();
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to control the water pump
int control_pump(int state) {
    digitalWrite(PUMP_GPIO, state);
    return 0;
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to send data to the server
void send_data_to_server(int moisture_level, int pump_state) {
    char message[100];
    snprintf(message, sizeof(message), "%d,%d", moisture_level, pump_state);

    if (send(socket_fd, message, strlen(message), 0) == -1) {
        fprintf(stderr, "Failed to send data to server: %s\n", strerror(errno));
    }
}

// Timer interrupt handler
void timer_interrupt_handler() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level == -1) {
        fprintf(stderr, "Failed to read moisture level, skipping pump control.\n");
        return;
    }

    int pump_state = 0;
    if (moisture_level < LOW_THRESHOLD) {
        control_pump(1); // Turn pump on
        pump_state = 1;
    } else if (moisture_level > HIGH_THRESHOLD) {
        control_pump(0); // Turn pump off
        pump_state = 0;
    }

    log_data(moisture_level, pump_state);
    send_data_to_server(moisture_level, pump_state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    close(socket_fd);
    close(spi_fd);
    wiringPiSPIClose(SPI_CHANNEL);
    wiringPiSetupGpio(); // Reinitialize to avoid issues
    pinMode(PUMP_GPIO, INPUT); // Set pin to input to avoid shorts
    digitalWrite(PUMP_GPIO, LOW);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize pump GPIO
    pinMode(PUMP_GPIO, OUTPUT);
    digitalWrite(PUMP_GPIO, LOW); // Ensure pump is initially off

    // Initialize socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", SERVER_IP);
        close(socket_fd);
        return 1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Connection failed: %s\n", strerror(errno));
        close(socket_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (every 5 seconds)
    if (wiringPiISR(0, INT_EDGE_RISING, timer_interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        delay(1000); // Sleep for 1 second
    }

    cleanup();
    return 0;
}

