#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0x00
#define SPO2_REG 0x03
#define HEART_RATE_REG 0x04
#define HEALTH_LOG_FILE "health_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_part_id();
int init_max30102();
int read_spo2();
int read_heart_rate();
void log_health_data(int spo2, int heart_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read Part ID register
int read_part_id() {
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    return part_id;
}

// Initialize MAX30102 sensor
int init_max30102() {
    // Add initialization sequence here based on the MAX30102 datasheet
    // This is a placeholder, replace with actual initialization
    int status = i2cWriteByteData(i2c_handle, 0x05, 0x01); // Example register write
    if (status < 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", status);
        return -1;
    }
    return 0;
}

// Read SpO2 value
int read_spo2() {
    int spo2 = i2cReadWordData(i2c_handle, SPO2_REG);
    if (spo2 < 0) {
        fprintf(stderr, "Error reading SpO2: %d\n", spo2);
        return -1;
    }
    return spo2;
}

// Read Heart Rate value
int read_heart_rate() {
    int heart_rate = i2cReadWordData(i2c_handle, HEART_RATE_REG);
    if (heart_rate < 0) {
        fprintf(stderr, "Error reading Heart Rate: %d\n", heart_rate);
        return -1;
    }
    return heart_rate;
}

// Log health data to file
void log_health_data(int spo2, int heart_rate) {
    FILE *fp = fopen(HEALTH_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, SpO2: %d, Heart Rate: %d\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int part_id = read_part_id();
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID, sensor may not be present.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x57) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X, expected 0x57\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() != 0) {
        fprintf(stderr, "Error initializing MAX30102 sensor.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read SpO2 and Heart Rate
        int spo2 = read_spo2();
        int heart_rate = read_heart_rate();

        if (spo2 < 0 || heart_rate < 0) {
            fprintf(stderr, "Error reading sensor data.\n");
        } else {
            // Log data if SpO2 is below 95% or Heart Rate is above 100 BPM
            if (spo2 < 95 || heart_rate > 100) {
