#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  // 1 MHz
#define NUM_CHANNELS 3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_INTERVAL_MS 500
#define VREF 3.3

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Function prototypes
int read_mcp3008(int channel);
char* get_iso8601_timestamp();
void log_data(char *timestamp, int channel, int voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adcValue = 0;
    int retries = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    while (retries < RETRY_COUNT) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == 0) {
            adcValue = ((buffer[1] & 0x03) << 8) + buffer[2];
            return adcValue;
        } else {
            fprintf(stderr, "SPI read failed (channel %d), retrying (%d/%d): %s\n", channel, retries + 1, RETRY_COUNT, strerror(errno));
            delay(RETRY_DELAY_MS);
            retries++;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries (channel %d)\n", RETRY_COUNT, channel);
    return -1; // Indicate failure
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to CSV file
void log_data(char *timestamp, int channel, int voltage) {
    if (logFile != NULL) {
        fprintf(logFile, "%s,%d,%d\n", timestamp, channel, voltage);
        fflush(logFile); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    keepRunning = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Open CSV file for logging
    logFile = fopen("analog_log.csv", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header row if the file is newly created
    fseek(logFile, 0, SEEK_END);
    long fileSize = ftell(logFile);
    if (fileSize == 0) {
        fprintf(logFile, "Timestamp,Channel,Voltage\n");
    }
    rewind(logFile);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data logging. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                int adcValue = read_mcp3008(i);
                if (adcValue != -1) {
                    float voltage = (adcValue / 1023.0) * VREF;
                    log_data(timestamp, i, (int)voltage);
                } else {
                    log_data(timestamp, i, -1.0); // Log error value
                }
            }
            free(timestamp);
        } else {
            fprintf(stderr, "Failed to get timestamp, skipping log.\n");
        }

        delay(LOG_INTERVAL_MS);
    }

    // Cleanup
    printf("Closing SPI and log file.\n");
    if (logFile != NULL) {
        fclose(logFile);
    }

    return 0;
}

