    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            printf("ADC Value: %d\n", adc_value);

            if (adc_value >= THRESHOLD) {
                control_buzzer(1); // Turn on buzzer
            } else {
                control_buzzer(0); // Turn off buzzer
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    return 0;
}

