#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_ACTIVE_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON_LATCHING 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define DISTANCE_THRESHOLD 20.0 // cm
#define SAMPLE_INTERVAL_MS 200
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define RELAY_PULSE_DURATION_S 3

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_reg(int fd, unsigned char reg, unsigned short value);
float read_distance();
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);
int initialize();
void cleanup();

// I2C read function
int i2c_read_reg(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned short value) {
    unsigned char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Read distance from ADS1115
float read_distance() {
    unsigned char data[2];
    int16_t adc_value;
    float voltage, distance;

    // Read ADC value
    if (i2c_read_reg(i2c_fd, ADS1115_REG_CONVERT, data, 2) != 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1.0;
    }

    adc_value = (data[0] << 8) | data[1];

    // Convert ADC value to voltage (assuming +/- 4.096V range)
    voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to distance (using a linear approximation)
    // This is a simplified approximation.  A more accurate calibration
    // would involve a lookup table or a more complex formula.
    distance = 27.0 / voltage - 1; // Example linear approximation

    return distance;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
