#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for chip select lines
#define CS0 8
#define CS1 7
#define CS2 25

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define SPI flags
#define SPI_FLAGS 0

// Global variables for SPI handle and file pointer
int spi_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
int read_sensor(int spi_handle, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to read from a specific sensor
int read_sensor(int spi_handle, int channel) {
    int value = read_mcp3008(spi_handle, channel);
    if (value == -1) {
        fprintf(stderr, "Error: Failed to read sensor %d\n", channel);
        return -1;
    }
    return value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close SPI interface
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for chip select lines
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Initialize SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(log_file);
    }
    rewind(log_file);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(spi_handle, 0);
        int sensor2_value = read_sensor(spi_handle, 1);
        int sensor3_value = read_sensor(spi_handle, 2);

        // Log data
        if (sensor1_value != -1 && sensor2_value != -1 && sensor3_value != -1) {
            if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor values\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

