#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3

// Global variables
int spi_handle;
double threshold = DEFAULT_THRESHOLD;
int pump_duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_data(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int count, adc_value = -1;
    char tx_buf[3], rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    for (count = 0; count < MAX_RETRIES; count++) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 3) {
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed, retrying...\n");
            log_data("SPI read failed, retrying...");
            gpioDelay(1000); // Wait 1ms before retry
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Skipping irrigation cycle.\n", MAX_RETRIES);
    log_data("SPI read failed after multiple retries. Skipping irrigation cycle.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
double calculate_moisture_percentage(int adc_value) {
    return ((double)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    sprintf(message, "Pump %s", state ? "ON" : "OFF");
    log_data(message);
}

// Function to log data to a file
void log_data(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

