#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PEAK_THRESHOLD 500
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_MS 10

// Global variables
static volatile int keepRunning = 1;
static int spi_fd;
static FILE *log_file = NULL;

// Function prototypes
int init_spi();
int read_mcp3008(int channel);
int detect_peak(int sample, int threshold);
void log_event(int sample);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin assignments
typedef struct {
    int ce0_pin;
    int clk_pin;
    int mosi_pin;
    int miso_pin;
} gpio_pins_t;

// Initialize GPIO pins
void init_gpio_pins(gpio_pins_t *pins) {
    pins->ce0_pin = 8;
    pins->clk_pin = 11;
    pins->mosi_pin = 10;
    pins->miso_pin = 9;
}

// Initialize SPI
int init_spi() {
    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "SPI setup failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Detect peak
int detect_peak(int sample, int threshold) {
    return (sample > threshold) ? 1 : 0;
}

// Log event
void log_event(int sample) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Sampled value = %d\n", buf, sample);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    keepRunning = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd >= 0) {
        // No direct SPI close function in wiringPi, but we can reset the pins
        digitalWrite(SPI_CHANNEL, LOW); // Reset CE pin
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pins
    gpio_pins_t pins;
    init_gpio_pins(&pins);

    // Initialize SPI
    if (init_spi() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (detect_peak(sample, PEAK_THRESHOLD)) {
            log_event(sample);
        }
        delay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

