#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define PCF8591_ADDR 0x48
#define AIN0_ADDR 0x40

int i2c_handle;

void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        // Dummy read to clear the result register
        if (i2cWriteByte(i2c_handle, AIN0_ADDR) < 0) {
            fprintf(stderr, "Error writing to I2C device\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        usleep(100000); // 100ms delay

        // Read AIN0
        int adc_value = i2cReadByte(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading from I2C device\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        printf("AIN0: %d\n", adc_value);
        usleep(100000); // 100ms delay
    }

    return 0;
}

