    // Main loop
    while (!terminate) {
        // Read soil moisture level
        int moisture_level = read_adc(ADC_CHANNEL);
        if (moisture_level == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            fprintf(stdout, "Moisture level below threshold. Watering...\n");
            log_event(moisture_level);

            // Activate the pump
            control_pump(1); // Turn pump on
            gpioDelay(WATERING_DURATION * 1000000); // Wait for 10 seconds (microseconds)
            control_pump(0); // Turn pump off

            fprintf(stdout, "Watering complete.\n");
        }

        // Wait before the next reading
        gpioDelay(READ_INTERVAL * 1000000); // Wait for 60 seconds (microseconds)
    }

    // Cleanup
    fprintf(stdout, "Shutting down...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

