int read_adc(int channel);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer the SPI message
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate an error
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate the ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1; // Indicate an error
    }

    return adc_value;
}

// Function to control the water pump via GPIO
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
    }
}

// Function to log watering events to a file
void log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Moisture level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure the data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture level
        int moisture_level = read_adc(ADC_CHANNEL);
        if (moisture_level == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            fprintf(stdout, "Moisture level below threshold. Watering...\n");
            log_event(moisture_level);

            // Activate the pump
            control_pump(1); // Turn pump on
            gpioDelay(WATERING_DURATION * 1000000); // Wait for 10 seconds (microseconds)
            control_pump(0); // Turn pump off

            fprintf(stdout, "Watering complete.\n");
        }

        // Wait before the next reading
        gpioDelay(READ_INTERVAL * 1000000); // Wait for 60 seconds (microseconds)
    }

    // Cleanup
    fprintf(stdout, "Shutting down...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

