#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define RAIN_SENSOR_CHANNEL 0
#define VREF 3.3
#define ADC_RESOLUTION 1024 // 10-bit ADC
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int spi_channel, int spi_baud);
int read_mcp3008(int spi_handle, int channel);
float map_adc_to_rainfall(int adc_value);
void log_data(float rainfall_intensity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initializes the SPI interface
int initialize_spi(int spi_channel, int spi_baud) {
    int handle = spiOpen(spi_channel, spi_baud, 0); // SPI0, CE0, 1MHz, Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Reads the ADC value from the MCP3008
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Maps the ADC value to a rainfall intensity level
float map_adc_to_rainfall(int adc_value) {
    // Assuming ADC value ranges from 0 (dry) to 1023 (wet)
    // Linear mapping: 0 = 0.0, 1023 = 1.0
    return (float)adc_value / ADC_RESOLUTION;
}

// Logs the data to stdout
void log_data(float rainfall_intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, ADC Value: %d, Rainfall Intensity: %.2f\n", timestamp, read_mcp3008(spi_handle, RAIN_SENSOR_CHANNEL), rainfall_intensity);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(SPI_CHANNEL, SPI_BAUD);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_handle, RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue; // Skip to the next iteration
        }

        // Map ADC value to rainfall intensity
        float rainfall_intensity = map_adc_to_rainfall(adc_value);

        // Log the data
        log_data(rainfall_intensity);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Rain sensor data logging stopped.\n");

    return 0;
}

