#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define SAMPLE_INTERVAL_MS 100
#define THRESHOLD_DEFAULT 100.0

// Global variables
int i2c_handle;
double threshold = THRESHOLD_DEFAULT;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int *raw_value);
double convert_to_gauss(int raw_value);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// ADS1115 configuration function
int configure_ads1115() {
    // Single-ended AIN0, PGA gain 4.096V, Continuous conversion mode, 128 SPS
    unsigned char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010
    config[2] = 0x83; // 0b10000011

    int result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// ADS1115 read function
int read_ads1115(int *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Conversion to Gauss function
double convert_to_gauss(int raw_value) {
    // Assuming 1.65 Gauss/LSB for a typical Hall-effect sensor
    // and a PGA gain of 4.096V (corresponds to a full-scale range of 4.096V)
    return (double)raw_value * 1.65 / 32768.0 * 4.096;
}

// LED control function
void control_led(int on) {
    gpioWrite(GPIO_LED, on);
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Resources released.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        threshold = strtod(argv[1], &endptr);
        if (*endptr != '\0') {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    int raw_value;
    double gauss_value;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to Gauss
            gauss_value = convert_to_gauss(raw_value);

            // Print magnetic field strength
            printf("Magnetic Field: %.2f Gauss\n", gauss_value);

            // Check threshold and blink LED if necessary
            if (gauss_value > threshold) {
                printf("Threshold exceeded! Blinking LED.\n");
                control_led(1); // Turn on LED
                gpioDelay(50000); // 50 ms
                control_led(0); // Turn off LED
                gpioDelay(50000); // 50 ms
                for (int i = 0; i < 4; i++) {
                    control_led(1);
                    gpioDelay(50000);
                    control_led(0);
                    gpioDelay(50000);
                }
            }
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

