#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_controller"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_CONTROL_TOPIC "pump_control"
#define MQTT_SUBSCRIPTION_TOPIC "pump_control"
#define SENSOR_READ_INTERVAL 60 // seconds
#define SENSOR_READ_WINDOW 5 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_moisture_percentage(int adc_value);
void control_pump(int moisture_percentage);
void publish_moisture_value(int moisture_percentage);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
int calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1;
    }

    // Simple linear mapping (adjust as needed based on sensor calibration)
    int moisture_percentage = 100 - (int)(((float)adc_value / 1023.0) * 100.0);
    return moisture_percentage;
}

// Function to control the pump
void control_pump(int moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD_LOW) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        syslog(LOG_INFO, "Pump turned ON (Moisture: %d%%)", moisture_percentage);
    } else if (moisture_percentage > MOISTURE_THRESHOLD_HIGH) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        syslog(LOG_INFO, "Pump turned OFF (Moisture: %d%%)", moisture_percentage);
    }
}

// Function to publish moisture value to MQTT
void publish_moisture_value(int moisture_percentage) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", moisture_percentage);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture value: %d%%", moisture_percentage);
    }
}

// MQTT on_connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_SUBSCRIPTION_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

// MQTT on_message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "pump_on") == 0) {
            syslog(LOG_INFO, "Received pump_on command");
            gpioWrite(PUMP_GPIO, 1);
        } else if (strcmp(payload, "pump_off") == 0) {
            syslog(LOG_INFO, "Received pump_off command");
            gpioWrite(PUMP_GPIO, 0);
        } else {
            syslog(LOG_WARNING, "Received unknown command: %s", payload);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int pump_state = 0; // 0 = OFF, 1 = ON
    int last_adc_value = 1023; // Initialize to max value
    time_t last_sensor_read_time = 0;
    int adc_value;
    int moisture_percentage;

    while (!terminate) {
        // Read sensor every SENSOR_READ_INTERVAL seconds
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sensor_read_time) >= SENSOR_READ_INTERVAL) {
            adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                syslog(LOG_ERR, "Failed to read ADC value, retrying...");
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage < 0) {
                syslog(LOG_ERR, "Failed to calculate moisture percentage, retrying...");
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            last_adc_value = adc_value;
            last_sensor_read_time = current_time;

            control_pump(moisture_percentage);
            publish_moisture_value(moisture_percentage);
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is OFF
    gpioTerminate();
    closelog();

    return 0;
}

