    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        float sound_level = 0.0;
        float light_level = 0.0;
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            error_code = -1; // ADC read error
        } else {
            sound_level = calculate_db(adc_value);
        }

        if (read_bh1750(&light_level) != 0) {
            fprintf(stderr, "Error: Failed to read BH1750 value\n");
            error_code = -2; // I2C read error
        }

        log_data(sound_level, light_level, error_code);

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

