#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  // 1 MHz
#define SPI_MODE 0
#define VALVE_PIN 17       // BCM GPIO 17
#define PWM_RANGE 100
#define PWM_CLOCK 192      // For 100Hz (19.2MHz / 192 = 100kHz)
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_wiringpi();
int initialize_spi();
int read_mcp3008(int channel);
float average_adc_values(int *values, int num_values);
int set_valve_position(float average_adc);
int log_data(int sensor1, int sensor2, int sensor3, float average_adc, int valve_position);
void signal_handler(int signal);

// Function to initialize wiringPi
int initialize_wiringpi() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED, SPI_MODE) == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;
    int retries = 3;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    while (retries > 0) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
            fprintf(stderr, "SPI read error: %s\n", strerror(errno));
            retries--;
            delay(10); // Small delay before retrying
        } else {
            adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
            break; // Exit loop on success
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read ADC value after multiple retries.\n");
    }

    return adc_value;
}

// Function to average ADC values
float average_adc_values(int *values, int num_values) {
    int valid_count = 0;
    int sum = 0;

    for (int i = 0; i < num_values; i++) {
        if (values[i] != -1) {
            sum += values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return (float)sum / valid_count;
    } else {
        return -1.0; // Indicate error
    }
}

// Function to set valve position based on average ADC value
int set_valve_position(float average_adc) {
    int valve_position = 0;

    if (average_adc >= 0 && average_adc <= 100) {
        valve_position = (int)((average_adc / 100.0) * PWM_RANGE);
    } else {
        fprintf(stderr, "Invalid ADC value: %f\n", average_adc);
        return -1;
    }

    pwmWrite(VALVE_PIN, valve_position);
    return valve_position;
}

// Function to log data to file
int log_data(int sensor1, int sensor2, int sensor3, float average_adc, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d, Sensor3: %d, Average ADC: %.2f, Valve Position: %d\n",
                timestamp, sensor1, sensor2, sensor3, average_adc, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Set valve to 0
    pwmWrite(VALVE_PIN, 0);

    // Close SPI
    // No explicit close function in wiringPiSPI, but setting SPI_CHANNEL to -1 will disable it

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int sensor_values[NUM_SENSORS];
    float average_adc;
    int valve_position;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (initialize_wiringpi() == -1) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Configure PWM
    pinMode(VALVE_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(PWM_CLOCK);

    printf("Soil Moisture Monitoring and Irrigation System\n");

    while (program_running) {
        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
        }

        // Average ADC values
        average_adc = average_adc_values(sensor_values, NUM_SENSORS);

        // Set valve position
        if (average_adc >= 0) {
            valve_position = set_valve_position(average_adc);
        } else {
            valve_position = -1; // Indicate error
        }

        // Log data
        log_data(sensor_values[0], sensor_values[1], sensor_values[2], average_adc, valve_position);

        delay(5000); // Wait 5 seconds
    }

    return 0;
}

