// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CE 8 // CE0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_SPI_RETRIES 5
#define RETRY_DELAY_BASE 100 // milliseconds

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int setup_spi();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int mode;
    int ce;
} spi_config_t;

// Function to setup SPI
int setup_spi() {
    spi_config_t config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .mode = SPI_MODE,
        .ce = SPI_CE
    };

    spi_handle = spiOpen(config.channel, config.baud, config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    int delay = RETRY_DELAY_BASE;
    int result = -1;

    while (retries < MAX_SPI_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            result = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return result;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d/%d). Retrying in %d ms.\n", retries + 1, MAX_SPI_RETRIES, delay);
            gpioDelay(delay);
            delay *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Skipping sample.\n", MAX_SPI_RETRIES);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d. Must be between 0 and 1023.\n", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating program.\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup SPI
    if (setup_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value);
            if (moisture_percentage != -1.0) {
                log_data(moisture_percentage);
            } else {
                fprintf(stderr, "Error converting ADC value to moisture percentage.\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    fprintf(stderr, "Soil moisture monitoring stopped.\n");
    return 0;
}

