#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins
#define TrigPin 23
#define EchoPin 24
#define PWM_Pin 18
#define MCP3008_CS 8

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 440

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 0.5

// Define calibration parameters file
#define CONFIG_FILE "theremin_config.txt"

// Global variables
static volatile int running = 1;
static int last_distance = 0;
static int last_volume = 0;
static int pwm_enabled = 0;

// Calibration parameters
static float distance_min = 10.0;
static float distance_max = 100.0;
static int volume_min = 0;
static int volume_max = 1023;

// Function prototypes
void signal_handler(int signal);
int read_mcp3008(int channel);
float get_distance();
int get_volume();
int map_distance_to_frequency(float distance);
int map_volume_to_duty_cycle(int volume);
void set_pwm_frequency(int frequency);
void set_pwm_duty_cycle(int duty_cycle);
void trigger_ultrasonic_sensor();
void cleanup();
int load_calibration_parameters();
int save_calibration_parameters();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read analog value from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    int handle = spiOpen(SPI_CHANNEL, 100000, 0); // Open SPI channel
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel: %d\n", handle);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    spiXfer(handle, tx_buffer, rx_buffer, 3);

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    spiClose(handle);
    return adc_value;
}

// Function to get distance from ultrasonic sensor
float get_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TrigPin, 0); // Ensure Trig is low
    gpioDelay(2);

    gpioWrite(TrigPin, 1);
    gpioDelay(10);
    gpioWrite(TrigPin, 0);

    // Wait for echo to go high (with timeout)
    int timeout_counter = 0;
    while (gpioRead(EchoPin) == 0 && timeout_counter < (TIMEOUT_DURATION * 1000000)) {
        gpioDelay(1); // Check every 1 microsecond
        timeout_counter++;
    }

    if (timeout_counter >= (TIMEOUT_DURATION * 1000000)) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout_counter = 0;
    while (gpioRead(EchoPin) == 1 && timeout_counter < (TIMEOUT_DURATION * 1000000)) {
        gpioDelay(1);
        timeout_counter++;
    }

    if (timeout_counter >= (TIMEOUT_DURATION * 1000000)) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (low).\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff_tick / 1000000.0 * 34300.0 / 2.0;

    return distance;
}

// Function to get volume from photoresistor
int get_volume() {
    int volume = read_mcp3008(0);
    if (volume < 0) {
        fprintf(stderr, "Error: Could not read volume from MCP3008.\n");
        return last_volume; // Return the last valid volume
    }
    return volume;
}

// Function to map distance to frequency
int map_distance_to_frequency(float distance) {
    if (distance < distance_min) {
        return 200; // Minimum frequency
    } else if (distance > distance_max) {
        return 1000; // Maximum frequency
    } else {
        // Linear mapping
        float frequency = 200 + (distance - distance_min) * (1000 - 200) / (distance_max - distance_min);
        return (int)frequency;
    }
}

// Function to map volume to duty cycle
int map_volume_to_duty_cycle(int volume) {
    if (volume < volume_min) {
        return 0; // Minimum duty cycle
    } else if (volume > volume_max) {
        return 1000000; // Maximum duty cycle
    } else {
        // Linear mapping
        int duty_cycle = 0 + (volume - volume_min) * (1000000 - 0) / (volume_max - volume_min);
        return duty_cycle;
    }
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm%d/enable", frequency);
    FILE *fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM enable file.\n");
        return;
    }
    fprintf(fp, "1");
    fclose(fp);

    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm%d/period", frequency);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM period file.\n");
        return;
    }
    fprintf(fp, "%d", 1000000 / frequency); // Period in nanoseconds
    fclose(fp);

    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", frequency);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM duty_cycle file.\n");
        return;
    }
    fprintf(fp, "%d", map_volume_to_duty_cycle(get_volume()));
    fclose(fp);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_FREQUENCY);
    FILE *fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM duty_cycle file.\n");
        return;
    }
    fprintf(fp, "%d", duty_cycle);
    fclose(fp);
}

// Function to trigger the ultrasonic sensor
void trigger_ultrasonic_sensor() {
    gpioWrite(TrigPin, 1);
    gpioDelay(10);
    gpioWrite(TrigPin, 0);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (pwm_enabled) {
        set_pwm_duty_cycle(0); // Stop PWM
    }
    gpioTerminate();
}

// Function to load calibration parameters from file
int load_calibration_parameters() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open configuration file. Using default values.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "distance_min") == 0) {
                distance_min = atof(value);
            } else if (strcmp(key, "distance_max") == 0) {
                distance_max = atof(value);
            } else if (strcmp(key, "volume_min") == 0) {
                volume_min = atoi(value);
            } else if (strcmp(key, "volume_max") == 0) {
                volume_max = atoi(value);
            }
        }
    }

    fclose(fp);
    printf("Calibration parameters loaded: distance_min=%.2f, distance_max=%.2f, volume_min=%d, volume_max=%d\n",
           distance_min, distance_max, volume_min, volume_max);
    return 0;
}

// Function to save calibration parameters to file
int save_calibration_parameters() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file for writing.\n");
        return -1;
    }

    fprintf(fp, "distance_min=%.2f\n", distance_min);
    fprintf(fp, "distance_max=%.2f\n", distance_max);
    fprintf(fp, "volume_min=%d\n", volume_min);
    fprintf(fp, "volume_max=%d\n", volume_max);

    fclose(fp);
    printf("Calibration parameters saved.\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TrigPin, PI_OUTPUT);
    gpioSetMode(EchoPin, PI_INPUT);
    gpioSetMode(PWM_Pin, PI_OUTPUT);
    gpioSetMode(MCP3008_CS, PI_OUTPUT);

    // Set PWM frequency
    set_pwm_frequency(PWM_FREQUENCY);
    pwm_enabled = 1;

    // Load calibration parameters
    if (load_calibration_parameters() != 0) {
        fprintf(stderr, "Warning: Failed to load calibration parameters. Using default values.\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Theremin instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        float distance = get_distance();
        int volume = get_volume();

        // Map sensor values to frequency and duty cycle
        int frequency = map_distance_to_frequency(distance);
        int duty_cycle = map_volume_to_duty_cycle(volume);

        // Update last valid values
        last_distance = distance;
        last_volume = volume;

        // Set PWM frequency and duty cycle
        if (pwm_enabled) {
            set_pwm_frequency(frequency);
            set_pwm_duty_cycle(duty_cycle);
        }

        // Print sensor values and PWM parameters
        printf("Distance: %.2f cm, Volume: %d, Frequency: %d Hz, Duty Cycle: %d\n", distance, volume, frequency, duty_cycle);

        // Delay
        gpioDelay(50);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

