#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define SAMPLING_INTERVAL 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_alcohol_ppm(int adc_value);
const char *classify_alcohol_level(float ppm);
void log_data(float ppm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    float ppm;
    const char *status;
} SensorData;

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0 CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    for (count = 0; count < 3; count++) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result != 0) {
            fprintf(stderr, "SPI transfer failed: %d\n", result);
            return -1; // Indicate error
        }
    }

    // Extract ADC value from response
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate alcohol concentration (ppm)
float calculate_alcohol_ppm(int adc_value) {
    // Simple linear conversion (adjust based on sensor calibration)
    // Assuming 0V = 0 ppm, 3.3V = 100 ppm
    return (adc_value / 1023.0) * 100.0;
}

// Function to classify alcohol level
const char *classify_alcohol_level(float ppm) {
    if (ppm > 50.0) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < 20.0) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Function to log data to file
void log_data(float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int adc_value;
    float ppm;
    const char *status;

    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
