#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define potentiometer calibration values
#define POT1_MIN 0
#define POT1_MAX 1023
#define POT2_MIN 0
#define POT2_MAX 1023

// Define motor speed limits
#define MAX_SPEED 255
#define MIN_SPEED 0

// Global variables for SPI handle and program state
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int map_pot_to_speed(int pot_value, int pot_min, int pot_max, int speed_min, int speed_max);
void set_motor_speed(int motor_enable_pin, int direction_pin, int speed);
void accelerate(int motor_enable_pin, int direction_pin, int speed);
void decelerate(int motor_enable_pin, int direction_pin, int speed);
void reverse_direction(int motor1_dir_pin, int motor2_dir_pin);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to speed
int map_pot_to_speed(int pot_value, int pot_min, int pot_max, int speed_min, int speed_max) {
    if (pot_value < pot_min) {
        pot_value = pot_min;
    }
    if (pot_value > pot_max) {
        pot_value = pot_max;
    }
    return (int)(((float)(pot_value - pot_min) / (pot_max - pot_min)) * (speed_max - speed_min) + speed_min);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_enable_pin, int direction_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > MAX_SPEED) speed = MAX_SPEED;

    // Set motor direction
    gpioWrite(direction_pin, speed > 0); // HIGH for forward, LOW for backward

    // Set PWM duty cycle
    gpioPWM(motor_enable_pin, speed);
}

// Function to accelerate motor speed
void accelerate(int motor_enable_pin, int direction_pin, int speed) {
    int current_speed = 0;
    int increment = 10; // Adjust increment for desired acceleration rate
    int delay_ms = 10;   // Adjust delay for desired acceleration rate

    while (current_speed <= speed) {
        current_speed += increment;
        if (current_speed > speed) current_speed = speed;
        set_motor_speed(motor_enable_pin, direction_pin, current_speed);
        gpioDelay(delay_ms);
    }
}

// Function to decelerate motor speed
void decelerate(int motor_enable_pin, int direction_pin, int speed) {
    int current_speed = speed;
    int decrement = 10; // Adjust decrement for desired deceleration rate
    int delay_ms = 10;   // Adjust delay for desired deceleration rate

    while (current_speed >= 0) {
        current_speed -= decrement;
        if (current_speed < 0) current_speed = 0;
        set_motor_speed(motor_enable_pin, direction_pin, current_speed);
        gpioDelay(delay_ms);
    }
}

// Function to reverse motor direction
void reverse_direction(int motor1_dir_pin, int motor2_dir_pin) {
    gpioWrite(motor1_dir_pin, 0); // Stop Motor 1
    gpioWrite(motor2_dir_pin, 0); // Stop Motor 2

    gpioDelay(100); // Short delay to ensure motors stop

    gpioWrite(motor1_dir_pin, 1); // Reverse Motor 1 direction
    gpioWrite(motor2_dir_pin, 1); // Reverse Motor 2 direction

    gpioDelay(100); // Short delay to ensure motors reverse direction
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Skipping motor control.\n");
            gpioDelay(100); // Small delay to prevent spamming errors
            continue;
        }

        // Map potentiometer values to speeds
        int motor1_speed = map_pot_to_speed(pot1_value, POT1_MIN, POT1_MAX, MIN_SPEED, MAX_SPEED);
        int motor2_speed = map_pot_to_speed(pot2_value, POT2_MIN, POT2_MAX, MIN_SPEED, MAX_SPEED);

        // Accelerate motor 1
        accelerate(MOTOR1_ENABLE, MOTOR1_DIR, motor1_speed);

        // Accelerate motor 2
        accelerate(MOTOR2_ENABLE, MOTOR2_DIR, motor2_speed);

        // Hold constant speed for 2 seconds
        gpioDelay(2000);

        // Decelerate motor 1
        decelerate(MOTOR1_ENABLE, MOTOR1_DIR, motor1_speed);

        // Decelerate motor 2
        decelerate(MOTOR2_ENABLE, MOTOR2_DIR, motor2_speed);

        // Reverse direction of both motors
        reverse_direction(MOTOR1_DIR, MOTOR2_DIR);

        // Pause for 5 seconds
        gpioDelay(5000);
    }

    // Stop motors
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIR, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIR, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

