#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_noise_level(int duration_seconds);
int calculate_threshold(int noise_level, int calibration_duration_seconds);
int is_above_threshold(int sound_level, int threshold);
void control_led(int state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting CS pin mode\n");
        return -1;
    }
    if (gpioSetMode(MOSI_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOSI pin mode\n");
        return -1;
    }
    if (gpioSetMode(MISO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting MISO pin mode\n");
        return -1;
    }
    if (gpioSetMode(SCLK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting SCLK pin mode\n");
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate noise level
int calibrate_noise_level(int duration_seconds) {
    int sum = 0;
    for (int i = 0; i < duration_seconds * 10; i++) { // Sample every 10 ms for the specified duration
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level during calibration\n");
            return -1;
        }
        sum += sound_level;
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    }
    return sum / (duration_seconds * 10);
}

// Function to calculate threshold
int calculate_threshold(int noise_level, int calibration_duration_seconds) {
    return noise_level + (calibration_duration_seconds * 5);
}

// Function to check if sound level is above threshold
int is_above_threshold(int sound_level, int threshold) {
    return sound_level > threshold;
}

// Function to control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate noise level
    int noise_level = calibrate_noise_level(5);
    if (noise_level < 0) {
        fprintf(stderr, "Calibration failed, exiting\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calculate threshold
    int threshold = calculate_threshold(noise_level, 5);

    printf("Noise level: %d, Threshold: %d\n", noise_level, threshold);

    // Main loop
    while (!terminate) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level\n");
            continue; // Skip to the next iteration
        }

        if (is_above_threshold(sound_level, threshold)) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(10000); // Sample every 10 ms
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

