#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(int adc_value);
void log_data(float airflow);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the ADC value from the specified channel
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (4 bits)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Converts the ADC value to airflow using a linear calibration curve
float voltage_to_airflow(int adc_value) {
    // Assuming a linear relationship: Airflow = (ADC Value / Max ADC Value) * Max Airflow
    float max_airflow = 20.0; // Example: Max Airflow in SLPM
    float max_adc_value = 1023.0; // Example: Max ADC Value for MCP3008

    return ((float)adc_value / max_adc_value) * max_airflow;
}

// Logs the airflow data to a file with a timestamp
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Airflow: %.2f SLPM\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value >= 0) {
            float airflow = voltage_to_airflow(adc_value);
            log_data(airflow);
        } else {
            fprintf(stderr, "ERROR: ADC read failed\n");
            fprintf(log_file, "ERROR: ADC read failed\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    printf("Closing SPI, log file, and terminating pigpio...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

