        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float x_raw, y_raw, z_raw;
        float x_g, y_g, z_g;
        float x_smoothed, y_smoothed, z_smoothed;

        // Read raw ADC values
        for (int i = 0; i < NUM_SAMPLES; ++i) {
