#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the magnetic field range in millitesla
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the sensor value to a magnetic field strength in millitesla
float convert_to_mT(int sensor_value) {
    if (sensor_value == 0) {
        return 0.0;
    } else if (sensor_value == 1) {
        return 3300.0;
    } else {
        fprintf(stderr, "Invalid sensor value: %d\n", sensor_value);
        return -1.0; // Indicate an error
    }
}

// Function to log the magnetic field values to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "sensor1_mT,sensor2_mT,sensor3_mT\n");
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert the sensor values to magnetic field strengths
        float sensor1_mT = convert_to_mT(sensor1_value);
        float sensor2_mT = convert_to_mT(sensor2_value);
        float sensor3_mT = convert_to_mT(sensor3_value);

        // Check if the magnetic field strengths are within the valid range
        if (sensor1_mT < MIN_FIELD || sensor1_mT > MAX_FIELD ||
            sensor2_mT < MIN_FIELD || sensor2_mT > MAX_FIELD ||
            sensor3_mT < MIN_FIELD || sensor3_mT > MAX_FIELD) {
            fprintf(stderr, "Warning: Magnetic field strength out of range.\n");
        }

        // Log the data
        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

