#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define MOISTURE_HYSTERESIS 35
#define READ_INTERVAL 60 // seconds
#define ADC_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_level(int adc_value);
void control_pump(int pump_state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid ADC channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture level (0-100%)
float calculate_moisture_level(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_event("Error: Invalid ADC value.");
        return -1.0;
    }
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the pump relay
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
    char message[100];
    sprintf(message, "Pump turned %s", pump_state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("watering.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off at startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    // Main loop
    int pump_state = 0; // 0 = off, 1 = on
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value.");
            gpioDelay(READ_INTERVAL * 1000); // Wait before retrying
            continue;
        }

        // Calculate moisture level
        float moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0) {
            log_event("Error: Failed to calculate moisture level.");
            gpioDelay(READ_INTERVAL * 1000); // Wait before retrying
            continue;
        }

        char message[100];
        sprintf(message, "Moisture level: %.2f%% (ADC: %d)", moisture_level, adc_value);
        log_event(message);

        // Control pump based on moisture level
        if (moisture_level < MOISTURE_THRESHOLD && pump_state == 0) {
            control_pump(1); // Turn pump on
            pump_state = 1;
        } else if (moisture_level > MOISTURE_HYSTERESIS && pump_state == 1) {
            control_pump(0); // Turn pump off
            pump_state = 0;
        }

        gpioDelay(READ_INTERVAL * 1000); // Wait for the next reading
    }

    // Clean up (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

