#include <linux/spi/spidev.h>
#include <errno.h>

// SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel definitions
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define MCP3008_CHANNEL_2 2

// Global variables for SPI file descriptor and CSV file pointer
static int spi_fd = -1;
static FILE *csv_file = NULL;

// Function prototypes
int spi_init(void);
int read_mcp3008_channel(int channel);
int log_data_to_csv(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int sig);

// Structure to hold SPI configuration
typedef struct {
    char *device;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Function to initialize the SPI interface
int spi_init(void) {
    spi_config_t config = {
        .device = SPI_DEVICE,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    spi_fd = open(config.device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read a single channel from the MCP3008
int read_mcp3008_channel(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to a CSV file
int log_data_to_csv(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen("sensor_data.csv", "a");
        if (csv_file == NULL) {
            perror("Error opening CSV file");
            return -1;
        }
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n"); // Write header
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    exit(0);
}

int main(void) {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        int channel0_value = read_mcp3008_channel(MCP3008_CHANNEL_0);
        int channel1_value = read_mcp3008_channel(MCP3008_CHANNEL_1);
        int channel2_value = read_mcp3008_channel(MCP3008_CHANNEL_2);

        if (channel0_value < 0 || channel1_value < 0 || channel2_value < 0) {
            fprintf(stderr, "Error reading MCP3008 channels. Retrying in 1 second.\n");
        } else {
            if (log_data_to_csv(channel0_value, channel1_value, channel2_value) < 0) {
                fprintf(stderr, "Error logging data to CSV. Retrying in 1 second.\n");
            }
        }

        sleep(1);
    }

    return 0;
}

