#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60.0

// Global variables (minimize usage)
static struct mosquitto *mosq = NULL;
static int running = 1;
static int led_state = 0; // Initial LED state (off)
static int reconnect_delay = 1.0; // Initial reconnection delay

// Function prototypes
void signal_handler(int sig);
int mqtt_connect_with_backoff(struct mosquitto **mosq, const char *host, int port, const char *client_id);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
int set_gpio_output(int gpio_pin, int led_state);
void log_error(const char *message);

// Signal handler for clean shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    running = 0;
    printf("Signal received, shutting down...\n");
}

// MQTT connect with exponential backoff
int mqtt_connect_with_backoff(struct mosquitto **mosq, const char *host, int port, const char *client_id) {
    int rc = 0;
    int retry_count = 0;
    int backoff_delay = 1.0;

    while (running && retry_count < 10) {
        rc = mosquitto_connect(*mosq, host, port, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Connected to MQTT broker.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error connecting to MQTT broker: %s. Retrying in %.2f seconds...\n", mosquitto_strerror(rc), backoff_delay);
            log_error("MQTT connection failed");
            sleep(backoff_delay);
            backoff_delay *= 2.0; // Exponential backoff
            if (backoff_delay > MAX_RECONNECT_DELAY) {
                backoff_delay = MAX_RECONNECT_DELAY;
            }
            retry_count++;
        }
    }

    log_error("MQTT connection failed after multiple retries");
    return -1; // Failure
}

// MQTT on_connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(result));
        log_error("MQTT connection failed");
    }
}

// MQTT on_disconnect callback
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        fprintf(stderr, "Disconnected from MQTT broker with error code %d\n", rc);
        log_error("MQTT disconnection error");
    } else {
        printf("Disconnected from MQTT broker.\n");
    }
}

// MQTT on_message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        printf("Received message on topic %s: %s\n", message->topic, (char *)message->payload);

        if (parse_json_payload((char *)message->payload, &led_state) == 0) {
            set_gpio_output(GPIO_PIN, led_state);
        } else {
            log_error("Invalid JSON payload");
        }
    } else {
        fprintf(stderr, "Empty message received on topic %s\n", message->topic);
        log_error("Empty MQTT message");
    }
}

// JSON parsing function
int parse_json_payload(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        log_error("JSON parsing error");
        return -1;
    }

    json_t *state_json = json_object_get(root, "led_state");
    if (!state_json) {
        fprintf(stderr, "Error: 'led_state' not found in JSON\n");
        log_error("JSON missing led_state key");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(state_json)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean\n");
        log_error("JSON led_state is not a boolean");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(state_json);
    json_decref(root);
    return 0;
}

// GPIO control function
int set_gpio_output(int gpio_pin, int led_state) {
    gpioWrite(gpio_pin, led_state);
    return 0;
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

int main() {
    pthread_t mqtt_thread;
    int rc = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_gpio_output(GPIO_PIN, 0); // Turn LED off initially

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create MQTT client instance
    mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        log_error("MQTT client creation failed");
        gpioTerminate();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start MQTT loop in a separate thread
    rc = pthread_create(&mqtt_thread, NULL, (void *(*)(void *))mosquitto_loop_start, mosq);
    if (rc) {
        fprintf(stderr, "Error creating MQTT thread: %s\n", strerror(rc));
        log_error("MQTT loop thread creation failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Main loop (wait for signal)
    while (running) {
        sleep(1);
    }

    // Clean up
    pthread_join(mqtt_thread, NULL);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    set_gpio_output(GPIO_PIN, 0); // Turn LED off
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

