    // Set GPIO17 as input for the sound sensor
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    // Set GPIO18 as output for the alarm LED
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the sound sensor value
int read_sound_sensor() {
    int sound_level = gpioRead(SOUND_SENSOR_PIN);
    if (sound_level < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", SOUND_SENSOR_PIN);
        return -1; // Indicate an error
    }
    return sound_level;
}

// Function to trigger the alarm LED
void trigger_alarm() {
    if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
        return;
    }
    gpioDelay(1000); // 1 second
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
        return;
    }
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            cleanup_gpio();
            return 1;
        }

        if (sound_level == 0) {
            printf("Sound detected!\n");
            trigger_alarm();
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

