#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    return 0;
}

int i2c_init() {
    int file;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return 0;
}

int read_accelerometer(int file, int reg) {
    int value = i2c_smbus_read_byte_data(file, reg);
    if (value < 0) {
        perror("Failed to read accelerometer data");
        return -1;
    }
    return value;
}

int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

void shutdown_system() {
    printf("Shutting down system...\n");
    log_message("System shutdown triggered by vibration.");
    system("sudo shutdown -h now");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpio_init() != 0) {
        return 1;
    }

    if (i2c_init() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int accel_x = read_accelerometer(i2c_fd, 0x01);
        int accel_y = read_accelerometer(i2c_fd, 0x03);
        int accel_z = read_accelerometer(i2c_fd, 0x05);

        if (accel_x < 0 || accel_y < 0 || accel_z < 0) {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Simple threshold check (adjust as needed)
        if (abs(accel_x) > 100 || abs(accel_y) > 100 || abs(accel_z) > 100) {
            gpioDelay(100); // Debounce
            int event = gpioRead(GPIO_PIN);
            if (event == 0) { // Falling edge detected
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                char message[200];
                snprintf(message, sizeof(message), "Vibration detected at [%d-%02d-%02d %02d:%02d:%02d] - Accel: X=%d, Y=%d, Z=%d",
                         tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                         accel_x, accel_y, accel_z);

                log_message(message);
                printf("%s\n", message);
                shutdown_system();
                break; // Exit after shutdown
            }
        }

        gpioDelay(50); // Check every 50ms
    }

    gpioTerminate();
    close(i2c_fd);
    printf("Vibration monitoring stopped.\n");
    return 0;
}

