#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_NORMAL 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int bmp280_init();
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
double bmp280_calculate_altitude(double pressure);
int log_altitude_data(double altitude);
void signal_handler(int signal);
int read_calibration_data();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// BMP280 initialization function
int bmp280_init() {
    // Check if the sensor is present
    int chip_id;
    if (i2cReadByteData(i2c_handle, BMP280_REG_CHIPID) < 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set oversampling and mode
    int ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL;
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set filter and standby time
    int config = (0x02 << 5) | (0x05 << 2); // Filter coefficient = 4, Standby time = 1000ms
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data() {
    unsigned char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data block\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the sensor
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    unsigned char data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)(((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | ((uint32_t)data[2] >> 4));
    *temperature = (int32_t)(((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | ((uint32_t)data[5] >> 4));

    return 0;
}

// Function to compensate temperature
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
