#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // LM35 connected to MCP3008 channel 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5 // seconds
#define VREF 3.3 // Reference voltage

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
void print_buffer(const CircularBuffer *cb);
void write_buffer_to_file(const CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0; // 10-bit ADC
    float temperature = voltage * 100.0; // LM35: 10mV/°C
    return temperature;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Print the contents of the circular buffer
void print_buffer(const CircularBuffer *cb) {
    printf("Temperature: ");
    for (int i = 0; i < cb->count; i++) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%.2f ", cb->buffer[index]);
    }
    printf("\n");
}

// Write the contents of the circular buffer to a file
void write_buffer_to_file(const CircularBuffer *cb) {
    FILE *fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return;
    }

    size_t elements_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (elements_written != cb->count) {
        fprintf(stderr, "Error writing to file!\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    CircularBuffer temperature_buffer = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping this sample.\n");
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Add temperature to circular buffer
        add_to_buffer(&temperature_buffer, temperature);

        // Print temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Write buffer to file
        write_buffer_to_file(&temperature_buffer);

        // Delay for 5 seconds
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

