int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Invalid I2C handle.\n");
        return -1;
    }

    // Send power on and start measurement command (0x01)
    if (i2cWriteByte(i2c_handle, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return -1;
    }

