#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down resistor on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to read the sensor state
int read_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return state;
}

// Function to log the event to a CSV file
int log_event(const char *filename, int pin, int state) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);
    return 0;
}

// Function to check for flame
void check_flame(int pin, int state) {
    if (state == 1) {
        printf("Flame detected!\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pin
    if (initialize_gpio(GPIO_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_state = read_sensor(GPIO_PIN);
        if (sensor_state >= 0) {
            if (log_event(LOG_FILE, GPIO_PIN, sensor_state) != 0) {
                fprintf(stderr, "Error logging event\n");
            }
            check_flame(GPIO_PIN, sensor_state);
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up GPIO resources
    gpioTerminate();
    printf("GPIO resources released.\n");

    return 0;
}

