    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value / ADC_RESOLUTION) * VREF;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    return temperature;
}

// Function to write to MCP4725 DAC
int write_mcp4725(int handle, float voltage) {
    if (voltage < 0.0 || voltage > VOLTAGE_RANGE) {
        fprintf(stderr, "Error: Invalid voltage: %.2f\n", voltage);
        return -1;
    }

    // Calculate DAC value
    int dac_value = (int)((voltage / VREF) * ADC_RESOLUTION);

    // Construct I2C message
    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Control byte: write DAC value
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    tx_buffer[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    // Transfer data
    int result = i2cWriteDevice(handle, tx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: I2C write failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int adc_value, float temperature, float voltage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %d, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            adc_value, temperature, voltage);
    fflush(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            fprintf(log_file, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to Celsius
        float temperature = adc_to_celsius(adc_value);

        // Write voltage to DAC
        if (write_mcp4725(i2c_handle, temperature) != 0) {
            fprintf(stderr, "Error: Failed to write to DAC\n");
            fprintf(log_file, "Error: Failed to write to DAC\n");
            continue; // Retry
        }

        // Log data
        if (log_data(log_file, adc_value, temperature, temperature * VREF) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Print to stdout
        printf("ADC: %d, Temp: %.2f °C, DAC: %.2f V\n", adc_value, temperature, temperature * VREF);

        // Wait 0.5 seconds
        gpioDelay(500000); // 0.5 seconds = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

