void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Release all GPIO lines
    gpioSetMode(RELAY1_PIN, PI_INPUT); // Set to input to release
    gpioSetMode(RELAY2_PIN, PI_INPUT);
    gpioSetMode(RELAY3_PIN, PI_INPUT);
    gpioSetMode(RELAY4_PIN, PI_INPUT);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to the OFF state (LOW)
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
