// Define GPIO pins for motor control
#define MOTOR_FORWARD_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_ENABLE_PIN 27

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 0
#define PWM_RANGE 255

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_rain_sensor();
void control_motor(int forward);
void log_data(int rain_level);
void signal_handler(int signal);
int initialize_spi();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | 0) << 4; // Single-ended mode, channel 0
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error reading SPI data: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to control the motor direction and speed
void control_motor(int forward) {
    if (forward) {
        digitalWrite(MOTOR_FORWARD_PIN, HIGH);
        digitalWrite(MOTOR_REVERSE_PIN, LOW);
        pwmWrite(MOTOR_ENABLE_PIN, 150); // 150 out of 255
    } else {
        digitalWrite(MOTOR_FORWARD_PIN, LOW);
        digitalWrite(MOTOR_REVERSE_PIN, HIGH);
        pwmWrite(MOTOR_ENABLE_PIN, 150); // 150 out of 255
    }
}

// Function to log the rain level and timestamp to a file
void log_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, rain_level);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    int rain_level;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() == -1) {
        return 1;
    }

    // Set GPIO pins as output
    pinMode(MOTOR_FORWARD_PIN, OUTPUT);
    pinMode(MOTOR_REVERSE_PIN, OUTPUT);
    pinMode(MOTOR_ENABLE_PIN, PWM_OUTPUT);

    // Set PWM range
    pwmSetRange(PWM_RANGE);

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    printf("Rain sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        rain_level = read_rain_sensor();
        if (rain_level == -1) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            delay(1000); // Wait before retrying
            continue;
        }

        log_data(rain_level);

        if (rain_level > RAIN_THRESHOLD) {
            printf("Rain level above threshold. Opening window.\n");
            control_motor(MOTOR_FORWARD);
            delay(3000); // Run for 3 seconds
            control_motor(MOTOR_STOP);
            printf("Window closed.\n");
        } else {
            printf("Rain level below threshold. Closing window.\n");
            control_motor(MOTOR_REVERSE);
            delay(3000); // Run for 3 seconds
            control_motor(MOTOR_STOP);
            printf("Window opened.\n");
        }

        delay(1000); // Poll every 1 second
    }

    // Cleanup before exiting
    printf("Cleaning up...\n");
    control_motor(MOTOR_STOP); // Stop the motor
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

