#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define constants
#define ADC_SAMPLES 1000
#define CLAP_THRESHOLD 500
#define DEBOUNCE_INTERVAL_MS 50
#define LED_ON_TIME_MS 500

// Global variables
volatile sig_atomic_t program_running = 1;
int adc_value = 0;
int clap_count = 0;
time_t last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int on);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        control_led(0); // Turn off LED
        gpioTerminate(); // Release GPIO resources
        printf("\nProgram terminated gracefully.\n");
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(ADC_PIN, PI_INPUT); // Set ADC pin as input
    gpioSetMode(LED_PIN, PI_OUTPUT);  // Set LED pin as output
    control_led(0); // Ensure LED is off initially

    return 0; // Indicate success
}

// Read ADC value using bit-banging
int read_adc() {
    int sum = 0;
    for (int i = 0; i < ADC_SAMPLES; i++) {
        sum += gpioRead(ADC_PIN); // Read digital value (0 or 1)
        gpioDelay(1); // Small delay for sampling rate control
    }
    return sum;
}

// Detect clap event
int detect_clap(int adc_value) {
    return (adc_value > CLAP_THRESHOLD);
}

// Control LED state
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Log message with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("[%s] %s\n", buf, message);
}

int main() {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Clap detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        adc_value = read_adc();

        if (detect_clap(adc_value)) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_clap_time) * 1000 > DEBOUNCE_INTERVAL_MS) {
                log_message("Clap detected!");
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME_MS * 1000); // Keep LED on for specified time
                control_led(0); // Turn off LED
                clap_count++;
                last_clap_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

