#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define MCP3008_CS 8  // GPIO8 (BCM)
#define MCP3008_DIN 9 // GPIO9 (BCM)
#define MCP3008_DOUT 10 // GPIO10 (BCM)
#define MCP3008_CLK 11 // GPIO11 (BCM)

// Define SPI parameters
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define DRV5055-A1 parameters
#define VREF 3.3
#define SENSITIVITY 0.002 // 2 mV/Gauss
#define ZERO_FIELD_VOLTAGE 1.65 // V

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int channel);
float adc_to_magnetic_field(int adc_value);
void log_data(float magnetic_field);
void signal_handler(int signal);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Set CS low
    if (gpioWrite(MCP3008_CS, 0) != 0) {
        fprintf(stderr, "Error setting CS low\n");
        return -1;
    }

    // Perform SPI transfer
    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading MCP3008\n");
        if (gpioWrite(MCP3008_CS, 1) != 0) {
            fprintf(stderr, "Error setting CS high\n");
        }
        return -1;
    }

    // Set CS high
    if (gpioWrite(MCP3008_CS, 1) != 0) {
        fprintf(stderr, "Error setting CS high\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to magnetic field strength
float adc_to_magnetic_field(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float magnetic_field = (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY;
    return magnetic_field;
}

// Function to log data to file
void log_data(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);

    // Release GPIO line
    gpioWrite(MCP3008_CS, 1);

    // Close SPI file descriptor
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_DIN, PI_OUTPUT);
    gpioSetMode(MCP3008_DOUT, PI_INPUT);
    gpioSetMode(MCP3008_CLK, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float magnetic_field = adc_to_magnetic_field(adc_value);
            log_data(magnetic_field);
            printf("Magnetic Field: %.2f Gauss\n", magnetic_field);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        usleep(500000); // 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(MCP3008_CS, 1);
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

