#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce parameters
#define DEBOUNCE_READS 5
#define DEBOUNCE_DELAY_MS 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio);
int debounce_read(int gpio);
void log_sensor_state(int sensor_id, int state);
void check_alert_condition(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Function to read the sensor state
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to perform debouncing
int debounce_read(int gpio) {
    int readings[DEBOUNCE_READS];
    int i, sum = 0;

    for (i = 0; i < DEBOUNCE_READS; i++) {
        readings[i] = read_sensor(gpio);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    for (i = 0; i < DEBOUNCE_READS; i++) {
        if (readings[i] == 0) {
            sum++;
        }
    }

    return (sum >= DEBOUNCE_READS / 2) ? 0 : 1; // Return 0 if majority is 0, otherwise 1
}

// Function to log the sensor state
void log_sensor_state(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d: %s\n", timestamp, sensor_id, state ? "1" : "0");
}

// Function to check the alert condition
void check_alert_condition(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set pull-up resistors (if needed, depends on sensor module)
    // gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    // gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_state = debounce_read(SENSOR_1_GPIO);
        int sensor2_state = debounce_read(SENSOR_2_GPIO);

        log_sensor_state(1, sensor1_state);
        log_sensor_state(2, sensor2_state);
        check_alert_condition(sensor1_state, sensor2_state);

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

