#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <wiringPi.h>

#define PIR_PIN 17 // wiringPi pin number
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define ISO8601_FORMAT "%Y-%m-%dT%H:%M:%SZ"
#define CAPTURE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

int initialize_wiringPi() {
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return -1;
    }
    pinMode(PIR_PIN, INPUT);
    pullUpDnControl(PIR_PIN, PUD_DOWN); // Enable pull-down resistor
    return 0;
}

int read_pir_sensor() {
    return digitalRead(PIR_PIN);
}

int debounce_delay() {
    delay(DEBOUNCE_DELAY_MS);
    return read_pir_sensor();
}

int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char filename[100];
    char command[200];
    int ret;
    int child_pid;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), ISO8601_FORMAT, timeinfo);

    snprintf(filename, sizeof(filename), "%s%s.jpg", CAPTURE_DIR, timestamp);

    // Construct the libcamera-still command
    snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

    child_pid = fork();

    if (child_pid == -1) {
        syslog(LOG_ERR, "Failed to fork: %s", strerror(errno));
        return -1;
    } else if (child_pid == 0) {
        // Child process
        execlp("sh", "sh", "-c", command, (char *)NULL);
        syslog(LOG_ERR, "execl failed: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(child_pid, &status, 0);

        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0) {
                syslog(LOG_ERR, "libcamera-still failed with exit status %d", WEXITSTATUS(status));
                return -1;
            } else {
                syslog(LOG_INFO, "Image captured: %s", filename);
                return 0;
            }
        } else {
            syslog(LOG_ERR, "Child process terminated abnormally");
            return -1;
        }
    }
}

int main() {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting motion detector...");

    if (initialize_wiringPi() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi, exiting.");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Assume no motion initially

    while (program_running) {
        int current_state = read_pir_sensor();

        if (current_state != last_state) {
            if (debounce_delay() == current_state) {
                if (capture_image() == 0) {
                    syslog(LOG_INFO, "Motion detected and image captured.");
                } else {
                    syslog(LOG_ERR, "Failed to capture image.");
                }
            } else {
                syslog(LOG_WARNING, "Debounce failed, ignoring state change.");
            }
            last_state = current_state;
        }
        delay(POLL_INTERVAL_MS);
    }

    syslog(LOG_INFO, "Stopping motion detector...");
    closelog();
    return 0;
}

