#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Define the default CSI device
#define DEFAULT_CSI_DEVICE "/dev/video0"

// Define the number of frames to capture
#define NUM_FRAMES 100

// Define the buffer size (adjust as needed)
#define BUFFER_SIZE (384 * 384 * 2) // 384x384 grayscale image (2 bytes per pixel)

// Structure to hold camera configuration
typedef struct {
    int fd;
    void *buffer;
    int fd_in;
    int fd_out;
    int buffer_count;
} camera_context_t;

// Global variables
static int csi_device = DEFAULT_CSI_DEVICE;
static int num_cameras = 1;
static int camera_fds[NUM_CAMERAS];
static camera_context_t *camera_contexts = NULL;
static int frame_count = 0;
static volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize a camera
int init_camera(int camera_index, const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        return -1;
    }

    // Check if the device is a video device
    struct stat st;
    if (fstat(fd, &st) == 0) {
        if (S_ISVID(st.st_mode)) {
            fprintf(stderr, "%s is a video device\n", device_name);

            // Set the camera to grayscale mode (8-bit)
            if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
                fprintf(stderr, "Error setting format: %s\n", strerror(errno));
                close(fd);
                return -1;
            }

            // Allocate memory for the buffer
            camera_contexts[camera_index].buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
            if (camera_contexts[camera_index].buffer == MAP_FAILED) {
                fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
                close(fd);
                return -1;
            }

            camera_contexts[camera_index].fd = fd;
            camera_contexts[camera_index].buffer_count = 0;

            return 0;
        } else {
            fprintf(stderr, "%s is not a video device\n", device_name);
            close(fd);
            return -1;
        }
    } else {
        fprintf(stderr, "Error getting file status for %s: %s\n", device_name, strerror(errno));
        close(fd);
        return -1;
    }
}

// Function to capture a frame from a camera
int capture_frame(int camera_index, unsigned char **frame_data) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(camera_contexts[camera_index].fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(camera_contexts[camera_index].fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    } else {
        // Frame is available, read it from the buffer
        ssize_t bytes_read = read(camera_contexts[camera_index].fd, camera_contexts[camera_index].buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading frame: %s\n", strerror(errno));
            return -1;
        }

        // Increment the frame count
        frame_count++;

        // Allocate memory for the frame data
        *frame_data = (unsigned char *)malloc(bytes_read);
        if (*frame_data == NULL) {
            fprintf(stderr, "Error allocating memory for frame data\n");
            return -1;
        }

        // Copy the frame data from the buffer
        memcpy(*frame_data, camera_contexts[camera_index].buffer, bytes_read);

        return 0;
    }
}

// Function to save a frame as a PGM file
int save_frame(unsigned char *frame_data, int frame_number) {
    char filename[50];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_number);

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", 384, 384); // PGM header
    fwrite(frame_data, 1, 384 * 384, fp);

    fclose(fp);
    return 0;
}

// Function to uninitialize a camera
void uninit_camera(int camera_index) {
    if (camera_contexts[camera_index].buffer != NULL) {
        munmap(camera_contexts[camera_index].buffer, BUFFER_SIZE);
    }
    if (camera_contexts[camera_index].fd > 0) {
        close(camera_contexts[camera_index].fd);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        csi_device = argv[1];
        num_cameras = 2; // Assume two cameras for now
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Allocate memory for camera contexts
    camera_contexts = (camera_context_t *)malloc(num_cameras * sizeof(camera_context_t));
    if (camera_contexts == NULL) {
        fprintf(stderr, "Error allocating memory for camera contexts\n");
        return 1;
    }

    // Initialize cameras
    for (int i = 0; i < num_cameras; i++) {
        camera_fds[i] = -1; // Initialize to -1 to indicate not opened
        if (init_camera(i, csi_device) < 0) {
            fprintf(stderr, "Error initializing camera %d\n", i + 1);
            // Uninitialize any previously initialized cameras
            for (int j = 0; j < i; j++) {
                uninit_camera(j);
            }
            free(camera_contexts);
            return 1;
        }
    }

    // Main loop
    unsigned char *frame_data;
    while (!terminate) {
        for (int i = 0; i < num_cameras; i++) {
            if (camera_fds[i] < 0) {
                // Camera not initialized, skip
                continue;
            }

            if (capture_frame(i, &frame_data) == 0) {
                if (save_frame(frame_data, frame_count) != 0) {
                    fprintf(stderr, "Error saving frame\n");
                }
                free(frame_data);
            }
        }
    }

    // Uninitialize cameras
    for (int i = 0; i < num_cameras; i++) {
        uninit_camera(i);
    }

    // Free allocated memory
    free(camera_contexts);

    return 0;
}

