#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define BUFFER_SIZE 1024

// Structure to hold video capture parameters
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int width;
    int height;
} video_params_t;

// Global variables
volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        keep_running = 0;
    }
}

// Function to initialize video capture parameters
int init_video_capture(video_params_t *params) {
    params->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (params->fd == -1) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(params->fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = params->width = 640; // Set desired width
    fmt.fmt.pix.height = params->height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Request MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(params->fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(params->fd);
