#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <linux/videodev2.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define TARGET_IP "127.0.0.1" // Replace with your target IP
#define TARGET_PORT 12345
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define MAX_BUFFER_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // YUYV format
#define MAX_UDP_PACKET_SIZE 65000
#define NUM_BUFFERS 4

// Structure to hold camera buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables (try to minimize)
static int                    fd                    = -1;
static struct buffer           *buffers               = NULL;
static volatile unsigned int  frame_count           = 0;
static volatile int           running               = 1;

// Function prototypes
int init_camera(const char *device_name);
int configure_buffers(int fd, int num_buffers, size_t *buffer_sizes);
int capture_frame(int fd, void **buffer, size_t *buffer_size);
int fragment_frame(void *frame_data, size_t frame_size, int frame_index, int total_fragments, size_t payload_size, unsigned char **datagram);
int send_datagram(int sockfd, const unsigned char *datagram, size_t datagram_size, const char *target_ip, int target_port);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping...\n", signum);
        running = 0;
    }
}

// Initialize the camera device
int init_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device_name);
        close(fd);
        return -1;
    }

    return fd;
}

// Configure the camera buffers
int configure_buffers(int fd, int num_buffers, size_t *buffer_sizes) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    for (int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffer_sizes[i] = buf.length;
    }

    return 0;
}

// Capture a single frame
int capture_frame(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *buffer = buf.buffer;
    *buffer_size = buf.bytesused;

    return 0;
}

// Fragment the frame into UDP datagrams
int fragment_frame(void *frame_data, size_t frame_size, int frame_index, int total_fragments, size_t payload_size, unsigned char **datagram) {
    if (frame_index >= total_fragments) {
        fprintf(stderr, "Frame index out of bounds\n");
        return -1;
    }

    size_t datagram_size = sizeof(unsigned char) * 16 + payload_size; // 16 bytes for header + payload
    *datagram = (unsigned char *)malloc(datagram_size);
    if (*datagram == NULL) {
        perror("Error allocating memory for datagram");
        return -1;
    }

    // Create the header
    unsigned char header[16];
    header[0] = (unsigned char)(frame_index & 0xFF); // Frame index (low byte)
    header[1] = (unsigned char)((frame_index >> 8) & 0xFF); // Frame index (high byte)
    header[2] = (unsigned char)(frame_index & 0xFF); // Frame index (low byte)
    header[3] = (unsigned char)((frame_index >> 8) & 0xFF); // Frame index (high byte)
    header[4] = (unsigned char)(frame_index & 0xFF); // Frame index (low byte)
    header[5] = (unsigned char)((frame_index >> 8) & 0xFF); // Frame index (high byte)
    header[6] = (unsigned char)(frame_index & 0xFF); // Frame index (low byte)
    header[7] = (unsigned char)((frame_index >> 8) & 0xFF); // Frame index (high byte)
    header[8] = (unsigned char)(total_fragments & 0xFF); // Total fragments (low byte)
    header[9] = (unsigned char)((total_fragments >> 8) & 0xFF); // Total fragments (high byte)
    header[10] = (unsigned char)(payload_size & 0xFF); // Payload size (low byte)
    header[11] = (unsigned char)((payload_size >> 8) & 0xFF); // Payload size (high byte)
    header[12] = 0; // Spare byte
    header[13] = 0; // Spare byte
    header[14] = 0; // Spare byte
    header[15] = 0; // Spare byte

    memcpy(*datagram, header, 16);
    memcpy(*datagram + 16, frame_data + (frame_index * payload_size), payload_size);

    return 0;
}

// Send the datagram via UDP
int send_datagram(int sockfd, const unsigned char *datagram, size_t datagram_size, const char *target_ip, int target_port) {
    struct sockaddr_in servaddr;

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(target_port);
    if (inet_pton(AF_INET, target_ip, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(sockfd, datagram, datagram_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error sending datagram");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    int sockfd;
    unsigned char *datagram;
    size_t datagram_size;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "i:p:")) != -1) {
        switch (opt) {
            case 'i':
                TARGET_IP = optarg;
                break;
            case 'p':
                TARGET_PORT = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-i target_ip] [-p target_port]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(DEVICE_NAME) < 0) {
        return EXIT_FAILURE;
    }

    // Configure the buffers
    size_t buffer_sizes[NUM_BUFFERS];
    if (configure_buffers(fd, NUM_BUFFERS, buffer_sizes) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        buffers[i].length = buffer_sizes[i];
        buffers[i].start = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, i);
        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Create a UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        // Unmap all buffers before exiting
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        void *frame_data = NULL;
        size_t frame_size = 0;

        if (capture_frame(fd, &frame_data, &frame_size) < 0) {
            fprintf(stderr, "Error capturing frame, exiting...\n");
            break;
        }

        // Fragment the frame
        int total_fragments = (frame_size + MAX_UDP_PACKET_SIZE - 1) / MAX_UDP_PACKET_SIZE;
        for (int i = 0; i < total_fragments; i++) {
            if (fragment_frame(frame_data, frame_size, i, total_fragments, MAX_UDP_PACKET_SIZE, &datagram) < 0) {
                fprintf(stderr, "Error fragmenting frame, exiting...\n");
                break;
            }

            if (send_datagram(sockfd, datagram, datagram_size, TARGET_IP, TARGET_PORT) < 0) {
                fprintf(stderr, "Error sending datagram, exiting...\n");
                break;
            }

            free(datagram);
        }

        frame_count++;
    }

    // Clean up
    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }
    close(fd);

    return EXIT_SUCCESS;
}

