#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 192
#define HEIGHT 108
#define PIXEL_FORMAT V4L2_PIX_FMT_MJPEG
#define NUM_BUFFERS 4
#define IMAGE_FILE "image.jpg"

static int fd = -1;
static FILE *image_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

struct buffer *buffers = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    stop_flag = 1;
    fprintf(stderr, "\nCaught signal, stopping...\n");
}

// Function to initialize the video device
int init_device() {
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture or streaming\n");
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to allocate memory for the buffers
int allocate_buffers() {
    buffers = calloc(NUM_BUFFERS, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    for (int i = 0; i < NUM_BUFFERS; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to dequeue a single frame
int dequeue_frame(struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to write the raw MJPEG bytes to a file
int write_image_to_file(const void *data, size_t size) {
    if (fwrite(data, 1, size, image_file) != size) {
        perror("Error writing to file");
        return -1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        for (int i = 0; i < NUM_BUFFERS; ++i) {
            if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }

        close(fd);
    }

    if (image_file != NULL) {
        fclose(image_file);
    }

    free(buffers);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_device() < 0) {
        return EXIT_FAILURE;
    }

    if (allocate_buffers() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (start_streaming() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer for writing");
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_image_to_file(buf.bytes, buf.bytesused) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        cleanup();
        return EXIT_FAILURE;
    }

    cleanup();

    printf("Streaming stopped. Image saved to %s\n", IMAGE_FILE);

    return EXIT_SUCCESS;
}

