#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define servo position range
#define MIN_POSITION 25
#define MAX_POSITION 125

// Global variables for servo positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
void signal_handler(int signal);
void pan_left();
void pan_right();
void tilt_up();
void tilt_down();
void set_servo_position(int axis, int position);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Stop PWM signals
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO pins
    gpioSetMode(PAN_SERVO_PIN, PI_INPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_INPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    gpioTerminate();
    exit(0);
}

// Function to move the pan servo left
void pan_left() {
    int new_position = pan_position - 5;
    if (new_position < MIN_POSITION) {
        new_position = MIN_POSITION;
    }
    set_servo_position('p', new_position);
}

// Function to move the pan servo right
void pan_right() {
    int new_position = pan_position + 5;
    if (new_position > MAX_POSITION) {
        new_position = MAX_POSITION;
    }
    set_servo_position('p', new_position);
}

// Function to move the tilt servo up
void tilt_up() {
    int new_position = tilt_position - 5;
    if (new_position < MIN_POSITION) {
        new_position = MIN_POSITION;
    }
    set_servo_position('t', new_position);
}

// Function to move the tilt servo down
void tilt_down() {
    int new_position = tilt_position + 5;
    if (new_position > MAX_POSITION) {
        new_position = MAX_POSITION;
    }
    set_servo_position('t', new_position);
}

// Function to set the servo position
void set_servo_position(char axis, int position) {
    int duty_cycle;
    if (axis == 'p') {
        duty_cycle = (int)(((float)(position - MIN_POSITION) / (MAX_POSITION - MIN_POSITION)) * PWM_RANGE);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    } else if (axis == 't') {
        duty_cycle = (int)(((float)(position - MIN_POSITION) / (MAX_POSITION - MIN_POSITION)) * PWM_RANGE);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    } else {
        fprintf(stderr, "Error: Invalid axis specified.\n");
        return;
    }

    gpioPWM(PAN_SERVO_PIN, duty_cycle);
    gpioPWM(TILT_SERVO_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Initialize servo positions
    set_servo_position('p', pan_position);
    set_servo_position('t', tilt_position);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
