#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <jpeglib.h>
#include <math.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

// Structure to hold camera parameters
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    struct v4l2_buffer buf;
} camera_params_t;

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Function to initialize a camera
int init_camera(camera_params_t *params) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    // Open the camera
    params->fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (params->fd < 0) {
        fprintf(stderr, "Error opening /dev/video0: %s\n", strerror(errno));
        return -1;
    }

    // Check capabilities
    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming I/O\n");
        close(params->fd);
        return -1;
    }

    // Set the video format
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // YUYV format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(params->fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    // Request buffers
    CLEAR(req);
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    // Allocate memory for the buffer
    params->buffer_size = req.length;
    params->buffer = mmap(NULL, req.length, PROT_READ | PROT_WRITE, MAP_SHARED, params->fd, 0);
    if (params->buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    // Queue the buffer
    params->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    params->buf.memory = V4L2_MEMORY_MMAP;
    params->buf.index = 0;

    if (ioctl(params->fd, VIDIOC_QBUF, &params->buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(params->buffer, params->buffer_size);
        close(params->fd);
        return -1;
    }

    return 0;
}

// Function to dequeue a frame
int dequeue_frame(camera_params_t *params) {
    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return buf.bytesused;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    unsigned char y, u, v;
    unsigned char r, g, b;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            // YUYV format: Y0 U Y1 V
            y = yuyv[0];
            u = yuyv[1];
            v = yuyv[3];

            // RGB conversion formulas (simplified)
            r = y + 1.370705 * (v - 128);
            g = y - 0.698001 * (u - 128) - 0.336332 * (v - 128);
            b = y + 1.732446 * (u - 128);

            // Clamp to 0-255 range
            if (r < 0) r = 0;
            if (r > 255) r = 255;
            if (g < 0) g = 0;
            if (g > 255) g = 255;
            if (b < 0) b = 0;
            if (b > 255) b = 255;

            // Store RGB values
            rgb[0] = r;
            rgb[1] = g;
            rgb[2] = b;

            // Move to the next YUYV pair
            yuyv += 2;
            rgb += 3;
        }
    }
}

// Function to apply a blur filter
void blur_image(unsigned char *rgb, int width, int height, int kernel_size) {
    int i, j;
    double sum[3];
    unsigned char *temp_rgb = (unsigned char *)malloc(width * height * 3);
    if (temp_rgb == NULL) {
        fprintf(stderr, "Error allocating memory for blur buffer\n");
        return;
    }

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            sum[0] = 0;
            sum[1] = 0;
            sum[2] = 0;

            for (int k = -kernel_size; k <= kernel_size; k++) {
                for (int l = -kernel_size; l <= kernel_size; l++) {
                    int x = j + k;
                    int y = i + l;

                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        sum[0] += rgb[y * width * 3 + x * 3 + 0];
                        sum[1] += rgb[y * width * 3 + x * 3 + 1];
                        sum[2] += rgb[y * width * 3 + x * 3 + 2];
                    }
                }
            }

            temp_rgb[i * width * 3 + j * 3 + 0] = (unsigned char)sum[0] / ((kernel_size * 2 + 1) * (kernel_size * 2 + 1));
            temp_rgb[i * width * 3 + j * 3 + 1] = (unsigned char)sum[1] / ((kernel_size * 2 + 1) * (kernel_size * 2 + 1));
            temp_rgb[i * width * 3 + j * 3 + 2] = (unsigned char)sum[2] / ((kernel_size * 2 + 1) * (kernel_size * 2 + 1));
        }
    }

    memcpy(rgb, temp_rgb, width * height * 3);
    free(temp_rgb);
}

// Function to encode an RGB image as JPEG
int encode_jpeg(unsigned char *rgb, int width, int height, int quality, unsigned char **jpeg_data, unsigned long *jpeg_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((row_stride = width * 3) != 1) {
        fprintf(stderr, "jpeg_stdio_dest can only handle 1-pixel-row-stride data\n");
        return -1;
    }

    jpeg_stdio_dest(&cinfo, &outfile, &cinfo.err);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);

    *jpeg_size = cinfo.outbuf_size;
    *jpeg_data = cinfo.outbuf;

    return 0;
}

// Function to save the JPEG image to a file
int save_jpeg(unsigned char *jpeg_data, unsigned long jpeg_size, const char *filename) {
    FILE *outfile = fopen(filename, "wb");
    if (outfile == NULL) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fwrite(jpeg_data, 1, jpeg_size, outfile) != jpeg_size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(outfile);
        return -1;
    }

    fclose(outfile);
    return 0;
}

int main() {
    camera_params_t camera1, camera2;
    unsigned char *jpeg_data1, *jpeg_data2;
    unsigned long jpeg_size1, jpeg_size2;
    time_t rawtime;
    struct tm *timeinfo;
    char filename1[80], filename2[80];
    int frame_size1, frame_size2;
    int i;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize cameras
    if (init_camera(&camera1) < 0) {
        fprintf(stderr, "Error initializing camera 1\n");
        return 1;
    }
    if (init_camera(&camera2) < 0) {
        fprintf(stderr, "Error initializing camera 2\n");
        close(camera1.fd);
        munmap(camera1.buffer, camera1.buffer_size);
        return 1;
    }

    // Get current timestamp for filename
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename1, sizeof(filename1), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);
    strftime(filename2, sizeof(filename2), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    // Main loop
    while (keep_running) {
        // Dequeue frame from camera 1
        frame_size1 = dequeue_frame(&camera1);
        if (frame_size1 < 0) {
            fprintf(stderr, "Error dequeueing frame from camera 1\n");
            break;
        }

        // Dequeue frame from camera 2
        frame_size2 = dequeue_frame(&camera2);
        if (frame_size2 < 0) {
            fprintf(stderr, "Error dequeueing frame from camera 2\n");
            break;
        }

        // Convert YUYV to RGB24
        unsigned char *rgb1 = (unsigned char *)malloc(frame_size1);
        unsigned char *rgb2 = (unsigned char *)malloc(frame_size2);
        if (!rgb1 || !rgb2) {
            fprintf(stderr, "Error allocating memory for RGB buffers\n");
            break;
        }

        yuyv_to_rgb24(camera1.buffer, rgb1, 640, 480);
        yuyv_to_rgb24(camera2.buffer, rgb2, 640, 480);

        // Apply blur filter
        blur_image(rgb1, 640, 480, 3);
        blur_image(rgb2, 640, 480, 3);

        // Encode as JPEG
        if (encode_jpeg(rgb1, 640, 480, 75, &jpeg_data1, &jpeg_size1) < 0) {
            fprintf(stderr, "Error encoding JPEG for camera 1\n");
            break;
        }
        if (encode_jpeg(rgb2, 640, 480, 75, &jpeg_data2, &jpeg_size2) < 0) {
            fprintf(stderr, "Error encoding JPEG for camera 2\n");
            break;
        }

        // Save JPEG images
        if (save_jpeg(jpeg_data1, jpeg_size1, filename1) < 0) {
            fprintf(stderr, "Error saving JPEG for camera 1\n");
            break;
        }
        if (save_jpeg(jpeg_data2, jpeg_size2, filename2) < 0) {
            fprintf(stderr, "Error saving JPEG for camera 2\n");
            break;
        }

        free(rgb1);
        free(rgb2);

        // Queue buffers back to the camera
        camera1.buf.index = 0;
        if (ioctl(camera1.fd, VIDIOC_QBUF, &camera1.buf) < 0) {
            fprintf(stderr, "Error queuing buffer for camera 1: %s\n", strerror(errno));
            break;
        }

        camera2.buf.index = 0;
        if (ioctl(camera2.fd, VIDIOC_QBUF, &camera2.buf) < 0) {
            fprintf(stderr, "Error queuing buffer for camera 2: %s\n", strerror(errno));
            break;
        }

        // Wait for a short period
        usleep(100000); // 100ms
    }

    // Clean up
    close(camera1.fd);
    munmap(camera1.buffer, camera1.buffer_size);
    close(camera2.fd);
    munmap(camera2.buffer, camera2.buffer_size);

    return 0;
}

