#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <string.h>

#define DEVICE_NAME "/dev/video0"

// Structure to hold frame size and interval information
typedef struct {
    struct v4l2_frmsize_enum size;
    struct v4l2_frmiinterval_enum interval;
} frame_info_t;

// Function to check if a file exists
int file_exists(const char *filename) {
    return (access(filename, F_OK) == 0);
}

// Function to open the device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_device_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying device capabilities: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, frame_info_t *frame_infos, int max_infos) {
    struct v4l2_frmsize_enum enum_size;
    enum_size.index = 0;
    enum_size.pixel_format = V4L2_PIX_FMT_YUYV; // Example pixel format
    enum_size.type = V4L2_FRM_TYPE_VIDEO;

    int count;
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &enum_size) < 0) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        return -1;
    }
    count = enum_size.count;

    if (count > max_infos) {
        fprintf(stderr, "Warning: More frame sizes than expected.  Limiting to %d.\n", max_infos);
        count = max_infos;
    }

    for (int i = 0; i < count; i++) {
        if (ioctl(fd, VIDIOC_QUERY_DVR, &enum_size) < 0) {
            fprintf(stderr, "Error querying frame size %d: %s\n", i, strerror(errno));
            return -1;
        }
        frame_infos[i].size = enum_size;
    }
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, int size_index, frame_info_t *frame_infos, int max_infos) {
    struct v4l2_frmiinterval_enum enum_interval;
    enum_interval.pixel_format = V4L2_PIX_FMT_YUYV; // Example pixel format
    enum_interval.type = V4L2_FRM_TYPE_VIDEO;
    enum_interval.index = 0;

    int count;
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &enum_interval) < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        return -1;
    }

    if (count > max_infos) {
        fprintf(stderr, "Warning: More frame intervals than expected.  Limiting to %d.\n", max_infos);
        count = max_infos;
    }

    for (int i = 0; i < count; i++) {
        if (ioctl(fd, VIDIOC_QUERY_DVR, &enum_interval) < 0) {
            fprintf(stderr, "Error querying frame interval %d: %s\n", i, strerror(errno));
            return -1;
        }
        frame_infos[i].interval = enum_interval;
    }
    return 0;
}

// Function to query a control
int query_control(int fd, enum v4l2_buf_type type, unsigned int control_id) {
    struct v4l2_control control;
    memset(&control, 0, sizeof(control));
    control.id = control_id;
    control.value = 0;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &control) < 0) {
        fprintf(stderr, "Error querying control 0x%08X: %s\n", control_id, strerror(errno));
        return -1;
    }

    if (control.value != 0) {
        return 0; // Control exists and has a non-zero value
    } else {
        return -1; // Control exists but has a zero value
    }
}

// Function to print device information
void print_device_info(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying device capabilities: %s\n", strerror(errno));
        return;
    }

    printf("Device: %s\n", cap.device);
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);
}

// Function to print frame size and interval information
void print_frame_info(frame_info_t *frame_infos, int num_infos) {
    printf("\nSupported Frame Sizes and Intervals:\n");
    for (int i = 0; i < num_infos; i++) {
        printf("  Frame Size: %dx%d\n", frame_infos[i].size.discrete.width, frame_infos[i].size.discrete.height);
        printf("  Frame Interval: %d\n", frame_infos[i].interval.discrete.numerator);
        printf("  Frame Interval: %d\n", frame_infos[i].interval.discrete.denominator);
        printf("  Frame Rate: %f\n", (float)frame_infos[i].interval.discrete.numerator / (float)frame_infos[i].interval.discrete.denominator);
        printf("\n");
    }
}

// Function to print focus auto capability
void print_focus_info(int fd) {
    int focus_auto_supported = query_control(fd, V4L2_BUF_TYPE_VIDEO_CAPTURE, V4L2_CID_FOCUS_AUTO);
    if (focus_auto_supported == 0) {
        printf("Focus Auto is supported.\n");
    } else {
        printf("Focus Auto is not supported.\n");
    }
}

int main() {
    int fd;
    frame_info_t frame_infos[10]; // Assuming a maximum of 10 frame sizes and intervals
    int num_frame_infos = 0;

    // Check if the device file exists
    if (!file_exists(DEVICE_NAME)) {
        fprintf(stderr, "Error: Device file %s does not exist.\n", DEVICE_NAME);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Query device capabilities
    if (query_device_capabilities(fd) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame sizes
    if (enumerate_frame_sizes(fd, frame_infos, 10) < 0) {
        close(fd);
        return 1;
    }
    num_frame_infos = (num_frame_infos > (sizeof(frame_infos) / sizeof(frame_infos[0]))) ? (sizeof(frame_infos) / sizeof(frame_infos[0])) : num_frame_infos;

    // Enumerate frame intervals for each size
    for (int i = 0; i < num_frame_infos; i++) {
        if (enumerate_frame_intervals(fd, i, frame_infos, 10) < 0) {
            close(fd);
            return 1;
        }
    }

    // Print device information
    print_device_info(fd);

    // Print frame size and interval information
    print_frame_info(frame_infos, num_frame_infos);

    // Print focus auto capability
    print_focus_info(fd);

    // Close the device
    close(fd);

    return 0;
}

