#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width range
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define PWM frequency
#define PWM_FREQUENCY 50

// Global variables for servo pulse widths
int pan_pulse_width = 1500;
int tilt_pulse_width = 1500;

// Function prototypes
void signal_handler(int signal);
void button_up_callback(int gpio, int level, uint32_t tick);
void button_down_callback(int gpio, int level, uint32_t tick);
void button_left_callback(int gpio, int level, uint32_t tick);
void button_right_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop PWM on both servo pins
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release pigpio resources
    gpioTerminate();

    exit(0);
}

// Button UP callback function
void button_up_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed
        pan_pulse_width += 10;
        if (pan_pulse_width < MIN_PULSE_WIDTH) {
            pan_pulse_width = MIN_PULSE_WIDTH;
        } else if (pan_pulse_width > MAX_PULSE_WIDTH) {
            pan_pulse_width = MAX_PULSE_WIDTH;
        }
        printf("Pan UP button pressed, new pulse width: %d\n", pan_pulse_width);
    }
}

// Button DOWN callback function
void button_down_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed
        pan_pulse_width -= 10;
        if (pan_pulse_width < MIN_PULSE_WIDTH) {
            pan_pulse_width = MIN_PULSE_WIDTH;
        } else if (pan_pulse_width > MAX_PULSE_WIDTH) {
            pan_pulse_width = MAX_PULSE_WIDTH;
        }
        printf("Pan DOWN button pressed, new pulse width: %d\n", pan_pulse_width);
    }
}

// Button LEFT callback function
void button_left_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed
        tilt_pulse_width -= 10;
        if (tilt_pulse_width < MIN_PULSE_WIDTH) {
            tilt_pulse_width = MIN_PULSE_WIDTH;
        } else if (tilt_pulse_width > MAX_PULSE_WIDTH) {
            tilt_pulse_width = MAX_PULSE_WIDTH;
        }
        printf("Tilt LEFT button pressed, new pulse width: %d\n", tilt_pulse_width);
    }
}

