#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <wiringPi.h>
#include <curl/curl.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 2000
#define POLL_INTERVAL_MS 100
#define IMAGE_QUALITY 85
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JSON_BUFFER_SIZE 256
#define SERVER_URL_MAX_LENGTH 256

// Global variables
static volatile int running = 1;
static char *server_url = NULL;
static int socket_fd = -1;
static CURL *curl = NULL;
static char json_buffer[JSON_BUFFER_SIZE];

// Function prototypes
int initialize_gpio();
int read_sensor();
int capture_image(char *filename);
int post_image(char *filename);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Read sensor value
int read_sensor() {
    return digitalRead(GPIO_PIN);
}

// Capture image using raspistill
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -w %d -h %d -q %d -o %s", IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY, filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Post image to server using libcurl
int post_image(char *filename) {
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, filename);

    // Set Content-Type header
    headers = curl_slist_append(headers, "Content-Type: image/jpeg");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        return -1;
    }

    curl_slist_free_all(headers);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (curl) {
        curl_easy_cleanup(curl);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    wiringPiSetupGpio(); // Reinitialize to avoid issues
    pinMode(GPIO_PIN, INPUT); // Set back to input
    pullUpDnControl(GPIO_PIN, PUD_DOWN);
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_url = argv[1];
    int server_port = atoi(argv[2]);

    if (initialize_gpio() == -1) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create motion_captures directory if it doesn't exist
    char command[128];
    snprintf(command, sizeof(command), "mkdir -p motion_captures");
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error creating directory: %s\n", strerror(errno));
    }

    time_t last_motion_time = 0;
    int motion_detected = 0;

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == HIGH && !motion_detected) {
            // Debounce
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) * 1000 >= DEBOUNCE_TIME_MS) {
                motion_detected = 1;
                last_motion_time = current_time;

                // Generate filename
                time_t rawtime;
                struct tm *timeinfo;
                char filename[128];
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(filename, sizeof(filename), "motion_capture_%Y%m%d_%H%M%S.jpg", timeinfo);
                char filepath[256];
                snprintf(filepath, sizeof(filepath), "motion_captures/%s", filename);

                // Capture image
                if (capture_image(filepath) == 0) {
                    printf("Captured image: %s\n", filepath);

                    // Post image
                    if (post_image(filepath) == 0) {
                        printf("Image posted successfully.\n");
                    } else {
                        fprintf(stderr, "Failed to post image.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image.\n");
                }
            }
        } else if (sensor_value == LOW) {
            motion_detected = 0;
        }

        delay(POLL_INTERVAL_MS);
    }

    cleanup();
    return 0;
}

