#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(25 * sizeof(char)); // Allocate memory for the filename

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 25, "%Y%m%d_%H%M%S", timeinfo);
    char extension[5] = ".jpg";
    strcat(filename, extension);
    return filename;
}

// Function to capture an image using raspistill
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s", filename);
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(log_file, "%s: raspistill command failed with exit status %d\n", __func__, WEXITSTATUS(status));
        fflush(log_file);
        return -1;
    }
    return 0;
}

// Function to log messages to a file
void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected
        char *filename = generate_filename();
        if (filename == NULL) {
            log_message("Failed to generate filename");
            return;
        }

        if (capture_image(filename) == 0) {
            char log_message_buffer[128];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Captured image: %s", filename);
            log_message(log_message_buffer);
        } else {
            log_message("Failed to capture image");
        }

        free(filename);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up edge detection (falling edge)
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);

    return 0;
}

