} camera_config_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping streaming...\n");
    keep_running = 0;
}

// Function to initialize the camera
int init_camera(int *fd_ptr, camera_config_t *config) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the device
    *fd_ptr = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd_ptr < 0) {
        perror("Error opening device");
        return -1;
    }

    // Query capabilities
    if (ioctl(*fd_ptr, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(*fd_ptr);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd_ptr);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(*fd_ptr);
        return -1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = config->pixel_format;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(*fd_ptr, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(*fd_ptr);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd_ptr, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(*fd_ptr);
        return -1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(*fd_ptr, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(*fd_ptr);
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd_ptr, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(*fd_ptr);
        return -1;
    }

