    if (ioctl(*fd_ptr, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(*fd_ptr);
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(*fd_ptr, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(*fd_ptr);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, void *buffer, int buffer_size, camera_config_t config) {
    struct v4l2_buffer buf;
    struct timeval tv;
    fd_set fds;
    int r;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    // Wait for frame to be ready
    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = SELECT_TIMEOUT;
        tv.tv_usec = 0;
        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            perror("Error during select");
            return -1;
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            return -1;
        }
    } while (ioctl(fd, VIDIOC_DQBUF, &buf) < 0 && errno == EINTR);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to crop and save the frame
int crop_and_save(void *frame_buffer, int buffer_size, int width, int height, int crop_x, int crop_y, int crop_width, int crop_height) {
    unsigned char *yuyv_data = (unsigned char *)frame_buffer;
    unsigned char *output_data = NULL;
    int output_size = crop_width * crop_height * 2;
    int i, j, k;

    // Calculate output buffer size
    output_size = crop_width * crop_height * 2;
    output_data = (unsigned char *)malloc(output_size);
    if (output_data == NULL) {
        perror("Error allocating output buffer");
        return -1;
    }

    // Copy YUYV data to output buffer
    for (i = crop_y; i < crop_y + crop_height; i++) {
        for (j = crop_x; j < crop_x + crop_width; j++) {
            // YUYV format: Y0, U, Y1, V
            int y0 = yuyv_data[i * width * 2 + j * 2 + 0];
            int u = yuyv_data[i * width * 2 + j * 2 + 1];
            int y1 = yuyv_data[i * width * 2 + j * 2 + 2];
            int v = yuyv_data[i * width * 2 + j * 2 + 3];

            // Copy YUYV to output buffer
            output_data[i * crop_width * 2 + j * 2 + 0] = y0;
            output_data[i * crop_width * 2 + j * 2 + 1] = u;
            output_data[i * crop_width * 2 + j * 2 + 2] = y1;
            output_data[i * crop_width * 2 + j * 2 + 3] = v;
        }
    }

    // Save the cropped frame to file
    output_file = fopen("cropped.yuv", "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        free(output_data);
        return -1;
    }

    size_t bytes_written = fwrite(output_data, 1, output_size, output_file);
    if (bytes_written != output_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %d\n", bytes_written, output_size);
        fclose(output_file);
        free(output_data);
        return -1;
    }

    fclose(output_file);
    free(output_data);

    return 0;
}

// Function to verify the captured frame
int verify_frame(void *frame_buffer, int buffer_size, int width, int height, enum v4l2_pix_format pixel_format) {
    camera_config_t config = {width, height, pixel_format};
    if (init_camera(&fd, &config) != 0) {
