        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeueing buffer for verification");
        return -1;
    }

    if (ioctl(fd, VIDIOC_S_FMT, &config) != 0) {
        perror("Error setting format for verification");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer for verification");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    // Verify width and height
    if (buf.length != width * height * 2) {
        fprintf(stderr, "Incorrect buffer length: expected %d, got %d\n", width * height * 2, buf.length);
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    // Verify pixel format
    if (buf.fmt.pix.pixelformat != pixel_format) {
        fprintf(stderr, "Incorrect pixel format: expected %d, got %d\n", pixel_format, buf.fmt.pix.pixelformat);
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    munmap(buffer, buf.length);
    close(fd);
    return 0;
}

