#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000

// Define angle limits for servos
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define delay between commands in milliseconds
#define DELAY_MS 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the angle of a servo motor
int set_servo_angle(int gpio, int angle) {
    // Validate angle
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d is out of range (0-%d to %d-%d).\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate failure
    }

    // Calculate pulse width (SG90 servo: 1000us for 0 degrees, 2000us for 180 degrees)
    int pulse_width = 1000 + (angle * 1000 / 180);

    // Set PWM duty cycle
    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d.\n", gpio);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Exit with error code
    }

    // Set GPIO modes for pan and tilt servos as outputs
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Set initial servo positions to neutral (90 degrees)
    if (set_servo_angle(PAN_GPIO, 90) != 0) {
