        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_GPIO, 90) != 0) {
        fprintf(stderr, "Error: Failed to set initial tilt servo angle.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read input and control servos
    int pan_angle = 90;
    int tilt_angle = 90;
    char input;

    printf("Enter commands (pan/t, pan-, pan+, tilt/y, tilt-, tilt+, q): ");
    while (program_running) {
        // Read input from stdin
        input = getchar();

        // Handle input and update servo angles
        switch (input) {
            case 'p':
                pan_angle++;
                if (pan_angle > MAX_ANGLE) pan_angle = MAX_ANGLE;
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan servo angle.\n");
