// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    temp = atoi(buffer);
    return temp;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[256];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat file: %s\n", strerror(errno));
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat file: %s\n", strerror(errno));
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat data\n");
        return -1.0;
    }

    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;

    sleep(1);

    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat data\n");
        return -1.0;
    }

    unsigned long long prev_user_again = user;
    unsigned long long prev_nice_again = nice;
    unsigned long long prev_system_again = system;
    unsigned long long prev_idle_again = idle;
    unsigned long long prev_iowait_again = iowait;
    unsigned long long prev_irq_again = irq;
    unsigned long long prev_softirq_again = softirq;
    unsigned long long prev_steal_again = steal;
    unsigned long long prev_guest_again = guest;
    unsigned long long prev_guest_nice_again = guest_nice;

    unsigned long long user_diff = user - prev_user_again;
    unsigned long long nice_diff = nice - prev_nice_again;
    unsigned long long system_diff = system - prev_system_again;
    unsigned long long idle_diff = idle - prev_idle_again;
    unsigned long long iowait_diff = iowait - prev_iowait_again;
    unsigned long long irq_diff = irq - prev_irq_again;
    unsigned long long softirq_diff = softirq - prev_softirq_again;
    unsigned long long steal_diff = steal - prev_steal_again;
    unsigned long long guest_diff = guest - prev_guest_again;
    unsigned long long guest_nice_diff = guest_nice - prev_guest_nice_again;

    unsigned long long total_diff = user_diff + nice_diff + system_diff + idle_diff + iowait_diff + irq_diff + softirq_diff + steal_diff + guest_diff + guest_nice_diff;
    unsigned long long idle_prev = prev_idle;
    unsigned long long idle_current = idle;

    usage = (float)(total_diff - (idle_current - idle_prev)) / total_diff * 100.0;

    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    oled_fd = wiringPiI2CSetup(OLED_ADDR);
    if (oled_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        error_exit("OLED initialization failed");
    }

    // Initialization sequence (SSD1306 datasheet)
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xAE); // Display off
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xD5); // Set display clock divide ratio/oscillator frequency
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x80); // --ratio
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xA8); // Set multiplex ratio
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x3F); // --height-1
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xD3); // Set display offset
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x00); // --offset
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x40); // Set start line address
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x8D); // Charge pump setting
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x14); // --enable
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x20); // Set memory addressing mode
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x00); // --horizontal addressing mode
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xA1); // Set segment re-map
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xC8); // Set COM output scan direction
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xDA); // Set COM pins hardware configuration
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x12); // --alternative
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x81); // Set contrast control
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xCF); // --contrast
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xD9); // Set pre-charge period
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xF1); // --period
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xDB); // Set VCOM deselect level
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0x40); // --level
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xA4); // Display all points off
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xA6); // Set normal display
    wiringPiI2CWriteReg8(oled_fd, 0x00, 0xAF); // Display on
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        wiringPiI2CWriteReg8(oled_fd, 0x40, 0x00); // Write 0 to all pixels
    }
}

// Function to draw a character at a specific position
void oled_draw_char(int x, int y, char c) {
    if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
    c -= 32; // Adjust index to font array

    for (int i = 0; i < 5; i++) {
        unsigned char byte = font[c][i];
        for (int j = 0; j < 8; j++) {
            if ((byte >> j) & 0x01) {
                // Set pixel
                wiringPiI2CWriteReg8(oled_fd, 0x40, 0x10); // Set pixel data
                wiringPiI2CWriteReg8(oled_fd, 0x40, 0x01); // Set column address
                wiringPiI2CWriteReg8(oled_fd, 0x40, (x + i) & 0x0F); // Set page address
                wiringPiI2CWriteReg8(oled_fd, 0x40, (y / 8) | ((x + i) >> 3)); // Set lower column address
            } else {
                // Clear pixel
                wiringPiI2CWriteReg8(oled_fd, 0x40, 0x00); // Set pixel data
                wiringPiI2CWriteReg8(oled_fd, 0x40, 0x01); // Set column address
                wiringPiI2CWriteReg8(oled_fd, 0x40, (x + i) & 0x0F); // Set page address
                wiringPiI2CWriteReg8(oled_fd, 0x40, (y / 8) | ((x + i) >> 3)); // Set lower column address
            }
        }
    }
}

// Function to draw a string at a specific position
void oled_draw_string(int x, int y, const char *str) {
    while (*str) {
        oled_draw_char(x, y, *str);
        x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

// Function to display data on the OLED
