#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define DHT22_PIN 4
#define LCD_ADDR 0x27 // I2C address of the LCD

// Define LCD constants
#define LCD_CHR 1 // Mode - Sending data
#define LCD_CMD 0 // Mode - Sending command

#define LCD_BACKLIGHT 0x08  // On
#define ENABLE 0b00000100 // Enable bit

// Global variables
volatile int pulse_count = 0;
volatile unsigned long last_tick = 0;
float total_volume = 0.0;
float temperature = 0.0;
int lcd_handle;

// Function prototypes
void flow_sensor_callback(int gpio, int level, unsigned int tick, void *user);
float calculate_flow_rate(int pulse_count);
float calculate_volume(float flow_rate, float temperature, float time_elapsed);
void lcd_init();
void lcd_send_command(int cmd);
void lcd_send_data(int data);
void lcd_clear();
void lcd_print(int row, int col, char *str);
void signal_handler(int signal);

// Function to initialize the LCD
void lcd_init() {
    // Initialise display
    lcd_send_command(0x33); // Initialise
    lcd_send_command(0x32); // Initialise
    lcd_send_command(0x06); // Cursor move direction
    lcd_send_command(0x0C); // 0x0F = Display on, 0x0C = Display off
    lcd_send_command(0x28); // Data length, number of lines, font size
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);
}

// Function to send a command to the LCD
void lcd_send_command(int cmd) {
    char data_u, data_l;
    unsigned char data_t[4];

    data_u = (cmd & 0xF0);
    data_l = ((cmd << 4) & 0xF0);

    data_t[0] = data_u | LCD_BACKLIGHT;
    data_t[1] = data_u | LCD_BACKLIGHT | ENABLE;
    data_t[2] = data_u | LCD_BACKLIGHT | ENABLE | LCD_CMD;
    data_t[3] = data_l | LCD_BACKLIGHT | ENABLE | LCD_CMD;

    for (int i = 0; i < 4; i++) {
        gpioWrite(8, 0);
        for (int j = 0; j < 8; j++) {
            gpioWrite(7, (data_t[i] >> (7 - j)) & 0x01);
            gpioDelay(1);
        }
        gpioWrite(7, 1);
        gpioDelay(1);
    }
}

// Function to send data to the LCD
void lcd_send_data(int data) {
    char data_u, data_l;
    unsigned char data_t[4];

    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_t[0] = data_u | LCD_BACKLIGHT;
    data_t[1] = data_u | LCD_BACKLIGHT | ENABLE;
    data_t[2] = data_u | LCD_BACKLIGHT | ENABLE | LCD_CHR;
    data_t[3] = data_l | LCD_BACKLIGHT | ENABLE | LCD_CHR;

    for (int i = 0; i < 4; i++) {
        gpioWrite(8, 0);
        for (int j = 0; j < 8; j++) {
            gpioWrite(7, (data_t[i] >> (7 - j)) & 0x01);
            gpioDelay(1);
        }
        gpioWrite(7, 1);
        gpioDelay(1);
    }
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_send_command(0x01);
    gpioDelay(2000);
}

// Function to print a string to the LCD at a specific row and column
void lcd_print(int row, int col, char *str) {
    lcd_send_command(0x80 + row); // Set row
    lcd_send_command(0x00 + (col & 0x0F)); // Set column
    lcd_send_command(0x00 + ((col >> 4) & 0x0F)); // Set column
    lcd_send_data(0); //Blank space
    for (int i = 0; str[i] != 0; i++) {
        lcd_send_data(str[i]);
    }
}

// Callback function for the flow sensor
void flow_sensor_callback(int gpio, int level, unsigned int tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate the flow rate in liters per minute
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / 7.5; // 7.5 pulses per liter
}

