#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Configuration
#define ANEMOMETER_PIN 17
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LCD_ADDR 0x27 // PCF8574 I2C address
#define SAMPLE_WINDOW_MS 500
#define SAMPLE_INTERVAL_MS 500
#define PULSES_PER_REVOLUTION 1.0 // Adjust based on your anemometer
#define WIND_SPEED_THRESHOLD 0.5 // m/s
#define WIND_DIRECTION_THRESHOLD 0.1 // Radians
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
int spi_fd;
int i2c_fd;
int lcd_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void anemometer_interrupt(void);
int read_wind_direction(void);
float calculate_wind_speed(int pulses);
void lcd_init(void);
void lcd_clear(void);
void lcd_write_string(int row, int col, const char *str);
void lcd_send_command(unsigned char cmd);
void lcd_send_data(unsigned char data);
void lcd_print(int row, int col, float wind_speed, float wind_direction);
void signal_handler(int signal);
int spi_transfer(unsigned char data);
int i2c_read_adc(int channel);

// Anemometer interrupt handler
void anemometer_interrupt(void) {
    pulse_count++;
}

// Function to read wind direction from MCP3008
int read_wind_direction(void) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // MCP3008 configuration: Start bit, single-ended mode, channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | 0x00) << 4; // Single-ended, channel 0
    tx_buf[2] = 0x00;

    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("SPI write failed");
        return -1;
    }

    if (read(spi_fd, rx_buf, 3) != 3) {
        perror("SPI read failed");
        return -1;
    }

    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate wind speed
float calculate_wind_speed(int pulses) {
    float revolutions = (float)pulses / PULSES_PER_REVOLUTION;
    float wind_speed = (revolutions / SAMPLE_WINDOW_MS) * 60.0 * 1000.0 / 1000.0; // m/s
    return wind_speed;
}

// LCD initialization function
void lcd_init(void) {
    lcd_fd = wiringPiI2CSetup(LCD_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error initializing I2C LCD: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialization sequence (PCF8574 backpack)
    usleep(50000); // Wait for more than 40ms after VCC rises to 2.7V
    lcd_send_command(0x33); // Initialize
    usleep(5000);      // Wait for more than 4.1ms
    lcd_send_command(0x33); // Initialize
    usleep(15000);     // Wait for more than 10ms
    lcd_send_command(0x33); // Initialize
    usleep(1000);      // Wait for more than 100us
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    lcd_send_command(0x06); // Increment cursor, no shift
    lcd_clear();
}

// Function to clear the LCD
void lcd_clear(void) {
    lcd_send_command(0x01); // Clear display
    usleep(2000);           // Wait for more than 1.53ms
}

// Function to write a string to the LCD
void lcd_write_string(int row, int col, const char *str) {
    int i;
    unsigned char data;

    // Set cursor position
    unsigned char addr = (row == 0) ? 0x80 : 0xC0;
    addr += col;
    lcd_send_command(addr);

    // Send data
    for (i = 0; str[i] != 0; i++) {
        data = str[i];
        lcd_send_data(data);
    }
}

// Function to send a command to the LCD
void lcd_send_command(unsigned char cmd) {
    unsigned char data_u, data_l;

    data_u = (cmd & 0xF0) | 0x04; // Enable bit
    data_l = (cmd & 0x0F) | 0x04; // Enable bit

    wiringPiI2CWriteReg8(lcd_fd, data_u, data_l);
}

// Function to send data to the LCD
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;

    data_u = (data & 0xF0) | 0x04; // Enable bit
    data_l = (data & 0x0F) | 0x04; // Enable bit

    wiringPiI2CWriteReg8(lcd_fd, data_u, data_l);
}

// Function to print wind speed and direction to the LCD
void lcd_print(int row, int col, float wind_speed, float wind_direction) {
    char buffer[32];

    lcd_clear();
    lcd_write_string(row, col, "Wind Speed:");
    snprintf(buffer, sizeof(buffer), "%.2f m/s", wind_speed);
    lcd_write_string(row + 1, col, buffer);

    lcd_write_string(row, col + 16, "Wind Dir:");
    snprintf(buffer, sizeof(buffer), "%.2f rad", wind_direction);
    lcd_write_string(row + 1, col + 16, buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// SPI transfer function
int spi_transfer(unsigned char data) {
    unsigned char tx_buf[1] = {data};
    unsigned char rx_buf[1] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 1,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return rx_buf[0];
}

// I2C read ADC function
int i2c_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // MCP3008 configuration: Start bit, single-ended mode, channel
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel
    tx_buf[2] = 0x00;

    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("SPI write failed");
        return -1;
    }

    if (read(spi_fd, rx_buf, 3) != 3) {
        perror("SPI read failed");
        return -1;
    }

    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

int main(void) {
    int wind_direction;
    float wind_speed;
    struct timeval start, end;
    long elapsed_time;
    int prev_adc_value = 0;
    int prev_pulse_count = 0;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize LCD
    lcd_init();

    // Set up interrupt on anemometer pin
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, &anemometer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Wind sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        gettimeofday(&start, NULL);

        // Sample window
        pulse_count = 0;
        gettimeofday(&end, NULL);
        elapsed_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        if (elapsed_time > SAMPLE_WINDOW_MS) {
            elapsed_time = SAMPLE_WINDOW_MS;
        }

        // Calculate wind speed
        wind_speed = calculate_wind_speed(pulse_count);

        // Read wind direction
        wind_direction = read_wind_direction();

        // Check for sensor-absent conditions
        if (wind_direction == -1) {
            fprintf(stderr, "Error reading wind direction.\n");
        } else if (wind_direction == 0 || wind_direction == 1023) {
            fprintf(stderr, "Wind vane reading stuck at 0 or 1023.\n");
        }

        // Check wind speed threshold
        if (wind_speed > WIND_SPEED_THRESHOLD) {
            fprintf(stderr, "Wind speed exceeds threshold (%.2f m/s > %.2f m/s).\n", wind_speed, WIND_SPEED_THRESHOLD);
        }

        // Check wind direction change
        if (wind_direction != 0) {
            float prev_direction = atan2(sin(prev_pulse_count * 2 * M_PI / 360.0), cos(prev_pulse_count * 2 * M_PI / 360.0));
            float current_direction = atan2(sin(wind_direction * 2 * M_PI / 360.0), cos(wind_direction * 2 * M_PI / 360.0));
            float delta_direction = fabs(current_direction - prev_direction);
            if (delta_direction > WIND_DIRECTION_THRESHOLD) {
                fprintf(stderr, "Significant change in wind direction detected (%.2f rad).\n", delta_direction);
            }
        }

        // Update LCD
        lcd_print(0, 0, wind_speed, wind_direction);

        // Prepare for next sample
        prev_pulse_count = pulse_count;
        prev_adc_value = wind_direction;

        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait for the next sample interval
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    lcd_clear();
    lcd_write_string(0, 0, "Exiting...");
    usleep(1000000); // Wait for 1 second

    return EXIT_SUCCESS;
}

