#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define SLEEP_DURATION_MS 1000
#define PULSE_COUNT_THRESHOLD 500 // Adjust as needed

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
void display_flow_rate(float flow_rate);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_write_string(int line, const char *str);

// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to initialize the LCD
int lcd_init() {
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize LCD. Check I2C connection.\n");
        return -1;
    }
    return 0;
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_write_string(0, "  ");
    lcd_write_string(1, "  ");
}

// Function to write a string to the LCD at a specific line
void lcd_write_string(int line, const char *str) {
    int addr;
    if (line == 0) {
        addr = 0x80; // First line
    } else {
        addr = 0xC0; // Second line
    }
    wiringPiI2CWriteReg8(lcd_fd, addr, str[0]);
    for (int i = 1; i < strlen(str); i++) {
        wiringPiI2CWriteReg8(lcd_fd, addr + i, str[i]);
    }
}

// Function to display the flow rate on the LCD
void display_flow_rate(float flow_rate) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_write_string(1, buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Initialize LCD
    if (lcd_init() == -1) {
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on GPIO17
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up interrupt on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;
        gpioDelay(SLEEP_DURATION_MS * 1000); // Sleep for 1 second

        // Calculate flow rate
        float flow_rate = (float)pulse_count / PULSES_PER_LITER * 60.0;

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Reset pulse count
        pulse_count = 0;
    }

    // Clean up and exit
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    lcd_clear();
    gpioTerminate();
    return 0;
}

