#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Define the number of rows and columns
const int num_rows = 8;
const int num_cols = 8;

// Define the delay between row activations (800 us)
const int delay_us = 800;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio(int pin, int level)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to clear the LED matrix
void clear_matrix()
{
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            if (set_gpio(row_pins[i], 1) != 0) return; // Error setting row HIGH
            if (set_gpio(col_pins[j], 0) != 0) return; // Error setting column LOW
            gpioDelay(delay_us);
        }
    }
}

// Function to display a single frame of the wave animation
void display_frame(int *frame, int row_offset, int col_offset)
{
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            int index = (i + row_offset) % num_rows;
            int col_index = (j + col_offset) % num_cols;

            if (set_gpio(row_pins[i], 1) != 0) return; // Error setting row HIGH
            if (set_gpio(col_pins[col_index], 0) != 0) return; // Error setting column LOW
            gpioDelay(delay_us);
        }
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Left-to-right wave animation
        for (int i = 0; i < num_cols; i++) {
            display_frame(i, 0, i);
            gpioDelay(delay_us);
        }
        clear_matrix();
        gpioDelay(delay_us);

        // Right-to-left wave animation
        for (int i = 0; i < num_cols; i++) {
            display_frame(num_cols - 1 - i, 0, num_cols - 1 - i);
            gpioDelay(delay_us);
        }
        clear_matrix();
        gpioDelay(delay_us);
    }

    // Clear matrix before exiting
    clear_matrix();

    // Release GPIO pins
    for (int i = 0; i < num_rows; i++) {
        set_gpio(row_pins[i], 0);
    }
    for (int i = 0; i < num_cols; i++) {
        set_gpio(col_pins[i], 1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

