#define MLX75031_REG_DISTANCE_MSB 0x00
#define MLX75031_REG_DISTANCE_LSB 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
int log_data(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify sensor initialization (check for a specific register value)
    // Replace 0x02 with the appropriate register to check
    int init_value = i2cReadByteData(i2c_handle, 0x02); // Example register
    if (init_value < 0) {
        fprintf(stderr, "Failed to read initialization register: %d\n", init_value);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (init_value != 0x01) { // Example value, replace with the expected value
        fprintf(stderr, "Sensor initialization failed: expected 0x01, got 0x%02X\n", init_value);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    printf("Sensor initialized successfully\n");
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Read the distance data (MSB and LSB)
    result = i2cReadI2CBlockData(i2c_handle, MLX75031_REG_DISTANCE_MSB, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

