        fprintf(stderr, "Sensor initialization failed, exiting\n");
        return 1;
    }

    // Main loop
    int distance;
    while (!terminate) {
        // Read the distance from the sensor
        if (read_distance(&distance) == 0) {
            // Log the data
            if (log_data(distance) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance, attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            if (initialize_sensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed, exiting\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close the I2C handle and terminate the pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated\n");
    return 0;
}

