#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(SENSOR_PIN, INPUT);
    pinMode(LED_PIN, OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return digitalRead(SENSOR_PIN);
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write the timestamp and message to the log file
int write_to_log(const char* timestamp, const char* message) {
    FILE *fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s %s\n", timestamp, message);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led() {
    digitalWrite(LED_PIN, HIGH);
    delay(100);
    digitalWrite(LED_PIN, LOW);
}

int main() {
    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    int last_sensor_value = 1; // Assume initially no object is detected (HIGH)

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == -1) {
            fprintf(stderr, "Error reading sensor value.\n");
            delay(100); // Avoid spamming errors
            continue;
        }

        // Detect falling edge (object detected)
        if (sensor_value == 0 && last_sensor_value == 1) {
            char* timestamp = get_timestamp();
            if (timestamp != NULL) {
                if (write_to_log(timestamp, "Object detected") == 0) {
                    printf("Object detected at %s\n", timestamp);
                } else {
                    fprintf(stderr, "Error writing to log.\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }

            blink_led();
            last_sensor_value = 0; // Update last sensor value
        } else if (sensor_value == 1) {
            last_sensor_value = 1; // Object not detected
        }

        delay(100);
    }

    // Clean up GPIO on exit
    digitalWrite(LED_PIN, LOW); // Turn off LED
    pinMode(SENSOR_PIN, INPUT); // Set sensor pin to input
    pinMode(LED_PIN, INPUT);    // Set LED pin to input

    printf("Exiting.\n");
    return 0;
}

