    if (i2cWriteByteData(i2c_handle, 0x07, 0x03) < 0) return -1; // PS1_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x08, 0x03) < 0) return -1; // PS2_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x09, 0x03) < 0) return -1; // PS3_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x03) < 0) return -1; // ALS_IR_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x0B, 0x03) < 0) return -1; // ALS_VIS_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x03) < 0) return -1; // ALS_UV_ADCMUX

