    if (i2cWriteByteData(i2c_handle, 0x1D, 0x6B) < 0) return -1; // VCOEF1
    if (i2cWriteByteData(i2c_handle, 0x1E, 0x00) < 0) return -1; // VCOEF2
    if (i2cWriteByteData(i2c_handle, 0x1F, 0x00) < 0) return -1; // VCOEF3

