#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 30000        // 30 ms timeout in microseconds
#define MIN_DISTANCE 2.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm
#define WATERING_THRESHOLD 15.0 // Distance threshold for watering in cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void check_watering_condition(float distance);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_time = 0, end_time = 0;

    // Wait for the echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout: Echo start never detected\n");
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout: Echo end never detected\n");
        return -1; // Timeout
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // ISO 8601 timestamp format: YYYY-MM-DDTHH:MM:SSZ + null terminator

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Check if the plant needs watering
void check_watering_condition(float distance) {
    if (distance < WATERING_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[21];

        time(&rawtime);
        timeinfo = gmtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        if (log_file != NULL) {
            fprintf(log_file, "%s,Time to water the plant!\n", timestamp);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
                check_watering_condition(distance);
            } else {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[21];

                time(&rawtime);
                timeinfo = gmtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                fprintf(log_file, "%s,Distance out of range: %.2f cm\n", timestamp, distance);
                fflush(log_file);
            }
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[21];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,Measurement failed\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

