        return -1;
    }

    // Set ATIME (integration time)
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to APDS9960_ATIME\n");
        return -1;
    }

    // Set PTIME (proximity time)
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0x06) < 0) {
        fprintf(stderr, "Error writing to APDS9960_PTIME\n");
        return -1;
