// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROX_DATA_REG 0x08
#define SAMPLE_INTERVAL_MS 100
#define BPM_CONVERSION_FACTOR 0.5 // Example conversion factor
#define CSV_FILE "heartrate.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int read_proximity_data(int *proximity_value);
float calculate_bpm(int proximity_value);
int write_to_csv(float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read proximity data from the sensor
int read_proximity_data(int *proximity_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PROX_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    *proximity_value = (buf[1] << 8) | buf[0];
    return 0;
}

// Calculate beats per minute (BPM) from proximity data
float calculate_bpm(int proximity_value) {
    return proximity_value * BPM_CONVERSION_FACTOR;
}

// Write timestamp and BPM to CSV file
int write_to_csv(float bpm) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fflush(fp);
    fclose(fp);
    return 0;
}

