    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int proximity_value;
    float bpm;

    printf("Starting heart rate monitoring...\n");

    while (running) {
        if (read_proximity_data(&proximity_value) == 0) {
            bpm = calculate_bpm(proximity_value);
            if (write_to_csv(bpm) != 0) {
                fprintf(stderr, "Error writing to CSV file.\n");
            }
        } else {
            fprintf(stderr, "Error reading proximity data, skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Heart rate monitoring stopped.\n");
    return 0;
}

