int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (vl53l0x_init() != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO trigger
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Set up interrupt callback for falling edge on GPIO 17
    gpioSetAlertFuncEx(GPIO_TRIGGER, trigger_callback, NULL);

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_TRIGGER, NULL, NULL); // Disable callback
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// VL53L0X Initialization Function
int vl53l0x_init() {
    int status;
    unsigned char data[2];
    int i;

    // Check sensor presence (read model ID)
    status = i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, (char *)data, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "VL53L0X not found (Model ID: 0x%02X)\n", data[0]);
        return -1;
    }

    // Perform VL53L0X initialization sequence
    for (i = 0; i < sizeof(init_sequence) / sizeof(init_sequence[0]); i++) {
        status = i2cWriteI2CBlockData(i2c_handle, init_sequence[i][0], (char *)&init_sequence[i][1], 1);
        if (status < 0) {
            fprintf(stderr, "Error writing to register 0x%02X: %d\n", init_sequence[i][0], status);
            return -1;
        }
    }

    return 0;
}

// VL53L0X Read Distance Function
int vl53l0x_read_distance() {
    int status;
    unsigned char data[2];
    int distance;

    // Start a single measurement
    status = i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting measurement: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (polling RESULT_INTERRUPT_STATUS)
    int timeout_count = 0;
    while (timeout_count < MEASUREMENT_TIMEOUT_MS * 10) {
        status = i2cReadI2CBlockData(i2c_handle, RESULT_INTERRUPT_STATUS_REG, (char *)data, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            return -1;
        }
        if (data[0] & 0x01) {
            break; // Measurement complete
        }
        gpioDelay(1); // Wait 1ms
        timeout_count++;
    }

    if (timeout_count >= MEASUREMENT_TIMEOUT_MS * 10) {
        fprintf(stderr, "Measurement timeout\n");
        return -1;
    }

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, DISTANCE_MSB_REG, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1;
    }
    distance = (data[0] << 8) | data[1];

    return distance;
}

// Log Distance Function
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Trigger Callback Function
void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected
        int distance = vl53l0x_read_distance();
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance in callback\n");
        }
    }
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

