#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm
#define ICU20201_ADDR 0x6A
#define ICU20201_WHO_AM_I 0x00
#define ICU20201_DISTANCE_MSB 0x01
#define ICU20201_DISTANCE_LSB 0x02

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the sensor by reading the WHO_AM_I register
int verify_sensor() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ICU20201_WHO_AM_I, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", result);
        return -1;
    }

    // Check if the WHO_AM_I value matches the expected value for ICU-20201
    if (buf[0] != 0x41 || buf[1] != 0x4B) {
        fprintf(stderr, "WHO_AM_I verification failed. Expected 0x414B, got 0x%02X%02X\n", buf[0], buf[1]);
        return -1;
    }

    printf("Sensor verification successful.\n");
    return 0;
}

// Read the distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ICU20201_DISTANCE_MSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Control the LED based on the distance
void control_led(int distance) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log the data to a file
void log_data(int distance) {
    FILE *fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm\n", s, distance);
    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        printf("Using threshold: %d mm\n", threshold);
    } else {
        printf("Using default threshold: %d mm\n", DEFAULT_THRESHOLD);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify the sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
