// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEASURE_COMMAND_SIZE 4
#define MEASURE_COMMAND_DATA_SIZE 4
#define MEASURE_COMMAND_DATA_0 0x01
#define MEASURE_COMMAND_DATA_1 0x02
#define MEASURE_COMMAND_DATA_2 0x03
#define MEASURE_COMMAND_DATA_3 0x04
#define MEASURE_RESPONSE_SIZE 15
#define MEASURE_RESPONSE_HEADER 0x00
#define MEASURE_RESPONSE_DATA_0 0x00
#define MEASURE_RESPONSE_DATA_1 0x00
#define MEASURE_RESPONSE_DATA_2 0x00
#define MEASURE_RESPONSE_DATA_3 0x00
#define MEASURE_RESPONSE_DISTANCE_0 0x00
#define MEASURE_RESPONSE_DISTANCE_1 0x00
#define MEASURE_RESPONSE_DISTANCE_2 0x00
#define MEASURE_RESPONSE_DISTANCE_3 0x00
#define SAMPLE_DELAY_MS 100
#define INTRUSION_THRESHOLD 1000 // mm
#define NUM_SAMPLES 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, const uint8_t *command, size_t command_size);
int read_response(int handle, uint8_t *response, size_t response_size);
int verify_response(const uint8_t *response, size_t response_size);
int extract_distance(const uint8_t *response, size_t response_size);
float calculate_average_distance(int *distances, int num_distances);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, const uint8_t *command, size_t command_size) {
    int result = i2cWriteDevice(handle, (char *)command, command_size);
    if (result != command_size) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response from the sensor
int read_response(int handle, uint8_t *response, size_t response_size) {
    int result = i2cReadDevice(handle, (char *)response, response_size);
    if (result != response_size) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the response header
int verify_response(const uint8_t *response, size_t response_size) {
    if (response[0] != MEASURE_RESPONSE_HEADER) {
        fprintf(stderr, "Error: Invalid response header\n");
        return -1;
    }
    return 0;
}

// Extract the distance from the response
int extract_distance(const uint8_t *response, size_t response_size) {
    uint16_t distance = 0;
    distance = (response[11] << 8) | response[12];
    return distance;
}

// Calculate the average distance
float calculate_average_distance(int *distances, int num_distances) {
    float sum = 0.0;
    for (int i = 0; i < num_distances; i++) {
        sum += distances[i];
    }
    return sum / num_distances;
}

// Log intrusion event
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t command[MEASURE_COMMAND_SIZE] = {
            MEASURE_COMMAND_DATA_0,
            MEASURE_COMMAND_DATA_1,
            MEASURE_COMMAND_DATA_2,
            MEASURE_COMMAND_DATA_3
        };
        uint8_t response[MEASURE_RESPONSE_SIZE];
        int distances[NUM_SAMPLES];
        int i;

        // Send command
        if (send_command(i2c_handle, command, MEASURE_COMMAND_SIZE) != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Read response
        if (read_response(i2c_handle, response, MEASURE_RESPONSE_SIZE) != 0) {
            fprintf(stderr, "Error reading response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Verify response
        if (verify_response(response, MEASURE_RESPONSE_SIZE) != 0) {
            fprintf(stderr, "Error verifying response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract distance
        int distance = extract_distance(response, MEASURE_RESPONSE_SIZE);

        // Sample multiple times
        for (i = 0; i < NUM_SAMPLES; i++) {
            distances[i] = distance;
            gpioDelay(SAMPLE_DELAY_MS);
        }

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            log_intrusion(average_distance);
        }

        gpioDelay(SAMPLE_DELAY_MS); // Delay between cycles
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

