#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A
#define DISTANCE_REG 0x00 // Example register address

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 500ms
    unsigned char buf[2];
    int distance;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device presence (read a register)
    buf[0] = DISTANCE_REG;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    if (read(i2c_fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 sensor detected.\n");

    // Main loop
    while (keep_running) {
        // Read distance measurement
        if (read(i2c_fd, buf, 2) == 2) {
            distance = (buf[0] << 8) | buf[1];
            printf("Distance: %d mm\n", distance);
        } else {
            perror("Error reading distance from I2C device");
