#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // 200 ms timeout in microseconds
#define MAX_PULSE_DURATION_US 38000 // 38 ms maximum pulse duration

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_duration_us);
void log_distance(double distance);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag on rising edge
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag on falling edge
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_duration_us)
{
    if (pulse_duration_us <= 0 || pulse_duration_us > MAX_PULSE_DURATION_US) {
        return -1.0; // Invalid pulse duration
    }
    return (double)pulse_duration_us * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to convert to cm
}

// Function to log distance with timestamp
void log_distance(double distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance >= 0) {
        printf("%s Distance: %.2f cm\n", timestamp, distance);
    } else {
        printf("%s Invalid distance measurement\n", timestamp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        trigger_sensor();
        gpioDelay(1000000); // Wait 1 second

        if (echo_valid) {
            int pulse_duration = echo_end_tick - echo_start_tick;
            double distance = calculate_distance(pulse_duration);
            log_distance(distance);
        } else {
            log_distance(-1.0); // Log invalid measurement
        }
    }

    return 0;
}

