char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// UART initialization function
int uart_init(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;              /* mask the character size bits */
    tty.c_cflag |= CS8;                /* 8-bit data */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity */
    tty.c_cflag &= ~CSTOPB;             /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;            /* no hardware flowcontrol */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;            /* read doesn't block */
    tty.c_cc[VTIME] = 5;           /* 0.5 seconds read timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a frame from the UART
int read_frame(int fd, unsigned char *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    }
    return (int)bytes_read;
}

// Function to validate the magic word
int validate_magic_word(const unsigned char *buffer, size_t size) {
    if (size < MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error: Magic word too short (%zu bytes)\n", size);
        return -1;
    }

    unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(buffer, magic_word, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Error: Invalid magic word\n");
        return -1;
    }
    return 0;
}

// Function to decode the range profile
int decode_range_profile(const unsigned char *buffer, int num_bins, float *distances) {
    if (num_bins != NUM_BINS) {
        fprintf(stderr, "Error: Invalid number of bins (%d)\n", num_bins);
        return -1;
    }

    for (int i = 0; i < num_bins; i++) {
        short raw_distance = (buffer[2 * i] << 8) | buffer[2 * i + 1];
        distances[i] = (float)raw_distance * 0.01; // Example scaling
    }
    return 0;
}

// Function to detect a target within the threshold
int detect_target(const float *distances, int num_bins, float distance_threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (distances[i] <= distance_threshold) {
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Function to log an intrusion entry
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to activate the alert LED
int activate_led(int gpio_pin, int duration_ms) {
    if (gpio_pin < 0) {
        fprintf(stderr, "Error: Invalid GPIO pin number\n");
        return -1;
    }

    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize UART
    uart_fd = uart_init(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    unsigned char frame_buffer[FRAME_SIZE];
    float distances[NUM_BINS];
    char *timestamp;

    fprintf(stderr, "Starting radar intrusion detection...\n");

    while (program_running) {
        // Read a frame from the UART
        int bytes_read = read_frame(uart_fd, frame_buffer, FRAME_SIZE);
        if (bytes_read > 0) {
            // Validate the magic word
            if (validate_magic_word(frame_buffer, bytes_read) == 0) {
                // Decode the range profile
                if (decode_range_profile(frame_buffer, NUM_BINS, distances) == 0) {
                    // Detect a target
                    if (detect_target(distances, NUM_BINS, DISTANCE_THRESHOLD)) {
                        // Get the current timestamp
                        timestamp = get_iso8601_timestamp();

                        // Log the intrusion
                        if (log_intrusion(timestamp, distances[0]) == 0) {
                            fprintf(stderr, "Intrusion detected! Timestamp: %s, Distance: %.2f meters\n", timestamp, distances[0]);

                            // Activate the LED
                            activate_led(GPIO_LED, 2000); // 2 seconds

                            free(timestamp); // Free the allocated memory
                        } else {
                            fprintf(stderr, "Error: Failed to log intrusion\n");
                        }
                    }
                } else {
                    fprintf(stderr, "Error: Failed to decode range profile\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid magic word\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Close UART and log file
    close(uart_fd);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

