// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x68
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_distance(float *distance);
int log_distance(float distance);
void check_distance_and_alert(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Distance reading function
int read_distance(float *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait for measurement (5ms)

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert raw data to distance (example conversion)
    int raw_distance = (buffer[0] << 8) | buffer[1];
    *distance = (float)raw_distance * 0.01; // Example scaling

    return 0;
}

// Logging function
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", buf, distance);
    fclose(log_file);

    return 0;
}

// Distance monitoring and alert function
void check_distance_and_alert(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is LOW
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set GPIO back to input
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize GPIO to LOW

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            check_distance_and_alert(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    cleanup();
    return 0;
}

