// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void log_distance(int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Example initialization sequence (adjust as needed)
    char data[2];

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    data[1] = 0x00; // Read command
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X for sensor ID check\n");
        return -1;
    }
    char sensor_id;
    if (i2cReadDevice(i2c_handle, &sensor_id, 1) != 0) {
        fprintf(stderr, "Error reading sensor ID from VL53L1X\n");
        return -1;
    }

    if (sensor_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", sensor_id);
        return -1;
    }

    // Add more initialization steps here as needed

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance() {
    // Start a single measurement
    char cmd[1];
    cmd[0] = 0x01; // Start single measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing start measurement command\n");
        return -1;
    }

    // Wait for measurement to be ready (polling)
    int timeout = 100; // Timeout in milliseconds
    while (timeout > 0) {
        data[0] = VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY;
        data[1] = 0x00; // Read command
        if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
            fprintf(stderr, "Error writing to VL53L1X for data ready check\n");
            return -1;
        }
        char data_ready;
        if (i2cReadDevice(i2c_handle, &data_ready, 1) != 0) {
            fprintf(stderr, "Error reading data ready status from VL53L1X\n");
            return -1;
        }

        if (data_ready & 0x01) {
            break; // Measurement ready
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    data[1] = 0x00; // Read command
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X for distance read\n");
        return -1;
    }

    char distance_data[2];
    if (i2cReadDevice(i2c_handle, distance_data, 2) != 0) {
        fprintf(stderr, "Error reading distance from VL53L1X\n");
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];
    return distance;
}

// Log distance to file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
}

// Print parking guidance message
void print_guidance(int distance) {
    if (distance < 300) {
