// Define sensor and LED parameters
#define I2C_BUS 1
#define CH201_ADDR 0x40
#define LED_GPIO 18

// Define blink frequency range
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
float calculate_frequency(int distance);
void control_led(float frequency);
void log_data(int distance, float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the CH201 sensor
int initialize_sensor() {
    // No specific initialization needed for CH201 in this example
    // Assuming the sensor is ready to use after power-on
    return 0; // Return 0 for success
}

// Read distance from the CH201 sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1; // Indicate failure
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0; // Indicate success
}

// Calculate LED blink frequency based on distance
float calculate_frequency(int distance) {
    // Map distance (0-10000) to frequency (0.5-5.0)
    // This is a linear mapping, adjust as needed
    float frequency = MIN_FREQUENCY + (float)(distance / 10000.0) * (MAX_FREQUENCY - MIN_FREQUENCY);
    return frequency;
}

// Control the LED blinking frequency
void control_led(float frequency) {
    // Calculate the period of the blinking waveform
    float period = 1.0 / frequency;

    // Calculate the on and off times for each half-cycle
    float on_time = period / 2.0;
    float off_time = period / 2.0;

    // Convert times to microseconds
    int on_us = (int)(on_time * 1000000);
    int off_us = (int)(off_time * 1000000);

    // Turn the LED on
    gpioWrite(LED_GPIO, 1);
    gpioDelay(on_us);

    // Turn the LED off
    gpioWrite(LED_GPIO, 0);
    gpioDelay(off_us);
}

// Log the distance and frequency to stdout
void log_data(int distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    float frequency;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Calculate frequency
            frequency = calculate_frequency(distance);

            // Control LED
            control_led(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

