#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_command(int handle, unsigned char command);
int read_distance(int handle, unsigned short *distance);
int log_data(FILE *fp, time_t timestamp, unsigned short distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write a command to the MLX75030
int write_command(int handle, unsigned char command) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(handle, command);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read distance data from the MLX75030
int read_distance(int handle, unsigned short *distance) {
    int result, retries = 0;
    char buffer[2];

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, buffer, 2);
        if (result == 2) {
            *distance = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Log data to a CSV file
int log_data(FILE *fp, time_t timestamp, unsigned short distance) {
    if (fp == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    fprintf(fp, "%ld,%u\n", timestamp, distance);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned short distance;
        time_t timestamp = time(NULL);

        // Trigger measurement
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error triggering measurement.\n");
            continue; // Skip to the next iteration
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds

        // Read distance
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance.\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(log_file, timestamp, distance) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print to console for debugging
        printf("Timestamp: %ld, Distance: %u cm\n", timestamp, distance);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

