        if (sensor2_value != sensor2_prev_state) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            if (read_sensor(SENSOR_2_GPIO) == sensor2_value) { // Re-read after debounce
                if (sensor2_value == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
                sensor2_prev_state = sensor2_value;
            }
        }

        // Delay for 10 ms
        gpioDelay(10 * 1000); // 10 ms delay
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

