// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define CSV_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_MS 500
#define TIMEOUT_MS 50

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int init_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int read_distance();
void log_data(time_t timestamp, int distance_mm);
void signal_handler(int signal);

// Structure to hold sensor configuration (example)
typedef struct {
    int i2c_address;
    int measurement_mode;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read a single byte from a register
int read_register(int reg) {
    int value = i2cReadByteData(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a single byte to a register
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance() {
    // Trigger measurement (example: write to MEAS_STATUS_REG)
    if (write_register(MEAS_STATUS_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to trigger measurement.\n");
        return -1;
    }

    // Wait for measurement to complete (polling MEAS_STATUS_REG)
    int status = -1;
    int timeout_counter = 0;
    while (timeout_counter < TIMEOUT_MS) {
        status = read_register(MEAS_STATUS_REG);
        if (status >= 0 && (status & 0x01)) { // Check if measurement is ready
            break;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (status < 0) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    // Read distance data
    int distance = read_register(DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Failed to read distance data.\n");
        return -1;
    }

    return distance;
}

// Log data to CSV file
void log_data(time_t timestamp, int distance_mm) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(csv_file, "%s,%d\n", timestamp_str, distance_mm);
    fflush(csv_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,distance_mm\n");
    }
    rewind(csv_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        time_t current_time = time(NULL);
        int distance = read_distance();
        if (distance >= 0) {
            log_data(current_time, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_fd);
    fclose(csv_file);
    gpioTerminate();
    return 0;
}

