#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance data (replace with actual value)
#define DISTANCE_REG 0x00

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 100

// Define the maximum number of retries for I2C transactions
#define MAX_RETRIES 3

// Global variable to store the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance data from the MLX75030 sensor
int read_distance(int i2c_handle) {
    int distance = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (distance >= 0) {
            // Success, break out of the loop
            break;
        } else {
            fprintf(stderr, "Error reading distance data (attempt %d): %d\n", retries + 1, distance);
            retries++;
            gpioDelay(10); // Wait 10 ms before retrying
        }
    }

    if (distance < 0) {
        fprintf(stderr, "Failed to read distance data after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return distance;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and log distance data
    while (1) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Get the current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Log the distance and timestamp to the console
            printf("Timestamp: %ld ms, Distance: %d mm\n", timestamp_ms, distance);
        } else {
            fprintf(stderr, "Failed to read distance data.\n");
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

