        fprintf(stderr, "Error setting I2C address.\n");
        return -1;
    }

    // Recommended settings from the datasheet (example)
    char init_data[] = {0x01, 0x02, 0x03, 0x04}; // Example initialization data
    if (i2cWriteI2CBlockData(i2c_handle, 0x0207, init_data, sizeof(init_data)) != sizeof(init_data)) {
        fprintf(stderr, "Error writing initialization data.\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int read_distance(int *distance)
{
    char range_msb, range_lsb;
    uint16_t range;

    // Start a new measurement
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting measurement.\n");
        return -1;
    }

    // Wait for the measurement to complete (polling the status register)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        char status;
        if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
            fprintf(stderr, "Error reading range status.\n");
            return -1;
        }

        if (status & 0x01) { // Check if the measurement is complete
            break;
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    // Read the range data
    if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range_msb, 1) != 1) {
        fprintf(stderr, "Error reading range MSB.\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &range_lsb, 1) != 1) {
        fprintf(stderr, "Error reading range LSB.\n");
        return -1;
    }

    range = (range_msb << 8) | range_lsb;

    *distance = range;
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L4CX sensor
    if (init_vl53l4cx() != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    struct timespec ts;
    char timestamp[30];

    // Main loop
    while (!terminate) {
        // Poll the interrupt status register
        char interrupt_status;
        if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS, &interrupt_status, 1) != 1) {
            fprintf(stderr, "Error reading interrupt status.\n");
            gpioDelay(500); // Retry after 500ms
            continue;
        }

        // Check if the interrupt status bit is set
        if (interrupt_status & 0x01) {
            // Read the distance
            if (read_distance(&distance) == 0) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    sprintf(timestamp + strlen(timestamp), ".%06ld", ts.tv_nsec / 1000); // Append microseconds

                    // Log the data
                    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
                } else {
                    fprintf(stderr, "Error getting timestamp.\n");
                }
            } else {
                fprintf(stderr, "Error reading distance.\n");
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

