#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)
#define LOG_FILE "sensor_data.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
float get_distance();
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    return 0; // Indicate success
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Get distance from the ultrasonic sensor
float get_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT); // Ensure ECHO_PIN is in input mode

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Map distance to servo angle
float map_distance_to_angle(float distance) {
    if (distance < 2.0) {
        return -90.0;
    } else if (distance > 400.0) {
        return 90.0;
    } else {
        return (distance - 2.0) * (90.0 / 398.0);
    }
}

// Set servo angle
void set_servo_angle(float angle) {
    int pulse_width = (int)(angle * 1000.0 / 90.0 + 500.0); // Map angle (-90 to 90) to pulse width (500 to 2500)
    gpioServo(SERVO_PIN, pulse_width);
}

// Log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();
        float distance = get_distance();

        if (distance > 0) {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }

        gpioDelay(200000); // 200 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    return 0;
}

