#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds
#define BUZZER_ON_THRESHOLD 30.0 // Distance threshold for buzzer activation in cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_duration);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Release pigpio resources
    exit(0);
}

// Function to generate a 10 µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo has started
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset echo received flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_duration) {
    if (pulse_duration < 0 || pulse_duration > TIMEOUT_US) {
        fprintf(stderr, "Error: Invalid pulse duration: %u us\n", pulse_duration);
        return -1.0; // Indicate error
    }
    float distance = (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < BUZZER_ON_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();

        // Wait for echo to be received or timeout
        int timeout_counter = 0;
        while (echo_received == 0 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_counter++;
        }

        if (echo_received == 0) {
            fprintf(stderr, "Error: No echo received (timeout)\n");
            gpioDelay(100000); // Wait 100ms before next attempt
            continue;
        }

        // Calculate pulse duration
        unsigned int pulse_duration = end_tick - start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_duration);

        if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance reading\n");
            gpioDelay(100000); // Wait 100ms before next attempt
            continue;
        }

        // Control buzzer
        control_buzzer(distance);

        // Output distance
        printf("Distance: %.2f cm\n", distance);

        // Wait 100 ms
        gpioDelay(100000);
    }

    return 0; // This line will never be reached due to the infinite loop
}

