#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 1000
#define CLOSED_ANGLE 1500
#define DISTANCE_THRESHOLD 200 // mm
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void set_servo_angle(int angle);
void open_gate();
void close_gate();
void log_event(const char *message);
void signal_handler(int signal);
void force_open_gate();
void force_close_gate();
void status_request();

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_SPAD_NB_DETECTED 0x0081
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

// VL53L1X Initialization Sequence (Example - refer to datasheet for correct sequence)
const unsigned char init_sequence[][2] = {
    {VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x0000},
    {VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x0000},
    {VL53L1X_REG_SYSTEM_START, 0x01}
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        log_event("VL53L1X initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin to output mode
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance();
        if (distance < 0) {
            log_event("Error reading distance");
        } else {
            char message[100];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_event(message);

            if (distance < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    close_gate(); // Ensure gate is closed on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

int vl53l1x_init() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C device");
        return -1;
    }

    // Check sensor ID (Example - refer to datasheet for correct value)
    char sensor_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id, 1) != 1) {
        log_event("Error reading sensor ID");
        i2cClose(i2c_handle);
        return -1;
    }

    if (sensor_id != 0xEA) { // Example ID - replace with actual ID
        log_event("Incorrect sensor ID");
        i2cClose(i2c_handle);
        return -1;
    }

    // Initialize the sensor (Example - refer to datasheet for correct sequence)
    for (int i = 0; i < sizeof(init_sequence) / sizeof(init_sequence[0]); i++) {
        if (i2cWriteI2CBlockData(i2c_handle, init_sequence[i][0], &init_sequence[i][1], 1) != 1) {
            log_event("Error writing to sensor");
            i2cClose(i2c_handle);
            return -1;
        }
        gpioDelay(RETRY_DELAY_MS); // Small delay after each write
    }

    return 0;
}

int vl53l1x_read_distance() {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) {
        log_event("Error reading distance data");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void set_servo_angle(int angle) {
    gpioServo(SERVO_PIN, angle);
}

void open_gate() {
    log_event("Opening gate");
    set_servo_angle(OPEN_ANGLE);
    gpioDelay(500); // Allow servo to reach position
}

void close_gate() {
    log_event("Closing gate");
    set_servo_angle(CLOSED_ANGLE);
    gpioDelay(500); // Allow servo to reach position
}

void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

void signal_handler(int signal) {
    log_event("Signal received, terminating...");
    terminate = 1;
}

void force_open_gate() {
    log_event("Force opening gate");
    set_servo_angle(OPEN_ANGLE);
}

void force_close_gate() {
    log_event("Force closing gate");
    set_servo_angle(CLOSED_ANGLE);
}

void status_request() {
    log_event("Status requested");
    // Implement status request logic here (e.g., read sensor data and log it)
}

