#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 30000       // Timeout in microseconds (30ms)
#define MIN_PULSE_WIDTH_US 100  // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH_US TIMEOUT_US // Maximum pulse width in microseconds
#define TIMEOUT_MS 60          // Timeout in milliseconds

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10 µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1; // Set flag to indicate rising edge received
    } else if (level == 0 && echo_received) {
        falling_tick = tick;
        echo_received = 0; // Reset flag after falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to convert to cm
}

// Function to log distance with timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(stdout, "%s Distance: %.2f cm\n", timestamp, distance);
    fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo or timeout
        uint32_t start_time = gpioTick();
        while (!echo_received && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout: No echo received within %d us\n", TIMEOUT_US);
            fprintf(log_file, "Timeout: No echo received within %d us\n", TIMEOUT_US);
            fflush(log_file);
        } else {
            uint32_t pulse_width = falling_tick - rising_tick;

            // Handle wraparound
            if (falling_tick < rising_tick) {
                pulse_width += (0xFFFFFFFF - falling_tick) + rising_tick;
            }

            if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
                fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width);
                fprintf(log_file, "Invalid pulse width: %d us\n", pulse_width);
                fflush(log_file);
            } else {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
            }
        }

        gpioDelay(200); // 5 Hz sampling rate
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

