    if (vl53l1x_write_byte(i2c_handle, 0x02dd, 0x06) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02de, 0x07) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02df, 0x08) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e0, 0x09) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e1, 0x0a) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e2, 0x0b) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e3, 0x0c) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e4, 0x0d) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e5, 0x0e) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e6, 0x0f) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e7, 0x10) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e8, 0x11) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02e9, 0x12) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x02ea, 0x13) != 0) return -1;
