// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, (char *)&reg, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *data) {
    if (i2cWriteDevice(handle, (char *)&reg, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X\n", reg);
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;

    // Check if the sensor is present by reading the model ID
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading VL53L1X model ID\n");
        return -1;
