// Function to read the distance from the VL53L1X sensor
int read_distance() {
    uint16_t distance;
    uint8_t data_ready;

    // Check if data is ready
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &data_ready) != 0) {
        fprintf(stderr, "Error reading data ready status\n");
        return -1;
    }

    if (data_ready & 0x01) {
        // Read the distance
        if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
            fprintf(stderr, "Error reading distance\n");
            return -1;
        }
        return distance;
    } else {
        return -1; // Data not ready
    }
}

// Function to control the servo motor
void control_servo(int distance) {
    int pulse_width;

    if (distance < OPEN_THRESHOLD) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (distance > CLOSE_THRESHOLD) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    } else {
        // Hysteresis
        if (distance < OPEN_THRESHOLD + HYSTERESIS) {
            pulse_width = SERVO_MIN_PULSE_WIDTH;
        } else {
            pulse_width = SERVO_MAX_PULSE_WIDTH;
        }
    }

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log events to a file
void log_event(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Smart Parking Gate started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance > 0) {
            if (gate_open && distance > OPEN_THRESHOLD + HYSTERESIS) {
                // Close the gate
                control_servo(distance);
                gate_open = 0;
                log_event(distance);
            } else if (!gate_open && distance < CLOSE_THRESHOLD - HYSTERESIS) {
                // Open the gate
                control_servo(distance);
                gate_open = 1;
                log_event(distance);
            }
        } else {
            fprintf(stderr, "Error reading distance, skipping gate control\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop the servo
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Smart Parking Gate terminated.\n");
    return 0;
}

