        return -1;
    }
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Example configuration (adjust as needed)
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x0A) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1;

