// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    uint8_t range_status;
    uint16_t distance;

    // Start a new measurement
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1;

    // Wait for measurement to complete (polling)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) return -1;
        if ((range_status & 0x01) != 0) break; // Check if measurement is ready
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read distance
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) return -1;

    return distance;
}

