    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int gate_open = 0; // Track gate state
    while (!terminate) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (distance < DISTANCE_THRESHOLD && !gate_open) {
            control_gate(1);
            gate_open = 1;
        } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
            control_gate(0);
            gate_open = 0;
        }

        gpioDelay(POLLING_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

