#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance thresholds
#define MIN_DISTANCE 100
#define MAX_DISTANCE 300

// Define VL53L1X register addresses (Example - refer to datasheet for correct values)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void motor_forward();
void motor_backward();
void motor_stop();
void trigger_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// VL53L1X initialization function
int vl53l1x_init() {
    // Check sensor ID (Example - refer to datasheet for correct value)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Perform a soft reset (Example - refer to datasheet for correct value)
    if (i2cWriteByteData(i2c_handle, 0x002D, 0x01) < 0) {
        fprintf(stderr, "Error writing soft reset command: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance() {
    int distance = -1;
    int status;

    // Poll status register until data is ready
    int timeout = 0;
    while (timeout < 100) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading status register: %d\n", status);
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance value
    distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }

    return distance;
}

