    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: Backward\n");
}

void motor_stop() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Stop\n");
}

// Interrupt handler function
void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < MIN_DISTANCE) {
                motor_forward();
            } else if (distance > MAX_DISTANCE) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Error reading distance in ISR\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

