#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RESET_CMD 0x80
#define TOUCH_STATUS_REG 0x00
#define ELE_CONFIG_REG 0x5E
#define LED_GPIO_0 17
#define LED_GPIO_1 18
#define LED_GPIO_2 27
#define LED_GPIO_3 22

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void mpr121_drive_led(uint16_t touch_status);
void log_event(uint16_t touch_status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    uint8_t buf[2];
    int result;

    // Soft reset
    buf[0] = RESET_CMD;
    buf[1] = 0x63; // Release from reset
    result = i2cWriteDevice(i2c_fd, buf, 2);
    if (result != 0) {
        fprintf(log_file, "%s", "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    buf[0] = ELE_CONFIG_REG;
    buf[1] = 0x0C; // Set touch and release thresholds for all electrodes
    result = i2cWriteDevice(i2c_fd, buf, 2);
    if (result != 0) {
        fprintf(log_file, "%s", "Error: Electrode config failed\n");
        return -1;
    }

    // Enable all electrodes
    buf[0] = ELE_CONFIG_REG;
    buf[1] = 0x0F; // Enable all electrodes
    result = i2cWriteDevice(i2c_fd, buf, 2);
    if (result != 0) {
        fprintf(log_file, "%s", "Error: Enable electrodes failed\n");
        return -1;
    }

    return 0;
}

// MPR121 touch status reading function
int mpr121_read_touch_status(uint16_t *touch_status) {
    uint8_t buf[1];
    int result;

    buf[0] = TOUCH_STATUS_REG;
    result = i2cWriteDevice(i2c_fd, buf, 1);
    if (result != 0) {
        fprintf(log_file, "%s", "Error: Writing to touch status register failed\n");
        return -1;
    }

    result = i2cReadDevice(i2c_fd, (char *)touch_status, 2);
    if (result != 2) {
        fprintf(log_file, "%s", "Error: Reading touch status failed\n");
        return -1;
    }

    return 0;
}

// LED driving function
void mpr121_drive_led(uint16_t touch_status) {
    gpioWrite(LED_GPIO_0, (touch_status >> 0) & 1);
    gpioWrite(LED_GPIO_1, (touch_status >> 1) & 1);
    gpioWrite(LED_GPIO_2, (touch_status >> 2) & 1);
    gpioWrite(LED_GPIO_3, (touch_status >> 3) & 1);
}

// Event logging function
void log_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Touch status = 0x%04X\n", timestamp, touch_status);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    uint16_t touch_status;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(log_file, "MPR121 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_GPIO_0, PI_OUTPUT);
    gpioSetMode(LED_GPIO_1, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);
    gpioSetMode(LED_GPIO_3, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = mpr121_read_touch_status(&touch_status);
        if (result == 0) {
            mpr121_drive_led(touch_status);
            log_event(touch_status);
        } else {
            fprintf(log_file, "Error reading touch status, retrying...\n");
        }
        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup
    gpioWrite(LED_GPIO_0, 0);
    gpioWrite(LED_GPIO_1, 0);
    gpioWrite(LED_GPIO_2, 0);
    gpioWrite(LED_GPIO_3, 0);

    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

