// File to log proximity events
#define LOG_FILE "proximity.log"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x2B
#define MPR121_FFI_CONFIG 0x2B
#define MPR121_SFI_CONFIG 0x2C
#define MPR121_ESI_CONFIG 0x2D
#define MPR121_DEBOUNCE_CONFIG 0x2E

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void log_proximity_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODE_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    // Recommended settings from datasheet
    if (i2cWriteByteData(i2c_handle, MPR121_FFI_CONFIG, 0x24) < 0) {
        fprintf(stderr, "Error writing to MPR121_FFI_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_SFI_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error writing to MPR121_SFI_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_ESI_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error writing to MPR121_ESI_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to MPR121_DEBOUNCE_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODE_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

