#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms in microseconds
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define LOG_FILE "distance_log.txt"

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        printf("Caught SIGINT, exiting gracefully.\n");
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(5);              // Wait 5 us
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Hold high for 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    long pulse_width = -1; // Initialize to an invalid value

    // Wait for the echo pin to go high, with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin never rose.\n");
        return -1; // Indicate error
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low, with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin never fell.\n");
        return -1; // Indicate error
    }

    end_time = gpioTick();

    pulse_width = end_time - start_time;
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[21];

                time(&rawtime);
                timeinfo = gmtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                fprintf(log_file, "%s,Error: Distance out of range (%.2f cm)\n", timestamp, distance);
                fflush(log_file);
            }
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[21];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,Error: Invalid pulse width\n", timestamp);
            fflush(log_file);
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

