}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Disable ISR
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

