int main() {
    int distance;
    int status;

    // Initialize syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1); // Enable sensor

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance
        if (vl53l1x_read_distance(&distance) == 0) {
            // Get sensor status
            status = gpioRead(XSHUT_PIN); // Read XSHUT pin to get status

            // Log data
            syslog(LOG_INFO, "Distance: %d mm, Status: %d", distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Shutdown
    vl53l1x_shutdown();
    gpioTerminate();
    closelog();

    return 0;
}

int vl53l1x_init() {
    int i, result;

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }

    // Initialize VL53L1X (example initialization sequence)
    for (i = 0; i < sizeof(init_sequence) / 2; i++) {
        result = i2cWriteByteData(i2c_handle, init_sequence[2 * i], init_sequence[2 * i + 1]);
        if (result < 0) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            i2cClose(i2c_handle);
            return -1;
        }
    }

    // Start continuous ranging
    result = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to start ranging: %s", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

int vl53l1x_read_distance(int *distance) {
    int status;
    int result;

    // Read range status
    result = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to read range status: %s", strerror(errno));
        return -1;
    }
    status = result;

    // Read distance
    result = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        return -1;
    }
    *distance = result;

    return 0;
}

void vl53l1x_shutdown() {
    // Stop continuous ranging
    i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x00);

    // Close I2C device
    i2cClose(i2c_handle);
}

void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

