        log_data("VL53L1X initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, 0); // Initialize gate to closed state

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
