        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(1000); // Small delay after write

    if (i2cWriteByteData(i2c_handle, 0x02d8, 0x00) < 0) { // Example register write
        fprintf(stderr, "Error writing to I2C device\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(1000); // Small delay after write

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, 0x000, 0x01) < 0) {
        log_data("Error starting measurement");
        return -1;
    }
    gpioDelay(1000); // Wait for measurement to complete (adjust as needed)

    // Read distance data
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE);
    if (distance < 0) {
        log_data("Error reading distance data");
        return -1;
    }

    // Convert to centimeters
    return distance / 10; // mm to cm
}

// Control gate actuator
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_GATE, 1); // Open gate
    } else {
        gpioWrite(GPIO_GATE, 0); // Close gate
    }
}

// Log data to file
void log_data(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_data("Received signal, shutting down...");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

