#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define TIMEOUT_US 30000        // 30 ms timeout
#define TRIGGER_PULSE_US 10      // 10 us trigger pulse
#define SAMPLE_RATE_MS 100       // 100 ms sample rate
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t new_pulse = 0;
volatile unsigned int pulse_width = 0;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(unsigned int pulse_width);
int set_servo_angle(float angle);
int log_data(float distance, int servo_angle);
float filter_distance(float new_distance, float *history, int history_size, int history_index);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo
    gpioSetPWMrange(SERVO_PIN, 20000); // 20ms period (50Hz)

    // Set PWM frequency for servo
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int echo_received = 0;

    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset echo received flag
    } else if (level == 0) {
        if (echo_received) {
            unsigned int pulse_width_us = tick - start_tick;
            if (pulse_width_us > TIMEOUT_US) {
                pulse_width_us = TIMEOUT_US; // Cap at timeout
            }
            pulse_width = pulse_width_us;
            new_pulse = 1; // Set new pulse flag
        }
    }
}

// Calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // No echo received
    }
    float time_in_seconds = (float)pulse_width / 1000000.0;
    float distance = (time_in_seconds * SPEED_OF_SOUND) / 2.0;
    return distance;
}

// Set servo angle using pigpio API
int set_servo_angle(float angle) {
    if (angle < 0.0 || angle > 180.0) {
        fprintf(stderr, "Invalid servo angle: %f\n", angle);
        return 1;
    }

    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioPWM(SERVO_PIN, pulse_width);
    return 0;
}

// Log data to CSV file
int log_data(float distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

// Filter distance readings with a moving average
float filter_distance(float new_distance, float *history, int history_size, int history_index) {
    static int history_index_local = 0;
    static float sum = 0.0;

    sum -= history[history_index_local];
    history[history_index_local] = new_distance;
    sum += new_distance;

    history_index_local = (history_index_local + 1) % history_size;

    return sum / history_size;
}

int main() {
