    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    fflush(log_file);

    // Initialize moving average history
    float distance_history[MOVING_AVG_SIZE] = {0.0};
    int history_index = 0;

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Starting distance measurement...\n");

    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for a short period
        gpioDelay(SAMPLE_RATE_MS);

        // Read pulse width
        float filtered_distance = -1.0;
        if (new_pulse) {
            filtered_distance = calculate_distance(pulse_width);
            pulse_width = 0; // Reset pulse width
            new_pulse = 0; // Reset new pulse flag
        } else {
            filtered_distance = filter_distance(0.0, distance_history, MOVING_AVG_SIZE, history_index);
        }

        // Validate distance
        if (filtered_distance < MIN_DISTANCE || filtered_distance > MAX_DISTANCE) {
            filtered_distance = -1.0; // Log invalid reading
        }

        // Set servo angle
        int servo_angle = 90; // Default angle
        if (filtered_distance >= 0.0) {
            servo_angle = (int)((180.0 - filtered_distance / 100.0) * 180.0 / 400.0 * 180.0); // Map distance to angle
            if (servo_angle < 0) servo_angle = 0;
            if (servo_angle > 180) servo_angle = 180;
        }

        // Log data
        if (log_data(filtered_distance, servo_angle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Set servo angle
        if (set_servo_angle((float)servo_angle) != 0) {
            fprintf(stderr, "Error setting servo angle\n");
        }

        // Print current state (for debugging)
        printf("Distance: %.2f cm, Servo Angle: %d deg\n", filtered_distance, servo_angle);
    }

    // Stop servo
    set_servo_angle(0.0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

