volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void update_led(int distance);
void add_to_buffer(CircularBuffer *cb, int distance);
int get_from_buffer(CircularBuffer *cb, int index, int *distance);
