// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, int distance) {
    cb->buffer[cb->head] = distance;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get a value from the circular buffer
int get_from_buffer(CircularBuffer *cb, int index, int *distance) {
    if (index < 0 || index >= cb->count) {
        return -1; // Invalid index
    }
    int actual_index = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *distance = cb->buffer[actual_index];
    return 0;
}

