        return -1;
    }

    // Enable signal-rate checking
    data[0] = 0x01; // Register address
    data[1] = 0x02; // Value to write

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization: %s\n", strerror(errno));
        return -1;
    }

    // Configure cross-talk compensation
    data[0] = 0x03; // Register address
    data[1] = 0x04; // Value to write

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization: %s\n", strerror(errno));
        return -1;
    }

    // Start ranging
    data[0] = 0x05; // Register address
    data[1] = 0x06; // Value to write

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

