// Default I2C address
#define DEFAULT_I2C_ADDRESS 0x60

// Default threshold
#define DEFAULT_THRESHOLD 1000

// GPIO pin for interrupt
#define GPIO_PIN 27

// Log file name
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
