// Function to initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, no flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to initialize GPIO
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up/down\n");
        return -1;
    }
    return 0;
}

