// Function to read proximity value
int read_proximity(int i2c_handle) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return (buffer[0] << 8) | buffer[1]; // Combine the two bytes into a 16-bit value
