#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 200.0     // Maximum measurable distance in cm
#define PWM_FREQUENCY 4000000  // PWM frequency in Hz (4 MHz)
#define TIMEOUT_US 200000       // Timeout in microseconds (200 ms)

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
float measure_distance();
float map_distance_to_frequency(float distance);
void set_pwm_frequency(int frequency);
void set_pwm_duty_cycle(int duty_cycle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to generate a 10 µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    start_tick = 0;
    end_tick = 0;
    echo_received = 0;

    trigger_pulse();

    // Wait for echo or timeout
    int count = 0;
    while (!echo_received && count < TIMEOUT_US) {
        if (gpioRead(ECHO_PIN) == 1) {
            start_tick = gpioTick();
            echo_received = 1;
        }
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Echo signal not received within timeout.\n");
        return -1.0; // Indicate error
    }

    count = 0;
    while (!echo_received && count < TIMEOUT_US) {
        if (gpioRead(ECHO_PIN) == 0) {
            end_tick = gpioTick();
            echo_received = 1;
        }
        count++;
        gpioDelay(1);
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Echo signal not received within timeout.\n");
        return -1.0; // Indicate error
    }

    // Calculate pulse width in microseconds
    unsigned int pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    return distance;
}

// Function to map distance to frequency using a logarithmic scale
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate error
    }

    // Logarithmic mapping
    float frequency = 200.0 + (2000.0 - 200.0) * log10(distance / MIN_DISTANCE + 1.0) / log10(MAX_DISTANCE / MIN_DISTANCE + 1.0);

    return frequency;
}

// Function to set the PWM frequency
void set_pwm_frequency(int frequency) {
    gpioSetPWMfrequency(SPEAKER_PIN, frequency);
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM frequency
    set_pwm_frequency(PWM_FREQUENCY);

    // Set PWM range (optional, but recommended for clean PWM)
    gpioSetPWMrange(SPEAKER_PIN, 1000000); // Set range to 1MHz

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = measure_distance();
        if (distance < 0) {
            // Error occurred, maintain previous frequency
            float frequency = -1.0; // Indicate error
        } else {
            float frequency = map_distance_to_frequency(distance);
            if (frequency < 0) {
                // Error occurred, maintain previous frequency
                frequency = -1.0; // Indicate error
            }
        }

        if (frequency >= 0) {
            set_pwm_frequency(PWM_FREQUENCY);
            set_pwm_duty_cycle((int)frequency);
        } else {
            // Maintain previous frequency
            set_pwm_frequency(PWM_FREQUENCY);
            set_pwm_duty_cycle((int)(-1.0)); // Maintain previous duty cycle
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Clean up and exit
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();          // Terminate pigpio
    return 0;
}

