#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUZZER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 5.0      // cm
#define MAX_DISTANCE 50.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_MS 100         // ms
#define PWM_FREQUENCY 1000    // Hz
#define TRIGGER_PULSE_US 10   // us

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick, end_tick;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
unsigned int measure_pulse_width();
float calculate_distance(unsigned int pulse_width);
float map_distance_to_frequency(float distance);
void generate_tone(float frequency);
void print_data(float distance, float frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
unsigned int measure_pulse_width() {
    start_tick = gpioTick();
    while (!echo_received && (gpioTick() - start_tick) < 1000000) {
        // Wait for echo to go high
    }
    if (!echo_received) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return 0; // Timeout
    }

    end_tick = gpioTick();
    while (!echo_received && (gpioTick() - end_tick) < 1000000) {
        // Wait for echo to go low
    }
    if (!echo_received) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return 0; // Timeout
    }

    return end_tick - start_tick;
}

// Calculate the distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0;
}

// Map the distance to a frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        frequency = MAX_FREQUENCY;
    } else {
        frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

// Generate a tone on the buzzer
void generate_tone(float frequency) {
    int duty_cycle = 500000; // 50% duty cycle
    gpioPWM(BUZZER_PIN, duty_cycle);
    gpioSetPWMfrequency(BUZZER_PIN, frequency);
}

// Print the distance and frequency to the console
void print_data(float distance, float frequency) {
    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
}

// Cleanup GPIO resources
void cleanup() {
    gpioPWM(BUZZER_PIN, 0); // Stop the tone
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Main loop
    while (running) {
        trigger_sensor();
        unsigned int pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            float frequency = map_distance_to_frequency(distance);
            generate_tone(frequency);
            print_data(distance, frequency);
        } else {
            fprintf(stderr, "Error: Invalid pulse width\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

