#define TIMEOUT_US 50000        // 50 ms timeout in microseconds
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define CLOSE_THRESHOLD 10.0    // Distance threshold for "Too close!" in cm

// Global variables
volatile int terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long startTime = 0, endTime = 0;
    long pulseDuration = -1; // Initialize to -1 for timeout

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    endTime = gpioTick();

    pulseDuration = endTime - startTime;
    return pulseDuration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) {
        return -1.0; // Indicate timeout
    }
    return (float)pulseDuration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to validate the distance
int validateDistance(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to print the distance
void printDistance(float distance) {
    if (distance < 0) {
        printf("Invalid reading\n");
    } else if (distance < CLOSE_THRESHOLD) {
        printf("Distance: %.2f cm\n", distance);
        printf("Too close!\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is initially low

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulseDuration = measurePulse();
        float distance = calculateDistance(pulseDuration);

        if (validateDistance(distance)) {
            printDistance(distance);
        }

        gpioDelay(500); // 500 ms delay
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

