#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8 // Chip Select pin (GPIO8, CE0)

// Define sensor parameters (replace with actual values from datasheet)
#define SENSOR_INIT_COMMAND 0x00 // Example initialization command
#define DISTANCE_REG 0x01 // Example register address for distance
#define MAX_DISTANCE 5000 // Maximum measurable distance in mm
#define MIN_DISTANCE 200 // Minimum measurable distance in mm

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(time_t timestamp, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    char init_data[2];
    init_data[0] = SENSOR_INIT_COMMAND;
    init_data[1] = 0x00; // Example initialization data

    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = init_data[0];
    tx_buf[1] = init_data[1];

    gpioWrite(CS_PIN, 0); // Select the sensor
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance(int *distance) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Construct the read command (example)
    tx_buf[0] = DISTANCE_REG; // Address to read from
    tx_buf[1] = 0x00; // Dummy data for reading

    gpioWrite(CS_PIN, 0); // Select the sensor
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    if (result != 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Convert the received data to distance (example conversion)
    *distance = (rx_buf[0] << 8) | rx_buf[1];

    // Validate the distance reading
    if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance reading: %d\n", *distance);
        return -1;
    }

    return 0;
}

// Function to log data to a CSV file
void log_data(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the sensor initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int distance;
    time_t current_time;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            current_time = time(NULL);
            log_data(current_time, distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

