#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define MEAS_RATE_REG 0x08
#define PART_ID_REG 0x00
#define LUX_REG 0x04
#define PROX_REG 0x06
#define CSV_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int verify_sensor();
int configure_sensor();
int read_sensor_data(float *lux, int *proximity);
int log_data(float lux, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read a register from the sensor
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a register in the sensor
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Verify the sensor by reading the part ID
int verify_sensor() {
    int part_id = read_register(PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID, sensor may not be present.\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }
    printf("Sensor verified: Part ID = 0x%02X\n", part_id);
    return 0;
}

// Configure the sensor (example configuration)
int configure_sensor() {
    // Example configuration: Set measurement rate to 100ms (adjust as needed)
    if (write_register(MEAS_RATE_REG, 0x0A) < 0) {
        fprintf(stderr, "Error configuring sensor.\n");
        return -1;
    }
    return 0;
}

// Read ambient light and proximity data
int read_sensor_data(float *lux, int *proximity) {
    int lux_raw = read_register(LUX_REG);
    int prox_raw = read_register(PROX_REG);

    if (lux_raw < 0 || prox_raw < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    // Convert raw values to lux and proximity (example conversions)
    *lux = (float)lux_raw / 10.0; // Example conversion
    *proximity = prox_raw; // Raw value

    return 0;
}

// Log data to CSV file
int log_data(float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s,%.2f,%d\n", timestamp, lux, proximity);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify the sensor
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&lux, &proximity) == 0) {
            log_data(lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

