        return -1;
    }
    printf("Sensor verified: Part ID = 0x%02X\n", part_id);
    return 0;
}

// Configure the sensor (example configuration)
int configure_sensor() {
    // Example configuration: Set measurement rate to 100ms (adjust as needed)
    if (write_register(MEAS_RATE_REG, 0x0A) < 0) {
        fprintf(stderr, "Error configuring sensor.\n");
        return -1;
    }
    return 0;
}

// Read ambient light and proximity data
int read_sensor_data(float *lux, int *proximity) {
    int lux_raw = read_register(LUX_REG);
    int prox_raw = read_register(PROX_REG);

    if (lux_raw < 0 || prox_raw < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    // Convert raw values to lux and proximity (example conversions)
    *lux = (float)lux_raw / 10.0; // Example conversion
    *proximity = prox_raw; // Raw value

    return 0;
}

// Log data to CSV file
int log_data(float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s,%.2f,%d\n", timestamp, lux, proximity);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify the sensor
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (!terminate) {
