        fprintf(stderr, "Error: Failed to configure PS_LED2_SELECT.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x19, 0x6B) < 0) { // PS1_ADCMUX
        fprintf(stderr, "Error: Failed to configure PS1_ADCMUX.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x03) < 0) { // PS1_ADC_GAIN
        fprintf(stderr, "Error: Failed to configure PS1_ADC_GAIN.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x1B, 0x00) < 0) { // PS1_MEAS_RATE
        fprintf(stderr, "Error: Failed to configure PS1_MEAS_RATE.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x1C, 0x01) < 0) { // PS1_IRQ_ENABLE
        fprintf(stderr, "Error: Failed to configure PS1_IRQ_ENABLE.\n");
        return -1;
