#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 200.0    // Maximum measurable distance in cm
#define MIN_DISTANCE 20.0     // Minimum measurable distance in cm
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width for servo (us)
#define MIN_PULSE_WIDTH 500   // Minimum pulse width for servo (us)
#define TIMEOUT_US 50000       // Timeout for echo pulse (us)

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int echo_timeout = 0;

// Function prototypes
void trigger_sensor();
float measure_distance();
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);                 // Exit the program
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float measure_distance() {
    pulse_start = 0;
    pulse_end = 0;
    echo_timeout = 0;

    trigger_sensor();

    // Wait for echo to start
    int timeout_counter = 0;
    while (pulse_start == 0 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (pulse_start == 0) {
        echo_timeout = 1;
        return -1.0; // Timeout
    }

    // Wait for echo to end
    timeout_counter = 0;
    while (pulse_end == 0 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (pulse_end == 0) {
        echo_timeout = 2;
        return -1.0; // Timeout
    }

    // Calculate pulse duration in microseconds
    int pulse_duration = pulse_end - pulse_start;

    // Calculate distance in centimeters
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;

    return distance;
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    // Map angle (0-180) to pulse width (500-2500)
    int pulse_width = (int)(MIN_PULSE_WIDTH + (angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Measure distance
        float distance = measure_distance();

        // Check for timeout
        if (distance < 0) {
            printf("Error: Timeout occurred\n");
        } else if (distance > MAX_DISTANCE) {
            printf("Error: Distance out of range (%.2f cm)\n", distance);
        } else if (distance < MIN_DISTANCE) {
            printf("Error: Distance out of range (%.2f cm)\n", distance);
        } else {
            // Calculate servo angle
            int angle = 0;
            if (distance >= 200.0) {
                angle = 0;
            } else if (distance <= 110.0) {
