#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000
#define DISTANCE_THRESHOLD_FAR 250 // mm
#define DISTANCE_THRESHOLD_NEAR 200 // mm
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle, uint16_t *distance);
void set_servo_pulse_width(int gpio, int pulse_width_us);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0024
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_SYSTEM_MODE_GPIO1 0x001E

// VL53L1X model ID
#define VL53L1X_MODEL_ID 0xEA

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    uint8_t model_id;
    uint8_t data[2];

    // Verify model ID
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, (char*)&model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set timing budget (example: 50ms)
    data[0] = 0x00; // Register address
    data[1] = 0x05; // Value (50ms)
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, (char*)data, 2) != 2) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    // Start ranging
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Value (start ranging)
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, (char*)data, 2) != 2) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle, uint16_t *distance) {
    uint8_t data[2];

    // Check if data is ready
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, (char*)&data[0], 1) != 1) {
        fprintf(stderr, "Error checking data ready status\n");
        return -1;
    }

    if (!(data[0] & 0x01)) {
        // Data not ready, return -1
        return -1;
    }

    // Read distance
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char*)distance, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    return 0;
}

// Function to set the servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width_us) {
    gpioPWM(gpio, pulse_width_us / 10000); // pigpio uses 1/10000 for us
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    uint16_t distance;
    int pulse_width = 1000; // Initial pulse width (far)
    int pulse_width_near = 2000; // Pulse width (near)
    int i2c_address = VL53L1X_ADDR;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting gate control...\n");

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            // Convert distance to mm (assuming 16-bit distance register)
            int distance_mm = distance;

            // Control servo based on distance
            if (distance_mm > DISTANCE_THRESHOLD_FAR) {
                // Move towards near position
                if (distance_mm < DISTANCE_THRESHOLD_NEAR) {
                    pulse_width = pulse_width_near;
                } else {
                    // Smooth transition
                    pulse_width = (int)(((float)(pulse_width_near - pulse_width) / (DISTANCE_THRESHOLD_NEAR - DISTANCE_THRESHOLD_FAR)) * (distance_mm - DISTANCE_THRESHOLD_FAR) + pulse_width);
                }
            } else {
                // Move away from near position
                if (distance_mm > DISTANCE_THRESHOLD_NEAR) {
                    pulse_width = pulse_width_far;
                } else {
                    // Smooth transition
                    pulse_width = (int)(((float)(pulse_width_far - pulse_width) / (DISTANCE_THRESHOLD_FAR - DISTANCE_THRESHOLD_NEAR)) * (DISTANCE_THRESHOLD_FAR - distance_mm) + pulse_width);
                }
            }

            // Set servo pulse width
            set_servo_pulse_width(SERVO_GPIO, pulse_width);

            // Log event
            if (distance_mm > DISTANCE_THRESHOLD_FAR) {
                log_event("Gate opening");
            } else if (distance_mm < DISTANCE_THRESHOLD_NEAR) {
                log_event("Gate closing");
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    set_servo_pulse_width(SERVO_GPIO, 0); // Stop PWM
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

