#define MEASUREMENT_DELAY_MS 100 // 100 ms delay between measurements
#define MIN_DISTANCE 2.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0      // Maximum measurable distance in cm
#define MIN_ANGLE 0.0          // Minimum servo angle in degrees
#define MAX_ANGLE 180.0        // Maximum servo angle in degrees

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Stopping servo and exiting...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map the distance to a servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return 0;
    } else if (distance > MAX_DISTANCE) {
        return 180;
    } else {
        // Linear interpolation
        float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
        return (int)angle;
    }
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    // Calculate pulse width based on angle
    int pulse_width = 500 + (angle * 2000 / 180); // Map 0-180 to 500-2500

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic Servo Control Program\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the distance
        float distance = measure_distance();

        // Map the distance to a servo angle
        int angle = map_distance_to_angle(distance);

        // Set the servo angle
        set_servo_angle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Delay before the next measurement
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us
    }

    // Stop the servo
    set_servo_angle(0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

