#include <pigpio.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Configuration register value for temperature measurement
#define CONFIG_TEMP 0xE3

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si7005 sensor
int initialize_sensor() {
    // Configure the sensor for temperature measurement
    if (i2cWriteByteData(i2c_handle, 0xE3, 0x00) < 0) {
        fprintf(stderr, "Error writing to configuration register.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data
int read_sensor(float *temperature, float *humidity) {
    unsigned char data[2];
    int result;

    // Read temperature data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Read humidity data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, 0x01, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int raw_temperature = (data[0] << 8) | data[1];
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    // Convert raw data to humidity (%RH)
    int raw_humidity = (data[0] << 8) | data[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor(&temperature, &humidity) == 0) {
            // Log the data
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

