int validate_crc(uint8_t data[], int index);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from the SHT40 sensor
int read_sensor(uint8_t *data) {
    char cmd[1] = {MEASURE_CMD};
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (at least 10 ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int index) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < 2; i++) {
        crc ^= data[index + i];
        for (int j = 0; j < 8; j++) {
            bit = crc & 0x80;
            if (bit) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc = (crc << 1);
            }
        }
    }

    if (crc != data[index + 2]) {
        fprintf(stderr, "CRC check failed for temperature/humidity at byte %d\n", index + 2);
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Convert raw humidity to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Log temperature and humidity data
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("%s Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C communication
    if (init_i2c() != 0) {
        return 1;
    }

    uint8_t sensor_data[6];
    float temperature, humidity;
    int retry_count = 0;
    const int max_retries = 3;

    while (1) {
        if (read_sensor(sensor_data) == 0) {
            // Validate CRC checksums
            if (validate_crc(sensor_data, 0) == 0 && validate_crc(sensor_data, 2) == 0) {
                // Convert raw data to temperature and humidity
                uint16_t raw_temp = (sensor_data[0] << 8) | sensor_data[1];
                uint16_t raw_humidity = (sensor_data[3] << 8) | sensor_data[4];

                temperature = convert_temperature(raw_temp);
                humidity = convert_humidity(raw_humidity);

                // Log the data
                log_data(temperature, humidity);
            } else {
                fprintf(stderr, "CRC validation failed. Retrying...\n");
                i2cClose(i2c_handle);
                gpioDelay(100); // Wait before retrying
                if (init_i2c() != 0) {
                    fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                    break;
                }
                retry_count = 0; // Reset retry count after successful re-initialization
            }
        } else {
            fprintf(stderr, "Sensor read failed. Retrying...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before retrying
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup before exiting
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

