    if (raw_ambient < 0) {
        fprintf(stderr, "Failed to read ambient temperature: %d\n", raw_ambient);
        return -1;
    }

    raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
    if (raw_object < 0) {
        fprintf(stderr, "Failed to read object temperature: %d\n", raw_object);
        return -1;
    }

    *ambient_temp = (float)raw_ambient * TEMP_SCALE - TEMP_OFFSET;
    *object_temp = (float)raw_object * TEMP_SCALE - TEMP_OFFSET;

    return 0;
}

