        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fclose(log_file);

    return 0;
}

