    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    float ambient_temp, object_temp;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&ambient_temp, &object_temp) == 0) {
            if (log_data(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

