#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_HIGH_REPEATABILITY 0x2C06
#define ERROR_LOG_FILE "error_log.txt"
#define TEMP_LOG_FILE "enclosure_temp_log.txt"

int i2c_handle;

// Function to handle errors
void handle_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Failed to open error log file");
    }
}

// Function to read temperature from STS30-DIS sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cWriteByteData(i2c_handle, MEASURE_HIGH_REPEATABILITY >> 8, MEASURE_HIGH_REPEATABILITY & 0xFF);
    if (result != 0) {
        handle_error("Failed to write measurement command");
        return -1000.0; // Indicate error
    }

    gpioDelay(20); // Wait for measurement (at least 15ms)

    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result != 2) {
        handle_error("Failed to read temperature data");
        return -1000.0; // Indicate error
    }

    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    float temperature = -45.0 + (175.0 * raw_temp / 65535.0);
    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    FILE *fp = fopen(TEMP_LOG_FILE, "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f °C\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
        fclose(fp);
    } else {
        perror("Failed to open temperature log file");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        handle_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            handle_error("Failed to read temperature");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    return 0; // This line will not be reached due to the infinite loop, but it's good practice to include it.
}

