#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_INTERVAL_SEC 1
#define DATA_FRAME_LENGTH 9
#define CRC8_POLYNOMIAL 0x31
#define SDP810_SCALE_FACTOR 60.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(unsigned char *data);
int validate_crc(unsigned char data[], int index, unsigned char crc);
sensor_data_t convert_data(unsigned char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the SDP810 sensor for continuous measurement
int configure_sensor() {
    unsigned char command[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to configure sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP810
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_LENGTH);
    if (result != DATA_FRAME_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(unsigned char data[], int index, unsigned char crc) {
    unsigned char crc_calculated = 0xFF;
    unsigned char data_to_crc = data[index];

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_to_crc;
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(unsigned char *data) {
    sensor_data_t sensor_data;
    int16_t pressure_raw = (data[0] << 8) | data[1];
    int16_t temperature_raw = (data[3] << 8) | data[4];
    int16_t scale_factor_raw = (data[6] << 8) | data[7];

    sensor_data.pressure = (float)pressure_raw / SDP810_SCALE_FACTOR;
    sensor_data.temperature = (float)temperature_raw / SDP810_SCALE_FACTOR;

    return sensor_data;
}

// Log data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ + null terminator

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fclose(log_file);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[DATA_FRAME_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 0, data[1]) &&
                validate_crc(data, 3, data[4]) &&
                validate_crc(data, 6, data[7])) {
                // Convert data
                sensor_data = convert_data(data);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for the next measurement interval
        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

