#define SI7015_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int read_sensor_data(int handle, uint8_t command, uint16_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %s\n", bus, addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read sensor data with retry mechanism
int read_sensor_data(int handle, uint8_t command, uint16_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(handle, command);
        if (result < 0) {
            fprintf(stderr, "Failed to write command 0x%02x to I2C: %s\n", command, strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(20000); // Wait for measurement (20ms)

        result = i2cReadDevice(handle, (char *)data, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read data from I2C: %s\n", strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity to percentage relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to log data to a file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(i2c_handle, TEMP_CMD, &raw_temperature) == 0) {
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(i2c_handle, HUMID_CMD, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Log data
        if (log_data(log_file, temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Print to console
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

