#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDRESS 0x25

// Define the trigger command for continuous measurement
#define TRIGGER_COMMAND_MSB 0x36
#define TRIGGER_COMMAND_LSB 0x15

// Define the number of bytes to read from the sensor
#define NUM_BYTES_TO_READ 9

// Define the CRC polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C file descriptor and program state
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_write_byte(int fd, uint8_t data);
int i2c_read_bytes(int fd, uint8_t *data, int len);
int sdp800_trigger_measurement(int fd);
int sdp800_read_data(int fd, uint8_t *data);
int sdp800_validate_crc(uint8_t *data, int index);
sensor_data_t sdp800_convert_data(uint8_t *data);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t data) {
    uint8_t buffer[2];
    buffer[0] = TRIGGER_COMMAND_MSB;
    buffer[1] = data;

    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read bytes from the I2C device
int i2c_read_bytes(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to trigger continuous measurement on the SDP800-500Pa sensor
int sdp800_trigger_measurement(int fd) {
    if (i2c_write_byte(fd, TRIGGER_COMMAND_LSB) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    usleep(45000); // Wait 45 ms
    return 0;
}

// Function to read data from the SDP800-500Pa sensor
int sdp800_read_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, data, NUM_BYTES_TO_READ) != 0) {
        fprintf(stderr, "Failed to read data\n");
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int sdp800_validate_crc(uint8_t *data, int index) {
    uint8_t crc = 0xFF;
    uint8_t data_to_check[2];

    // Extract the data to check for CRC
    data_to_check[0] = data[index];
    data_to_check[1] = data[index + 1];

    // Calculate CRC
    for (int i = 0; i < 2; i++) {
        crc ^= data_to_check[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    // Compare calculated CRC with received CRC
    if (crc != data[index + 2]) {
        fprintf(stderr, "CRC validation failed at index %d\n", index);
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t sdp800_convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // Apply scale factor
    float pressure = (float)raw_pressure / (float)raw_scale_factor;
    float temperature = (float)raw_temperature / (float)raw_scale_factor;

    // Apply offset (if needed, according to datasheet)
    //pressure += offset_pressure;
    //temperature += offset_temperature;

    sensor_data.pressure = pressure;
    sensor_data.temperature = temperature;

    return sensor_data;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    FILE *fp = fopen("airflow_data.txt", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        uint8_t data[NUM_BYTES_TO_READ];
        sensor_data_t sensor_data;

        // Trigger measurement
        if (sdp800_trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            usleep(100000); // Wait 100 ms before retrying
            continue;
        }

        // Read data from sensor
        if (sdp800_read_data(i2c_fd, data) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            usleep(100000); // Wait 100 ms before retrying
            continue;
        }

        // Validate CRC for each word
        if (sdp800_validate_crc(data, 0) != 0 ||
            sdp800_validate_crc(data, 3) != 0 ||
            sdp800_validate_crc(data, 6) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            usleep(100000); // Wait 100 ms before retrying
            continue;
        }

        // Convert data to pressure and temperature
        sensor_data = sdp800_convert_data(data);

        // Log data
        if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
        }

        usleep(100000); // Wait 100 ms
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

