volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    uint16_t temp_raw, hum_raw;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, MEASURE_HIGH_REPEATABILITY_CMD, 0) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Validate CRC for temperature
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC error.\n");
        return -1;
    }

    // Validate CRC for humidity
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC error.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    temp_raw = (data[0] << 8) | data[1];
    hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

