#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define DATA_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int index);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void timestamp_data(time_t timestamp, float pressure, float temperature, char *timestamp_str);
int write_data_to_file(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send measurement command to the sensor
int send_measurement_command() {
    uint8_t command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int index) {
    uint8_t crc = 0xFF;
    uint8_t data_to_check[2];
    data_to_check[0] = data[index];
    data_to_check[1] = data[index + 1];

    for (int i = 0; i < 2; i++) {
        crc ^= data_to_check[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != 0) {
        fprintf(stderr, "CRC check failed at byte %d\n", index);
        return -1;
    }
    return 0;
}

// Convert raw pressure data to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 240.0f; // Sensitivity of SDP800-500Pa is 240 Pa/LSB
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0f; // Sensitivity of SDP800-500Pa is 200 °C/LSB
}

// Timestamp data
void timestamp_data(time_t timestamp, float pressure, float temperature, char *timestamp_str) {
    struct tm *timeinfo;
    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Write data to file
int write_data_to_file(const char *timestamp, float pressure, float temperature) {
    if (data_file == NULL) {
        fprintf(stderr, "Data file is not open\n");
        return -1;
    }

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(data_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
