    uint8_t crc = 0xFF;
    uint8_t data_to_check[2];
    data_to_check[0] = data[index];
    data_to_check[1] = data[index + 1];

    for (int i = 0; i < 2; i++) {
        crc ^= data_to_check[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
