#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float temperature[BUFFER_SIZE];
    time_t timestamp[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t temp_buffer;

// Function prototypes
int init_i2c();
float read_temperature();
void control_fan(float temperature);
void add_to_buffer(float temperature);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from Si7021 sensor
float read_temperature() {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
            return temperature;
        } else {
            fprintf(stderr, "Error reading temperature data: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", I2C_RETRY_COUNT);
    return -100.0; // Indicate error
}

// Control the cooling fan based on temperature
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Temperature: %.2f\u00b0C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f\u00b0C)\n", temperature);
    }
}

// Add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    time_t now = time(NULL);
    temp_buffer.temperature[temp_buffer.head] = temperature;
    temp_buffer.timestamp[temp_buffer.head] = now;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < temp_buffer.count; i++) {
        int index = (temp_buffer.head - temp_buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&temp_buffer.timestamp[index]));
        printf("[%s] Temperature: %.2f\u00b0C\n", time_str, temp_buffer.temperature[index]);
    }
    printf("-----------------------\n");
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&temp_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0) { // Check for valid temperature reading
            add_to_buffer(temperature);
            control_fan(temperature);
            print_buffer();
        } else {
            fprintf(stderr, "Error reading temperature. Skipping fan control and buffer update.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

