#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_connection(int bus, int addr);
int write_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
int verify_crc(unsigned char data[], int index, unsigned char checksum);
int parse_data(unsigned char *data, int *co2, float *temperature, float *humidity);
int log_data(FILE *fp, int co2, float temperature, float humidity);
void signal_handler(int signal);
int start_periodic_measurement(int handle);
int read_measurement(int handle, int *co2, float *temperature, float *humidity);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write command to SCD40
int write_command(int handle, unsigned short command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC
int verify_crc(unsigned char data[], int index, unsigned char checksum) {
    unsigned char crc = 0xFF;
    unsigned char data_byte = data[index];

    for (int i = 0; i < 2; i++) {
        crc ^= data_byte;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
            data_byte >>= 1;
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "CRC check failed at byte %d, expected 0x%02X, got 0x%02X\n", index, checksum, crc);
        return -1;
    }
    return 0;
}

// Parse data
int parse_data(unsigned char *data, int *co2, float *temperature, float *humidity) {
    *co2 = (data[0] << 8) | data[1];
    *temperature = -45 + 175 * ((data[3] << 8) | data[4]) / 65535;
    *humidity = 100 * ((data[6] << 8) | data[7]) / 65535;
    return 0;
}

// Log data to file
int log_data(FILE *fp, int co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co2, temperature, humidity);
    fflush(fp);
    return 0;
}

// Start periodic measurement
int start_periodic_measurement(int handle) {
    return write_command(handle, CMD_START_PERIODIC_MEASUREMENT);
}

// Read measurement
int read_measurement(int handle, int *co2, float *temperature, float *humidity) {
    unsigned char data[9];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (write_command(handle, CMD_READ_MEASUREMENT) == 0) {
            gpioDelay(1); // Small delay after writing the read command
            if (read_data(handle, data, 9) == 0) {
                if (verify_crc(data, 0, data[2]) == 0 &&
                    verify_crc(data, 3, data[5]) == 0 &&
                    verify_crc(data, 6, data[8]) == 0) {
                    return parse_data(data, co2, temperature, humidity);
                } else {
                    fprintf(stderr, "CRC verification failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read measurement data\n");
            }
