int read_scd40(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    char read_buf[9];
    int result;

    // Read measurement command
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return 1;
    }

    gpioDelay(1); // Wait for the command to be processed

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return 1;
    }

    // Validate CRC and extract data
    uint16_t co2_raw = (read_buf[0] << 8) | read_buf[1];
    uint16_t temp_raw = (read_buf[3] << 8) | read_buf[4];
    uint16_t hum_raw = (read_buf[6] << 8) | read_buf[7];

    validate_crc(co2_raw, read_buf[2]);
    validate_crc(temp_raw, read_buf[5]);
    validate_crc(hum_raw, read_buf[8]);

    *co2 = co2_raw;
    *temperature = -45 + 175 * ((float)temp_raw / 65535.0);
    *humidity = 100 * ((float)hum_raw / 65535.0);

    return 0;
}

// Validate CRC-8 checksum
void validate_crc(uint16_t data, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
