        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "CRC validation failed: expected 0x%02X, got 0x%02X\n", checksum, crc);
        exit(1);
    }
}

// Add data to circular buffer
void add_to_buffer(uint16_t co2, float temperature, float humidity) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("Index: %d, Timestamp: %ld, CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
