    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);

    // Stop periodic measurement
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, buf, 2);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_PIN, 0);
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input to avoid leaving it high

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

