#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement command
#define CRC_POLYNOMIAL 0x31
#define CSV_FILE "airflow.csv"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int handle, unsigned char *data) {
    if (i2cWriteByteData(handle, 0, MEASURE_CMD >> 8) < 0) {
        fprintf(stderr, "Error writing MSB of command.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, 0, MEASURE_CMD & 0xFF) < 0) {
        fprintf(stderr, "Error writing LSB of command.\n");
        return -1;
    }
    gpioDelay(45); // Wait for conversion
    if (i2cReadI2CBlockData(handle, 0, (char *)data, 9) != 9) {
        fprintf(stderr, "Error reading data from sensor.\n");
        return -1;
    }
    return 0;
}

// Function to validate CRC checksums
int validate_crc(const unsigned char *data, int len) {
    for (int i = 0; i < len; i += 2) {
        unsigned char crc_data = data[i];
        unsigned char crc_check = data[i + 1];
        unsigned char calculated_crc = crc8(data + i, 2);
        if (calculated_crc != crc_check) {
            fprintf(stderr, "CRC check failed at byte %d. Expected 0x%02X, got 0x%02X\n", i, crc_check, calculated_crc);
            return -1;
        }
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
void convert_data(const unsigned char *data, float *pressure, float *temperature) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    *pressure = (float)raw_pressure / (float)raw_scale_factor;
    *temperature = (float)raw_temperature / 200.0;
}

// Function to log data to a CSV file
int log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char data[9];
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, data) == 0) {
            if (validate_crc(data, 9) == 0) {
                convert_data(data, &pressure, &temperature);
                log_data(pressure, temperature);
            } else {
                fprintf(stderr, "CRC validation failed.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed.\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

