#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2C06 // Single shot, high repeatability, clock stretching disabled
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL 5 // seconds
#define CSV_FILE "environment.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_data(int handle, const char *data, int count);
int read_i2c_data(int handle, char *data, int count);
int validate_crc(const char *data, int len);
int read_sht35(int handle, float *temperature, float *humidity);
int log_data(const char *timestamp, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c_data(int handle, const char *data, int count) {
    int result = i2cWriteDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(const char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Read temperature and humidity from SHT35 sensor
int read_sht35(int handle, float *temperature, float *humidity) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char data[6];

    if (write_i2c_data(handle, cmd, 2) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }
    gpioDelay(15); // Wait at least 15 ms

    if (read_i2c_data(handle, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Validate CRC checksums
    if (!validate_crc(data, 2) || !validate_crc(data + 3, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * temperature_raw) / 65535.0;
    *humidity = 100.0 * humidity_raw / 65535.0;

    return 0;
}

// Log data to CSV file
int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Humidity (%%)\n");
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

