    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SHT35_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
