    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        handle_error("ERROR: Temperature read failed");
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    // Measure humidity
    result = i2cWriteByte(i2c_handle, MEASURE_HUMID_CMD);
    if (result != 0) {
        handle_error("ERROR: Humidity measurement command failed");
        return -1;
    }
    gpioDelay(100); // Wait for measurement (datasheet specifies 10ms)

    result = i2cReadDevice(i2c_handle, buf, 2);
