    unsigned char data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    unsigned char crc_calc = 0xFF;
    unsigned char polynomial = CRC_POLYNOMIAL;

    for (int i = 0; i < 2; i++) {
        crc_calc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calc & 0x80) {
                crc_calc = (crc_calc << 1) ^ polynomial;
            } else {
                crc_calc <<= 1;
            }
        }
    }

    return (crc_calc != crc);
}

