    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        handle_error("ERROR: Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), ISO8601_FORMAT, &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, temperature, humidity);
    fclose(fp);

    return 0;
}

