    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            // CRC verification
            if (verify_crc(sensor_data.temperature, 0) || verify_crc(sensor_data.humidity, 0)) {
                if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                    handle_error("ERROR: Failed to log data");
                }
            } else {
                handle_error("ERROR: CRC verification failed");
            }
        } else {
            handle_error("ERROR: Failed to read sensor data");
        }

        gpioDelay(SLEEP_DURATION_US); // Sleep for 5 seconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

