#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define FILE_NAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    fp = fopen(FILE_NAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor(float *pressure, float *temperature) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_COMMAND >> 8, MEASURE_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    // Wait for conversion time (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t pressure_crc = buffer[2];
    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};
    uint8_t temperature_crc = buffer[5];
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    *pressure = (float)raw_pressure / 30.0; // Pa
    *temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Function to log data to file
int log_data(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    float pressure, temperature;

    // Main loop
    while (!terminate) {
        if (read_sensor(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

