// Constants
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, float *pressure);
float calculate_flow_rate(int raw_pressure);
void set_fan_speed(int gpio, float flow_rate);
void log_data(const char *filename, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to read the sensor data
int read_sensor(int i2c_handle, float *pressure) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate failure
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert raw pressure to Pascals (Pa) - Refer to HAFBLF0100A2AX5 datasheet
    *pressure = (float)raw_pressure * 0.01; // Example conversion, adjust as needed

    return 0; // Indicate success
}

// Function to calculate the flow rate in LPM
float calculate_flow_rate(int raw_pressure) {
    // Linear relationship: flow_rate = (raw_pressure - offset) / scale
    // Example: flow_rate = (raw_pressure - 0) / 1000.0  // Adjust offset and scale as needed
    float flow_rate = (float)raw_pressure / 1000.0; // Example calculation
    return flow_rate;
}

// Function to set the fan speed using PWM
void set_fan_speed(int gpio, float flow_rate) {
    // Map flow rate to PWM duty cycle (0-255)
    int duty_cycle = (int)(flow_rate * 2.55); // Scale flow rate to 0-255
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(gpio, duty_cycle);
}

// Function to log the data to a file
void log_data(const char *filename, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

