    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure;
    // Main loop
    while (!terminate) {
        if (read_sensor(i2c_handle, &pressure) == 0) {
            float flow_rate = calculate_flow_rate((int)pressure);
            set_fan_speed(FAN_GPIO, flow_rate);
            log_data(LOG_FILE, pressure);
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    fclose(log_file);
    gpioTerminate();

    return 0;
}

