#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(float *pressure);
int read_temperature(float *temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Initialize LPS33HW sensor
int init_lps33hw() {
    // Enable continuous data acquisition (ODR = 100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read pressure data from LPS33HW
int read_pressure(float *pressure) {
    char buffer[3];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    int32_t raw_pressure = (buffer[2] << 16) | (buffer[1] << 8) | buffer[0];
    *pressure = (float)raw_pressure / 4096.0; // Convert to hPa

    return 0;
}

// Read temperature data from LPS33HW
int read_temperature(float *temperature) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    int16_t raw_temperature = (buffer[1] << 8) | buffer[0];
    *temperature = (float)raw_temperature / 100.0; // Convert to °C

    return 0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
