#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Ventilation control states
#define VENTILATION_OFF 0
#define VENTILATION_LOW 1
#define VENTILATION_HIGH 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int init_scd30(int i2c_handle);
int read_scd30_data(int i2c_handle, float *co2, float *temperature, float *humidity);
int process_data(float co2, float temperature, float humidity);
int control_ventilation(float co2);
int log_data(float co2, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8-ATM checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    float co2, temperature, humidity;
    int ventilation_state;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(1, SCD30_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30(i2c_handle) != 0) {
        fprintf(stderr, "Failed to initialize SCD30 sensor. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from SCD30
        if (read_scd30_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            // Process data
            ventilation_state = process_data(co2, temperature, humidity);

            // Log data
            log_data(co2, temperature, humidity);

            // Control ventilation
            if (ventilation_state == VENTILATION_HIGH) {
                printf("CO2 level high. Activating ventilation.\n");
            } else if (ventilation_state == VENTILATION_LOW) {
                printf("CO2 level moderate. Ventilation set to low.\n");
            } else {
                printf("CO2 level normal. Ventilation OFF.\n");
            }
        } else {
            fprintf(stderr, "Failed to read SCD30 data. Retrying in 5 seconds.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

int init_scd30(int i2c_handle) {
    // Start periodic measurement
    char buf[2];
    buf[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to be ready
    return 0;
}

int read_scd30_data(int i2c_handle, float *co2, float *temperature, float *humidity) {
    char buf[2];
    unsigned char data[18];
    int result;

    // Read measurement command
    buf[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    // Read 18 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC check
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8] ||
        crc8(data + 9, 2) != data[11] ||
        crc8(data + 12, 2) != data[14] ||
        crc8(data + 15, 2) != data[17]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data to float
    *co2 = (float)((data[0] << 8) | data[1]);
    *temperature = (float)((data[3] << 8) | data[4]);
    *humidity = (float)((data[6] << 8) | data[7]);

    return 0;
}

int process_data(float co2, float temperature, float humidity) {
    if (co2 < 800) {
        return VENTILATION_OFF;
    } else if (co2 < 1200) {
        return VENTILATION_LOW;
    } else {
        return VENTILATION_HIGH;
    }
}

int control_ventilation(float co2) {
    if (co2 < 800) {
        return VENTILATION_OFF;
    } else if (co2 < 1200) {
        return VENTILATION_LOW;
    } else {
        return VENTILATION_HIGH;
    }
}

int log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up resources.\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

