int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

int init_scd30(int i2c_handle) {
    // Start periodic measurement
    char buf[2];
    buf[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to be ready
    return 0;
}

int read_scd30_data(int i2c_handle, float *co2, float *temperature, float *humidity) {
    char buf[2];
    unsigned char data[18];
    int result;

    // Read measurement command
    buf[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    // Read 18 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC check
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8] ||
        crc8(data + 9, 2) != data[11] ||
        crc8(data + 12, 2) != data[14] ||
        crc8(data + 15, 2) != data[17]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data to float
    *co2 = (float)((data[0] << 8) | data[1]);
    *temperature = (float)((data[3] << 8) | data[4]);
    *humidity = (float)((data[6] << 8) | data[7]);

    return 0;
}

int process_data(float co2, float temperature, float humidity) {
    if (co2 < 800) {
        return VENTILATION_OFF;
    } else if (co2 < 1200) {
        return VENTILATION_LOW;
    } else {
        return VENTILATION_HIGH;
    }
}

int control_ventilation(float co2) {
    if (co2 < 800) {
        return VENTILATION_OFF;
    } else if (co2 < 1200) {
        return VENTILATION_LOW;
    } else {
        return VENTILATION_HIGH;
    }
}

int log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up resources.\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

