#include <pigpio.h>
#include <stdint.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the trigger command for continuous measurement
#define TRIGGER_CMD_1 0x36
#define TRIGGER_CMD_2 0x15

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handle and program state
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
void validate_crc(const uint8_t *data, int len);
void convert_data(const uint8_t *data, sensor_data_t *sensor_data);
void log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger continuous measurement
int trigger_measurement() {
    uint8_t cmd[2] = {TRIGGER_CMD_1, TRIGGER_CMD_2};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
void validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i += 3) {
        uint8_t data_word[3] = {data[i], data[i + 1], data[i + 2]};
        uint8_t calculated_crc = crc8(data_word, 3);
        if (calculated_crc != data[i + 2]) {
            fprintf(stderr, "CRC mismatch at byte %d\n", i + 3);
            exit(EXIT_FAILURE);
        }
        crc = calculated_crc;
    }
}

// Convert raw data to pressure and temperature
void convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Apply scale factors (from datasheet)
    sensor_data->pressure = (float)raw_pressure / 60.0; // Pa
    sensor_data->temperature = (float)raw_temperature / 200.0; // °C
}

// Log data to stdout
void log_data(const sensor_data_t *sensor_data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", sensor_data->pressure, sensor_data->temperature);
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C communication
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    uint8_t sensor_data_raw[9];
    sensor_data_t sensor_data;

    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        gpioDelay(45000); // Wait for conversion (45 ms)

        // Read sensor data
        if (read_sensor_data(sensor_data_raw) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Validate CRC checksum
        validate_crc(sensor_data_raw, 9);

        // Convert data
        convert_data(sensor_data_raw, &sensor_data);

        // Log data
        log_data(&sensor_data);

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

