#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Temperature reading function
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (10ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        unsigned int raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

// Temperature logging function
void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

