// ICP-10101 register addresses
#define ICP10101_WHO_AM_I 0x0F
#define ICP10101_RESET 0x1B
#define ICP10101_MEASURE 0x06
#define ICP10101_TEMP_MSB 0x03
#define ICP10101_TEMP_LSB 0x04
#define ICP10101_PRESS_MSB 0x00
#define ICP10101_PRESS_LSB 0x01
#define ICP10101_PRESS_XLSB 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *temperature, float *pressure);
void process_sensor_data(unsigned char *data, float *temperature, float *pressure);
void print_sensor_data(float temperature, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ICP-10101 sensor
int initialize_sensor() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, ICP10101_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x41\n", who_am_i);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10101_RESET, 0x80) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    return 0;
}

// Read temperature and pressure data from the sensor
int read_sensor_data(float *temperature, float *pressure) {
    unsigned char data[6];
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, ICP10101_MEASURE, 0x07); // High resolution mode
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(7); // Wait for measurement to complete

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, ICP10101_PRESS_MSB, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Process the data
    process_sensor_data(data, temperature, pressure);

    return 0;
}

// Process the raw sensor data
void process_sensor_data(unsigned char *data, float *temperature, float *pressure) {
    int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    // Convert raw data to temperature and pressure (example formulas, adjust as needed)
    *temperature = (float)raw_temperature / 100.0; // Example conversion
    *pressure = (float)raw_pressure / 100.0;       // Example conversion
}

// Print the sensor data with timestamp
void print_sensor_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, pressure;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &pressure) == 0) {
            print_sensor_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

