#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C address of the MLX90819 sensor
#define MLX90819_ADDR 0x60

// Define the register address for pressure data (replace with actual value)
#define PRESSURE_REG 0x01

// Define the I2C bus number (typically 1 for Raspberry Pi)
#define I2C_BUS 1

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close the I2C device if it's open
    if (i2c_fd != -1)
    {
        i2cClose(i2c_fd);
        printf("I2C device closed.\n");
    }

    // Terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to read pressure from the MLX90819 sensor
int read_pressure(int i2c_fd)
{
    char buf[2];
    int result;

    // Read two bytes from the pressure register
    result = i2cReadI2CBlockData(i2c_fd, PRESSURE_REG, buf, 2);

    if (result != 2)
    {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit integer
    int pressure = (buf[0] << 8) | buf[1];

    return pressure;
}

// Function to get the current timestamp in ISO 8601 format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_fd = i2cOpen(I2C_BUS, MLX90819_ADDR, 0);

    if (i2c_fd < 0)
    {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and print pressure data
    while (1)
    {
        int pressure = read_pressure(i2c_fd);

        if (pressure != -1)
        {
            char timestamp[21];
            get_timestamp(timestamp);
            printf("%s Pressure: %d Pa\n", timestamp, pressure);
        }
        else
        {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

