#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Trigger measurement command
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00
#define SAMPLE_INTERVAL_MS 45
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(unsigned char *data);
int validate_crc(const unsigned char *data, int index);
sensor_data_t process_sensor_data(const unsigned char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const unsigned char *data, int index) {
    unsigned char crc = data[index];
    unsigned char polynomial = CRC_POLYNOMIAL;
    unsigned char data_byte = data[index + 1];

    for (int i = 0; i < 8; i++) {
        unsigned char discrepancy = (crc ^ data_byte) & 0x01;
        polynomial >>= 1;
        if (polynomial & 0x80) {
            polynomial ^= CRC_POLYNOMIAL;
        }
        crc >>= 1;
        if (discrepancy) {
            crc ^= 0x01;
        }
        data_byte >>= 1;
    }

    return (crc != 0);
}

// Process sensor data
sensor_data_t process_sensor_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    int16_t differential_pressure_raw = (data[0] << 8) | data[1];
    int16_t temperature_raw = (data[3] << 8) | data[4];

    sensor_data.pressure = (float)differential_pressure_raw / 50.0; // Pa
    sensor_data.temperature = (float)temperature_raw / 200.0; // °C

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    unsigned char sensor_data[9];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for measurement

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(sensor_data, 0) || validate_crc(sensor_data, 2) || validate_crc(sensor_data, 4)) {
            fprintf(stderr, "CRC validation failed, discarding data\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process sensor data
        processed_data = process_sensor_data(sensor_data);

        // Log data
        if (log_data(processed_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next measurement
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

