                uint16_t raw_pressure = (data[0] << 8) | data[1];
                uint8_t crc = data[2];

                // CRC check
                uint8_t crc_calculated = crc8(data, 2);
                if (crc_calculated != crc) {
                    fprintf(stderr, "CRC check failed!\n");
                    continue; // Skip to the next iteration
                }

                float pressure = convert_pressure(raw_pressure);
                if (log_data(pressure) != 0) {
                    fprintf(stderr, "Error logging data!\n");
