        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the HIH6130 sensor
int read_hih6130(float *temperature, float *humidity) {
    char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(40); // Wait 40ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate status bits
    if ((buf[0] & 0xC0) != 0) {
        fprintf(stderr, "Error: Sensor status indicates an issue (0x%02X)\n", buf[0]);
        return -1;
    }

    // Convert data to temperature and humidity
    unsigned int humidity_raw = ((buf[0] & 0x3F) << 8) | buf[1];
    unsigned int temperature_raw = (buf[2] << 6) | (buf[3] >> 2);

    *humidity = ((float)humidity_raw / 16383) * 100;
    *temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return 0;
}

