#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1MB

int i2c_handle;
FILE *log_file;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the HIH6130 sensor
int read_hih6130(float *temperature, float *humidity) {
    char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(40); // Wait 40ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate status bits
    if ((buf[0] & 0xC0) != 0) {
        fprintf(stderr, "Error: Sensor status indicates an issue (0x%02X)\n", buf[0]);
        return -1;
    }

    // Convert data to temperature and humidity
    unsigned int humidity_raw = ((buf[0] & 0x3F) << 8) | buf[1];
    unsigned int temperature_raw = (buf[2] << 6) | (buf[3] >> 2);

    *humidity = ((float)humidity_raw / 16383) * 100;
    *temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return 0;
}

// Function to log data to a file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%dT%H:%M:%SZ", t);

    // Check if the log file exceeds the maximum size
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size > MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for truncation: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

