// Define GPIO pin for SENT data
#define SENT_GPIO 4

// Define SENT timing constants (in microseconds)
#define SYNC_PULSE_MIN 36
#define SYNC_PULSE_MAX 813
#define DATA_PULSE_MIN 12
#define DATA_PULSE_MAX 271
#define CHECKSUM_PULSE_MIN 12
#define CHECKSUM_PULSE_MAX 271

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 500

// Define checksum calculation function
unsigned char calculate_checksum(unsigned char data1, unsigned char data2, unsigned char data3) {
    return data1 + data2 + data3;
}

// Define error handling function
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Define signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Define function to read SENT data
int read_sent_data(unsigned int *status, unsigned int *data1, unsigned int *data2, unsigned int *data3, unsigned int *checksum) {
    unsigned int start_tick, end_tick, pulse_width;
    unsigned int sync_pulse_count = 0;
    unsigned int data_pulse_count = 0;
    unsigned int checksum_pulse_count = 0;
    unsigned int last_tick = 0;
    unsigned int current_tick;

    // Wait for the start of the SENT frame (falling edge)
    while (gpioRead(SENT_GPIO) == 1 && (current_tick = gpioTick()) < TIMEOUT_DURATION * 1000) {
        // Wait for a short time to avoid busy-waiting
        gpioDelay(1); // Delay for 1 microsecond
    }

    if (gpioRead(SENT_GPIO) == 1) {
        handle_error("Timeout waiting for SENT start pulse.");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Read the sync pulse
    while (gpioRead(SENT_GPIO) == 0 && (current_tick = gpioTick()) < start_tick + TIMEOUT_DURATION * 1000) {
        // Wait for a short time to avoid busy-waiting
        gpioDelay(1); // Delay for 1 microsecond
    }

    if (gpioRead(SENT_GPIO) == 0) {
        handle_error("Timeout waiting for SENT sync pulse.");
        return -1; // Timeout error
    }

    end_tick = gpioTick();
    sync_pulse_count = end_tick - start_tick;

    // Read the status nibble
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1 && (current_tick = gpioTick()) < start_tick + TIMEOUT_DURATION * 1000) {
        // Wait for a short time to avoid busy-waiting
        gpioDelay(1); // Delay for 1 microsecond
    }

    if (gpioRead(SENT_GPIO) == 1) {
        handle_error("Timeout waiting for SENT status nibble.");
        return -1; // Timeout error
    }

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < DATA_PULSE_MIN || pulse_width > DATA_PULSE_MAX) {
        handle_error("Invalid status nibble pulse width.");
        return -1; // Invalid pulse width
    }

    // Read the data nibbles
    *status = 0;
    for (int i = 0; i < 4; i++) {
        start_tick = gpioTick();
        while (gpioRead(SENT_GPIO) == 0 && (current_tick = gpioTick()) < start_tick + TIMEOUT_DURATION * 1000) {
            // Wait for a short time to avoid busy-waiting
            gpioDelay(1); // Delay for 1 microsecond
        }

        if (gpioRead(SENT_GPIO) == 0) {
            handle_error("Timeout waiting for SENT data nibble.");
            return -1; // Timeout error
        }

        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;
        if (pulse_width < DATA_PULSE_MIN || pulse_width > DATA_PULSE_MAX) {
            handle_error("Invalid data nibble pulse width.");
            return -1; // Invalid pulse width
        }

        *status |= (1 << (3 - i));
    }

    // Read the checksum nibble
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1 && (current_tick = gpioTick()) < start_tick + TIMEOUT_DURATION * 1000) {
        // Wait for a short time to avoid busy-waiting
        gpioDelay(1); // Delay for 1 microsecond
    }

    if (gpioRead(SENT_GPIO) == 1) {
        handle_error("Timeout waiting for SENT checksum nibble.");
        return -1; // Timeout error
    }

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < DATA_PULSE_MIN || pulse_width > DATA_PULSE_MAX) {
        handle_error("Invalid checksum nibble pulse width.");
        return -1; // Invalid pulse width
    }

    // Read the checksum pulse
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 0 && (current_tick = gpioTick()) < start_tick + TIMEOUT_DURATION * 1000) {
        // Wait for a short time to avoid busy-waiting
        gpioDelay(1); // Delay for 1 microsecond
    }

    if (gpioRead(SENT_GPIO) == 0) {
        handle_error("Timeout waiting for SENT checksum pulse.");
        return -1; // Timeout error
    }

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < CHECKSUM_PULSE_MIN || pulse_width > CHECKSUM_PULSE_MAX) {
        handle_error("Invalid checksum pulse width.");
        return -1; // Invalid pulse width
    }

    // Calculate the checksum
    unsigned char calculated_checksum = calculate_checksum(
        (unsigned char)(*status & 0x0F),
        (unsigned char)((*status >> 4) & 0x0F),
        (unsigned char)(*status >> 8 & 0x0F),
        (unsigned char)(*status >> 12 & 0x0F)
    );

    // Verify the checksum
    if (calculated_checksum != (unsigned char)(*checksum & 0x0F)) {
        handle_error("Checksum mismatch.");
        return -1; // Checksum mismatch
    }

    return 0; // Success
}

