        handle_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(SENT_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int status, data1, data2, data3, checksum;
    float pressure;
    int result;

    // Main loop
    while (1) {
        // Read SENT data
        result = read_sent_data(&status, &data1, &data2, &data3, &checksum);

        if (result == 0) {
            // Extract pressure value
            pressure = (float)((data1 << 12) | (data2 << 8) | (data3 & 0x0F));

            // Log pressure data
            log_pressure_data(pressure);
        } else {
            handle_error("Failed to read SENT data.");
        }

        // Delay before next reading
        gpioDelay(10000); // 10 ms
    }

    // Clean up and exit (this part will not be reached in the infinite loop)
    gpioTerminate();
    return 0;
}

