int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x%04X)\n", device_id, DEVICE_ID);
        return -1;
    }

    printf("Device ID verified: 0x%04X\n", device_id);
    return 0;
}

// Read temperature from the TMP117 sensor
float read_temperature() {
    int16_t raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    float temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Log temperature to file
int log_temperature(float temperature) {
    size_t bytes_written = fwrite(&temperature, sizeof(float), 1, data_file);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Open data file for writing
    data_file = fopen(DATA_FILE, "wb");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (log_temperature(temperature) == 0) {
                printf("Temperature: %.2f °C\n", temperature);
            } else {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

