#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00
#define DATA_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c_data(int handle, uint8_t command);
int read_i2c_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t *data, int index, uint8_t crc);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c_data(int handle, uint8_t command) {
    int result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t *data, int index, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    uint8_t data_to_check[2];
    data_to_check[0] = data[index];
    data_to_check[1] = data[index + 1];

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_to_check[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

