    i2c_handle = open_i2c_device(I2C_BUS, SHT40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data collection...\n");

    while (!terminate) {
        // Send measurement command
        if (write_i2c_data(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(8500); // Wait for conversion (at least 8.5 ms)

        // Read data
        uint8_t data[6];
        if (read_i2c_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(data, 0, data[2]) || !validate_crc(data + 3, 0, data[5])) {
            fprintf(stderr, "CRC validation failed, data invalid\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];

        float temperature = convert_temperature(raw_temp);
        float humidity = convert_humidity(raw_humidity);

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Close resources
    printf("Closing resources...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

