#include <time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for the circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
void flush_buffer_to_file(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to add a temperature reading to the circular buffer
void add_to_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to flush the circular buffer to a file
void flush_buffer_to_file(CircularBuffer *cb) {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        perror("Error opening temperature_log.dat for writing");
        return;
    }

    size_t bytes_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (bytes_written != cb->count) {
        fprintf(stderr, "Error writing to temperature_log.dat: wrote %zu bytes, expected %d\n", bytes_written, cb->count);
    }

    fclose(fp);
    printf("Temperature log saved to temperature_log.dat\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

