int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature from TMP117 sensor
float read_temperature() {
    int16_t raw_temp;
    int result;

    result = i2cReadWordData(i2c_handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    raw_temp = (int16_t)result;
    return raw_temp * 0.0078125; // Convert to Celsius
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    CircularBuffer temp_buffer;
    init_buffer(&temp_buffer);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(&temp_buffer, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Flush the buffer to file before exiting
    flush_buffer_to_file(&temp_buffer);

    // Cleanup resources
    cleanup();

    return 0;
}

