#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define ROTATIONAL_SPEED_REG 0x01 // Example register address
#define TEMPERATURE_REG 0x02       // Example register address
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(float *rotational_speed, float *temperature);
int log_data(float rotational_speed, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(float *rotational_speed, float *temperature) {
    char buf[4]; // Buffer to hold raw data
    int bytes_read;
    int raw_speed, raw_temp;

    // Read rotational speed
    bytes_read = i2cReadI2CBlockData(i2c_handle, ROTATIONAL_SPEED_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read rotational speed: %d\n", bytes_read);
        *rotational_speed = NAN; // Indicate error with NaN
    } else {
        raw_speed = (buf[0] << 8) | buf[1];
        *rotational_speed = (float)raw_speed; // Example conversion
    }

    // Read temperature
    bytes_read = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", bytes_read);
        *temperature = NAN; // Indicate error with NaN
    } else {
        raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (float)raw_temp; // Example conversion
    }

    return 0;
}

// Function to log data to file
int log_data(float rotational_speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Rotational Speed (RPM),Temperature (C)\n"); // Write header
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rotational_speed, temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    float rotational_speed, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&rotational_speed, &temperature) == 0) {
            // Log data
            if (log_data(rotational_speed, temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            // Log NaN values if read fails
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Failed to log NaN values\n");
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

