#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"

int i2c_handle;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the TMP117 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate an error with a very low temperature
    }

    // Combine the two bytes into a 16-bit integer
    short raw_temp = (buf[0] << 8) | buf[1];

    // Convert the raw temperature to Celsius (0.0078125 degrees Celsius per LSB)
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C bus
    int init_attempts = 0;
    while (initialize_i2c() != 0 && init_attempts < 3) {
        fprintf(stderr, "I2C initialization failed. Retrying... (%d/3)\n", init_attempts + 1);
        gpioDelay(1000); // Wait 1 second before retrying
        init_attempts++;
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed after multiple attempts. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping log.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

