#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DHT11_PIN 4
#define LED_PIN 17

// Define constants
#define START_SIGNAL_LOW 18000  // 18 ms
#define START_SIGNAL_HIGH 4000  // 4 ms
#define BIT_LOW 500
#define BIT_HIGH_0 2600
#define BIT_HIGH_1 2800
#define CHECKSUM_SIZE 8
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold DHT11 data
typedef struct {
    int humidity_int;
    int humidity_decimal;
    int temperature_int;
    int temperature_decimal;
    int checksum;
} DHT11Data;

// Function prototypes
int initialize_gpio();
int generate_start_signal();
int read_dht11_data(DHT11Data *data);
int verify_checksum(const DHT11Data *data);
int log_data(const DHT11Data *data);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT11_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially off

    return 0;
}

// Function to generate the start signal
int generate_start_signal() {
    gpioWrite(DHT11_PIN, 0); // Low
    gpioDelay(START_SIGNAL_LOW * 1000); // Wait 18 ms
    gpioWrite(DHT11_PIN, 1); // High
    gpioDelay(START_SIGNAL_HIGH * 1000); // Wait 4 ms
    gpioWrite(DHT11_PIN, 0); // Low
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to read DHT11 data
int read_dht11_data(DHT11Data *data) {
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    int i, j;

    // Wait for the DHT11 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT11_PIN) == 1) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
        if (timeout > 100) {
            fprintf(log_file, "Error: Timeout waiting for DHT11 response (start signal low)\n");
            fflush(log_file);
            return -1;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the DHT11 to pull the line low
        timeout = 0;
        while (gpioRead(DHT11_PIN) == 1) {
            gpioDelay(1); // Wait 1 ms
            timeout++;
            if (timeout > 100) {
                fprintf(log_file, "Error: Timeout waiting for DHT11 response (start signal low)\n");
                fflush(log_file);
                return -1;
            }
        }

        // Measure the high pulse duration
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout = 0;
        while (gpioRead(DHT11_PIN) == 0) {
            gpioDelay(1); // Wait 1 ms
            timeout++;
            if (timeout > 100) {
                fprintf(log_file, "Error: Timeout waiting for DHT11 response (data bit low)\n");
                fflush(log_file);
                return -1;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        long high_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine if the bit is 0 or 1
        if (high_time > BIT_HIGH_0 && high_time < BIT_HIGH_1) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        } else {
            fprintf(log_file, "Error: Invalid DHT11 data bit\n");
            fflush(log_file);
            return -1;
        }

        // Wait for the DHT11 to pull the line low again
        timeout = 0;
        while (gpioRead(DHT11_PIN) == 1) {
            gpioDelay(1); // Wait 1 ms
            timeout++;
            if (timeout > 100) {
                fprintf(log_file, "Error: Timeout waiting for DHT11 response (data bit high)\n");
                fflush(log_file);
                return -1;
            }
        }
    }

    // Decode the data
    data->humidity_int = (raw_data[0] << 8) | raw_data[1];
    data->humidity_decimal = raw_data[2];
    data->temperature_int = (raw_data[3] << 8) | raw_data[4];
    data->temperature_decimal = 0; // Always 0
    data->checksum = (raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3] + raw_data[4]) & 0xFF;

    return 0;
}

// Function to verify the checksum
int verify_checksum(const DHT11Data *data) {
    unsigned char checksum = 0;
    unsigned char data_array[4];

    data_array[0] = data->humidity_int;
    data_array[1] = data->humidity_decimal;
    data_array[2] = data->temperature_int;
    data_array[3] = data->temperature_decimal;

    checksum = data_array[0] + data_array[1] + data_array[2] + data_array[3];

    if (checksum == data->checksum) {
        return 0; // Checksum is valid
    } else {
        fprintf(log_file, "Error: Checksum failure\n");
        fflush(log_file);
        return -1; // Checksum is invalid
    }
}

// Function to log data to a file
int log_data(const DHT11Data *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Humidity: %d, Temperature: %d\n", timestamp, data->humidity_int, data->temperature_int);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_PIN, 1); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    DHT11Data data;
    int retries = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Generate start signal
        if (generate_start_signal() != 0) {
            fprintf(log_file, "Error: Failed to generate start signal\n");
            fflush(log_file);
        } else {
            // Read DHT11 data
            if (read_dht11_data(&data) == 0) {
                // Verify checksum
                if (verify_checksum(&data) == 0) {
                    // Log data
                    log_data(&data);
                } else {
                    fprintf(log_file, "Error: Checksum verification failed\n");
                    fflush(log_file);
                }
            } else {
                fprintf(log_file, "Error: Failed to read DHT11 data\n");
                fflush(log_file);
            }
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

