int init_pigpio();
int open_i2c_device();
int write_i2c_data(int handle, uint16_t command);
int read_i2c_data(int handle, char *data, int count);
uint8_t crc8(const uint8_t *data, int len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write data to I2C device
int write_i2c_data(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, buf, 2) == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write failed, retry %d\n", retries + 1);
        gpioDelay(1000); // Wait 1 ms before retry
        retries++;
    }
    fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Read data from I2C device
int read_i2c_data(int handle, char *data, int count) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cReadDevice(handle, data, count);
        if (result == count) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read failed, retry %d\n", retries + 1);
        gpioDelay(1000); // Wait 1 ms before retry
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

