#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define sensor addresses and register addresses
#define ADPD105_ADDR_1 0x39
#define ADPD105_ADDR_2 0x38
#define ADPD105_REG_DATA_0 0x00
#define ADPD105_REG_DATA_1 0x01

// Global variables for I2C handles and file pointer
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor_data(int i2c_handle, unsigned char *data);
float calculate_cct(float c1, float c2);
int log_cct(float cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(0);
}

// Function to read sensor data from ADPD105
int read_sensor_data(int i2c_handle, unsigned char *data) {
    int result;
    result = i2cReadI2CBlockData(i2c_handle, ADPD105_REG_DATA_0, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to calculate correlated color temperature (CCT)
float calculate_cct(float c1, float c2) {
    // Implement McCamy's approximation for CCT calculation
    float X = c1 / 100.0;
    float Y = c2 / 100.0;
    float Z = 1.0 - X - Y;

    float n = (X - 0.3320) / (0.1858 - Y);
    float N = n * n;
    float CCT = 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;

    return CCT;
}

// Function to log CCT to a file
int log_cct(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, cct);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus for both sensors
    i2c_handle_1 = i2cOpen(1, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 1: %d\n", i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(1, ADPD105_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 2: %d\n", i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        unsigned char data1[2], data2[2];
        float c1, c2, avg_cct;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle_1, data1) == 0) {
            c1 = (data1[0] << 8) | data1[1];
        } else {
            c1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle_2, data2) == 0) {
            c2 = (data2[0] << 8) | data2[1];
        } else {
            c2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (c1 >= 0 && c2 >= 0) {
            avg_cct = calculate_cct((float)c1, (float)c2);
            log_cct(avg_cct);
        } else {
            fprintf(stderr, "Error: Invalid sensor data. Skipping CCT calculation.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop condition is changed.
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();
    return 0;
}

