#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_ADDR 0x43
#define TEMP_REG 0x00
#define GPIO_LED 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define MAX_I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from STTS2004 sensor
float read_temperature() {
    int raw_temp;
    int retries = 0;
    float temperature = -100.0; // Initialize with an invalid value

    while (retries < MAX_I2C_RETRIES) {
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Success
            temperature = (float)((raw_temp >> 4) * 0.0625);
            return temperature;
        } else {
            // Error
            fprintf(stderr, "I2C read error (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_I2C_RETRIES);
    return temperature; // Return the invalid value
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x43, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0) { // Check if temperature read was successful
            printf("Temperature: %.2f °C\n", temperature);
            control_led(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping LED control.\n");
        }

        gpioDelay(1000000); // Wait for 1 second (1000000 microseconds)
    }

    // Cleanup before exiting
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

