#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_HOLD_CMD 0xE3
#define MEASURE_HUMID_HOLD_CMD 0xE5
#define READ_TEMP_FROM_RH_CMD 0xE1
#define TEMP_ERROR -999.0
#define HUMID_ERROR -999.0
#define LOG_FILE "environment.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
int validate_sensor();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Validate sensor presence
int validate_sensor() {
    int id = i2cReadByteData(i2c_handle, 0x00); // Read ID register
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }

    if (id != 0x28) {
        fprintf(stderr, "Sensor ID mismatch: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;

    // Measure Relative Humidity, No Master Hold
    result = i2cWriteByteData(i2c_handle, MEASURE_HUMID_HOLD_CMD, 0);
    if (result < 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait 20ms

    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    *humidity = (125.0 * (buf[0] & 0x7F) + 125.0 * (buf[1] & 0x7F)) / 256.0;
    if (buf[0] & 0x80) {
        *humidity = -*humidity;
    }

    // Measure Temperature, No Master Hold
    result = i2cWriteByteData(i2c_handle, MEASURE_TEMP_HOLD_CMD, 0);
    if (result < 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait 20ms

    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *temperature = (175.72 * (buf[0] & 0x7F) + 175.72 * (buf[1] & 0x7F)) / 256.0;
    if (buf[0] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Validate sensor
    if (validate_sensor() != 0) {
        fprintf(stderr, "Sensor validation failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_sensor_data(&temperature, &humidity) == 0) {
                log_data(temperature, humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Sensor read failed, retrying (%d/3)...\n", retries + 1);
                gpioDelay(100); // Wait 100ms before retrying
                retries++;
            }
        }

        if (retries == 3) {
            fprintf(stderr, "Sensor read failed after 3 retries. Logging error.\n");
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
            printf("%s,ERROR,ERROR\n", timestamp);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

