#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define MEASUREMENT_REG 0x00
#define TEMP_REG 0x00
#define HUMID_REG 0x01

int i2c_handle;

// Function to initialize the HDC1080 sensor
int hdc1080_init(int i2c_handle) {
    // Configure the sensor for temperature and humidity measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure HDC1080 sensor.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1080 sensor
int hdc1080_read(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    // Trigger a measurement
    if (i2cWriteByte(i2c_handle, MEASUREMENT_REG) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }

    // Wait for at least 20 ms for conversion
    gpioDelay(20000); // 20 ms

    // Read the 4-byte data block
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error: Failed to read data from HDC1080 sensor (read %d bytes).\n", result);
        return -1;
    }

    // Convert the raw data to temperature and humidity
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    unsigned int raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log the data to a file
int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the file in append mode
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", filename);
        return -1;
    }

    // Write the data to the file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    // Close the file
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
