#define MEASURE_HIGH_REPEATABILITY 0x2C06
#define CRC8_POLYNOMIAL 0x31

int i2c_fd;
FILE *log_file;

// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
int read_sts40_temperature(int i2c_fd, float *temperature) {
    unsigned char cmd[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    unsigned char data[3];

    if (i2cWriteDevice(i2c_fd, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(10000); // Wait 10 ms for conversion

    if (i2cReadDevice(i2c_fd, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC Check
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC check failed.\n");
        return -1;
    }

    // Convert data to temperature (Celsius)
    int raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

