#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor(float *pressure, float *temperature, float *scale_factor);
int validate_crc(uint8_t data[], int len);
int log_data(float pressure, float temperature, float scale_factor);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float pressure, temperature, scale_factor;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            log_data(-1, -1, -1); // Log error
        } else {
            gpioDelay(50); // Wait for measurement

            // Read sensor data
            if (read_sensor(&pressure, &temperature, &scale_factor) == 0) {
                // Log data
                if (log_data(pressure, temperature, scale_factor) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
                log_data(-1, -1, -1); // Log error
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS - (gpioTick() % SAMPLE_INTERVAL_MS)); // Delay to achieve 1 second interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize sensor
int init_sensor() {
    // No specific initialization needed for SDP810 in continuous mode
    return 0;
}

// Read sensor data
int read_sensor(float *pressure, float *temperature, float *scale_factor) {
    uint8_t data[9];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }

    // Validate CRC for pressure
    if (validate_crc(data, 2) != 0) {
        fprintf(stderr, "CRC validation failed for pressure\n");
        return 1;
    }

    // Validate CRC for temperature
    if (validate_crc(data + 3, 2) != 0) {
        fprintf(stderr, "CRC validation failed for temperature\n");
        return 1;
    }

    // Validate CRC for scale factor
    if (validate_crc(data + 6, 3) != 0) {
        fprintf(stderr, "CRC validation failed for scale factor\n");
        return 1;
    }

    // Convert data to float values
    *pressure = (float)((int16_t)(data[0] << 8 | data[1]));
    *temperature = (float)((int16_t)(data[3] << 8 | data[4]));
    *scale_factor = (float)((int16_t)(data[6] << 8 | data[7]));

    return 0;
}

// Validate CRC-8
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len);
    return (crc != data[len]);
}

// Log data to file
int log_data(float pressure, float temperature, float scale_factor) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pressure, temperature, scale_factor);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        terminate = 1;
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

