#define ERROR_LOG "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define READ_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60
#define CRC_POLYNOMIAL 0x31

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle;
static circular_buffer_t buffer;
static pthread_t logging_thread;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the circular buffer
void circular_buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Function to add data to the circular buffer
void circular_buffer_add(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to read data from the circular buffer
sensor_data_t circular_buffer_read(circular_buffer_t *buffer) {
    sensor_data_t data;
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count > 0) {
        data = buffer->data[buffer->tail];
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
        buffer->count--;
    } else {
        data.timestamp = 0; // Indicate empty buffer
    }
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

// Function to start periodic measurement
int start_periodic_measurement(int i2c_handle) {
    char cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

