    gpioDelay(1); // Small delay after sending command

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *co2 = (uint16_t)((buffer[0] << 8) | buffer[1]);
    uint16_t crc_co2 = (uint16_t)((buffer[2] << 8) | buffer[3]);
    if (crc8(buffer, 2) != crc_co2) {
        fprintf(stderr, "CRC error for CO2\n");
        return -1;
    }

    *temperature = -45 + 175 * ((float)((buffer[4] << 8) | buffer[5])) / 65535;
    uint16_t crc_temp = (uint16_t)((buffer[6] << 8) | buffer[7]);
    if (crc8(buffer + 4, 2) != crc_temp) {
        fprintf(stderr, "CRC error for Temperature\n");
        return -1;
    }

    *humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535;
    uint16_t crc_hum = (uint16_t)((buffer[8] << 8) | buffer[8]);
    if (crc8(buffer + 4, 2) != crc_hum) {
        fprintf(stderr, "CRC error for Humidity\n");
        return -1;
    }

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement(int i2c_handle) {
    char cmd[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

