        }

        circular_buffer_t *buffer_ptr = (circular_buffer_t*)arg; // Cast back to pointer
        sensor_data_t data;
        int index = 0;
        while (index < buffer_ptr->count) {
            data = circular_buffer_read(buffer_ptr);
