#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define TRIGGER_CMD 0x362F // Continuous measurement without averaging
#define SAMPLE_INTERVAL_SEC 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_data(uint8_t *data);
int validate_crc(uint8_t data[], int index, uint8_t crc);
int convert_data(uint8_t *data, float *pressure, float *temperature, float *scale_factor);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        float pressure, temperature, scale_factor;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Continue to the next iteration
        }

        // Wait for measurement to complete
        gpioDelay(45000); // 45 ms

        // Read data
        if (read_data(data) != 0) {
            fprintf(stderr, "Failed to read data\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(data, 0, data[2]) != 0 ||
            validate_crc(data, 3, data[5]) != 0 ||
            validate_crc(data, 6, data[8]) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Continue to the next iteration
        }

        // Convert data
        if (convert_data(data, &pressure, &temperature, &scale_factor) != 0) {
            fprintf(stderr, "Failed to convert data\n");
            continue; // Continue to the next iteration
        }

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    uint8_t cmd[2] = {(TRIGGER_CMD >> 8) & 0xFF, TRIGGER_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read data from sensor
int read_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int index, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, index);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC mismatch at index %d (calculated: 0x%02X, received: 0x%02X)\n", index, calculated_crc, crc);
        return 1;
    }
    return 0;
}

// Convert data to physical units
int convert_data(uint8_t *data, float *pressure, float *temperature, float *scale_factor) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    *pressure = (float)raw_pressure / 240.0; // Pa
    *temperature = (float)raw_temperature / 200.0; // °C
    *scale_factor = (float)raw_scale_factor / 1000.0; // No units

    return 0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
