#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 95000.0
#define NORMAL_LED_FREQUENCY 1.0 // Hz
#define LOW_PRESSURE_LED_FREQUENCY 5.0 // Hz
#define HIGH_PRESSURE_LED_FREQUENCY 1.0 // Hz
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
float calculate_pressure(uint16_t raw_pressure);
float calculate_temperature(uint16_t raw_temperature);
int verify_crc(uint8_t data[], int nbrOfBytes);
void control_led(float pressure);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t pressure;
    uint16_t temperature;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int retries = I2C_RETRY_COUNT;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (bytes_read == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s (retries left: %d)\n", strerror(errno), retries);
            gpioDelay(1000); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to verify CRC
int verify_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // CRC-8-ATM polynomial
            else
                crc = (crc << 1);
        }
    }
    return (crc == 0);
}

// Function to calculate pressure
float calculate_pressure(uint16_t raw_pressure) {
    // Implement the pressure calculation formula from the datasheet
    // This is a placeholder; replace with the actual formula
    return (float)raw_pressure * 0.1; // Example conversion
}

// Function to calculate temperature
float calculate_temperature(uint16_t raw_temperature) {
    // Implement the temperature calculation formula from the datasheet
    // This is a placeholder; replace with the actual formula
    return (float)raw_temperature * 0.01; // Example conversion
}

// Function to control the LED
void control_led(float pressure) {
    static int led_state = 0; // 0: off, 1: on
    static double last_toggle_time = 0.0;
    double current_time = time_time();

    if (pressure < PRESSURE_THRESHOLD) {
        // Low pressure: 5 Hz blinking
        if (current_time - last_toggle_time > 0.1) {
            led_state = !led_state;
            gpioWrite(GPIO_LED, led_state);
            last_toggle_time = current_time;
        }
    } else {
        // Normal pressure: 1 Hz blinking
        if (current_time - last_toggle_time > 1.0) {
            led_state = !led_state;
            gpioWrite(GPIO_LED, led_state);
            last_toggle_time = current_time;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t sensor_values;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Verify CRC
            if (verify_crc(sensor_data, 6) == 0) {
                // Extract pressure and temperature
                sensor_values.pressure = (sensor_data[0] << 8) | sensor_data[1];
                sensor_values.temperature = (sensor_data[3] << 8) | sensor_data[4];

                // Calculate pressure and temperature (already done in calculate_pressure and calculate_temperature)
                float pressure = calculate_pressure(sensor_values.pressure);
                float temperature = calculate_temperature(sensor_values.temperature);

                // Control LED
                control_led(pressure);

                // Print sensor data
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            } else {
                fprintf(stderr, "CRC verification failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Delay for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close I2C connection and release GPIO
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

