#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(int *ambient, int *object);
float convert_to_celsius(int raw_temp);
void control_fan(float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from MLX90614 sensor
int read_temperature(int *ambient, int *object) {
    char buf[2];
    int result;

    // Read ambient temperature
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_TEMP_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read ambient temperature: %d\n", result);
        return -1;
    }
    *ambient = (buf[1] << 8) | buf[0];

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read object temperature: %d\n", result);
        return -1;
    }
    *object = (buf[1] << 8) | buf[0];

    return 0;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
