    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_temperature(&ambient_raw, &object_raw) == 0) {
                // Convert raw temperatures to Celsius
                ambient_temp = convert_to_celsius(ambient_raw);
                object_temp = convert_to_celsius(object_raw);

                // Validate temperature readings
                if (ambient_temp >= -40.0 && ambient_temp <= 125.0 &&
                    object_temp >= -40.0 && object_temp <= 125.0) {
                    // Control the fan
                    control_fan(object_temp);

                    // Log the temperature data
                    log_temperature(ambient_temp, object_temp);

                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Invalid temperature reading, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read temperature, retrying...\n");
            }
            retry++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read temperature after %d retries, skipping.\n", RETRY_COUNT);
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    cleanup();
    printf("Temperature monitoring stopped.\n");

    return 0;
}

