#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3

int i2c_handle;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    unsigned char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, MEASURE_HIGH_PRECISION, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10ms)

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        // Convert data
        unsigned int temp_ticks = (buf[0] << 8) | buf[1];
        unsigned int humidity_ticks = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)temp_ticks / 65535.0;
        *humidity = 100.0 * (float)humidity_ticks / 65535.0;

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to create an HTTP server
int create_http_server(int port) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    printf("Server listening on port %d\n", port);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening
        }

        // Read the request
        char buffer[1024] = {0};
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("recv");
            close(new_socket);
            continue;
        }
        buffer[bytes_received] = '\0';

        // Process the request (very basic example)
        char response[256];
        snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>SHT40 Data</h1><p>Temperature: %.2f C</p><p>Humidity: %.2f %%</p></body></html>", 25.0, 50.0); // Replace with actual data
        send(new_socket, response, strlen(response), 0);
        close(new_socket);
    }

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create HTTP server
    result = create_http_server(SERVER_PORT);
    if (result != 0) {
        fprintf(stderr, "Failed to create HTTP server\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        result = read_sht40(&temperature, &humidity);
        if (result == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

