        return -273.15; // Return absolute zero on error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    if (raw_temp & 0x800) {
        raw_temp |= 0xF000; // Sign extend if negative
    }

    float temperature = (float)(raw_temp >> 4) * 0.0625;
    return temperature;
}

