        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -273.0) {
            char timestamp[20];
            format_timestamp(timestamp);

            if (write_to_csv(timestamp, temperature) != 0) {
