#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define MEASUREMENT_CONFIG 0x0F

// Timeout duration (in milliseconds)
#define TIMEOUT_MS 500

// Maximum number of I2C retry attempts
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int hdc2010_write_register(int handle, int reg, int value);
int hdc2010_read_register(int handle, int reg);
int hdc2010_read_measurement(int handle, float *temperature, float *humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        printf("\nCtrl+C detected. Shutting down...\n");
    }
}

// Function to write a register value to the HDC2010
int hdc2010_write_register(int handle, int reg, int value) {
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, value);
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %d. Retrying...\n", reg, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to read a register value from the HDC2010
int hdc2010_read_register(int handle, int reg) {
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "Error reading from register 0x%02X: %d. Retrying...\n", reg, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "Failed to read from register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to read temperature and humidity from the HDC2010
int hdc2010_read_measurement(int handle, float *temperature, float *humidity) {
    int temp_raw, humid_raw;
    int retries = 0;

    // Trigger measurement
    if (hdc2010_write_register(handle, MEASUREMENT_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to trigger measurement.\n");
        return -1;
    }

    // Wait for measurement to complete (polling MEASUREMENT_CONFIG register)
    int config_value = 0;
    while (retries < MAX_RETRIES) {
        config_value = hdc2010_read_register(handle, MEASUREMENT_CONFIG);
        if (config_value >= 0) {
            if ((config_value & 0x01) == 0) { // Bit 0 is clear, measurement is complete
                break;
            } else {
                fprintf(stderr, "Measurement not complete (config_value = 0x%02X). Retrying...\n", config_value);
                retries++;
                gpioDelay(1000); // Wait 1 ms before retrying
            }
        } else {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register. Retrying...\n");
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Timeout waiting for measurement to complete.\n");
        return -1;
    }

    // Read temperature and humidity registers
    int temp_msb = hdc2010_read_register(handle, TEMP_REG);
    int temp_lsb = hdc2010_read_register(handle, TEMP_REG + 1);
    int humid_msb = hdc2010_read_register(handle, HUMID_REG);
    int humid_lsb = hdc2010_read_register(handle, HUMID_REG + 1);

    if (temp_msb < 0 || temp_lsb < 0 || humid_msb < 0 || humid_lsb < 0) {
        fprintf(stderr, "Error reading temperature or humidity registers.\n");
        return -1;
    }

    // Combine MSB and LSB values
    temp_raw = (temp_msb << 8) | temp_lsb;
    humid_raw = (humid_msb << 8) | humid_lsb;

    // Convert raw values to temperature and humidity
    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humid_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (hdc2010_read_measurement(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

