        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c()
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int handle, uint16_t *pressure, uint16_t *temperature)
{
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }

    gpioDelay(45); // Wait for measurement

    result = i2cReadDevice(handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }

    *pressure = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    *temperature = (uint16_t)buffer[3] | ((uint16_t)buffer[4] << 8);

    return 0;
}

// Function to calculate CRC checksum
uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(uint16_t data, uint8_t crc)
{
    uint8_t crc_calculated = crc8((uint8_t *)&data, 2);
    return (crc_calculated == crc);
}

// Function to process the sensor data
void process_sensor_data(uint16_t pressure, uint16_t temperature, uint8_t pressure_crc, uint8_t temperature_crc)
{
    if (validate_crc(pressure, pressure_crc) && validate_crc(temperature, temperature_crc)) {
        printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
    } else {
        fprintf(stderr, "CRC check failed!\n");
    }
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    uint16_t pressure, temperature;
    uint8_t pressure_crc, temperature_crc;

    // Main loop
    while (1) {
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            pressure_crc = (uint8_t)pressure & 0xFF;
            pressure &= 0xFF00;
            pressure_crc ^= (uint8_t)pressure;
            pressure_crc &= 0xFF;

            temperature_crc = (uint8_t)temperature & 0xFF;
            temperature &= 0xFF00;
            temperature_crc ^= (uint8_t)temperature;
            temperature_crc &= 0xFF;

            process_sensor_data(pressure, temperature, pressure_crc, temperature_crc);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

