#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SSR_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_TEMP 300.0  // Maximum allowed temperature in Celsius
#define MIN_TEMP 100.0  // Minimum allowed temperature in Celsius

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *log_file;
double target_temperature = 200.0; // Default target temperature
int running = 1;

// Structure to hold PID parameters
typedef struct {
    double kp;
    double ki;
    double kd;
} PIDParams;

// Function Prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, PIDParams *pid_params);
void set_ssr_duty_cycle(double duty_cycle);
void load_temperature_profile();
void log_temperature(double temperature);
void signal_handler(int signal);

// Function to read temperature from MAX6675 via SPI
double read_temperature() {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy data for SPI transfer
    char rx_buf[4];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1.0; // Indicate error
    }

    // Extract temperature data (bits 31:18) and convert to Celsius
    int16_t raw_temp = ((rx_buf[0] << 8) | rx_buf[1]) >> 2;
    double temperature = raw_temp * 0.25;

    // Validate temperature
    if (temperature < -100.0 || temperature > 1375.0) {
        fprintf(stderr, "Error: Invalid temperature reading (%.2f)\n", temperature);
        return -1.0; // Indicate error
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, PIDParams *pid_params) {
    double error = setpoint - actual_temperature;
    double proportional = pid_params->kp * error;

    // Integral term
    static double integral = 0.0;
    integral += error;
    double integral_term = pid_params->ki * integral;

    // Derivative term
    static double previous_error = 0.0;
    if (fabs(error) > 0.0) {
        double derivative = pid_params->kd * (error - previous_error);
        previous_error = error;
    } else {
        derivative = 0.0;
    }

    double output = proportional + integral_term + derivative;

    // Clamp the output to the range 0.0 to 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the SSR duty cycle using PWM
void set_ssr_duty_cycle(double duty_cycle) {
    int pwm_range = 1000; // Adjust as needed
    int pwm_value = (int)(duty_cycle * pwm_range);

    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > pwm_range) pwm_value = pwm_range;

    gpioPWM(SSR_GPIO, pwm_value);
}

// Function to load the temperature profile from a file
void load_temperature_profile() {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open profile file (%s)\n", PROFILE_FILE);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        double time, temp;
        if (sscanf(line, "%lf,%lf", &time, &temp) == 2) {
            // Validate temperature
            if (temp < MIN_TEMP || temp > MAX_TEMP) {
                fprintf(stderr, "Warning: Temperature in profile (%.2f) out of range. Skipping.\n", temp);
                continue;
            }
            target_temperature = temp; // Update target temperature
        } else {
            fprintf(stderr, "Warning: Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
}

// Function to log the temperature to a file
void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set SSR GPIO as output
    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file (%s)\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load temperature profile
    load_temperature_profile();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // PID parameters
    PIDParams pid_params = {KP, KI, KD};

    // Main loop
    double target_temp_current = target_temperature;
    double actual_temp;
    double pid_output;
    double duty_cycle;
    double integral = 0.0;
    double previous_error = 0.0;

    while (running) {
        // Read temperature
        actual_temp = read_temperature();

        if (actual_temp < 0.0) {
            fprintf(stderr, "Error: Failed to read temperature. Skipping PID calculation.\n");
            gpioDelay(1000000); // Wait 1 second
            continue;
        }

        // Calculate PID output
        pid_output = calculate_pid(target_temp_current, actual_temp, &pid_params);

        // Set duty cycle
        duty_cycle = pid_output;
        set_ssr_duty_cycle(duty_cycle);

        // Log temperature
        log_temperature(actual_temp);

        // Update target temperature for the next iteration
        target_temp_current = target_temperature; //Update target temperature for the next iteration

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Clean up
    spiClose(spi_handle);
    gpioWrite(SSR_GPIO, 0); // Turn off SSR
    gpioTerminate();
    fclose(log_file);

    return 0;
}

