#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define DS18B20_GPIO 4
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_CHANNEL 0
#define PWM_RANGE 1000000 // 1MHz
#define LOG_FILE "greenhouse.log"
#define SLEEP_SECONDS 5

// PID Gains
float Kp = 0.0;
float Ki = 0.0;
float Kd = 0.0;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
float calculate_pid(float setpoint, float current_temperature, float *integral, float *previous_error);
void set_pwm(int duty_cycle);
void set_relay(int state);
void log_data(float temperature, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read temperature from DS18B20 sensor
float read_temperature() {
    char filepath[256];
    FILE *fp;
    char line[256];
    float temperature = -1000.0; // Initialize to an invalid value
    int valid_reading = 0;

    // Construct the file path
    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/28-*/w1_slave");

    // Open the file for reading
    fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening w1_slave file");
        return -1000.0; // Indicate error
    }

    // Read the file line by line
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Check for the CRC check line
        if (strstr(line, "YES") != NULL) {
            // Extract the temperature from the line
            char *temp_str = strstr(line, "t=");
            if (temp_str != NULL) {
                long temp_raw = strtol(temp_str + 2, NULL, 10);
                temperature = (float)temp_raw / 1000.0;
                valid_reading = 1;
                break;
            }
        }
    }

    // Close the file
    fclose(fp);

    // Check if a valid reading was obtained
    if (!valid_reading) {
        fprintf(stderr, "Error: Invalid temperature reading or sensor absent.\n");
        return -1000.0; // Indicate error
    }

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float current_temperature, float *integral, float *previous_error) {
    float error = setpoint - current_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to set relay state
void set_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log data to file
void log_data(float temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, setpoint, pid_output, pwm_duty_cycle);

    fclose(fp);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    Kp = atof(argv[1]);
    Ki = atof(argv[2]);
    Kd = atof(argv[3]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(DS18B20_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(PWM_GPIO, 1000); // 1 kHz

    // Initialize relay to OFF
    set_relay(0);

    // Initialize PID variables
    float integral = 0.0;
    float previous_error = 0.0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();
        if (temperature < -900.0) {
            fprintf(stderr, "Error reading temperature, skipping PID calculation.\n");
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Calculate PID output
        float pid_output = calculate_pid(atof(argv[1]), temperature, &integral, &previous_error);

        // Set PWM duty cycle (map PID output to 0-100%)
        int duty_cycle = (int)(pid_output * 100.0 / 100.0); // Ensure within range
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
        set_pwm(duty_cycle);

        // Set relay state (ON if PID output > 0, OFF otherwise)
        set_relay((pid_output > 0) ? 1 : 0);

        // Log data
        log_data(temperature, atof(argv[1]), pid_output, duty_cycle);

        // Sleep for a while
        sleep(SLEEP_SECONDS);
    }

    // Clean up resources before exiting
    set_relay(0); // Turn off relay
    set_pwm(0);   // Set PWM to 0
    gpioTerminate(); // Terminate pigpio

    return 0;
}

