    time_t timestamp;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize AHT20 sensor
    if (init_aht20() != 0) {
        fprintf(stderr, "AHT20 initialisation failed\n");
        cleanup();
        return 1;
    }

    float humidity;
    while (!terminate) {
        // Read humidity from AHT20
        if (read_aht20(&humidity) == 0) {
            // Control dehumidifier
            control_dehumidifier(humidity);

            // Log data
            log_data(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Initially off
    return 0;
}

// Initialize AHT20 sensor
int init_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, init_cmd, 3);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 initialization failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }

    fprintf(stderr, "AHT20 initialization failed after %d attempts\n", MAX_RETRIES);
    return 1;
}

