int read_aht20(float *humidity) {
    char read_cmd[1] = {0xAC};
    char data[6];
    int retries = 0;
    int result;

    // Trigger measurement
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, read_cmd, 1);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "AHT20 measurement trigger failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "AHT20 measurement trigger failed after %d attempts\n", MAX_RETRIES);
        return 1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result == 6) {
            break; // Success
        } else {
            fprintf(stderr, "AHT20 data read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "AHT20 data read failed after %d attempts\n", MAX_RETRIES);
        return 1;
    }

    // Verify status bits
    if ((data[0] & 0xC0) != 0) {
        fprintf(stderr, "AHT20: Sensor busy or calibration error\n");
        return 1;
    }

    // Convert data to humidity
    unsigned int humidity_raw = ((unsigned int)data[1] << 12) | ((unsigned int)data[2] << 4) | ((unsigned int)data[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;

    return 0;
}

// Control dehumidifier
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    }
}

// Log data
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();
}

