#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int read_htu21d(int i2c_handle, float *humidity) {
    char buf[3];
    int result;
    unsigned int raw_humidity;

    // Trigger humidity measurement
    result = i2cWriteByte(i2c_handle, TRIGGER_HUMID_MEASURE);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %d", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (datasheet says 25ms max)

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1;
    }

    // CRC Check
    unsigned char msb = buf[0];
    unsigned char lsb = buf[1];
    unsigned char xlsb = buf[2];

    unsigned char crc = (msb >> 6) | ((msb & 0x0F) >> 2) | (lsb >> 4) | (lsb & 0x0F);
    crc = 0xFF & ~crc; // Complement
    for (int i = 0; i < 8; i++) {
        if ((crc & 0x80) != 0) {
            crc = (crc << 1) ^ 0x31; // Polynomial
        } else {
            crc = crc << 1;
        }
    }

    if (crc != xlsb) {
        syslog(LOG_ERR, "CRC check failed!");
        return -1;
    }

    // Convert to humidity
    raw_humidity = ((unsigned int)buf[0] << 8) | buf[1];
    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    return 0;
}

int post_humidity(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[50];
    char *http_method = "POST";

    // Create JSON payload
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Set up server address
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Standard HTTP port
    if (inet_pton(AF_INET, API_ENDPOINT, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed");
        close(sockfd);
        return -1;
    }

    // Send HTTP request
    char request[256];
    snprintf(request, sizeof(request), "%s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", http_method, API_ENDPOINT, strlen(json_data), json_data);
    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request");
        close(sockfd);
        return -1;
    }

    // Receive response
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to receive HTTP response");
        close(sockfd);
        return -1;
    }
    buffer[bytes_received] = '\0';
    syslog(LOG_INFO, "HTTP Response: %s", buffer);

    // Close socket
    close(sockfd);
    return 0;
}

int main() {
    float humidity;
    int result;

    // Initialize syslog
    openlog("humidity_logger", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity logger started");

    while (!terminate) {
        // Read humidity
        result = read_htu21d(i2c_handle, &humidity);
        if (result == 0) {
            syslog(LOG_INFO, "Humidity: %.2f %%", humidity);

            // Post humidity
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(60);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    syslog(LOG_INFO, "Humidity logger stopped");
    closelog();

    return 0;
}

