#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "sensor_log.csv"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir();
int log_data(float temperature, float humidity, int motion);
void signal_handler(int signal);
void cleanup();

// Helper function to write to I2C device
int i2c_write_bytes(int fd, unsigned char *buf, int len) {
    if (write(fd, buf, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Helper function to read from I2C device
int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    unsigned char buf[4];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (i2c_write_bytes(i2c_fd, "\x80\x64\x00\x00", 4) == 0) {
            if (i2c_read_bytes(i2c_fd, buf, 4) == 0) {
                int16_t raw_temp = (buf[0] << 8) | buf[1];
                *temperature = raw_temp * 0.0078125; // Resolution of TMP117
                return 0;
            }
        }
        gpioDelay(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }

    fprintf(stderr, "Failed to read TMP117 after multiple retries.\n");
    return -1;
}

// Read humidity from AHT20
int read_aht20(float *humidity) {
    unsigned char buf[6];
    int retries = 3;
    int delay_ms = 10;

    // Trigger measurement
    unsigned char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    if (i2c_write_bytes(i2c_fd, trigger_cmd, 3) != 0) {
        fprintf(stderr, "Failed to trigger AHT20 measurement.\n");
        return -1;
    }

    gpioDelay(80000); // Wait for measurement (at least 75ms)

    while (retries > 0) {
        if (i2c_write_bytes(i2c_fd, "\xBE\x08\x00", 3) == 0) {
            if (i2c_read_bytes(i2c_fd, buf, 6) == 0) {
                uint32_t raw_humidity = ((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4);
                *humidity = ((float)raw_humidity / 0x100000) * 100; // Resolution of AHT20
                return 0;
            }
        }
        gpioDelay(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }

    fprintf(stderr, "Failed to read AHT20 after multiple retries.\n");
    return -1;
}

// Read PIR sensor
int read_pir() {
    return gpioRead(PIR_GPIO);
}

// Log data to CSV file
int log_data(float temperature, float humidity, int motion) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float temperature, humidity;
    int motion;
    while (!terminate) {
        // Read sensor data
        if (read_tmp117(&temperature) != 0) {
            temperature = -999.0; // Indicate error
        }
        if (read_aht20(&humidity) != 0) {
            humidity = -999.0; // Indicate error
        }
        motion = read_pir();

        // Log data
        log_data(temperature, humidity, motion);

        // Print data to console
        printf("Temperature: %.2f C, Humidity: %.2f %%, Motion: %d\n", temperature, humidity, motion);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

