#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time
#define MOTOR_RUN_TIME 5 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int run_motor);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal, stopping motor and exiting...");
        program_running = 0;
        control_motor(0); // Stop the motor
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int run_motor) {
    if (run_motor) {
        gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
        gpioWrite(MOTOR_IN1_PIN, 1); // IN1 high
        gpioWrite(MOTOR_IN2_PIN, 0); // IN2 low
        log_message("Motor started");
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for 5 seconds
        gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
        gpioWrite(MOTOR_IN1_PIN, 0); // IN1 low
        gpioWrite(MOTOR_IN2_PIN, 0); // IN2 low
        log_message("Motor stopped");
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
        gpioWrite(MOTOR_IN1_PIN, 0); // IN1 low
        gpioWrite(MOTOR_IN2_PIN, 0); // IN2 low
        log_message("Motor stopped");
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = (read_rain_sensor() == 0); // Active low

        if (rain_detected) {
            log_message("Rain detected");
            control_motor(1); // Start motor
        } else {
            log_message("No rain detected");
        }

        gpioDelay(2000000); // Poll every 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

