// Function to read CPU load from /proc/stat
float read_cpu_load() {
    FILE *fp;
    char line[256];
    float user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float total_cpu_usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "cpu  %f %f %f %f %f %f %f %f %f %f",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading CPU stats\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);

    total_cpu_usage = (user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice) / 100.0;

    return total_cpu_usage;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0.0) {
        *red = 0;
        *green = 0;
        *blue = 0;
        return;
    }

    if (cpu_load < 0.5) {
        // Green to Yellow gradient
        *green = (int)(cpu_load * 255.0);
        *red = (int)((1.0 - cpu_load) * 255.0);
        *blue = 0;
    } else {
        // Yellow to Red gradient
        *green = 255;
        *red = (int)((cpu_load - 0.5) * 255.0);
        *blue = 0;
    }
}

