        }

        int red, green, blue;
        map_load_to_color(cpu_load, &red, &green, &blue);
        set_led_color(red, green, blue);

        // Update CPU load history
        cpu_load_history[history_index] = cpu_load;
        history_index = (history_index + 1) % 5;

        // Calculate average CPU load for the last 5 samples
        float avg_cpu_load = 0.0;
        for (int i = 0; i < 5; i++) {
