#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} BufferEntry;

// Circular buffer
BufferEntry circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_duty_cycle(float temperature);
void update_circular_buffer(float temperature, int duty_cycle);
void print_circular_buffer();
void signal_handler(int signal);
int initialize_spi();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char tx_buffer[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buffer[4];
    int result;

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Check for fault bits
    if (rx_buffer[3] & 0x01) {
        fprintf(stderr, "Thermocouple open fault\n");
        return -1;
    }
    if (rx_buffer[3] & 0x02) {
        fprintf(stderr, "Thermocouple short to GND fault\n");
        return -1;
    }
    if (rx_buffer[3] & 0x04) {
        fprintf(stderr, "Thermocouple short to VCC fault\n");
        return -1;
    }

    // Extract temperature data (bits 18-31)
    int16_t raw_temp = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature <= 40.0) {
        duty_cycle = (int)((temperature - 25.0) * 50.0);
    } else if (temperature > 40.0 && temperature <= 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) * 150.0);
    } else if (temperature > 60.0) {
        duty_cycle = 200;
    }

    return duty_cycle;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature, int duty_cycle) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_circular_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, circular_buffer[index].temperature, circular_buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Stopping fan and exiting.\n");
        terminate = 1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Update PWM duty cycle
            gpioPWM(FAN_GPIO, duty_cycle);

            // Update circular buffer
            update_circular_buffer(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature. Skipping fan update.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Stop the fan
    gpioPWM(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print circular buffer
    print_circular_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

