    char read_data[2];

    if (i2cWriteI2CBlockData(i2c_handle, write_data[0], &write_data[1], 1) != 1) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    write_data[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, write_data[0], NULL, 0) != 0) {
        fprintf(stderr, "Error writing MSB address\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (read_data[0] << 8) | read_data[1];
    return 0;
