// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define LOG_FILE "rtd_log.csv"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_FAULT_REG 0x02

// RTD Constants
#define RREF 430.0
#define A 0.0039083
#define B -0.0000005775
#define T0 0.0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, unsigned char reg);
int spi_write_register(int handle, unsigned char reg, unsigned char value);
float read_temperature(int handle);
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize_spi(void);
void cleanup(void);

// Function to read a register from the MAX31865
int spi_read_register(int handle, unsigned char reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set read bit (MSB)
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    return rx[1];
}

// Function to write a register to the MAX31865
int spi_write_register(int handle, unsigned char reg, unsigned char value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Clear read bit (MSB)
    tx[1] = value;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read the temperature from the MAX31865
float read_temperature(int handle) {
    int rtd_msb, rtd_lsb;
    float rtd_resistance;
    float temperature;

    rtd_msb = spi_read_register(handle, MAX31865_RTD_MSB_REG);
    rtd_lsb = spi_read_register(handle, MAX31865_RTD_MSB_REG + 1);

    if (rtd_msb == -1 || rtd_lsb == -1) {
        return -1000.0; // Indicate error
    }

    int rtd_raw = (rtd_msb << 8) | rtd_lsb;
    rtd_raw = rtd_raw >> 1; // Remove fault bit

    rtd_resistance = ((float)rtd_raw / 32768.0) * RREF;

    // Check fault register
    int fault = spi_read_register(handle, MAX31865_FAULT_REG);
    if (fault != 0) {
        fprintf(stderr, "Fault detected: 0x%02X\n", fault);
        return -1000.0; // Indicate error
    }

    // Callendar-Van Dusen equation
    temperature = T0 + (A * rtd_resistance) / (1 + (B * rtd_resistance));

    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI
int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed: %d\n", spi_handle);
        return -1;
    }

    // Configure MAX31865 for 3-wire RTD, 1MHz, enable bias voltage
    if (spi_write_register(spi_handle, MAX31865_CONFIG_REG, 0xC2) != 0) {
        fprintf(stderr, "MAX31865 configuration failed\n");
        spiClose(spi_handle);
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup(void) {
    fprintf(stderr, "Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(spi_handle);

        if (temperature > -999.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping log.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

