#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CONTROL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_CONTROL_HUM 0xF2
#define BME280_REG_CHIPID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init();
int bme280_read_calibration_data();
int bme280_read_data(double *temperature, double *humidity, double *pressure);
int log_data(double temperature, double humidity, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// BME280 initialization function
int bme280_init() {
    int chip_id;

    // Open I2C bus
    i2c_handle = i2cOpen(1, BME280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify chip ID
    chip_id = i2cReadByteData(i2c_handle, BME280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set sensor mode and oversampling
    if (i2cWriteByteData(i2c_handle, BME280_REG_CONTROL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error writing humidity control register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BME280_REG_CONTROL_MEAS, 0x25) < 0) {
        fprintf(stderr, "Error writing control register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// BME280 read calibration data function
int bme280_read_calibration_data() {
    unsigned char data[26];
    int i;

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data block 1\n");
        return -1;
    }

    calib.dig_T1 = (data[1] << 8) | data[0];
    calib.dig_T2 = (data[3] << 8) | data[2];
    calib.dig_T3 = (data[5] << 8) | data[4];
    calib.dig_P1 = (data[7] << 8) | data[6];
    calib.dig_P2 = (data[9] << 8) | data[8];
    calib.dig_P3 = (data[11] << 8) | data[10];
    calib.dig_P4 = (data[13] << 8) | data[12];
    calib.dig_P5 = (data[15] << 8) | data[14];
    calib.dig_P6 = (data[17] << 8) | data[16];
    calib.dig_P7 = (data[19] << 8) | data[18];
    calib.dig_P8 = (data[21] << 8) | data[20];
    calib.dig_P9 = (data[23] << 8) | data[22];
    calib.dig_H1 = data[25];

    if (i2cReadI2CBlockData(i2c_handle, 0xE1, (char *)data, 7) < 0) {
        fprintf(stderr, "Error reading calibration data block 2\n");
        return -1;
    }

    calib.dig_H2 = (data[1] << 8) | data[0];
    calib.dig_H3 = data[2];
    calib.dig_H4 = (data[3] << 4) | (data[4] & 0x0F);
    calib.dig_H5 = (data[5] << 4) | (data[4] >> 4);
    calib.dig_H6 = data[6];

    return 0;
}

// BME280 read data function
int bme280_read_data(double *temperature, double *humidity, double *pressure) {
    unsigned char data[8];
    int32_t raw_temp, raw_pressure, raw_humidity;
    int32_t var1, var2, t_fine;

    // Read raw data
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_PRESSURE_MSB, (char *)data, 8) < 0) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }

    raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    raw_humidity = (data[6] << 8) | data[7];

    // Temperature compensation
    var1 = ((((raw_temp >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
