// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// I2C bus
#define I2C_BUS 1

// Circular buffer size (60 seconds * 10 readings/second = 600 readings)
#define BUFFER_SIZE 600

// Rolling average window size (60 seconds)
#define ROLLING_WINDOW_SIZE 60

// Pressure deviation threshold (5 hPa)
#define PRESSURE_THRESHOLD 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular buffer
float pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Rolling average
float rolling_average = 0.0;
int rolling_average_index = 0;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t ut);
float calculate_pressure(int32_t up, int32_t ut);
void update_rolling_average(float new_pressure);
float calculate_rolling_average();
void trigger_alert(float current_pressure);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_i2c_word(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C block data from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_i2c_uword(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C block data from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    switch (BMP180_OSS) {
        case 0: gpioDelay(5000); break;
        case 1: gpioDelay(8000); break;
        case 2: gpioDelay(14000); break;
        case 3: gpioDelay(26000); break;
    }

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int32_t up, int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
