    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p;
}

// Function to update the rolling average
void update_rolling_average(float new_pressure)
{
    rolling_average -= pressure_buffer[rolling_average_index] / ROLLING_WINDOW_SIZE;
    pressure_buffer[rolling_average_index] = new_pressure;
    rolling_average += new_pressure / ROLLING_WINDOW_SIZE;
    rolling_average_index = (rolling_average_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average
float calculate_rolling_average()
{
