#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping fan and exiting...\n", signal);
}

int read_temperature(int *temperature) {
    FILE *fp;
    char buffer[10];

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    *temperature = atoi(buffer);
    return 0;
}

int map_temperature_to_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature < 40) {
        duty_cycle = 0;
    } else if (temperature > 70) {
        duty_cycle = PWM_RANGE;
    } else {
        duty_cycle = (int)(((float)(temperature - 40) / (70 - 40)) * PWM_RANGE);
    }

    return duty_cycle;
}

int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
    return 0;
}

int log_data(const char *timestamp, int temperature, int duty_cycle) {
    FILE *fp;

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %d, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature, exiting...\n");
            break;
        }

        // Map temperature to duty cycle
        duty_cycle = map_temperature_to_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(GPIO_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, exiting...\n");
            break;
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data
        if (log_data(timestamp, temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop the fan
    set_pwm_duty_cycle(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

