#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int read_calibration_data(int i2c_handle, struct bmp280_calib_data *calib);
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, double t_fine, struct bmp280_calib_data calib);
int write_data_to_file(FILE *log_file, double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data(int i2c_handle, struct bmp280_calib_data *calib) {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESSURE_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    return 0;
}

// Compensate temperature using Bosch formula
double compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using Bosch formula
double compensate_pressure(int32_t raw_pressure, double t_fine, struct bmp280_calib_data calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// Write temperature and pressure data to file
int write_data_to_file(FILE *log_file, double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
