#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/file.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
int gpio_line;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_average = 0.0;
volatile sig_atomic_t terminate = 0;

// Mutex
pthread_mutex_t mutex;

// Function prototypes
int init_i2c();
int init_gpio();
int init_mutex();
int read_temperature(double *temperature);
void update_running_average(double temperature);
void control_led(double temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    gpio_line = GPIO_LED;
    if (gpioSetMode(gpio_line, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(gpio_line, 0); // Initially turn off the LED
    return 0;
}

// Function to initialize mutex
int init_mutex() {
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Error initializing mutex\n");
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75 sensor
int read_temperature(double *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    *temperature = (double)raw_temp * 0.125;

    return 0;
}

// Function to update running average
void update_running_average(double temperature) {
    pthread_mutex_lock(&mutex);
    running_average -= temperature_buffer[buffer_index];
    temperature_buffer[buffer_index] = temperature;
    running_average += temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&mutex);
}

// Function to control LED based on temperature
void control_led(double temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(gpio_line, 1); // Turn on LED
    } else {
        gpioWrite(gpio_line, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioWrite(gpio_line, 0); // Turn off LED
    gpioSetMode(gpio_line, PI_INPUT); // Set GPIO back to input
    i2cClose(i2c_handle);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize mutex
    if (init_mutex() != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    double temperature;
    time_t last_log_time = 0;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            update_running_average(temperature);
            control_led(temperature);

            // Log temperature every 10 seconds
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 10) {
                printf("Temperature: %.2f °C, Running Average: %.2f °C\n", temperature, running_average / BUFFER_SIZE);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Error reading temperature, attempting re-initialization...\n");
            cleanup();
            if (init_i2c() != 0 || init_gpio() != 0 || init_mutex() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

