// Configuration structure
typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
} Config;

// Global variables
int spi_handle;
int pwm_gpio = 18;
int pwm_frequency = 1000; // Hz
int pwm_range = 1000;      // PWM range for 0-100% duty cycle
float reference_resistance = 430.0; // Ohms
float pt100_resistance = 100.0;      // Ohms
float pt100_coefficient = 0.0039083; // RTD coefficient
Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
float read_max31865(int spi_handle);
float calculate_temperature(float rtd_resistance);
float calculate_error(float target_temperature, float actual_temperature);
float calculate_proportional(float error, float kp);
float calculate_integral(float error, float ki, float *integral);
float calculate_derivative(float error, float kd, float previous_error);
float pid_control(float error, float kp, float ki, float kd, float *integral, float previous_error);
void set_pwm_duty_cycle(int gpio, int duty_cycle);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_pwm_duty_cycle(pwm_gpio, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read configuration from JSON file
int read_config(const char *filename, Config *config) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        fprintf(stderr, "Using default config values.\n");
        config->target_temperature = 25.0;
        config->kp = 1.0;
        config->ki = 0.1;
        config->kd = 0.01;
        return -1;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (!target_temp || !json_is_real(target_temp)) {
        fprintf(stderr, "Warning: target_temperature not found or invalid, using default.\n");
        config->target_temperature = 25.0;
    } else {
        config->target_temperature = json_real_value(target_temp);
    }

    json_t *kp = json_object_get(root, "kp");
    if (!kp || !json_is_real(kp)) {
        fprintf(stderr, "Warning: kp not found or invalid, using default.\n");
        config->kp = 1.0;
    } else {
        config->kp = json_real_value(kp);
    }

    json_t *ki = json_object_get(root, "ki");
    if (!ki || !json_is_real(ki)) {
        fprintf(stderr, "Warning: ki not found or invalid, using default.\n");
        config->ki = 0.1;
    } else {
        config->ki = json_real_value(ki);
    }

    json_t *kd = json_object_get(root, "kd");
    if (!kd || !json_is_real(kd)) {
        fprintf(stderr, "Warning: kd not found or invalid, using default.\n");
        config->kd = 0.01;
    } else {
        config->kd = json_real_value(kd);
    }

    json_decref(root);
    return 0;
}

// Function to read temperature from MAX31865
float read_max31865(int spi_handle) {
    char buf[4];
    int result = spiRead(spi_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI read failed (returned %d)\n", result);
        return -1.0; // Indicate error
    }

    // Check for fault bits
    if (buf[3] & 0x01) {
        fprintf(stderr, "Error: MAX31865 fault detected!\n");
        return -1.0; // Indicate error
    }

    // Extract RTD resistance (bits 18-31, signed 14-bit value)
    int16_t rtd_raw = ((buf[0] << 8) | buf[1]) >> 2; // Shift right by 2 to get rid of fault bits
    float rtd_resistance = (float)rtd_raw * reference_resistance / 32768.0;

    return rtd_resistance;
}

// Function to calculate temperature from RTD resistance
float calculate_temperature(float rtd_resistance) {
