float calculate_error(float target_temperature, float actual_temperature) {
    return target_temperature - actual_temperature;
}

// Function to calculate proportional term
float calculate_proportional(float error, float kp) {
    return kp * error;
}

// Function to calculate integral term
float calculate_integral(float error, float ki, float *integral) {
    *integral += error;
    // Anti-windup: limit integral term
    float integral_limit = 100.0; // Adjust as needed
    if (*integral > integral_limit) *integral = integral_limit;
    if (*integral < -integral_limit) *integral = -integral_limit;
    return ki * (*integral);
