    pressure = pressure + ((x1_pressure + x2_pressure + 3791) >> 4);

    return pressure;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data)
{
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to get data from the circular buffer
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index)
{
    return buffer->data[index];
}

// Function to print the contents of the circular buffer
void print_buffer(circular_buffer_t *buffer)
{
    printf("Buffer contents:\n");
    for (int i = 0; i < buffer->count; i++) {
        sensor_data_t data = get_from_buffer(buffer, i);
        struct tm *timeinfo = localtime(&data.timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("  [%d] Timestamp: %s, Temperature: %.2f °C, Pressure: %.2f Pa\n", i, timestamp_str, data.temperature, data.pressure);
