{
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);

        sensor_data_t data;
        data.timestamp = time(NULL);
        data.temperature = temperature;
        data.pressure = pressure;

        add_to_buffer(&buffer, data);
        control_fan(temperature);

