    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO pin for the fan
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW); // Initially turn the fan off

    // Set up timer callback (every 500ms)
    if (wiringPiISR(0, INT_EDGE_RISING, timer_callback) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    printf("BMP180 sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        delay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

