        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

