int read_raw_pressure(int32_t *raw_pressure) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)}; // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 1) != 0) {
        fprintf(stderr, "Failed to write pressure measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    char read_data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_data, 3) != 3) {
