#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Define temperature range for color mapping
#define MIN_TEMP 40000
#define MAX_TEMP 60000

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    int temp = 0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (ferror(fp))
    {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1)
    {
        fprintf(stderr, "Error reading temperature from file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm_duty(int gpio, int duty)
{
    if (gpioPWM(gpio, duty) != 0)
    {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to map temperature to RGB color values
void map_temp_to_color(int temp, int *red, int *green, int *blue)
{
    if (temp < MIN_TEMP)
    {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp > MAX_TEMP)
    {
        *red = 255;
        *green = 0;
        *blue = 0;
    } else
    {
        *red = 0;
        *green = 255;
        *blue = 0;
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, green, blue;
    int temp;

    // Main loop
    while (!terminate)
    {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1)
        {
            fprintf(stderr, "Failed to read temperature, skipping iteration.\n");
            sleep(0.5);
            continue;
        }

        // Map temperature to RGB color values
        map_temp_to_color(temp, &red, &green, &blue);

        // Set PWM duty cycle for each color channel
        if (set_pwm_duty(RED_PIN, red) != 0 ||
            set_pwm_duty(GREEN_PIN, green) != 0 ||
            set_pwm_duty(BLUE_PIN, blue) != 0)
        {
            fprintf(stderr, "Failed to set PWM duty cycle, skipping iteration.\n");
            sleep(0.5);
            continue;
        }

        // Print temperature and PWM values
        printf("Temp: %d m°C, R: %d, G: %d, B: %d\n", temp, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Turn off all LED channels
    set_pwm_duty(RED_PIN, 255);
    set_pwm_duty(GREEN_PIN, 255);
    set_pwm_duty(BLUE_PIN, 255);

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

