#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin mode
int set_gpio_mode(int gpio, int mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", gpio);
        return -1;
    }
    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i, j;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30us

    gpioSetMode(gpio, PI_INPUT);

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        int timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // Check every microsecond
            timeout++;
            if (timeout > 100) { // Timeout after 100us
                fprintf(stderr, "DHT22 timeout waiting for low signal\n");
                return -1;
            }
        }

        // Wait for the line to go high
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for high signal\n");
                return -1;
            }
        }

        // Determine if it's a 0 or a 1 based on the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for low signal during measurement\n");
                return -1;
            }
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            byte_index++;
            bit_count = 0;
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum mismatch\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

// Function to format data as JSON
int format_json(float temperature, float humidity, char *json_string, size_t buffer_size) {
    int ret = snprintf(json_string, buffer_size, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
    if (ret < 0 || ret >= buffer_size) {
        fprintf(stderr, "Error formatting JSON string\n");
        return -1;
    }
    return 0;
}

// Function to send data to the server using libcurl
int send_data(const char *json_string, const char *url) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
