    unsigned long current_tick = gpioTick();
    if (current_tick - last_interrupt_time > 200000) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = current_tick;
    }
}

// Signal handler function
