#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4
#define DEFAULT_API_URL "http://your-api-endpoint.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds
#define JSON_BUFFER_SIZE 128

// Global variables
static volatile int running = 1;
static char *api_url = DEFAULT_API_URL;
static int curl_handle = -1;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Function prototypes
int read_dht22(int gpio, float *temperature, float *humidity);
int validate_checksum(const unsigned char *data, int len);
int format_json(float temperature, float humidity, char *json_string, size_t buffer_size);
int post_data(const char *url, const char *json_data);
void signal_handler(int signal);
int initialize_curl();
void cleanup_curl();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize curl
int initialize_curl() {
    CURLcode res;
    curl_handle = curl_easy_init();
    if (curl_handle) {
        res = curl_easy_setopt(curl_handle, CURLOPT_URL, api_url);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "Failed to set URL: %s", curl_easy_strerror(res));
            return -1;
        }
        res = curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, NULL); // Disable write callback
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "Failed to set write function: %s", curl_easy_strerror(res));
            return -1;
        }
        return 0;
    } else {
        syslog(LOG_ERR, "Failed to initialize curl");
        return -1;
    }
}

// Cleanup curl
void cleanup_curl() {
    if (curl_handle != -1) {
        curl_easy_cleanup(curl_handle);
        curl_handle = -1;
    }
}

// Read DHT22 sensor data
int read_dht22(int gpio, float *temperature, float *humidity) {
    unsigned char data[5] = {0};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Pull the data line low for at least 1 ms
        gpioSetMode(gpio, PI_OUTPUT);
        gpioWrite(gpio, 0);
        gpioDelay(1000);

        // Release the data line
        gpioWrite(gpio, 1);
        gpioDelay(20); // 20-40 us

        // Set the data line as input
        gpioSetMode(gpio, PI_INPUT);

        // Wait for the DHT22 to respond (low for ~80 us, then high for ~80 us)
        gpioDelay(80);
        if (gpioRead(gpio) == 0) {
            gpioDelay(80);
            if (gpioRead(gpio) == 1) {
                // Read 40 bits of data
                for (int i = 0; i < 40; i++) {
                    // Wait for the start of the bit (low for ~50 us)
                    while (gpioRead(gpio) == 1) {
                        gpioDelay(1); // Small delay to prevent busy-waiting
                    }

                    // Measure the duration of the high pulse (0 or 1)
                    long start = gpioTick();
                    while (gpioRead(gpio) == 0) {
                        if (gpioTick() - start > 200) { // Timeout after 200 us
                            syslog(LOG_ERR, "DHT22 timeout waiting for high pulse");
                            goto retry;
                        }
                    }
                    long high_pulse_start = gpioTick();

                    while (gpioRead(gpio) == 1) {
                        if (gpioTick() - high_pulse_start > 200) { // Timeout after 200 us
                            syslog(LOG_ERR, "DHT22 timeout waiting for low pulse");
                            goto retry;
                        }
                    }
                    long high_pulse_end = gpioTick();

                    long pulse_duration = high_pulse_end - high_pulse_start;

                    // Determine if it's a 0 or a 1 based on the pulse duration
                    data[i / 8] <<= 1;
                    if (pulse_duration > 50) { // Threshold for 1
                        data[i / 8] |= 1;
                    }
                }

                // Validate checksum
                if (validate_checksum((const unsigned char *)data, 4)) {
                    // Extract temperature and humidity
                    *humidity = (float)(((unsigned int)data[0] << 8) | data[1]) / 10.0;
                    *temperature = (float)(((unsigned int)data[2] << 8) | data[3]) / 10.0;
                    if (*temperature > 125) {
                        *temperature = *temperature - 256;
                    }

                    return 0; // Success
                } else {
                    syslog(LOG_ERR, "DHT22 checksum validation failed");
                }
            } else {
                syslog(LOG_ERR, "DHT22 response low after initial high");
            }
        } else {
            syslog(LOG_ERR, "DHT22 response low after initial high");
        }

        retry:
        retries++;
        if (retries < MAX_RETRIES) {
            syslog(LOG_WARNING, "DHT22 read failed, retrying (%d/%d)...", retries, MAX_RETRIES);
            sleep(BACKOFF_DELAY);
        }
    }

    syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
    return -1; // Failure
}

// Validate checksum
int validate_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len - 1; i++) {
        checksum += data[i];
    }
    return (checksum == data[len - 1]);
}

// Format data as JSON
int format_json(float temperature, float humidity, char *json_string, size_t buffer_size) {
    int result = snprintf(json_string, buffer_size, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    if (result < 0 || result >= buffer_size) {
        syslog(LOG_ERR, "JSON formatting failed or buffer overflow");
        return -1;
    }
    return 0;
}

// Post data to API
int post_data(const char *url, const char *json_data) {
    CURLcode res;
    long response_code = 0;

    curl_easy_setopt(curl_handle, CURLOPT_POSTFIELDS, json_data);

    res = curl_easy_perform(curl_handle);
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        return -1;
    }

    curl_easy_getinfo(curl_handle, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code < 200 || response_code >= 300) {
        syslog(LOG_ERR, "HTTP request failed with status code: %ld", response_code);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    float temperature, humidity;
    char json_string[JSON_BUFFER_SIZE];

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize curl
    if (initialize_curl() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            if (format_json(temperature, humidity, json_string, sizeof(json_string)) == 0) {
                // Retry POST on failure
                int retries = 0;
                while (retries < MAX_RETRIES) {
                    if (post_data(api_url, json_string) == 0) {
                        syslog(LOG_INFO, "Data posted successfully: %s", json_string);
                        break; // Exit retry loop on success
                    } else {
                        syslog(LOG_WARNING, "POST failed, retrying (%d/%d)...", retries + 1, MAX_RETRIES);
                        sleep(BACKOFF_DELAY);
                        retries++;
                    }
                }
                if (retries == MAX_RETRIES) {
                    syslog(LOG_ERR, "Failed to post data after %d retries", MAX_RETRIES);
                }
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 data");
        }

        sleep(10);
    }

    // Cleanup
    cleanup_curl();
    gpioTerminate();
    closelog();

    return 0;
}

