#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_cpu_temp();
int read_fan_state();
int set_fan_speed(int speed);
int map_temp_to_speed(int temp);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    set_fan_speed(0); // Set fan to 0 (off)
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read CPU temperature
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(CPU_TEMP_FILE, "r");
        if (fp == NULL) {
            perror("Error opening CPU temperature file");
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        if (fscanf(fp, "%d", &temp) != 1) {
            fprintf(stderr, "Error reading CPU temperature\n");
            fclose(fp);
            retries++;
            sleep(1);
            continue;
        }

        fclose(fp);
        return temp;
    }

    log_event("Failed to read CPU temperature after multiple retries.");
    return -1; // Indicate failure
}

// Function to read fan state
int read_fan_state() {
    FILE *fp;
    int state = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "r");
        if (fp == NULL) {
            perror("Error opening fan state file");
            retries++;
            sleep(1);
            continue;
        }

        if (fscanf(fp, "%d", &state) != 1) {
            fprintf(stderr, "Error reading fan state\n");
            fclose(fp);
            retries++;
            sleep(1);
            continue;
        }

        fclose(fp);
        return state;
    }

    log_event("Failed to read fan state after multiple retries.");
    return -1; // Indicate failure
}

// Function to set fan speed
int set_fan_speed(int speed) {
    FILE *fp;
    char state_str[2];

    fp = fopen(FAN_STATE_FILE, "w");
    if (fp == NULL) {
        perror("Error opening fan state file for writing");
        log_event("Error opening fan state file for writing.");
        return -1;
    }

    snprintf(state_str, sizeof(state_str), "%d", speed);
    if (fwrite(state_str, 1, strlen(state_str), fp) != strlen(state_str)) {
        perror("Error writing to fan state file");
        fclose(fp);
        log_event("Error writing to fan state file.");
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to map temperature to fan speed
int map_temp_to_speed(int temp) {
    if (temp < 45) {
        return 0;
    } else if (temp < 55) {
        return 1;
    } else if (temp < 65) {
        return 2;
    } else {
        return 3;
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
