#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

// Define PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define temperature limits for failsafe
#define TEMP_MIN 0.0
#define TEMP_MAX 100.0

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm(double output);
void log_data(double temperature, double pwm_duty_cycle, double pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_DO, PI_INPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // Channel, Baud rate, Flags
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int i;

    // Read 4 bytes from SPI
    for (i = 0; i < 4; i++) {
        data[i] = gpioRead(SPI_DO);
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(log_file, "Fault: Open circuit\n");
        fflush(log_file);
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        pid_state.integral = 0.0;  // Reset PID state
        pid_state.previous_error = 0.0;
        return -273.15; // Return absolute zero as error indicator
    }
    if (data[3] & 0x02) {
        fprintf(log_file, "Fault: Short to GND\n");
        fflush(log_file);
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        pid_state.integral = 0.0;  // Reset PID state
        pid_state.previous_error = 0.0;
        return -273.15; // Return absolute zero as error indicator
    }
    if (data[3] & 0x04) {
        fprintf(log_file, "Fault: Short to VCC\n");
        fflush(log_file);
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        pid_state.integral = 0.0;  // Reset PID state
        pid_state.previous_error = 0.0;
        return -273.15; // Return absolute zero as error indicator
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    pid_state.integral += error;
    double derivative = error - pid_state.previous_error;
    double output = Kp * error + Ki * pid_state.integral + Kd * derivative;
    pid_state.previous_error = error;

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Function to set PWM duty cycle
void set_pwm(double output) {
    int duty_cycle = (int)output;
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, double pwm_duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f °C, PWM: %.2f%%, PID Output: %.2f\n",
            timestamp, temperature, pwm_duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioPWM(HEATER_PIN, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    double setpoint = 50.0;
    double temperature, pid_output;
    double pwm_duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature
        temperature = read_temperature();

        // Check for temperature out of range
        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(log_file, "Temperature out of range: %.2f °C\n", temperature);
            fflush(log_file);
            gpioPWM(HEATER_PIN, 0); // Turn off heater
            pid_state.integral = 0.0;  // Reset PID state
            pid_state.previous_error = 0.0;
            fprintf(stderr, "Temperature out of range, disabling heater.\n");
        } else {
            // Calculate PID output
            pid_output = calculate_pid(setpoint, temperature);

            // Set PWM duty cycle
            pwm_duty_cycle = pid_output;
            set_pwm(pwm_duty_cycle);

            // Log data
            log_data(temperature, pwm_duty_cycle, pid_output);
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

