#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temperature() {
    FILE *fp;
    int temp_milli_celsius;
    float temp_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Failed to read temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature <= 40.0) {
        return 0;
    } else if (temperature >= 70.0) {
        return 1000000; // 100% duty cycle
    } else {
        return (int)(((temperature - 40.0) / (70.0 - 40.0)) * 1000000.0);
    }
}

// Function to set PWM frequency and duty cycle
int set_pwm(int gpio, int frequency, int duty_cycle) {
    if (gpioSetPWMfrequency(gpio, frequency) != frequency) {
        fprintf(stderr, "Failed to set PWM frequency to %d\n", frequency);
        return -1;
    }

    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty_cycle);
        return -1;
    }

    return 0;
}

// Function to log data to a CSV file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, duty_cycle);

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    if (set_pwm(FAN_GPIO, PWM_FREQUENCY, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Failed to create log file");
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    fclose(fp);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, skipping this iteration.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        if (set_pwm(FAN_GPIO, PWM_FREQUENCY, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM, skipping this iteration.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, skipping this iteration.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Turn off the fan before exiting
    gpioPWM(FAN_GPIO, 0);
    gpioDelay(100000); // 100ms

    // Release GPIO resources
    gpioTerminate();

    printf("Fan control stopped.\n");
    return 0;
}

