#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define retry count
#define RETRY_COUNT 3

// Global variables for I2C handles
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_checksum(unsigned char data[], unsigned char crc);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    exit(0);
}

// Function to read data from the sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char data[3];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            // Checksum validation
            if (validate_checksum(data, data[2])) {
                // Convert data to flow rate (example conversion, adjust as needed)
                int raw_flow = (data[0] << 8) | data[1];
                *flow_rate = (float)raw_flow / 100.0; // Example scaling
                return 0; // Success
            } else {
                fprintf(stderr, "Checksum validation failed for sensor.\n");
                return -1; // Checksum failure
            }
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure after all retries
}

// Function to validate the checksum
int validate_checksum(unsigned char data[], unsigned char crc) {
    unsigned char crc_calculated = 0xFF;
    unsigned char data_to_crc[2] = {data[0], data[1]};

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_to_crc[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Function to log the flow data
void log_flow_data(float flow1, float flow2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening flow_log.txt for writing.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2;

    // Main loop
    while (1) {
        // Read flow rates from both sensors
        if (read_sensor(i2c_handle1, &flow_rate1) == 0 && read_sensor(i2c_handle2, &flow_rate2) == 0) {
            // Log the flow data
            log_flow_data(flow_rate1, flow_rate2);
        } else {
            fprintf(stderr, "Failed to read flow data from one or more sensors.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

