#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables for the quadrature state and previous state
static volatile int quadrature_state = 0;
static volatile int previous_state = 0;

// File pointer for the log file
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder_state();
float calculate_angle(int quadrature_state);
int log_position(float angle);
void cleanup_handler(int signum);

// Signal handler for graceful shutdown
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the encoder state
int read_encoder_state() {
    int a_state = gpioRead(ENCODER_A_PIN);
    int b_state = gpioRead(ENCODER_B_PIN);

    // Return the 2-bit quadrature state
    return (a_state << 1) | b_state;
}

// Function to calculate the angular position
float calculate_angle(int quadrature_state) {
    // Normalize the quadrature state to 0-360 degrees
    float angle = (float)quadrature_state * 10.0; // 360 degrees / 36 pulses per 10 degree increment

    // Handle the wrap-around case
    if (angle >= 360.0) {
        angle -= 360.0;
    }

    return angle;
}

// Function to log the position to a file
int log_position(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Write the timestamp and angle to the log file
    fprintf(log_file, "%s, %.2f\n", timestamp, angle);

    // Close the log file
    fclose(log_file);
    log_file = NULL;

    return 0;
}

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the encoder state
        int current_state = read_encoder_state();

        // Update the quadrature state
        quadrature_state = current_state;

        // Calculate the angular position
        float angle = calculate_angle(quadrature_state);

        // Log the position
        if (log_position(angle) != 0) {
            fprintf(stderr, "Error logging position!\n");
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(10000); // 10 milliseconds
    }

    return 0;
}

