#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins
#define SENSOR_1_PIN 18
#define SENSOR_2_PIN 23
#define SENSOR_3_PIN 24

// Define RPM threshold
#define RPM_THRESHOLD 1000.0

// Define log file name
#define LOG_FILE "rpm_log.txt"

// Global variables
volatile int pulse_count_1 = 0;
volatile int pulse_count_2 = 0;
volatile int pulse_count_3 = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void sensor1_isr(void);
void sensor2_isr(void);
void sensor3_isr(void);
float calculate_rpm(int pulse_count);
void log_rpm(float rpm1, float rpm2, float rpm3);
void signal_handler(int signal);

// Interrupt service routine for sensor 1
void sensor1_isr(void) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count_1++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Interrupt service routine for sensor 2
void sensor2_isr(void) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count_2++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Interrupt service routine for sensor 3
void sensor3_isr(void) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count_3++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate RPM
float calculate_rpm(int pulse_count) {
    if (pulse_count == 0) {
        return 0.00; // Handle missing sensor
    }
    return (float)pulse_count * 60.0; // Assuming one pulse per revolution
}

// Function to log RPM values
void log_rpm(float rpm1, float rpm2, float rpm3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, rpm1, rpm2, rpm3);
        fflush(log_file); // Flush the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Disable interrupts
    wiringPiISR(SENSOR_1_PIN, INT_EDGE_RISING, NULL);
    wiringPiISR(SENSOR_2_PIN, INT_EDGE_RISING, NULL);
    wiringPiISR(SENSOR_3_PIN, INT_EDGE_RISING, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate wiringPi
    wiringPiSetup(); // Reinitialize to allow cleanup functions to be called

    exit(0);
}

int main(void) {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: wiringPiSetup() failed.\n");
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Error: pthread_mutex_init() failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Register interrupt service routines
    if (wiringPiISR(SENSOR_1_PIN, INT_EDGE_RISING, sensor1_isr) < 0) {
        fprintf(stderr, "Error: wiringPiISR() failed for sensor 1.\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }
    if (wiringPiISR(SENSOR_2_PIN, INT_EDGE_RISING, sensor2_isr) < 0) {
        fprintf(stderr, "Error: wiringPiISR() failed for sensor 2.\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }
    if (wiringPiISR(SENSOR_3_PIN, INT_EDGE_RISING, sensor3_isr) < 0) {
        fprintf(stderr, "Error: wiringPiISR() failed for sensor 3.\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Reset pulse counts
        pulse_count_1 = 0;
        pulse_count_2 = 0;
        pulse_count_3 = 0;
        delay(1000); // Wait for 1 second

        // Calculate RPM
        float rpm1 = calculate_rpm(pulse_count_1);
        float rpm2 = calculate_rpm(pulse_count_2);
        float rpm3 = calculate_rpm(pulse_count_3);

        // Log RPM values
        log_rpm(rpm1, rpm2, rpm3);

        // Check RPM threshold
        if (rpm1 > RPM_THRESHOLD || rpm2 > RPM_THRESHOLD || rpm3 > RPM_THRESHOLD) {
            printf("RPM threshold exceeded!\n");
        }

        // Print RPM values
        printf("Sensor 1: %.2f RPM, Sensor 2: %.2f RPM, Sensor 3: %.2f RPM\n", rpm1, rpm2, rpm3);
    }

    return 0;
}

