#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define LED_GPIO 17
#define INFRARED_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *red, uint16_t *ir);
void log_data(uint16_t red, uint16_t ir);
void control_led(uint16_t ir);
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *red = (buf[0] << 8) | buf[1];
    *ir = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to log data to CSV file
void log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(uint16_t ir) {
    if (ir > INFRARED_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

