// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define FLOW_LOG_FILE "flow_log.csv"
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00
#define MEASUREMENT_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_sensor(float *flow_rate);
int validate_crc(unsigned char data[], int length);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Flow sensor reading function
int read_flow_sensor(float *flow_rate) {
    char cmd[1] = {0x36}; // Trigger measurement command
    char data[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (adjust as needed)

    result = i2cReadDevice(i2c_handle, data, 3);
    if (result != 3) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // CRC validation
    if (!validate_crc(data, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to flow rate (example conversion, adjust as needed)
    int raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 120.0; // Example scaling factor

    return 0;
}

// CRC validation function
int validate_crc(unsigned char data[], int length) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < length - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[length - 1]);
}

// Flow rate logging function
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_flow_sensor(&flow_rate) == 0) {
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

