#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define FRAME_SIZE (NUM_CHANNELS * (FORMAT == SND_PCM_FORMAT_S16_LE ? 2 : 4))
#define GPIO_PIN 17
#define BUFFER_SIZE 1024

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *fp = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int initialize_i2s() {
    int err;
    snd_pcm_hw_params_t *hw_params;

    /* Open PCM device for capture */
    err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    /* Allocate hardware parameters object */
    snd_pcm_hw_params_alloca(&hw_params);

    /* Initialize hardware parameters */
    err = snd_pcm_hw_params_any(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    /* Set access type to interleaved */
    err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    /* Set format */
    err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT);
    if (err < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    /* Set number of channels */
    err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    /* Set sample rate */
    int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    /* Set period size (frames per interrupt) */
    snd_pcm_uframes_t period_size = BUFFER_SIZE;
    err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &period_size, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    /* Apply hardware parameters */
    err = snd_pcm_hw_params(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

int set_gpio_output(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0); // Set to low initially
    return 0;
}

int select_left_channel(int pin) {
    gpioWrite(pin, 1); // Set high to select left channel
    return 0;
}

int unselect_left_channel(int pin) {
    gpioWrite(pin, 0); // Set low to unselect left channel
    return 0;
}

int write_audio_to_file(FILE *fp, const char *filename) {
    int err;
    int bytes_written = 0;
    char *buffer = NULL;
    size_t buffer_size = BUFFER_SIZE * FRAME_SIZE;

    buffer = (char *)malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for buffer\n");
        return -1;
    }

    while (keep_running) {
        err = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        } else {
            bytes_written += err;
            if (fwrite(buffer, 1, err, fp) != err) {
                fprintf(stderr, "Error writing to file\n");
                break;
            }
        }
    }

    free(buffer);
    return 0;
}

int cleanup() {
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    if (fp != NULL) {
        fclose(fp);
    }

    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }

    return 0;
}

int main() {
    int err;
    char filename[64];

    signal(SIGINT, signal_handler);

    snprintf(filename, sizeof(filename), "audio_capture.pcm");

    if (initialize_i2s() != 0) {
        fprintf(stderr, "I2S initialization failed\n");
        return 1;
    }

    if (set_gpio_output(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO output initialization failed\n");
        cleanup();
        return 1;
    }

    select_left_channel(GPIO_PIN);

    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        cleanup();
        return 1;
    }

    if (write_audio_to_file(fp, filename) != 0) {
        fprintf(stderr, "Error writing audio to file\n");
        cleanup();
        return 1;
    }

    unselect_left_channel(GPIO_PIN);

    cleanup();

    return 0;
}

