#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define PWM_FREQUENCY 100
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0; // Indicate success
}

// Function to read the flame sensor with debounce
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay in microseconds
    return reading;
}

// Function to control the fan using PWM
void control_fan(int state) {
    gpioPWM(FAN_PIN, 128); // 50% duty cycle (128/255)
    if (state) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("System Start", "System started successfully.");

    int flame_detected = 0;
    int last_sensor_state = 1; // Assume no flame initially (HIGH)

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW)
            if (!flame_detected) {
                log_event("Flame Detected", "Flame detected by sensor.");
                control_fan(1); // Turn fan on
                flame_detected = 1;
            }
        } else {
            if (flame_detected) {
                log_event("Flame Ended", "Flame ended.");
                control_fan(0); // Turn fan off
                flame_detected = 0;
            }

            // Check for sensor absent condition (no valid reading for a while)
            if (sensor_value != last_sensor_state) {
                last_sensor_state = sensor_value;
                gpioDelay(100000); // Check every 100ms
            }
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup
    control_fan(0); // Turn fan off
    gpioTerminate();
    fclose(log_file);
    log_event("System Shutdown", "System shut down successfully.");

    return 0;
}

