#include <wiringPi.h>

#define FLAME_SENSOR_PIN 20 // BCM GPIO20
#define LOG_FILE "flame_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int log_flame_state(const char* timestamp, const char* state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, state) < 0) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }
    return 0;
}

int main() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    pinMode(FLAME_SENSOR_PIN, INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int current_state = digitalRead(FLAME_SENSOR_PIN);
    int previous_state = current_state;

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_state = digitalRead(FLAME_SENSOR_PIN);

        if (current_state != previous_state) {
            char* timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (current_state == LOW) {
                    if (log_flame_state(timestamp, "Flame Detected") != 0) {
                        fprintf(stderr, "Failed to log flame detected.\n");
                    }
                } else {
                    if (log_flame_state(timestamp, "Flame Cleared") != 0) {
                        fprintf(stderr, "Failed to log flame cleared.\n");
                    }
                }
                free(timestamp);
            }
            previous_state = current_state;
        }
        delay(100);
    }

    printf("Exiting program.\n");
    return 0;
}

