#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define ISO8601_FORMAT "%Y-%m-%dT%H:%M:%S%z"
#define FILENAME "light_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_opt3001();
float read_lux();
void log_data(float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize OPT3001 sensor
int init_opt3001() {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0xCB); // Continuous conversion mode, auto range
        if (result >= 0) {
            printf("OPT3001 initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing OPT3001: %d. Retrying...\n", result);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to initialize OPT3001 after multiple retries.\n");
    return -1; // Failure
}

// Read lux value from OPT3001
float read_lux() {
    int result;
    int exponent, mantissa;
    float lux;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, RESULT_REG);
        if (result >= 0) {
            exponent = (result >> 12) & 0x0F;
            mantissa = result & 0x0FFF;
            lux = 0.01 * mantissa * (1 << exponent);
            return lux;
        } else {
            fprintf(stderr, "Error reading lux value: %d. Retrying...\n", result);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read lux value after multiple retries.\n");
    return -1.0; // Indicate failure
}

// Log data to file
void log_data(float lux) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), ISO8601_FORMAT, &tm);

    fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing.\n", FILENAME);
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3001 sensor
    if (init_opt3001() != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

