#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_PIN 17

static volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO configuration
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_config_t;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int initialize_gpio(gpio_config_t *config) {
    config->chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!config->chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    config->line = gpiod_chip_get_line(config->chip, GPIO_PIN);
    if (!config->line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(config->chip);
        return -1;
    }

    int ret = gpiod_line_request_input(config->line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(config->chip);
        gpiod_line_release(config->line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(gpio_config_t *config) {
    int value = gpiod_line_get_value(config->line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the flame detection status
void log_flame_status(int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (flame_detected == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio(gpio_config_t *config) {
    if (config->line) {
        gpiod_line_release(config->line);
    }
    if (config->chip) {
        gpiod_chip_close(config->chip);
    }
}

int main() {
    gpio_config_t gpio_config;

    // Install signal handler for SIGINT
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio(&gpio_config) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor(&gpio_config);
        if (flame_detected >= 0) {
            log_flame_status(flame_detected);
        } else {
            fprintf(stderr, "Failed to read flame sensor. Retrying.\n");
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 1;  // 1 second
        sleep_time.tv_nsec = 0; // 0 nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO resources
    cleanup_gpio(&gpio_config);

    return EXIT_SUCCESS;
}

