// Define the GPIO pins for the TTP226 channels
#define CHANNEL_1_PIN 2
#define CHANNEL_2_PIN 3
#define CHANNEL_3_PIN 4
#define CHANNEL_4_PIN 5
#define CHANNEL_5_PIN 6
#define CHANNEL_6_PIN 7
#define CHANNEL_7_PIN 8
#define CHANNEL_8_PIN 9

// Structure to hold the GPIO pin numbers for each channel
typedef struct {
    int channel1;
    int channel2;
    int channel3;
    int channel4;
    int channel5;
    int channel6;
    int channel7;
    int channel8;
} ChannelPins;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the pigpio library and set up the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set the GPIO pins as inputs
    if (gpioSetMode(CHANNEL_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_4_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_4_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_5_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_5_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_6_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_6_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_7_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_7_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CHANNEL_8_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_8_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the state of all eight channels
int read_channels(int *channel_states) {
    channel_states[0] = gpioRead(CHANNEL_1_PIN);
    channel_states[1] = gpioRead(CHANNEL_2_PIN);
    channel_states[2] = gpioRead(CHANNEL_3_PIN);
    channel_states[3] = gpioRead(CHANNEL_4_PIN);
    channel_states[4] = gpioRead(CHANNEL_5_PIN);
    channel_states[5] = gpioRead(CHANNEL_6_PIN);
    channel_states[6] = gpioRead(CHANNEL_7_PIN);
    channel_states[7] = gpioRead(CHANNEL_8_PIN);

    return 0;
}

// Function to log the channel states with a timestamp
void log_channel_states(int *channel_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < 8; i++) {
        printf("%d", channel_states[i]);
        if (i < 7) {
            printf(",");
        }
    }
    printf("\n");
}

// Function to release the pigpio resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for the channel states
    int *channel_states = (int *)malloc(8 * sizeof(int));
    if (channel_states == NULL) {
        fprintf(stderr, "Failed to allocate memory for channel states\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop to read and log the channel states
    while (program_running) {
        // Read the channel states
        if (read_channels(channel_states) != 0) {
            fprintf(stderr, "Failed to read channel states\n");
        } else {
            // Log the channel states
            log_channel_states(channel_states);
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Free the allocated memory
    free(channel_states);

    // Clean up the pigpio resources
    cleanup_gpio();

    return 0;
}

