#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[8] = {2, 3, 4, 5, 6, 7, 8, 9};

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the sensor pins as inputs with pull-down resistors
    for (int i = 0; i < 8; i++)
    {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Read the sensor values
        int sensor_values[8];
        for (int i = 0; i < 8; i++)
        {
            sensor_values[i] = gpioRead(sensor_pins[i]);
        }

        // Get the current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Print the sensor values
        printf("[%ld] ", timestamp_ms);
        for (int i = 0; i < 8; i++)
        {
            printf("CH%d=%d ", i + 1, sensor_values[i]);
        }
        printf("\n");

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

