// Define the GPIO pins connected to the TTP226 sensor channels
const int sensor_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Configure each sensor pin as an input
    for (int i = 0; i < num_channels; ++i) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set mode for pin %d\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of all sensor channels
int read_sensor_channels() {
    int channel_states = 0;
    for (int i = 0; i < num_channels; ++i) {
        int level = gpioRead(sensor_pins[i]);
        if (level < 0) {
            fprintf(stderr, "Failed to read level from pin %d\n", sensor_pins[i]);
            return -1; // Indicate an error
        }
        channel_states = (channel_states << 1) | level;
    }
    return channel_states;
}

// Function to format the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to write the timestamp and sensor channel states to the console
void write_to_console(const char *timestamp, int channel_states) {
    printf("%s,%d\n", timestamp, channel_states);
}

// Function to release the pigpio resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Install the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize the pigpio library and configure the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to read sensor channels and print data
    while (program_running) {
        // Read the sensor channels
        int channel_states = read_sensor_channels();
        if (channel_states < 0) {
            fprintf(stderr, "Error reading sensor channels, exiting...\n");
            break; // Exit the loop if there's an error
        }

        // Get the current timestamp
        char timestamp[21];
        get_iso8601_timestamp(timestamp);

        // Write the timestamp and sensor channel states to the console
        write_to_console(timestamp, channel_states);

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio's delay function takes microseconds
    }

    // Release the pigpio resources before exiting
    cleanup_gpio();

    return 0;
}

