#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int tilt_state = 1; // Assume not tilted initially
    int current_tilt_state;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Print startup banner
    printf("Tilt Sensor Monitoring\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read GPIO pin state
        current_tilt_state = gpioRead(GPIO_PIN);

        // Validate GPIO read
        if (current_tilt_state != 0 && current_tilt_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read value: %d\n", current_tilt_state);
        } else {
            // Check for tilt state change
            if (current_tilt_state != tilt_state) {
                // Flush stdout
                fflush(stdout);

                // Log tilt state
                if (current_tilt_state == 0) {
                    printf("Tilted\n");
                } else {
                    printf("Not Tilted\n");
                }

                // Update tilt state
                tilt_state = current_tilt_state;
            }
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

