#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_ADDR_1 0x70
#define I2C_ADDR_2 0x71
#define START_MEASUREMENT_CMD 0x3006
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define MEASUREMENT_INTERVAL 1 // seconds
#define START_DELAY 100 // ms
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int i2c_bus, int i2c_address);
int start_measurement(int i2c_handle);
int read_flow_rate(int i2c_handle);
float calculate_average_flow(float flow1, float flow2);
void control_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int signal);

// CRC calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle_1 = initialize_i2c(1, I2C_ADDR_1);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = initialize_i2c(1, I2C_ADDR_2);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        i2cClose(i2c_handle_1);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1 = read_flow_rate(i2c_handle_1);
        float flow2 = read_flow_rate(i2c_handle_2);

        if (flow1 >= 0 && flow2 >= 0) {
            float average_flow = calculate_average_flow(flow1, flow2);
            log_data(flow1, flow2, average_flow);
            control_alarm(average_flow);
        } else {
            fprintf(stderr, "Error reading flow rates. Skipping logging and alarm control.\n");
        }

        time_sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();

    return 0;
}

int initialize_i2c(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, handle);
        return -1;
    }
    return handle;
}

int start_measurement(int i2c_handle) {
    char cmd[2] = {(START_MEASUREMENT_CMD >> 8) & 0xFF, START_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

int read_flow_rate(int i2c_handle) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    // CRC validation
    unsigned char crc = crc8(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert to float
    int raw_flow = (buffer[0] << 8) | buffer[1];
    float flow_rate = (float)raw_flow / 120.0; // Scaling factor from datasheet
    return flow_rate;
}

float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

void control_alarm(float average_flow) {
    if (average_flow < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Turn on alarm
    } else {
        gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    }
}

void log_data(float flow1, float flow2, float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

