#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and obstacle status
typedef struct {
    time_t timestamp;
    int obstacle_detected;
} ObstacleEvent;

// Circular buffer
ObstacleEvent buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int obstacle_detected);
void print_buffer();
void signal_handler(int signal);

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Check if obstacle is detected (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time_t current_time = time(NULL);

            // Add event to buffer
            add_to_buffer(current_time, 1);

            // Print alert
            printf("Obstacle detected!\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // pigpio's delay function takes microseconds
    }

    return 0;
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable internal pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add an event to the circular buffer
void add_to_buffer(time_t timestamp, int obstacle_detected) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].obstacle_detected = obstacle_detected;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Obstacle: %s\n", timestamp_str, buffer[index].obstacle_detected ? "Yes" : "No");
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully.\n", signal);

    // Release pigpio resources
    gpioTerminate();

    // Print the buffer before exiting
    print_buffer();

    exit(0);
}

