#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define MODE_REG 0x02
#define MODE_VALUE 0x00 // Mode 0: 100 Hz, 1g
#define X_REG_L 0x28
#define X_REG_H 0x29
#define Y_REG_L 0x2A
#define Y_REG_H 0x2B
#define Z_REG_L 0x2C
#define Z_REG_H 0x2D
#define SAMPLE_INTERVAL_MS 500
#define ACTIVITY_TIMEOUT_S 1
#define CSV_FILE "fan_health.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int set_sensor_mode();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
int write_to_csv(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Set sensor mode
int set_sensor_mode() {
    int result = i2cWriteByteData(i2c_handle, MODE_REG, MODE_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error setting sensor mode: %d\n", result);
        return -1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, X_REG_L, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Write data to CSV file
int write_to_csv(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set sensor mode
    if (set_sensor_mode() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_active = 0;
    int read_count = 0;
    int16_t x, y, z;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Check if the sensor is active
        int sensor_value = i2cReadByteData(i2c_handle, MODE_REG);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor status: %d\n", sensor_value);
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (sensor_value > 0) {
            sensor_active = 1;
        }

        if (sensor_active) {
            read_count++;
            if (read_count >= 10) {
                // Sensor is active, read and write data
                if (read_acceleration(&x, &y, &z) == 0) {
                    if (write_to_csv(x, y, z) != 0) {
                        fprintf(stderr, "Error writing to CSV\n");
                    }
                } else {
                    fprintf(stderr, "Error reading acceleration data\n");
                }
                read_count = 0; // Reset read count after successful read
            }
        } else {
            read_count = 0; // Reset read count if sensor is inactive
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

