#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x08

// TMAG5170-Q1 Register Addresses
#define REG_X_AXIS_L 0x00
#define REG_X_AXIS_H 0x01
#define REG_Y_AXIS_L 0x02
#define REG_Y_AXIS_H 0x03
#define REG_Z_AXIS_L 0x04
#define REG_Z_AXIS_H 0x05
#define REG_CONFIG 0x06

// Configuration values
#define CONFIG_CONT_CONV 0x00 // Continuous conversion mode
#define CONFIG_ALL_AXES 0x00  // All axes enabled
#define CONFIG_50_MT_RANGE 0x00 // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the TMAG5170-Q1 sensor
int initialize_sensor() {
    // Configure the sensor for continuous conversion mode, all axes enabled, and 50 mT range
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, CONFIG_CONT_CONV | CONFIG_ALL_AXES | CONFIG_50_MT_RANGE) < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read X, Y, and Z axis data
    if (i2cReadI2CBlockData(i2c_handle, REG_X_AXIS_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", i2c_handle);
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to log data to a CSV file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Clean up resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

