    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Function to read the water level sensor
int read_water_level() {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO pin %d\n", GPIO_PIN);
        return -1;
    }
    return level;
}

// Function to generate an alert message
void generate_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("ALERT: Water detected at %s\n", timestamp);

    if (log_file != NULL) {
        fprintf(log_file, "%s ALERT: Water detected\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to log an error message
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to re-initialize the pigpio library
void re_initialize_gpio() {
    fprintf(stderr, "Attempting to re-initialize pigpio...\n");
    if (initialize_gpio() != 0) {
        log_error("Failed to re-initialize pigpio.");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        log_error("Failed to initialize pigpio. Exiting.");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int level = read_water_level();
        if (level == 1) {
            generate_alert();
        } else if (level < 0) {
            log_error("Failed to read water level. Attempting re-initialization.");
            re_initialize_gpio();
        }

        sleep(2);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

