    if (setup() != 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        unsigned int pulses = 0;
        unsigned int start_tick = micros();

        while (micros() - start_tick < SAMPLE_INTERVAL_US) {
            // Wait for the sample interval to pass
        }

        pulses = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval

        double rpm = calculate_rpm(pulses);
        log_rpm(rpm);

        delay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

