#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <unistd.h>

// Define GPIO pins for the Hall effect sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the I2C address of the MCP3008 ADC
#define ADC_I2C_ADDR 0x04

// Define the number of ADC channels to read
#define NUM_ADC_CHANNELS 2

// Define the quadrature state machine states
typedef enum {
    QUART_IDLE,
    QUART_A_HIGH,
    QUART_B_HIGH,
    QUART_A_LOW,
    QUART_B_LOW
} QuartetState;

// Define the direction enum
typedef enum {
    CLOCKWISE,
    COUNTER_CLOCKWISE,
    NONE
} Direction;

// Define the quadrature state
typedef struct {
    QuartetState current_state;
    QuartetState previous_state;
} QuartetStateT;

// Define the rotation event structure
typedef struct {
    Direction direction;
    long timestamp_ms;
} RotationEventT;

// Define the global variables
static volatile QuartetStateT quadrature_state = {QUART_IDLE, QUART_IDLE};
static pthread_mutex_t quadrature_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t rotation_event_cond = PTHREAD_COND_INITIALIZER;
static FILE *log_file = NULL;
static int i2c_fd;

// Function prototypes
void sensor_a_isr(void);
void sensor_b_isr(void);
Direction determine_direction(QuartetState current_state, QuartetState previous_state);
void log_rotation_event(RotationEventT event);
void *adc_reading_thread(void *arg);
void signal_handler(int signal);

// Function to read the ADC value from the MCP3008
int read_adc_channel(int channel)
{
    unsigned char buffer[3];
    int adc_value = 0;

    // Build the I2C command to read from the ADC
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    // Write the command to the I2C device
    if (wiringPiI2CWrite(i2c_fd, buffer[0]) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (wiringPiI2CWrite(i2c_fd, buffer[1]) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (wiringPiI2CWrite(i2c_fd, buffer[2]) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for the conversion to complete (at least 100us)
    delay(100);

    // Read the ADC value from the I2C device
    adc_value = ((wiringPiI2CRead(i2c_fd) & 0x03) << 8) + wiringPiI2CRead(i2c_fd);

    return adc_value;
}

// Interrupt service routine for Sensor A
void sensor_a_isr(void)
{
    static int last_adc_value_a = 0;
    int current_adc_value_a;
    static int last_adc_value_b = 0;
    int current_adc_value_b;
    QuartetState current_state;
    QuartetState previous_state;

    pthread_mutex_lock(&quadrature_mutex);

    // Read ADC values
    current_adc_value_a = read_adc_channel(0);
    current_adc_value_b = read_adc_channel(1);

    // Determine the current quadrature state
    if (digitalRead(SENSOR_A_PIN) == HIGH && digitalRead(SENSOR_B_PIN) == LOW) {
        current_state = QUART_A_HIGH;
    } else if (digitalRead(SENSOR_A_PIN) == LOW && digitalRead(SENSOR_B_PIN) == HIGH) {
        current_state = QUART_B_HIGH;
    } else if (digitalRead(SENSOR_A_PIN) == LOW && digitalRead(SENSOR_B_PIN) == LOW) {
        current_state = QUART_A_LOW;
    } else if (digitalRead(SENSOR_A_PIN) == HIGH && digitalRead(SENSOR_B_PIN) == HIGH) {
        current_state = QUART_B_LOW;
    } else {
        current_state = QUART_IDLE;
    }

    // Determine the previous quadrature state
    previous_state = quadrature_state.current_state;

    // Determine the direction of rotation
    Direction direction = determine_direction(current_state, previous_state);

    // Update the quadrature state
    quadrature_state.current_state = current_state;
    quadrature_state.previous_state = previous_state;

    // Create a rotation event
    RotationEventT event;
    event.direction = direction;
    event.timestamp_ms = millis();

    // Log the rotation event
    log_rotation_event(event);

    pthread_cond_signal(&rotation_event_cond);

    pthread_mutex_unlock(&quadrature_mutex);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(void)
{
    sensor_a_isr(); // Call the ISR for Sensor A
}

// Function to determine the direction of rotation
Direction determine_direction(QuartetState current_state, QuartetState previous_state)
{
    if (current_state == QUART_A_HIGH && previous_state == QUART_IDLE) {
        return CLOCKWISE;
    } else if (current_state == QUART_B_HIGH && previous_state == QUART_IDLE) {
        return COUNTER_CLOCKWISE;
    } else if (current_state == QUART_A_LOW && previous_state == QUART_IDLE) {
        return COUNTER_CLOCKWISE;
    } else if (current_state == QUART_B_LOW && previous_state == QUART_IDLE) {
        return CLOCKWISE;
    } else {
        return NONE;
    }
}

// Function to log a rotation event to the log file
void log_rotation_event(RotationEventT event)
{
    struct timespec ts;
    char timestamp[30];
    struct tm tm_info;

    // Get the current time
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format the timestamp
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    // Open the log file in append mode
    if (log_file == NULL) {
        log_file = fopen("rotation_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    // Write the event to the log file
    fprintf(log_file, "%s, Direction: %s\n", timestamp, (event.direction == CLOCKWISE) ? "Clockwise" : ((event.direction == COUNTER_CLOCKWISE) ? "Counter-Clockwise" : "None"));

    // Flush the log file
    fflush(log_file);
}

// Thread function to read ADC values and trigger the rotation event
void *adc_reading_thread(void *arg)
{
    while (1) {
        // Read ADC values
        int adc_value_a = read_adc_channel(0);
        int adc_value_b = read_adc_channel(1);

        // Check for errors
        if (adc_value_a == -1 || adc_value_b == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Determine the current quadrature state
        QuartetState current_state;
        if (adc_value_a > adc_value_b) {
            current_state = QUART_A_HIGH;
        } else {
            current_state = QUART_B_HIGH;
        }

        // Create a rotation event
        RotationEventT event;
        event.direction = NONE; // Initially set to NONE
        event.timestamp_ms = millis();

        // Log the rotation event
        log_rotation_event(event);

        // Signal the rotation event condition variable
        pthread_cond_signal(&rotation_event_cond);

        // Wait for a short period before reading again
        delay(10);
    }

    return NULL;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal)
{
    printf("Caught signal %d. Exiting gracefully.\n", signal);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the condition variable
    pthread_cond_destroy(&rotation_event_cond);

    // Destroy the mutex
    pthread_mutex_destroy(&quadrature_mutex);

    // Terminate the wiringPi library
    wiringPiSetup(); // Reinitialize to allow cleanup

    exit(0);
}

int main(void)
{
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to initialize wiringPi.\n");
        return 1;
    }

    // Initialize the I2C interface
    i2c_fd = wiringPiI2CSetup(ADC_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C interface.\n");
        return 1;
    }

    // Set up the GPIO pins as inputs with pull-up resistors
    pinMode(SENSOR_A_PIN, INPUT);
    pullUpDnControl(SENSOR_A_PIN, PUD_UP);
    pinMode(SENSOR_B_PIN, INPUT);
    pullUpDnControl(SENSOR_B_PIN, PUD_UP);

    // Set up the interrupt service routines
    if (wiringPiISR(SENSOR_A_PIN, INT_EDGE_BOTH, sensor_a_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR for sensor A.\n");
        return 1;
    }
    if (wiringPiISR(SENSOR_B_PIN, INT_EDGE_BOTH, sensor_b_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR for sensor B.\n");
        return 1;
    }

    // Set up the signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the ADC reading thread
    pthread_t adc_thread;
    if (pthread_create(&adc_thread, NULL, adc_reading_thread, NULL) != 0) {
        perror("Failed to create ADC reading thread");
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for a rotation event
        pthread_cond_wait(&rotation_event_cond, &quadrature_mutex);
    }

    return 0;
}

