#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);

int main() {
    // Open syslog for logging
    openlog("touch_led_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    log_event("Program started successfully.");

    // Main loop
    while (program_running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // Control LED based on touch sensor state
        if (touch_detected) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio's delay function takes microseconds
    }

    // Cleanup and exit
    log_event("Program shutting down gracefully.");
    gpioTerminate();
    closelog();
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO23 as input for the touch sensor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for the LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", LED_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    // Read the digital value from the touch sensor
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);

    // Return 1 if touch is detected (sensor value is 1), otherwise return 0
    return sensor_value;
}

// Function to control the LED
int control_led(int state) {
    // Set the LED pin to the specified state (0 for off, 1 for on)
    if (gpioWrite(LED_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO%d", LED_PIN);
        return 1;
    }
    return 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    // Log the message with a timestamp
    syslog(LOG_INFO, "%s: %s", buf, message);
}

// Signal handler function
void signal_handler(int signal) {
    // Log the received signal
    char message[100];
    sprintf(message, "Received signal %d", signal);
    log_event(message);

    // Turn off the LED
    control_led(0);

    // Terminate pigpio library
    gpioTerminate();

    // Set program_running to 0 to exit the main loop
    program_running = 0;
}

