#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void debounce();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize LED to LOW
    gpioWrite(LED_PIN, 0);

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle LED state
void toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
}

// Debounce function
void debounce() {
    unsigned long current_time = gpioTick();
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        last_touch_time = current_time;
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor and LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // Check for rising edge
        if (touch_detected) {
            // Debounce
            debounce();

            // Toggle LED
            toggle_led();

            // Log event with timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("Touch detected at %s, LED toggled\n", timestamp);
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    printf("Program terminated gracefully.\n");
    return 0;
}

