#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Define overflow counter
#define OVERFLOW_THRESHOLD 50

// Structure to store log entry
typedef struct {
    int sensor_pin;
    long timestamp;
    int state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void control_led(int gpio_pin, int state);
void add_log_entry(int sensor_pin, long timestamp, int state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control LED state
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to add log entry to the circular buffer
void add_log_entry(int sensor_pin, long timestamp, int state) {
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the log buffer
void print_log_buffer() {
    printf("Log Buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("Entry %d: Sensor %d, Timestamp %ld, State %d\n", i, log_buffer[index].sensor_pin, log_buffer[index].timestamp, log_buffer[index].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Print log buffer
    print_log_buffer();

    // Cleanup pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int sensor_1_state = 0;
    int sensor_2_state = 0;
    long last_touch_time_1 = 0;
    long last_touch_time_2 = 0;

    while (1) {
        // Read sensor values
        int current_sensor_1_state = read_sensor(SENSOR_1_PIN);
        int current_sensor_2_state = read_sensor(SENSOR_2_PIN);

        // Debounce sensor 1
        if (current_sensor_1_state == 1 && sensor_1_state == 0) {
            long current_time = time(NULL);
            if (current_time - last_touch_time_1 > 0.05) { // 50ms debounce
                add_log_entry(SENSOR_1_PIN, current_time, 1);
                control_led(LED_1_PIN, 1);
                sensor_1_state = 1;
                last_touch_time_1 = current_time;
            }
        } else if (current_sensor_1_state == 0 && sensor_1_state == 1) {
            add_log_entry(SENSOR_1_PIN, time(NULL), 0);
            control_led(LED_1_PIN, 0);
            sensor_1_state = 0;
            last_touch_time_1 = time(NULL);
        }

        // Debounce sensor 2
        if (current_sensor_2_state == 1 && sensor_2_state == 0) {
            long current_time = time(NULL);
            if (current_time - last_touch_time_2 > 0.05) { // 50ms debounce
                add_log_entry(SENSOR_2_PIN, current_time, 1);
                control_led(LED_2_PIN, 1);
                sensor_2_state = 1;
                last_touch_time_2 = current_time;
            }
        } else if (current_sensor_2_state == 0 && sensor_2_state == 1) {
            add_log_entry(SENSOR_2_PIN, time(NULL), 0);
            control_led(LED_2_PIN, 0);
            sensor_2_state = 0;
            last_touch_time_2 = time(NULL);
        }

        // Check for overflow
        if (overflow_count >= OVERFLOW_THRESHOLD) {
            fprintf(stderr, "Warning: Log buffer overflow!\n");
            overflow_count = 0; // Reset overflow count to avoid repeated warnings
        }

        // Check for sensor 1 overflow
        if (buffer_index == 0 && overflow_count < OVERFLOW_THRESHOLD) {
            overflow_count++;
            fprintf(stderr, "Warning: Sensor 1 log buffer overflow!\n");
        }

        // Check for sensor 2 overflow
        if (buffer_index == BUFFER_SIZE - 1 && overflow_count < OVERFLOW_THRESHOLD) {
            overflow_count++;
            fprintf(stderr, "Warning: Sensor 2 log buffer overflow!\n");
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms
    }

    return 0;
}

