#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_TIME_US 5000 // 5 ms
#define LOG_FILE "shaft_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_data(FILE *fp, int sensor1_state, int sensor2_state);
double calculate_rpm(double time_interval_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

// Function to read sensor state
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to calculate RPM
double calculate_rpm(double time_interval_seconds) {
    if (time_interval_seconds <= 0) {
        return 0.0;
    }
    return 60.0 / time_interval_seconds;
}

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    SensorStates current_states = {0, 0};
    SensorStates previous_states = {0, 0};
    time_t last_log_time = 0;
    double rpm = 0.0;
    double time_interval = 0.0;
    struct timespec start_time, current_time;
    int sensor1_state, sensor2_state;

    // Main loop
    while (program_running) {
        // Read sensor states
        sensor1_state = read_sensor(SENSOR_1_GPIO);
        sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Debounce and log data
        if (sensor1_state != current_states.sensor1_state || sensor2_state != current_states.sensor2_state) {
            gpioDelay(DEBOUNCE_TIME_US); // Debounce
            current_states.sensor1_state = sensor1_state;
            current_states.sensor2_state = sensor2_state;

            if (log_data(log_file, current_states.sensor1_state, current_states.sensor2_state) != 0) {
                program_running = 0; // Stop if logging fails
                break;
            }

            if (current_states.sensor1_state != previous_states.sensor1_state || current_states.sensor2_state != previous_states.sensor2_state) {
                time(&last_log_time);
            }
        }

        // Calculate and print RPM every second
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (difftime(current_time.tv_sec, last_log_time) >= 1.0) {
            if (time_interval > 0) {
                rpm = calculate_rpm(time_interval);
                printf("RPM: %.2f\n", rpm);
            }
            time_interval = 0.0;
            last_log_time = current_time.tv_sec;
        }

        previous_states = current_states;
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

