// Define the I2C address of the Si1182 sensor
#define SI1182_I2C_ADDR 0x60

// Define the I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the log file name
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;

// Function prototypes
int read_si1182_data(int i2c_handle, int *heart_rate, int *spo2);
int log_data(FILE *log_file, int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read heart rate and SpO2 data from the Si1182 sensor
int read_si1182_data(int i2c_handle, int *heart_rate, int *spo2) {
    // Implement the I2C read operations to get heart rate and SpO2 data from the Si1182
    // This is a placeholder; replace with actual register reads and data parsing
    // based on the Si1182 datasheet.
    // Example (replace with actual register addresses and data format):
    char reg_addr = 0x20; // Example register address
    char buffer[4]; // Example buffer size
    int result;

    result = i2cWriteDevice(i2c_handle, &reg_addr, 1); // Write register address
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, 4); // Read 4 bytes
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Example data parsing (replace with actual parsing logic)
    *heart_rate = (buffer[0] << 8) | buffer[1];
    *spo2 = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to log the heart rate and SpO2 data to a file
int log_data(FILE *log_file, int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write the data to the log file
    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

int main() {
    int heart_rate, spo2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1182_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
