    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read data from the Si1182 sensor
        if (read_si1182_data(i2c_handle, &heart_rate, &spo2) == 0) {
            // Log the data to the file
            if (log_data(log_file, heart_rate, spo2) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

