#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CTRL1_REG 0x02
#define CTRL2_REG 0x03
#define X_LSB_REG 0x04
#define X_MSB_REG 0x05
#define Y_LSB_REG 0x06
#define Y_MSB_REG 0x07
#define Z_LSB_REG 0x08
#define Z_MSB_REG 0x09
#define LED_GPIO 17
#define THRESHOLD 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define ALERT_DURATION_S 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z);
int log_event(double magnitude);
int control_led(int state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    char buf[2];
    int result;

    // Verify sensor presence by reading CTRL1
    buf[0] = CTRL1_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to CTRL1 register: %s\n", strerror(errno));
        return -1;
    }
    char read_buf[1];
    result = i2cReadDevice(i2c_handle, read_buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from CTRL1 register: %s\n", strerror(errno));
        return -1;
    }
    if (read_buf[0] != 0x00) {
        fprintf(stderr, "Sensor not detected (CTRL1 = 0x%02X)\n", read_buf[0]);
        return -1;
    }

    // Clear the power-down bit in CTRL1
    buf[0] = CTRL1_REG;
    buf[1] = 0x01; // Power down mode
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to CTRL1 register (power down): %s\n", strerror(errno));
        return -1;
    }

    // Verify by reading CTRL1 again
    buf[0] = CTRL1_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to CTRL1 register for verification: %s\n", strerror(errno));
        return -1;
    }
    result = i2cReadDevice(i2c_handle, read_buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from CTRL1 register for verification: %s\n", strerror(errno));
        return -1;
    }
    if (read_buf[0] != 0x00) {
        fprintf(stderr, "Sensor not detected after power down: CTRL1 = 0x%02X\n", read_buf[0]);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    char read_buf[1];
    int result;
    int retries = RETRY_COUNT;

    // Read X axis
    buf[0] = X_LSB_REG;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to X_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error reading from X_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    *x = (int16_t)((read_buf[0] << 8) | 0);

    // Read Y axis
    buf[0] = Y_LSB_REG;
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to Y_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error reading from Y_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    *y = (int16_t)((read_buf[0] << 8) | 0);

    // Read Z axis
    buf[0] = Z_LSB_REG;
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to Z_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error reading from Z_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    *z = (int16_t)((read_buf[0] << 8) | 0);

    return 0;
}

// Calculate vibration magnitude
double calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log event
int log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control LED
int control_led(int state) {
    gpioWrite(LED_GPIO, state);
    return 0;
}

int main() {
    int16_t x, y, z;
    double magnitude;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, 0x00, 0); // Device address is not always 0
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate vibration magnitude
            magnitude = calculate_vibration_magnitude(x, y, z);

            // Check for threshold exceedance
            if (magnitude > THRESHOLD) {
                // Log event
                log_event(magnitude);

                // Control LED
                control_led(1);
                gpioDelay(ALERT_DURATION_S * 1000000); // Delay in microseconds
                control_led(0);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Seismic monitor stopped.\n");

    return 0;
}

