            fprintf(stderr, "Error writing to Y_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error reading from Y_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    *y = (int16_t)((read_buf[0] << 8) | 0);

    // Read Z axis
    buf[0] = Z_LSB_REG;
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to Z_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error reading from Z_LSB_REG: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        } else {
            break;
        }
    }
    if (retries == 0) return -1;

    *z = (int16_t)((read_buf[0] << 8) | 0);

    return 0;
}

// Calculate vibration magnitude
double calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log event
int log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control LED
int control_led(int state) {
    gpioWrite(LED_GPIO, state);
    return 0;
}

int main() {
    int16_t x, y, z;
    double magnitude;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, 0x00, 0); // Device address is not always 0
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate vibration magnitude
            magnitude = calculate_vibration_magnitude(x, y, z);

            // Check for threshold exceedance
            if (magnitude > THRESHOLD) {
                // Log event
                log_event(magnitude);

                // Control LED
                control_led(1);
                gpioDelay(ALERT_DURATION_S * 1000000); // Delay in microseconds
                control_led(0);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Seismic monitor stopped.\n");

    return 0;
}

