#include <pigpio.h>

// Define GPIO pins for sensors and LED
#define SENSOR_1 4
#define SENSOR_2 17
#define SENSOR_3 27
#define SENSOR_4 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetMode(SENSOR_4, PI_INPUT);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1);
    int sensor2_value = gpioRead(SENSOR_2);
    int sensor3_value = gpioRead(SENSOR_3);
    int sensor4_value = gpioRead(SENSOR_4);

    // Check for errors during read operations
    if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0 || sensor4_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate error
    }

    return (sensor1_value || sensor2_value || sensor3_value || sensor4_value); // Return 1 if any sensor detects an object, 0 otherwise
}

// Function to control the LED
void control_led(int object_detected) {
    gpioWrite(LED_PIN, object_detected);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int object_detected = read_sensors();

        if (object_detected == -1) {
            // Handle error from read_sensors
            gpioTerminate();
            return 1;
        }

        control_led(object_detected);

        gpioDelay(50); // Delay for 50 ms
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Program terminated.\n");

    return 0;
}

