#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the flame sensors
#define FLAME_SENSOR_1 2
#define FLAME_SENSOR_2 3
#define FLAME_SENSOR_3 4
#define FLAME_SENSOR_4 17
#define FLAME_SENSOR_5 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the syslog facility and identifier
#define SYSLOG_FACILITY LOG_USER
#define SYSLOG_IDENT "flame_monitor"

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Define the maximum number of sensors
#define MAX_SENSORS 5

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    int line_number;
    int last_state;
    int line_handle;
} sensor_data_t;

// Array of sensor data
sensor_data_t sensors[MAX_SENSORS];

// Flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int open_gpio_line(int gpio_pin);
int read_gpio_line(int line_handle);
int acquire_gpio_line(int line_handle);
int release_gpio_line(int line_handle);
void log_event(int sensor_id, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set the GPIO pins as inputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "pigpio initialisation failed");
        return -1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_4, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_5, PI_INPUT);

    syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "GPIO initialisation complete");
    return 0;
}

// Function to open a GPIO line for reading
int open_gpio_line(int gpio_pin) {
    int line_handle = gpioSetMode(gpio_pin, PI_INPUT);
    if (line_handle < 0) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to set GPIO %d as input", gpio_pin);
        return -1;
    }
    return line_handle;
}

// Function to read the state of a GPIO line
int read_gpio_line(int line_handle) {
    int value = gpioRead(line_handle);
    if (value < 0) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to read GPIO line %d", line_handle);
        return -1;
    }
    return value;
}

// Function to acquire a GPIO line for reading
int acquire_gpio_line(int line_handle) {
    int result = gpioSetAlertFuncEx(line_handle, NULL, NULL);
    if (result < 0) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to acquire GPIO line %d", line_handle);
        return -1;
    }
    return 0;
}

// Function to release a GPIO line
int release_gpio_line(int line_handle) {
    int result = gpioSetAlertFuncEx(line_handle, NULL, NULL);
    if (result < 0) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to release GPIO line %d", line_handle);
        return -1;
    }
    return 0;
}

// Function to log a flame detection event
void log_event(int sensor_id, int gpio_pin) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to open log file %s", LOG_FILE);
        return;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", buf, sensor_id, gpio_pin);
    fflush(fp);
    fclose(fp);

    syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Flame detected on sensor %d (GPIO %d)", sensor_id, gpio_pin);
}

// Signal handler function
void signal_handler(int signal) {
    syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Cleaning up resources...");

    // Release all acquired lines
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (sensors[i].line_handle >= 0) {
            release_gpio_line(sensors[i].line_handle);
        }
    }

    // Close the pigpio library
    gpioTerminate();

    syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Cleanup complete, exiting.");
    closelog();
}

int main() {
    // Initialize syslog
    openlog(SYSLOG_IDENT, LOG_PID | LOG_CONS, SYSLOG_FACILITY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensors array
    sensors[0].gpio_pin = FLAME_SENSOR_1;
    sensors[0].sensor_id = 1;
    sensors[0].line_handle = -1;

    sensors[1].gpio_pin = FLAME_SENSOR_2;
    sensors[1].sensor_id = 2;
    sensors[1].line_handle = -1;

    sensors[2].gpio_pin = FLAME_SENSOR_3;
    sensors[2].sensor_id = 3;
    sensors[2].line_handle = -1;

    sensors[3].gpio_pin = FLAME_SENSOR_4;
    sensors[3].sensor_id = 4;
    sensors[3].line_handle = -1;

    sensors[4].gpio_pin = FLAME_SENSOR_5;
    sensors[4].sensor_id = 5;
    sensors[4].line_handle = -1;

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "GPIO initialization failed, exiting.");
        cleanup();
        return 1;
    }

    // Open and acquire all GPIO lines
    for (int i = 0; i < MAX_SENSORS; i++) {
        sensors[i].line_handle = open_gpio_line(sensors[i].gpio_pin);
        if (sensors[i].line_handle < 0) {
            syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to open GPIO line %d, exiting.", sensors[i].gpio_pin);
            cleanup();
            return 1;
        }
        if (acquire_gpio_line(sensors[i].line_handle) != 0) {
            syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Failed to acquire GPIO line %d, exiting.", sensors[i].gpio_pin);
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < MAX_SENSORS; i++) {
            int current_state = read_gpio_line(sensors[i].line_handle);
            if (current_state < 0) {
                syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Error reading sensor %d, retrying.", sensors[i].sensor_id);
                gpioDelay(100); // Wait before retrying
                continue;
            }

            if (current_state == 0 && sensors[i].last_state == 1) {
                // Flame detected
                gpioDelay(DEBOUNCE_DELAY);
                int debounce_state = read_gpio_line(sensors[i].line_handle);
                if (debounce_state == 0) {
                    log_event(sensors[i].sensor_id, sensors[i].gpio_pin);
                } else {
                    syslog(SYSLOG_FACILITY, SYSLOG_IDENT, "Debounce failed for sensor %d, ignoring.", sensors[i].sensor_id);
                }
            }

            sensors[i].last_state = current_state;
        }

        gpioDelay(1000); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

