#include <errno.h>
#include <string.h>
#include <gpiod.h>

// Define the GPIO pins connected to the TTP226 sensor channels
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variables for GPIO chip and chip handle
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8];

// Flag to indicate if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to initialize a GPIO line as input
int initialize_line(int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    lines[pin - 5] = line; // Store the line for later use
    return 0;
}

// Function to read the state of a GPIO line
int read_line(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the touch event
void log_touch_event(int sensor_index, int pin, int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    printf("%s - Sensor %d (Pin %d): %s\n", buf, sensor_index, pin, state ? "Touch Detected" : "Touch Released");
}

// Function to release GPIO resources
void cleanup_gpio() {
    for (int i = 0; i < num_sensors; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize GPIO lines
    for (int i = 0; i < num_sensors; i++) {
        if (initialize_line(sensor_pins[i]) < 0) {
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    int previous_states[8] = {0}; // Store the previous state of each sensor
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_line(lines[i]);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, exiting...\n", i);
                program_running = 0;
                break;
            }

            if (current_state != previous_states[i]) {
                log_touch_event(i, sensor_pins[i], current_state);
                previous_states[i] = current_state;
            }
        }
        gpiod_line_event_wait(lines[0], 50, 0); // Wait 50ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

