#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define CONFIG_REG 0x00
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_lux(int *lux);
int map_lux_to_duty_cycle(int lux, int *duty_cycle);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(int lux, int duty_cycle, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 1/8
    unsigned char config_data[2] = {0x02, 0x00}; // IT = 100ms, Gain = 1/8
    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_data, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700
int read_lux(int *lux) {
    unsigned char data[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    *lux = (data[1] << 8) | data[0];
    return 0;
}

// Map lux value to PWM duty cycle
int map_lux_to_duty_cycle(int lux, int *duty_cycle) {
    if (lux < 100) {
        *duty_cycle = 100;
    } else if (lux < 500) {
        *duty_cycle = 75;
    } else if (lux < 1000) {
        *duty_cycle = 50;
    } else {
        *duty_cycle = 25;
    }
    return 0;
}

// Set PWM duty cycle on GPIO18
int set_pwm_duty_cycle(int duty_cycle) {
    int range = 1000000 / PWM_FREQ; // PWM range for 1000Hz
    int pwm_value = (int)(((float)duty_cycle / 100.0) * range);
    gpioPWM(PWM_GPIO, pwm_value);
    return 0;
}

// Log data to file
int log_data(int lux, int duty_cycle, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, lux, duty_cycle, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO mode
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, 1000000); // Set PWM range

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int lux, duty_cycle;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_lux(&lux) == 0) {
            // Map lux to duty cycle
            if (map_lux_to_duty_cycle(lux, &duty_cycle) == 0) {
                // Set PWM duty cycle
                if (set_pwm_duty_cycle(duty_cycle) != 0) {
                    fprintf(stderr, "Error setting PWM duty cycle\n");
                    error_code = -1; // Set error code
                } else {
                    // Log data
                    if (log_data(lux, duty_cycle, error_code) != 0) {
                        fprintf(stderr, "Error logging data\n");
                        error_code = -1; // Set error code
                    }
                }
            } else {
                fprintf(stderr, "Error mapping lux to duty cycle\n");
                error_code = -1; // Set error code
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
            error_code = -1; // Set error code
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    gpioPWM(PWM_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

