#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for sensor channels and LED
#define SENSOR_START_PIN 2
#define LED_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor_channel(int pin);
int log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(SENSOR_START_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_START_PIN + i, PI_PUD_DOWN);
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    control_led(0); // Ensure LED is off initially

    return 0; // Indicate success
}

// Function to read the state of a sensor channel
int read_sensor_channel(int pin) {
    return gpioRead(pin);
}

// Function to log a touch event to a file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1; // Indicate failure
    }

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fclose(log_file);

    return 0; // Indicate success
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int any_touched = 0;
        for (int i = 0; i < 8; i++) {
            int channel_state = read_sensor_channel(SENSOR_START_PIN + i);

            if (channel_state == 1) {
                if (log_touch_event(i + 1) == 0) {
                    any_touched = 1;
                }
                gpioDelay(DEBOUNCE_DELAY); // Debounce
            }
        }

        // Control LED based on sensor state
        if (any_touched) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(50); // Poll every 50 ms
    }

    return 0;
}

