    gpioWrite(LED_PIN, state);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int any_touched = 0;
        for (int i = 0; i < 8; i++) {
            int channel_state = read_sensor_channel(SENSOR_START_PIN + i);

            if (channel_state == 1) {
                if (log_touch_event(i + 1) == 0) {
                    any_touched = 1;
                }
                gpioDelay(DEBOUNCE_DELAY); // Debounce
            }
        }

        // Control LED based on sensor state
        if (any_touched) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(50); // Poll every 50 ms
    }

    return 0;
}

