        return -1;
    }
    return 0;
}

// Configure OPT3001 sensor
int config_opt3001() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw data from OPT3001 sensor
int read_opt3001(uint16_t *raw_data) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read result: %d\n", result);
        return -1;
    }
    *raw_data = (uint16_t)SWAP((uint16_t)result);
    return 0;
}

// Convert raw data to lux value
float convert_to_lux(uint16_t raw_data) {
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result = raw_data & 0x0FFF;
    return result * (0.01 * (1 << exponent));
}

