int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s,%.2f\n", timestamp, lux_value);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (config_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        if (read_opt3001(&raw_data) == 0) {
            float lux_value = convert_to_lux(raw_data);
            log_data(lux_value);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

