#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in the specified format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the file
void log_message(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", get_timestamp(), message);
        fflush(log_file); // Ensure the message is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle the touch event
void handle_touch_event(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Touch released
        log_message("Touch Released");
    } else { // Touch detected
        log_message("Touch Detected");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for touch events
    gpioSetAlertFunc(GPIO_PIN, handle_touch_event);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable interrupt handler
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

