#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x36
#define MEASURE_CMD 0x3608
#define CRC_POLYNOMIAL 0x31
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(int *flow_rate, uint8_t *flags);
uint8_t crc8(const uint8_t *data, size_t len);
float convert_flow_rate(int16_t flow_rate);
int validate_flow_rate(float flow_rate);
int log_data(float flow_rate, uint8_t flags, const char *status);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor(int *flow_rate, uint8_t *flags) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[4];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(2); // Wait at least 2 ms

    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *flow_rate = (buffer[0] << 8) | buffer[1];
    *flags = buffer[3];

    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    size_t i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw flow rate to ml/min
float convert_flow_rate(int16_t flow_rate) {
    // Assuming a linear relationship for simplicity.
    // Adjust the scaling factor based on the sensor's datasheet.
    float flow_rate_ml_min = (float)flow_rate / 100.0; // Example scaling
    return flow_rate_ml_min;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
        return -1;
    }
    return 0;
}

// Log data to CSV file
