#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define DEBOUNCE_DELAY_MS 50

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log flame detection events
void log_flame_detection(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Flame detected at %s on GPIO %d\n", timestamp, gpio);

    FILE *fp = fopen("flame_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening flame_events.txt for writing\n");
        return;
    }

    fprintf(fp, "Flame detected at %s on GPIO %d\n", timestamp, gpio);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = 1; // Assume no flame initially (HIGH)
    int current_state;

    while (running) {
        current_state = read_flame_sensor(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_state == 0 && last_state == 1) {
            // Falling edge detected (flame detected)
            log_flame_detection(FLAME_SENSOR_GPIO);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }

        last_state = current_state;
        gpioDelay(1000); // Check every 1 ms
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

