#include <string.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void log_touch_event();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    return 0;
}

// Read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle the LED
void toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
}

// Log the touch event to a file
void log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off the LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    int last_touch_state = 0; // 0 = released, 1 = touched
    int current_touch_state;
    struct timespec debounce_start, current_time;
    long debounce_time_elapsed;

    // Main loop
    while (running) {
        current_touch_state = read_touch_sensor();

        if (current_touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            clock_gettime(CLOCK_MONOTONIC, &debounce_start);
            last_touch_state = 1;
        }

        if (current_touch_state == 0 && last_touch_state == 1) {
            // Falling edge detected
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            debounce_time_elapsed = (current_time.tv_sec - debounce_start.tv_sec) * 1000000L + (current_time.tv_nsec - debounce_start.tv_nsec) / 1000L;

            if (debounce_time_elapsed >= DEBOUNCE_DELAY) {
                toggle_led();
                log_touch_event();
                last_touch_state = 0;
            }
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

