            clock_gettime(CLOCK_MONOTONIC, &current_time);
            debounce_time_elapsed = (current_time.tv_sec - debounce_start.tv_sec) * 1000000L + (current_time.tv_nsec - debounce_start.tv_nsec) / 1000L;

            if (debounce_time_elapsed >= DEBOUNCE_DELAY) {
                toggle_led();
                log_touch_event();
                last_touch_state = 0;
            }
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

