#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HEART_RATE_REG 0x24
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *raw_hr);
int apply_moving_average(int *data, int size, int *filtered_data);
int validate_bpm(int bpm);
int log_data(int bpm);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1182 sensor
int initialize_sensor() {
    // Check PART_ID and HW_REV
    int part_id, hw_rev;
    if (i2cReadI2CBlockData(i2c_handle, PART_ID_REG, (char*)&part_id, 1) != 1) {
        fprintf(log_file, "%s,ERROR,Failed to read PART_ID\n", __TIME__);
        fflush(log_file);
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, HW_REV_REG, (char*)&hw_rev, 1) != 1) {
        fprintf(log_file, "%s,ERROR,Failed to read HW_REV\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    if (part_id != 0x82 || hw_rev != 0x01) {
        fprintf(log_file, "%s,ERROR,Incorrect PART_ID or HW_REV: 0x%02X, 0x%02X\n", __TIME__, part_id, hw_rev);
        fflush(log_file);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // Example register write
        fprintf(log_file, "%s,ERROR,Failed to write to register 0x02\n", __TIME__);
        fflush(log_file);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x02) < 0) { // Example register write
        fprintf(log_file, "%s,ERROR,Failed to write to register 0x03\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    return 0;
}

// Read raw heart rate data from the sensor
int read_sensor_data(int *raw_hr) {
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
        if (result == 2) {
            *raw_hr = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(log_file, "%s,ERROR,I2C read failed (attempt %d): %d\n", __TIME__, i + 1, result);
            fflush(log_file);
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(log_file, "%s,ERROR,Failed to read heart rate after multiple retries\n", __TIME__);
    fflush(log_file);
    return -1; // Failure
}

// Apply a moving average filter
int apply_moving_average(int *data, int size, int *filtered_data) {
    if (size < MOVING_AVG_SIZE) return -1; // Not enough data for filtering

    int sum = 0;
    for (int i = 0; i < MOVING_AVG_SIZE; ++i) {
        sum += data[i];
    }
    filtered_data[0] = sum / MOVING_AVG_SIZE;

    for (int i = MOVING_AVG_SIZE; i < size; ++i) {
        sum = sum - data[i - MOVING_AVG_SIZE] + data[i];
        filtered_data[i - MOVING_AVG_SIZE + 1] = sum / MOVING_AVG_SIZE;
    }

    return 0;
}

// Validate the BPM value
int validate_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

// Log the data to a file
int log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    int raw_hr[MOVING_AVG_SIZE];
    int filtered_hr[MOVING_AVG_SIZE];
    int bpm;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_hr[MOVING_AVG_SIZE - 1]) == 0) {
            // Apply moving average filter
            if (apply_moving_average(raw_hr, MOVING_AVG_SIZE, filtered_hr) == 0) {
                // Validate BPM
                bpm = filtered_hr[MOVING_AVG_SIZE - 1];
                if (validate_bpm(bpm)) {
                    // Log data
                    log_data(bpm);
                } else {
                    fprintf(log_file, "%s,ERROR,BPM out of range: %d\n", __TIME__, bpm);
                    fflush(log_file);
                }
            } else {
                fprintf(log_file, "%s,ERROR,Failed to apply moving average filter\n", __TIME__);
                fflush(log_file);
            }
        } else {
            fprintf(log_file, "%s,ERROR,Failed to read sensor data\n", __TIME__);
            fflush(log_file);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

