#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;
static volatile int flame_detected = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to log the flame detection event
int log_flame_detection() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s FLAME DETECTED\n", timestamp);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file!\n");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file!\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0 && !flame_detected) {
            printf("FLAME DETECTED\n");
            if (log_flame_detection() != 0) {
                fprintf(stderr, "Error logging flame detection.\n");
            }
            flame_detected = 1; // Set the flag to prevent duplicate alerts
        } else if (sensor_value == 1 && flame_detected) {
