#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for input and output
#define NUM_CHANNELS 8
const int input_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
const int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

// Define GPIO chip and line numbers
const char *chip_name = "gpiochip0";

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *input_lines[NUM_CHANNELS];
struct gpiod_line *output_lines[NUM_CHANNELS];

// Global variables for counter and log file
volatile unsigned char counter = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int channel);
int update_counter(int channel);
int update_output(int channel, unsigned char value);
int log_event(int channel, unsigned char counter_value);
void cleanup_gpio(int signal);

// Signal handler for graceful shutdown
void cleanup_gpio(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Reset output pins to 0
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i] != NULL) {
            gpiod_line_set_value(output_lines[i], 0);
        }
    }

    // Release GPIO lines and chip
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (input_lines[i] != NULL) {
            gpiod_line_release(input_lines[i]);
        }
        if (output_lines[i] != NULL) {
            gpiod_line_release(output_lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines and chip
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", chip_name);
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    // Open input lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        input_lines[i] = gpiod_chip_get_line(chip, input_pins[i]);
        if (!input_lines[i]) {
            fprintf(stderr, "Error getting input line %d: %d\n", input_pins[i], input_pins[i]);
            perror("gpiod_chip_get_line");
            return -1;
        }

        if (gpiod_line_request_input(input_lines[i], "touch_sensor_input") < 0) {
            fprintf(stderr, "Error requesting input line %d: %d\n", input_pins[i], input_pins[i]);
            perror("gpiod_line_request_input");
            return -1;
        }
    }

    // Open output lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting output line %d: %d\n", output_pins[i], output_pins[i]);
            perror("gpiod_chip_get_line");
            return -1;
        }

        if (gpiod_line_request_output(output_lines[i], "touch_sensor_output", 0) < 0) {
            fprintf(stderr, "Error requesting output line %d: %d\n", output_pins[i], output_pins[i]);
            perror("gpiod_line_request_output");
            return -1;
        }
    }

    return 0;
}

// Read sensor value from a specific channel
int read_sensor(int channel) {
    if (channel < 0 || channel >= NUM_CHANNELS) {
        fprintf(stderr, "Invalid channel number: %d\n", channel);
        return -1;
    }

    int value = gpiod_line_get_value(input_lines[channel]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value from channel %d: %d\n", channel, input_pins[channel]);
        perror("gpiod_line_get_value");
        return -1;
    }

    return value;
}

// Update the 8-bit binary counter
int update_counter(int channel) {
    unsigned char new_value = counter + 1;
    if (new_value > 255) {
        new_value = 0;
    }
    counter = new_value;

    return counter;
}

// Update the output pins based on the counter value
int update_output(int channel, unsigned char value) {
    int bit = 0;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (i < value) {
            bit = 1;
        }
        if (gpiod_line_set_value(output_lines[i], bit) < 0) {
            fprintf(stderr, "Error setting output value for channel %d: %d\n", i, output_pins[i]);
            perror("gpiod_line_set_value");
            return -1;
        }
    }
    return 0;
}

// Log the event to a file
int log_event(int channel, unsigned char counter_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter_value);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup_gpio);
    signal(SIGTERM, cleanup_gpio);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        perror("fopen");
        // Continue without logging, but cleanup GPIO on exit
    }

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_sensor(i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor value from channel %d. Skipping.\n", i + 1);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1) {
                counter = update_counter(i);
                if (update_output(i, counter) < 0) {
                    fprintf(stderr, "Error updating output for channel %d.\n", i + 1);
                }
                if (log_event(i, counter) < 0) {
                    fprintf(stderr, "Error logging event for channel %d.\n", i + 1);
                }
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
        usleep(10000); // 10 ms delay
    }

    return 0;
}

