            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        if (write_to_csv(log_file, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
            // Handle write error, continue to the next iteration
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(100); // Wait 100ms
    }

    // Close the CSV file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

