#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate (Hz)
#define SAMPLING_RATE 8000

// Define LED on time (ms)
#define LED_ON_TIME 100

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int sample_microphone();
void handle_peak();
void signal_handler(int signal);
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Sample the microphone
int sample_microphone() {
    return gpioRead(MIC_PIN);
}

// Handle a detected peak
void handle_peak() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%lld.%09ld\n", ts.tv_sec, ts.tv_nsec);

    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(LED_ON_TIME * 1000); // Delay for 100 ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Microphone sampling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (sample_microphone() == 1) {
            handle_peak();
        }
        gpioDelay(1250); // Delay to achieve 8 kHz sampling rate
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

