#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGTERM received, exiting gracefully...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the sensor states
int read_sensor_states(int *left, int *center, int *right) {
    *left = gpioRead(LEFT_SENSOR_PIN);
    *center = gpioRead(CENTER_SENSOR_PIN);
    *right = gpioRead(RIGHT_SENSOR_PIN);

    if (*left < 0 || *center < 0 || *right < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1;
    }

    return 0;
}

// Function to log the sensor states to the console
void log_sensor_states(int left, int center, int right) {
    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int left_state, center_state, right_state;

    // Main loop
    while (program_running) {
        if (read_sensor_states(&left_state, &center_state, &right_state) == 0) {
            log_sensor_states(left_state, center_state, right_state);
        } else {
            fprintf(stderr, "Error reading sensor states, retrying...\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

