#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x49

// Si1175 register addresses (Example, adjust based on datasheet)
#define SI1175_REG_ALS_DATA_LSB 0x22
#define SI1175_REG_ALS_DATA_MSB 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read ALS data from Si1175
int read_als_data(int i2c_handle) {
    char buf[2];
    int result;

    // Read LSB
    result = i2cReadI2CBlockData(i2c_handle, SI1175_REG_ALS_DATA_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine LSB and MSB
    int als_value = (buf[1] << 8) | buf[0];

    return als_value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int als_value = read_als_data(i2c_handle);
        if (als_value >= 0) {
            printf("ALS Value: %d\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

