#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 2
#define MIDDLE_SENSOR 3
#define RIGHT_SENSOR 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int left_gpio, int middle_gpio, int right_gpio) {
    int left_value, middle_value, right_value;

    // Read left sensor
    left_value = gpioRead(left_gpio);
    if (left_value < 0) {
        fprintf(stderr, "Error reading left sensor: %d\n", left_value);
        return -1; // Indicate an error
    }

    // Read middle sensor
    middle_value = gpioRead(middle_gpio);
    if (middle_value < 0) {
        fprintf(stderr, "Error reading middle sensor: %d\n", middle_value);
        return -1; // Indicate an error
    }

    // Read right sensor
    right_value = gpioRead(right_gpio);
    if (right_value < 0) {
        fprintf(stderr, "Error reading right sensor: %d\n", right_value);
        return -1; // Indicate an error
    }

    return (left_value << 2) | (middle_value << 1) | right_value; // Combine into a single integer
}

// Function to log the sensor values
void log_sensor_data(int sensor_data) {
    printf("L:%d M:%d R:%d\n", sensor_data & 0x01, (sensor_data >> 1) & 0x01, sensor_data >> 2);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor_data = read_sensors(LEFT_SENSOR, MIDDLE_SENSOR, RIGHT_SENSOR);
        if (sensor_data >= 0) {
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        // Wait 100 milliseconds
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

