#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for each channel
#define CH1_PIN 5
#define CH2_PIN 6
#define CH3_PIN 13
#define CH4_PIN 19
#define CH5_PIN 26
#define CH6_PIN 12
#define CH7_PIN 16
#define CH8_PIN 20

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read the state of all channels
int read_channels(int *channels)
{
    int result;

    result = gpioRead(CH1_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH1: %d\n", result);
        return -1;
    }
    channels[0] = result;

    result = gpioRead(CH2_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH2: %d\n", result);
        return -1;
    }
    channels[1] = result;

    result = gpioRead(CH3_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH3: %d\n", result);
        return -1;
    }
    channels[2] = result;

    result = gpioRead(CH4_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH4: %d\n", result);
        return -1;
    }
    channels[3] = result;

    result = gpioRead(CH5_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH5: %d\n", result);
        return -1;
    }
    channels[4] = result;

    result = gpioRead(CH6_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH6: %d\n", result);
        return -1;
    }
    channels[5] = result;

    result = gpioRead(CH7_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH7: %d\n", result);
        return -1;
    }
    channels[6] = result;

    result = gpioRead(CH8_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading CH8: %d\n", result);
        return -1;
    }
    channels[7] = result;

    return 0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(CH1_PIN, PI_INPUT);
    gpioSetMode(CH2_PIN, PI_INPUT);
    gpioSetMode(CH3_PIN, PI_INPUT);
    gpioSetMode(CH4_PIN, PI_INPUT);
    gpioSetMode(CH5_PIN, PI_INPUT);
    gpioSetMode(CH6_PIN, PI_INPUT);
    gpioSetMode(CH7_PIN, PI_INPUT);
    gpioSetMode(CH8_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec ts;
    int channels[8];
    double elapsed_time;

    // Main loop
    while (!terminate) {
        // Read the state of all channels
        if (read_channels(channels) != 0) {
            fprintf(stderr, "Error reading channels, exiting...\n");
            break;
        }

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        elapsed_time = (ts.tv_sec + ts.tv_nsec / 1000000000.0);

        // Print the data to the console
        printf("[%.6f] ", elapsed_time);
        for (int i = 0; i < 8; i++) {
            printf("CH%d=%d ", i + 1, channels[i]);
        }
        printf("\n");

        // Wait for 200ms
        gpioDelay(200000); // 200ms = 200000 microseconds
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

