#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

// Define fade duration (in seconds)
#define FADE_DURATION 5

// Define fade steps
#define FADE_STEPS (FADE_DURATION * 10) // 10ms intervals

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int set_pwm_frequency(int frequency);
int set_pwm_range(int range);
int set_gpio_mode(int pin, int mode);
int set_gpio_dutycycle(int pin, int dutycycle);
int fade_color(int red_start, int green_start, int blue_start, int red_end, int green_end, int blue_end, int steps);
int generate_random_color();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");
    return 0;
}

// Set PWM frequency
int set_pwm_frequency(int frequency) {
    if (gpioSetPWMfrequency(RED_PIN, frequency) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for Red pin");
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, frequency) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for Green pin");
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, frequency) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for Blue pin");
        return -1;
    }
    syslog(LOG_INFO, "PWM frequency set to %d Hz", frequency);
    return 0;
}

// Set PWM range
int set_pwm_range(int range) {
    if (gpioSetPWMrange(RED_PIN, range) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for Red pin");
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, range) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for Green pin");
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, range) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for Blue pin");
        return -1;
    }
    syslog(LOG_INFO, "PWM range set to %d", range);
    return 0;
}

// Set GPIO mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for pin %d", pin);
        return -1;
    }
    syslog(LOG_INFO, "GPIO mode set to %d for pin %d", mode, pin);
    return 0;
}

// Set GPIO dutycycle
int set_gpio_dutycycle(int pin, int dutycycle) {
