// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO pin for LED
#define LED_PIN 17

// Red value threshold
#define RED_THRESHOLD 200

// I2C handle
int i2c_handle;

// Function prototypes
int tcs34725_init();
int tcs34725_read_data(unsigned int *red, unsigned int *green, unsigned int *blue, unsigned int *clear);
void control_led(unsigned int red_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// TCS34725 initialization function
int tcs34725_init() {
    // Power on the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to power on TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Failed to set integration time\n");
        return -1;
    }

    // Enable RGBC (AEN)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to enable RGBC\n");
        return -1;
    }

    return 0;
}

// TCS34725 data reading function
int tcs34725_read_data(unsigned int *red, unsigned int *green, unsigned int *blue, unsigned int *clear) {
    unsigned char data[8];

    // Read all color data (C, R, G, B) in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, (char *)data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read color data\n");
        return -1;
    }

    // Combine the bytes to form 16-bit color values
    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

// LED control function
void control_led(unsigned int red_value) {
    if (red_value > RED_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int red, green, blue, clear;

    // Main loop
    while (1) {
        // Read color data
        if (tcs34725_read_data(&red, &green, &blue, &clear) == 0) {
            // Control LED
            control_led(red);

            // Print color values
            printf("R: %u, G: %u, B: %u, C: %u\n", red, green, blue, clear);
        } else {
            // Attempt to re-initialize the sensor
            fprintf(stderr, "Error: Failed to read data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            if (gpioInitialise() < 0) {
                fprintf(stderr, "Error: pigpio initialisation failed during re-initialization\n");
                return 1;
            }
            i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to open I2C bus during re-initialization\n");
                gpioTerminate();
                return 1;
            }
            if (tcs34725_init() < 0) {
                fprintf(stderr, "Error: TCS34725 initialisation failed during re-initialization\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        // Wait 200ms
        gpioDelay(200000); // 200ms = 200000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

