#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define BH1750_ADDR 0x23
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float calculate_brightness(int lux);
void set_led_color(int led_index, int red, int green, int blue);
void send_led_data(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config[1] = {0x10}; // Continuous high-resolution mode
    char buffer[2];
    int lux = -1; // Initialize to an error value
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(180000); // 180ms delay

        if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        lux = (buffer[0] << 8) | buffer[1];
        break; // Exit retry loop on success
    }

    if (lux == -1) {
        fprintf(stderr, "Failed to read lux value after multiple retries.\n");
    }

    return lux;
}

// Function to calculate brightness level from lux value
float calculate_brightness(int lux) {
    // Use a logarithmic scale to map lux to brightness (0-100)
    // Adjust the base of the logarithm to control the sensitivity
    float brightness = 100.0 * log10(lux + 1) / log10(10000 + 1); // Assuming max lux is 10000
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;
    return brightness;
}

// Function to set the color of a single LED
void set_led_color(int led_index, int red, int green, int blue) {
    // WS2812B uses a 24-bit color code: GRB
    // Each bit represents a color component (0=off, 1=on)
    // The LED strip expects a 50us pulse for 0 and a 150us pulse for 1
    // This is a simplified version and assumes a single color for all LEDs
    // In a real application, you would need to send the correct color data for each LED
