#include <errno.h>
#include <string.h>

// Configuration
#define BH1750_ADDR 0x23
#define SPI_BUS 0
#define SPI_DEVICE 0
#define NUM_LEDS 16
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE_NAME "/dev/spidev0.0"

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int bh1750_init(int fd);
int bh1750_read_light(int fd);
int bh1750_is_present(int fd);
int apa102_init(int spi_bus, int spi_device);
int apa102_set_led_brightness(int spi_fd, int brightness);
int apa102_send_frame(int spi_fd, uint32_t start_frame, uint32_t led_frame, uint32_t end_frame);
void signal_handler(int sig);

// BH1750 functions
int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

int bh1750_read_light(int fd) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading light data");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int bh1750_is_present(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        if (errno == ENXIO) {
            return 0; // Not present
        }
        perror("Error checking for BH1750 presence");
        return -1;
    }
    return 1; // Present
}

// APA102 functions
int apa102_init(int spi_bus, int spi_device) {
    int fd = open(SPI_DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int apa102_set_led_brightness(int spi_fd, int brightness) {
    uint8_t data[4];
    data[0] = 0xE0; // Global brightness
    data[1] = (brightness & 0xFF) << 4; // Blue
    data[2] = ((brightness & 0x0F) << 4) | 0xFF; // Green
    data[3] = 0x00; // Red

    uint8_t buffer[4];
    for (int i = 0; i < 4; i++) {
        buffer[i] = data[i];
    }

    if (write(spi_fd, buffer, 4) != 4) {
        perror("Error writing to SPI device");
        return -1;
    }
    return 0;
}

int apa102_send_frame(int spi_fd, uint32_t start_frame, uint32_t led_frame, uint32_t end_frame) {
    uint8_t buffer[12];
    buffer[0] = (start_frame >> 24) & 0xFF;
    buffer[1] = (start_frame >> 16) & 0xFF;
    buffer[2] = (start_frame >> 8) & 0xFF;
    buffer[3] = start_frame & 0xFF;

    for (int i = 0; i < 4; i++) {
        buffer[4 + i] = (led_frame >> 24) & 0xFF;
        buffer[5 + i] = (led_frame >> 16) & 0xFF;
        buffer[6 + i] = (led_frame >> 8) & 0xFF;
        buffer[7 + i] = led_frame & 0xFF;
    }

    buffer[12] = (end_frame >> 24) & 0xFF;
    buffer[11] = (end_frame >> 16) & 0xFF;
    buffer[10] = (end_frame >> 8) & 0xFF;
    buffer[9] = end_frame & 0xFF;

    if (write(spi_fd, buffer, 12) != 12) {
        perror("Error writing to SPI device");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Initialize APA102
    spi_fd = apa102_init(SPI_BUS, SPI_DEVICE);
    if (spi_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read light level
        int light_level = bh1750_read_light(i2c_fd);
        if (light_level < 0) {
            fprintf(stderr, "Error reading light level, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Scale brightness
        int brightness = (int)(((float)light_level / 65535.0) * 255.0);
        if (brightness < 0) brightness = 0;
        if (brightness > 255) brightness = 255;

        // Set LED brightness
        if (apa102_set_led_brightness(spi_fd, brightness) < 0) {
            fprintf(stderr, "Error setting LED brightness, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Send frame
        uint32_t start_frame = 0x00000000;
        uint32_t led_frame = (brightness << 24) | (0 << 16) | (0 << 8) | 0;
        uint32_t end_frame = 0x00000000;
        if (apa102_send_frame(spi_fd, start_frame, led_frame, end_frame) < 0) {
            fprintf(stderr, "Error sending frame, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

