#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define NUM_SENSORS 3
#define I2C_BUS 1
#define APA102_GPIO 10
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_LEDS 10
#define FADE_DURATION 500 // milliseconds

// Global variables
int i2c_handles[NUM_SENSORS];
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float average_light_levels(int light_levels[], int num_sensors);
void fade_led_strip(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    int light_level = -1; // Initialize to an error value
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, 0x10) != 0) { // Start measurement in high resolution mode
            fprintf(stderr, "Error: Failed to start measurement. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        gpioDelay(180000); // Wait for measurement (at least 180ms)

        light_level = i2cReadWordData(i2c_handle, 0x00);
        if (light_level >= 0) {
            return light_level;
        } else {
            fprintf(stderr, "Error: Failed to read light level. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to read light level after multiple retries.\n");
    return -1; // Indicate error
}

// Function to average light levels
float average_light_levels(int light_levels[], int num_sensors) {
    int valid_count = 0;
    int sum = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (light_levels[i] != -1) { // Check for valid reading
            sum += light_levels[i];
            valid_count++;
        }
    }

    if (valid_count == 0) {
        return 0.0; // Return 0 if no valid readings
    }

    return (float)sum / valid_count;
}

// Function to fade the LED strip brightness
void fade_led_strip(int brightness) {
    int num_steps = 20; // Number of steps for smooth fading
    int step_size = (brightness > 255) ? (brightness - 255) : 0;
    int current_brightness = 0;
    int increment = step_size / num_steps;

    for (int i = 0; i < num_steps; i++) {
        current_brightness += increment;
        if (current_brightness > 255) {
            current_brightness = 255;
        }

        // APA102 data format: Start frame (4 bytes of 0x00), LED data (4 bytes per LED), End frame (4 bytes of 0xFF)
        // Each LED has 4 bytes: Blue, Green, Red, Global brightness (0-255)

        // Start frame
        gpioWrite(APA102_GPIO, 0); // MOSI low
        gpioDelay(1000); // 1 us

        // LED data
        for (int j = 0; j < NUM_LEDS; j++) {
            // Blue
            gpioWrite(APA102_GPIO, 0x06); // MOSI high
            gpioDelay(1000); // 1 us
            gpioWrite(APA102_GPIO, 0x00); // MOSI low
            gpioDelay(1000); // 1 us

            // Green
            gpioWrite(APA102_GPIO, 0x06); // MOSI high
            gpioDelay(1000); // 1 us
            gpioWrite(APA102_GPIO, 0x00); // MOSI low
            gpioDelay(1000); // 1 us

            // Red
            gpioWrite(APA102_GPIO, 0x06); // MOSI high
            gpioDelay(1000); // 1 us
            gpioWrite(APA102_GPIO, 0x00); // MOSI low
            gpioDelay(1000); // 1 us

            // Global brightness
            gpioWrite(APA102_GPIO, 0x06); // MOSI high
            gpioDelay(1000); // 1 us
            gpioWrite(APA102_GPIO, (unsigned char)current_brightness); // MOSI low
            gpioDelay(1000); // 1 us
        }

        // End frame
        gpioWrite(APA102_GPIO, 0xFF); // MOSI high
        gpioDelay(1000); // 1 us
        gpioWrite(APA102_GPIO, 0xFF); // MOSI low
        gpioDelay(1000); // 1 us

        gpioDelay(1000); // 1 us delay between frames
    }
}

