#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// GPIO pin for WS2812B data line
#define LED_PIN 18

// Gamma correction parameters
#define GAMMA 2.2

// I2C handle
int i2c_handle;

// Function prototypes
int init_veml7700();
int read_veml7700(uint16_t *als_data);
float calculate_lux(uint16_t als_data);
uint8_t gamma_correct(float lux);
void drive_led(uint8_t brightness);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configuration value: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Example configuration, adjust as needed
    char buf[3];
    buf[0] = VEML7700_CONFIG;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register\n");
        return -1;
    }
    return 0;
}

// Read ambient light data from VEML7700
int read_veml7700(uint16_t *als_data) {
    char reg = VEML7700_ALS_DATA;
    char buf[1];
    buf[0] = reg;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to VEML7700 ALS data register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS data register\n");
        return -1;
    }

    *als_data = (data[1] << 8) | data[0];
    return 0;
}

// Calculate lux value from ambient light data
float calculate_lux(uint16_t als_data) {
    // Conversion formula from VEML7700 datasheet
    // This is a simplified example; refer to the datasheet for the correct formula
    // based on your configuration.
    float lux = (float)als_data * 0.0576; // Example conversion factor
    return lux;
}

// Gamma correction function
uint8_t gamma_correct(float lux) {
    float linear_brightness = lux / 1000.0; // Scale lux to a reasonable range
    float gamma_corrected_brightness = powf(linear_brightness, 1.0 / GAMMA); // Apply gamma correction
    uint8_t brightness = (uint8_t)(gamma_corrected_brightness * 255.0); // Scale to 0-255
    return brightness;
}

// Drive WS2812B LED strip
void drive_led(uint8_t brightness) {
    // Bit-banging implementation (simplified)
    for (int i = 0; i < 24; i++) {
        // Set bit (1) or clear bit (0) based on the bit value of the brightness
        gpioWrite(LED_PIN, (brightness >> i) & 1);
        gpioDelay(1); // Adjust delay for desired frequency (approx. 800 kHz)
    }
    gpioDelay(1000); // Keep LED on for 1ms
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als_data;
    float lux;
    uint8_t brightness;

    // Main loop
    while (!terminate) {
        // Read ambient light data
        if (read_veml7700(&als_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(als_data);

            // Gamma correct the lux value
            brightness = gamma_correct(lux);

            // Drive the LED strip
            drive_led(brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Error reading VEML7700 data\n");
        }

        // Wait for 200ms
        gpioDelay(200000); // 200ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

