    log_event("Self-test started");

    // LED blink test
    for (int i = 0; i < 2; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500);
        gpioWrite(LED_PIN, 0);
        gpioDelay(500);
    }
    log_event("LED blink test passed");

