    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Run self-test
    self_test();

    // Main loop
    int last_flame_state = 1; // Assume no flame initially
    while (program_running) {
        int flame_state = gpioRead(FLAME_SENSOR_PIN);

        if (flame_state == 0 && last_flame_state == 1) {
            printf("Flame detected!\n");
