            log_event("Flame cleared");
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
        }

        last_flame_state = flame_state;
        gpioDelay(50); // Check every 50 ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

