#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MIN_LUX 0
#define MAX_LUX 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_bh1750();
void init_gpio();
void cleanup_gpio();
void init_circular_buffer(CircularBuffer *cb);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_lux);
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
float read_bh1750() {
    char config[1] = {0x10}; // Continuous high-resolution mode
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1.0;
    }
    gpioDelay(200); // Wait for measurement (at least 180ms)

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1.0;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / 1.2; // Convert to lux
}

// Initialize GPIO
void init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        terminate = 1; // Signal termination
    }
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set back to input (safer)
    gpioTerminate();
}

// Control LED frequency based on lux
void control_led(float average_lux) {
    float frequency = MIN_FREQUENCY + (average_lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_LUX - MIN_LUX);
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    float period = 1.0 / frequency;
    float on_time = period / 2.0;
    float off_time = period / 2.0;

    gpioWrite(GPIO_LED, 1); // Turn on LED
    gpioDelay(on_time * 1000000); // Delay in microseconds
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioDelay(off_time * 1000000); // Delay in microseconds
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    init_gpio();

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0) {
            add_to_circular_buffer(&lux_buffer, lux);
            float average_lux = calculate_average(&lux_buffer);
            control_led(average_lux);
        } else {
            fprintf(stderr, "Error reading lux, skipping sample.\n");
        }

        sleep(1);
    }

    // Cleanup
    cleanup_gpio();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

