#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define BUTTON_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int led_state = 0;
    int button_state = 1; // Initialize button state to HIGH (pulled up)
    int last_button_state = 1; // Store the last button state for edge detection
    int gpio_initialized = 0; // Flag to track if GPIO is initialized

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set button pin as input with pull-up resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on button pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on falling edge of button pin
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, (gpioISRFuncEx_t)button_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt on button pin\n");
        gpioTerminate();
        return 1;
    }

    // Main loop to blink the LED
    while (program_running) {
        gpioWrite(LED_PIN, led_state);
        gpioDelay(1000000); // 1 second delay

        // Toggle LED state
        led_state = !led_state;

        // Check button state
        button_state = gpioRead(BUTTON_PIN);

        // Check for button press (falling edge detected by interrupt)
        if (button_state == 0 && last_button_state == 1) {
            printf("Button pressed! Stopping blinking and exiting.\n");
            gpioWrite(LED_PIN, 0); // Turn off LED
            gpioTerminate(); // Terminate pigpio
            break; // Exit the main loop
        }

        last_button_state = button_state;
    }

    return 0;
}

void button_interrupt(int gpio, int level, uint32_t tick, void *user) {
    // This interrupt is triggered when the button falls (goes low)
    // The main loop will handle the LED blinking and program termination
}

