#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track button state
static volatile int button_pressed = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 (LED) as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO22 (Button) as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-down resistor on GPIO22
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0)
    {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        // Read button state
        int button_state = gpioRead(BUTTON_PIN);

        // Check if button is pressed (low signal due to pull-down)
        if (button_state == 0 && !button_pressed)
        {
            // Button is pressed
            button_pressed = 1;

            // Blink LED
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(500000);      // Wait 500ms
            gpioWrite(LED_PIN, 0); // Turn LED off
            gpioDelay(500000);      // Wait 500ms
        }
        else
        {
            // Button is not pressed
            button_pressed = 0;

            // Turn LED off
            gpioWrite(LED_PIN, 0);
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    // This point should not be reached due to the signal handler
    return 0;
}

