#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-1000 for 10ms period)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to set the color of the RGB LED
void set_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a random color
void generate_random_color(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

// Function to perform PWM on a single color channel
void pwm_loop(int pin, int intensity) {
    int range = PWM_RANGE;
    int period = 1000000 / PWM_FREQUENCY; // Period in microseconds
    int delay_us = period - (intensity * period / 100);

    for (int i = 0; i < range && program_running; ++i) {
        gpioWrite(pin, 1);
        gpioDelay(delay_us);
        gpioWrite(pin, 0);
        gpioDelay(delay_us);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("RGB LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int red, green, blue;

        // Generate a random color
        generate_random_color(&red, &green, &blue);

        // Set the color of the LED
        set_color(red, green, blue);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up GPIO pins before exiting
    gpioTerminate();

    return 0;
}

