#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// ADPD188BI Register Addresses
#define ADPD188BI_ALS_LSB 0x00
#define ADPD188BI_ALS_MSB 0x01
#define ADPD188BI_RED_LSB 0x02
#define ADPD188BI_RED_MSB 0x03
#define ADPD188BI_GREEN_LSB 0x04
#define ADPD188BI_GREEN_MSB 0x05
#define ADPD188BI_BLUE_LSB 0x06
#define ADPD188BI_BLUE_MSB 0x07

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
int write_sensor_register(uint8_t reg, uint8_t value);
int read_sensor_register(uint8_t reg, uint8_t *value);
uint16_t combine_16bit_data(uint8_t lsb, uint8_t msb);
int set_led_brightness(uint16_t als);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read Sensor Data
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t als_lsb, als_msb, red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    als_lsb = read_sensor_register(ADPD188BI_ALS_LSB, &als_lsb);
    als_msb = read_sensor_register(ADPD188BI_ALS_MSB, &als_msb);
    red_lsb = read_sensor_register(ADPD188BI_RED_LSB, &red_lsb);
    red_msb = read_sensor_register(ADPD188BI_RED_MSB, &red_msb);
    green_lsb = read_sensor_register(ADPD188BI_GREEN_LSB, &green_lsb);
    green_msb = read_sensor_register(ADPD188BI_GREEN_MSB, &green_msb);
    blue_lsb = read_sensor_register(ADPD188BI_BLUE_LSB, &blue_lsb);
    blue_msb = read_sensor_register(ADPD188BI_BLUE_MSB, &blue_msb);

    if (als_lsb < 0 || als_msb < 0 || red_lsb < 0 || red_msb < 0 || green_lsb < 0 || green_msb < 0 || blue_lsb < 0 || blue_msb < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *als = combine_16bit_data(als_lsb, als_msb);
    *red = combine_16bit_data(red_lsb, red_msb);
    *green = combine_16bit_data(green_lsb, green_msb);
    *blue = combine_16bit_data(blue_lsb, blue_msb);

    return 0;
}

// Write to Sensor Register
int write_sensor_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read from Sensor Register
int read_sensor_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Combine 16-bit Data
uint16_t combine_16bit_data(uint8_t lsb, uint8_t msb) {
    return (uint16_t)((msb << 8) | lsb);
}

// Set LED Brightness
int set_led_brightness(uint16_t als) {
    // Map ALS value to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als / 65535.0) * 255.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_GPIO, duty_cycle);
    return 0;
}

// Log Data to CSV
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, 255);

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als, red, green, blue;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            set_led_brightness(als);
            log_data(als, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

