// Function to verify the WHO_AM_I register
int verify_who_am_i(int i2c_handle) {
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I mismatch! Expected 0xC7, got 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

