#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDR 0x69

// GY-50 L3G4200D register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F

// Calibration sample size
#define CALIBRATION_SAMPLES 100

// Alert threshold (dps)
#define ALERT_THRESHOLD 50.0

// Log file name
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int init_gyro();
int calibrate_gyro();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void check_alert(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the gyroscope
int init_gyro() {
    // Enable all gyro axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x48) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x48\n", who_am_i);
        return -1;
    }

    return 0;
}

// Function to calibrate the gyroscope
int calibrate_gyro() {
    float x_sum = 0.0;
    float y_sum = 0.0;
    float z_sum = 0.0;
    float x, y, z;

    printf("Calibrating gyroscope...\n");

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        gpioDelay(2); // Small delay between readings
    }

    x_offset = x_sum / CALIBRATION_SAMPLES;
    y_offset = y_sum / CALIBRATION_SAMPLES;
    z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to degrees per second (dps) - sensitivity is 14.375 LSB/dps
    *x = (float)x_raw / 14.375 - x_offset;
    *y = (float)y_raw / 14.375 - y_offset;
    *z = (float)z_raw / 14.375 - z_offset;

    return 0;
}

// Function to log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for alert condition
void check_alert(float x, float y, float z) {
