    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for alert condition
void check_alert(float x, float y, float z) {
    if (fabs(x) > ALERT_THRESHOLD || fabs(y) > ALERT_THRESHOLD || fabs(z) > ALERT_THRESHOLD) {
        fprintf(stderr, "WARNING: Axis(es) exceeding threshold!\n");
        fprintf(log_file, "ALERT: Axis(es) exceeding threshold!\n");
