    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, ADXL345_REG_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure ADXL345 for full-resolution mode and ±2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, ADXL345_FULL_RESOLUTION | ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

