        }

        gpioDelay(100000); // 100 ms delay (10 Hz sampling rate)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

