#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define I2C addresses for the two sensors
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define the I2C bus
#define I2C_BUS 1

// Define the sampling interval (10 ms)
#define SAMPLING_INTERVAL_US 10000

// Define the number of samples to read
#define NUM_SAMPLES 100

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, short *data);
double calculate_tdoa(short sensor1_data, short sensor2_data);
int log_data(FILE *fp, struct timespec ts, short sensor1_data, short sensor2_data, double tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close the log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data from the I2C bus
int read_sensor_data(int handle, short *data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (short)((buffer[0] << 8) | buffer[1]);

    return 0;
}

// Function to calculate the TDOA between the two channels
double calculate_tdoa(short sensor1_data, short sensor2_data) {
    // This is a placeholder for the actual TDOA calculation.
    // Replace with the appropriate algorithm for your application.
    // For example, you could use cross-correlation to find the time difference.
    // This example simply returns the difference between the two samples.
    return (double)(sensor1_data - sensor2_data);
}

// Function to log the data to a CSV file
int log_data(FILE *fp, struct timespec ts, short sensor1_data, short sensor2_data, double tdoa) {
    if (fprintf(fp, "%ld.%09ld,%d,%d,%lf\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        short sensor1_data, sensor2_data;
        struct timespec ts;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
            // Read data from sensor 2
            if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
                // Get the current timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    // Calculate the TDOA
                    double tdoa = calculate_tdoa(sensor1_data, sensor2_data);

                    // Log the data to the file
                    if (log_data(log_file, ts, sensor1_data, sensor2_data, tdoa) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "Error getting timestamp\n");
                }
            } else {
                fprintf(stderr, "Error reading from sensor 2\n");
            }
        } else {
            fprintf(stderr, "Error reading from sensor 1\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_US);
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

