#define ADIS16488A_REG_GLOB_CMD 0x68
#define ADIS16488A_REG_DIAG_STS 0x66

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function Prototypes
int spi_read_register(int reg_addr, uint16_t *data);
int spi_write_register(uint16_t command, uint16_t data);
void cleanup();
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = 0x80 | (reg_addr & 0x07); // Read command (MSB = 1, register address = 7 bits)
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Extract the data from the receive buffer
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

