    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = command & 0x07; // Write command (MSB = 0, register address = 7 bits)
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

