    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Read gyroscope data
        uint16_t gyro_x, gyro_y, gyro_z;
        if (spi_read_register(ADIS16488A_REG_XGYRO_OUT, &gyro_x) != 0 ||
            spi_read_register(ADIS16488A_REG_YGYRO_OUT, &gyro_y) != 0 ||
            spi_read_register(ADIS16488A_REG_ZGYRO_OUT, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
            continue;
        }

        // Read accelerometer data
        uint16_t accel_x, accel_y, accel_z;
        if (spi_read_register(ADIS16488A_REG_XACCEL_OUT, &accel_x) != 0 ||
            spi_read_register(ADIS16488A_REG_YACCEL_OUT, &accel_y) != 0 ||
            spi_read_register(ADIS16488A_REG_ZACCEL_OUT, &accel_z) != 0) {
            fprintf(stderr, "Error reading accel data\n");
            continue;
        }

        // Convert raw data to physical units
        float gyro_x_rate = gyro_x * 0.005;
        float gyro_y_rate = gyro_y * 0.005;
        float gyro_z_rate = gyro_z * 0.005;
        float accel_x_g = accel_x * 0.00025;
        float accel_y_g = accel_y * 0.00025;
        float accel_z_g = accel_z * 0.00025;

        // Log data to CSV file
        fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp_ms, gyro_x_rate, gyro_y_rate, gyro_z_rate, accel_x_g, accel_y_g, accel_z_g);
        fflush(fp); // Ensure data is written to disk immediately

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

