#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define ADIS16448_REG_GYRO_XOUT 0x04
#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCL_XOUT 0x0A
#define ADIS16448_REG_ACCL_YOUT 0x0C
#define ADIS16448_REG_ACCL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3
#define CS_PIN 8

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} sensor_data_t;

// Function Prototypes
int initialize_spi();
int read_register(uint8_t reg_addr, int16_t *data);
sensor_data_t process_data(int16_t raw_data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read a single register from the ADIS16448
int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    gpioWrite(CS_PIN, 0); // Assert CS

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        gpioWrite(CS_PIN, 1); // De-assert CS
        return -1;
    }

    gpioWrite(CS_PIN, 1); // De-assert CS

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Process raw data to get physical units
sensor_data_t process_data(int16_t raw_data) {
    sensor_data_t data;

    // Gyroscope
    data.gyro_x = (float)raw_data * 0.02; // 0.02 dps/LSB
    data.gyro_y = (float)raw_data * 0.02;
    data.gyro_z = (float)raw_data * 0.02;

    // Accelerometer
    data.accel_x = (float)raw_data * 0.00025; // 0.00025 g/LSB
    data.accel_y = (float)raw_data * 0.00025;
    data.accel_z = (float)raw_data * 0.00025;

    return data;
}

// Log sensor data to the console
void log_data(sensor_data_t data) {
    printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Acc X: %.4f g, Acc Y: %.4f g, Acc Z: %.4f g\n",
           data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // De-assert CS initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_data;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_register(ADIS16448_REG_GYRO_XOUT, &raw_data) == 0) {
            sensor_data.gyro_x = process_data(raw_data).gyro_x;
        } else {
            sensor_data.gyro_x = 0.0; // Set to 0 on error
        }

        // Read accelerometer data
        if (read_register(ADIS16448_REG_ACCL_XOUT, &raw_data) == 0) {
            sensor_data.accel_x = process_data(raw_data).accel_x;
        } else {
            sensor_data.accel_x = 0.0; // Set to 0 on error
        }

        // Read gyroscope data
        if (read_register(ADIS16448_REG_GYRO_YOUT, &raw_data) == 0) {
            sensor_data.gyro_y = process_data(raw_data).gyro_y;
        } else {
            sensor_data.gyro_y = 0.0; // Set to 0 on error
        }

        // Read accelerometer data
        if (read_register(ADIS16448_REG_ACCL_YOUT, &raw_data) == 0) {
            sensor_data.accel_y = process_data(raw_data).accel_y;
        } else {
            sensor_data.accel_y = 0.0; // Set to 0 on error
        }

        // Read gyroscope data
        if (read_register(ADIS16448_REG_GYRO_ZOUT, &raw_data) == 0) {
            sensor_data.gyro_z = process_data(raw_data).gyro_z;
        } else {
            sensor_data.gyro_z = 0.0; // Set to 0 on error
        }

        // Read accelerometer data
        if (read_register(ADIS16448_REG_ACCL_ZOUT, &raw_data) == 0) {
            sensor_data.accel_z = process_data(raw_data).accel_z;
        } else {
            sensor_data.accel_z = 0.0; // Set to 0 on error
        }

        // Log the data
        log_data(sensor_data);

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

