#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the MPU-6886
int init_mpu6886(int i2c_handle)
{
    // Wake up the MPU-6886 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6886\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6886(int i2c_handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buf[14];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14);
        if (result == 14) {
            // Success
            *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
            *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
            *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
            *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
            *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
            *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: I2C read failed after multiple retries\n");
    return -1; // Failure
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mpu6886(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 us
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

