#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define WHO_AM_I 0x0D
#define LED_GPIO 17
#define THRESHOLD 2.0f
#define SENSITIVITY 1024.0f // Counts per g
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor_id();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void handle_signal(int signal);

// Signal handler
void handle_signal(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        fprintf(stderr, "Sensor ID verification failed.\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure accelerometer (±2g range, 100 Hz ODR)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    int sensor_id = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", sensor_id);
        return -1;
    }

    if (sensor_id != 0x48) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    printf("Sensor ID verified: 0x%02X\n", sensor_id);
    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", i2c_handle);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SENSITIVITY;
    float y_g = (float)y / SENSITIVITY;
    float z_g = (float)z / SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log data to file
int log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            log_data(x, y, z, magnitude);

            if (magnitude > THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn on LED
                gpioDelay(500);         // Wait 500 ms
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

