#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define INT1_GPIO 17
#define FREEFALL_THRESHOLD 0.2 // g
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds
#define LOG_FILE "freefall_log.csv"

// ADXL345 Registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_FILTER 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init(int i2c_fd);
int adxl345_read_acceleration(int i2c_fd, float *x, float *y, float *z);
int adxl345_freefall_detected(int i2c_fd);
int log_data(FILE *log_file, float x, float y, float z);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Helper function to read a register
int adxl345_read_register(int i2c_fd, uint8_t reg, uint8_t *value) {
    if (i2c_smbus_read_byte_data(i2c_fd, reg) < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = i2c_smbus_read_byte_data(i2c_fd, reg);
    return 0;
}

// Helper function to write a register
int adxl345_write_register(int i2c_fd, uint8_t reg, uint8_t value) {
    if (i2c_smbus_write_byte_data(i2c_fd, reg, value) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INT1_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float x, y, z;
    int freefall_active = 0;
    uint32_t last_interrupt_time = 0;

    while (program_running) {
        if (adxl345_freefall_detected(i2c_fd)) {
            if (!freefall_active) {
                freefall_active = 1;
                printf("Freefall detected!\n");
            }
        } else {
            freefall_active = 0;
            printf("Freefall ended.\n");
        }

        if (freefall_active) {
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                if (log_data(log_file, x, y, z) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error reading acceleration data.\n");
            }
        }

        usleep(SAMPLE_PERIOD);
    }

    // Clean up
    gpioSetISRFuncEx(INT1_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

int adxl345_init(int i2c_fd) {
    uint8_t device_id;

    // Verify device ID
    if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0, &device_id) != 0) {
        fprintf(stderr, "Error reading device ID.\n");
        return -1;
    }

    if (device_id != 0xAD) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Set data format: +/- 2g range, full resolution
    if (adxl345_write_register(i2c_fd, ADXL345_REG_DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Error setting data format.\n");
        return -1;
    }

    // Set filter: ODR = 100 Hz, BW = 62.5 Hz
    if (adxl345_write_register(i2c_fd, ADXL345_REG_FILTER, 0x03) != 0) {
        fprintf(stderr, "Error setting filter.\n");
        return -1;
    }

    // Set power control: Measure mode
    if (adxl345_write_register(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error setting power control.\n");
        return -1;
    }

    return 0;
}

int adxl345_read_acceleration(int i2c_fd, float *x, float *y, float *z) {
    uint8_t x0, x1, y0, y1, z0, z1;
    int16_t x_raw, y_raw, z_raw;

    if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0, &x0) != 0 ||
        adxl345_read_register(i2c_fd, ADXL345_REG_DATAX1, &x1) != 0 ||
        adxl345_read_register(i2c_fd, ADXL345_REG_DATAY0, &y0) != 0 ||
        adxl345_read_register(i2c_fd, ADXL345_REG_DATAY1, &y1) != 0 ||
        adxl345_read_register(i2c_fd, ADXL345_REG_DATAZ0, &z0) != 0 ||
        adxl345_read_register(i2c_fd, ADXL345_REG_DATAZ1, &z1) != 0) {
        fprintf(stderr, "Error reading acceleration data.\n");
        return -1;
    }

    x_raw = (int16_t)((x1 << 8) | x0);
    y_raw = (int16_t)((y1 << 8) | y0);
    z_raw = (int16_t)((z1 << 8) | z0);

    // Convert to g units (assuming +/- 2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

int adxl345_freefall_detected(int i2c_fd) {
    uint8_t int_source;

    if (adxl345_read_register(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) != 0) {
        fprintf(stderr, "Error reading interrupt source.\n");
        return 0; // Return 0 to avoid false positives
    }

    return (int_source & 0x04); // Check if freefall interrupt is active
}

int log_data(FILE *log_file, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    // This function is called when INT1 goes high.
    // It's not necessary to do anything here, as the main loop handles the data.
}

void signal_handler(int signal) {
    (void)signal; // unused
    program_running = 0;
    printf("Caught signal, exiting...\n");
}

