#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Configuration values
#define ACCEL_RANGE 2.0f // ±2g
#define GYRO_RANGE 250.0f // ±250 dps
#define ODR 104.0f       // 104 Hz

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // g
#define IMPACT_THRESHOLD 2.5f  // g
#define IMPACT_WINDOW 1.0f    // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
sensor_data_t read_sensor_data();
float calculate_acceleration_magnitude(sensor_data_t data);
int detect_fall(sensor_data_t data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 104 Hz, ±250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from the LSM6DSR
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
    } else {
        int16_t accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
        int16_t accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
        int16_t accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

        // Convert to g
        data.accel_x = (float)accel_x / 16384.0f * ACCEL_RANGE;
        data.accel_y = (float)accel_y / 16384.0f * ACCEL_RANGE;
        data.accel_z = (float)accel_z / 16384.0f * ACCEL_RANGE;
    }

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
    } else {
        int16_t gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
        int16_t gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
        int16_t gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

        // Convert to dps
        data.gyro_x = (float)gyro_x / 131.0f * GYRO_RANGE;
        data.gyro_y = (float)gyro_y / 131.0f * GYRO_RANGE;
        data.gyro_z = (float)gyro_z / 131.0f * GYRO_RANGE;
    }

    return data;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Detect a fall based on acceleration magnitude
int detect_fall(sensor_data_t data) {
    static time_t last_impact_time = 0.0f;
    time_t current_time = time(NULL);

    float magnitude = calculate_acceleration_magnitude(data);

    if (magnitude < FREEFALL_THRESHOLD) {
        // Transition to FREEFALL state
        return 0;
    } else if (magnitude > IMPACT_THRESHOLD) {
        // Check if the impact occurred within the detection window
        if (last_impact_time == 0.0f) {
            last_impact_time = current_time;
        } else if (current_time - last_impact_time <= IMPACT_WINDOW) {
            // Transition to IMPACT state
            return 1;
        } else {
            // Reset the impact timer
            last_impact_time = 0.0f;
            return -1; // No impact within window
        }
    } else {
        // Reset the impact timer
        last_impact_time = 0.0f;
        return -1; // No impact
    }
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    int fall_state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT

    while (!terminate) {
        // Read sensor data
        sensor_data = read_sensor_data();

        // Detect fall
        if (detect_fall(sensor_data) == 0) {
            fall_state = 1; // Transition to FREEFALL
        } else if (detect_fall(sensor_data) == 1) {
            fall_state = 2; // Transition to IMPACT
        } else {
            fall_state = 0; // Reset to IDLE
        }

        // Log data
        log_data(sensor_data);

        // Print fall state for debugging
        printf("Fall State: %d\n", fall_state);

        // Delay for 10 ms (104 Hz)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

