#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3       // CPOL=1, CPHA=1
#define SPI_CE 0         // CE0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg_addr);
int spi_write_register(int reg_addr, int data);
int verify_who_am_i();
float read_angular_rate(int axis);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Structure for gyro data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to read a 16-bit register from the ADIS16266
int spi_read_register(int reg_addr) {
    char tx_buf[3];
    char rx_buf[3];
    int result;

    // Prepare the transmit buffer: register address (MSB first)
    tx_buf[0] = (reg_addr << 1) | 0x80; // OR with 0x80 for read
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine the received bytes to form the 16-bit value
    return ((rx_buf[1] << 8) | rx_buf[2]);
}

// Function to write a 16-bit value to a register in the ADIS16266
int spi_write_register(int reg_addr, int data) {
    char tx_buf[3];
    char rx_buf[3];
    int result;

    // Prepare the transmit buffer: register address (MSB first) and data
    tx_buf[0] = (reg_addr << 1) & 0x7F; // AND with 0x7F for write
    tx_buf[1] = (data >> 8) & 0xFF;
    tx_buf[2] = data & 0xFF;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to verify the WHO_AM_I register
int verify_who_am_i() {
    int who_am_i = spi_read_register(ADIS16266_WHO_AM_I);
    if (who_am_i < 0) {
