    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Angular_Rate(deg/s),Y_Angular_Rate(deg/s),Z_Angular_Rate(deg/s)\n");
    }
