    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read angular rates
        float x_rate = read_angular_rate(ADIS16266_XGYRO_OUT);
        float y_rate = read_angular_rate(ADIS16266_YGYRO_OUT);
        float z_rate = read_angular_rate(ADIS16266_ZGYRO_OUT);

