#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDR 0x69

// GY-50 L3G4200D Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity (mdps/LSB)
#define SENSITIVITY 8.75 / 1000.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_gyro_data(int16_t x, int16_t y, int16_t z, float *x_mdps, float *y_mdps, float *z_mdps);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the GY-50 L3G4200D gyroscope
int initialize_gyro() {
    // Check WHO_AM_I register
    int who_am_i = -1;
    for (int i = 0; i < 3; ++i) {
        who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register, retrying...\n");
            gpioDelay(10000); // 10ms delay
        }
    }

    if (who_am_i != 0x48) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x48\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (Full scale selection)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Reads raw gyroscope data from the registers
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Converts raw gyroscope data to degrees per second
void convert_gyro_data(int16_t x, int16_t y, int16_t z, float *x_mdps, float *y_mdps, float *z_mdps) {
    *x_mdps = (float)x * SENSITIVITY;
    *y_mdps = (float)y * SENSITIVITY;
    *z_mdps = (float)z * SENSITIVITY;
}

// Logs the timestamped gyroscope data to a CSV file
int log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f\n", ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyro initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float x_mdps, y_mdps, z_mdps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Convert gyroscope data
            convert_gyro_data(x, y, z, &x_mdps, &y_mdps, &z_mdps);

            // Log the data
            if (log_data(x_mdps, y_mdps, z_mdps) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    // Close the log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

