        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read GPIO pin value
        flame_detected = gpioRead(GPIO_PIN);

        if (flame_detected < 0) {
            fprintf(stderr, "Error reading GPIO pin: %d\n", flame_detected);
            fprintf(log_file, "Error reading GPIO pin: %d\n", flame_detected);
            fflush(log_file);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log event to file
            if (flame_detected == 0) {
                fprintf(log_file, "%s - Flame detected: YES\n", timestamp);
