#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int sensor1_state, sensor2_state;
    struct timespec ts;
    char timestamp[30];
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    result = gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", SENSOR_1_GPIO, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    if (result != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d: %d\n", SENSOR_1_GPIO, result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", SENSOR_2_GPIO, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);
    if (result != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d: %d\n", SENSOR_2_GPIO, result);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor states
        sensor1_state = gpioRead(SENSOR_1_GPIO);
        sensor2_state = gpioRead(SENSOR_2_GPIO);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

        // Log sensor states to file
        fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately

        // Check if both sensors are high
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("HALT\n");
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio's delay function takes microseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Conveyor monitoring stopped.\n");

    return 0;
}

