#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x48
#define CTRL_REG1 0x2A
#define STBY_BIT 0x01
#define DATA_RATE_BIT 0x00
#define DATA_RATE_100HZ 0x03
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define TILT_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor_id();
int init_sensor();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    int who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }
    return 0;
}

// Initialize the sensor
int init_sensor() {
    // Set to standby mode
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, STBY_BIT) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, DATA_RATE_BIT | STBY_BIT) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active mode): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_fd, OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
