// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration parameters
#define OFFSET_X 0.0
#define OFFSET_Y 0.0
#define OFFSET_Z 0.0
#define SCALE_X 1.0
#define SCALE_Y 1.0
#define SCALE_Z 1.0

// Metal detector threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
void log_data(float x, float y, float z);
void check_metal_detector(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the LIS3MDL sensor
int initialize_sensor() {
    int retries = 3;
    while (retries > 0) {
        // Set continuous mode and 100 Hz data rate
        if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70) < 0) { //0x70 = 0b01110000
            fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Set full-scale range to ±4 gauss
        if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) { //0x00 = 0b00000000
            fprintf(stderr, "Error writing to CTRL_REG3: %s\n", strerror(errno));
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        return 0; // Initialization successful
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Initialization failed
}

// Read raw magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate the raw magnetometer data
void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)(raw_x - OFFSET_X) * SCALE_X;
    *calibrated_y = (float)(raw_y - OFFSET_Y) * SCALE_Y;
    *calibrated_z = (float)(raw_z - OFFSET_Z) * SCALE_Z;
}

// Log the calibrated data to a file
void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%09ld,%.6f,%.6f,%.6f\n", timestamp, ts.tv_nsec, x, y, z);
    fflush(log_file);
}

// Check for metal detector alert
void check_metal_detector(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(stderr, "%s.%09ld, METAL DETECTED! Magnitude: %.6f mG\n", timestamp, ts.tv_nsec, magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate the data
            calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Log the data
            log_data(calibrated_x, calibrated_y, calibrated_z);

            // Check for metal detector alert
            check_metal_detector(calibrated_x, calibrated_y, calibrated_z);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay (10 Hz sampling rate)
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

