// ADXL354B Register Addresses
#define ADXL354B_RESET_REG 0x2B
#define ADXL354B_POWER_CTL_REG 0x2D
#define ADXL354B_STATUS_REG 0x1D
#define ADXL354B_PARTID_REG 0x00
#define ADXL354B_XDATA_L 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Retry Configuration
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg);
int spi_write_register(int reg, int value);
int adxl354b_reset();
int adxl354b_power_down();
int adxl354b_read_partid();
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Function to read a register via SPI
int spi_read_register(int reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set read bit (MSB)
    tx[1] = 0x00;       // Dummy byte for reading

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx, rx, 2) == 0) {
            return rx[1];
        } else {
            fprintf(stderr, "SPI read error (reg 0x%02X), retry %d\n", reg, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "SPI read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Indicate failure
}

// Function to write a register via SPI
int spi_write_register(int reg, int value) {
