#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define ADIS16362_XGYRO_OUT 0x04
#define ADIS16362_YGYRO_OUT 0x06
#define ADIS16362_ZGYRO_OUT 0x08
#define ADIS16362_XACCEL_OUT 0x0A
#define ADIS16362_YACCEL_OUT 0x0C
#define ADIS16362_ZACCEL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CE 0 // CE0

// Scaling Factors
#define GYRO_SCALE 0.05 // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_pigpio();
int open_spi(int channel, int baud, int mode, int ce);
int read_register(int handle, uint8_t address, uint16_t *data);
void scale_data(uint16_t raw_data, float *scaled_data);
int log_data(FILE *file, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI device
int open_spi(int channel, int baud, int mode, int ce) {
    int handle = spiOpen(channel, baud, mode);
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from ADIS16362 register
int read_register(int handle, uint8_t address, uint16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = address | 0x80; // MSB = 1 for read
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *data = (rx_buffer[1] << 8) | rx_buffer[2];
    return 0;
}

// Scale raw data to physical units
void scale_data(uint16_t raw_data, float *scaled_data) {
    *scaled_data = (float)raw_data * GYRO_SCALE;
}

// Log data to CSV file
int log_data(FILE *file, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_sec = ts.tv_sec;
    long timestamp_nsec = ts.tv_nsec;

    fprintf(file, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp_sec, timestamp_nsec, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI device
    spi_handle = open_spi(SPI_CHANNEL, SPI_BAUD, SPI_MODE, SPI_CE);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Main loop
    uint16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    while (!terminate) {
        // Read gyroscope data
        if (read_register(spi_handle, ADIS16362_XGYRO_OUT, &gyro_x_raw) != 0) continue;
        if (read_register(spi_handle, ADIS16362_YGYRO_OUT, &gyro_y_raw) != 0) continue;
        if (read_register(spi_handle, ADIS16362_ZGYRO_OUT, &gyro_z_raw) != 0) continue;

        // Read accelerometer data
        if (read_register(spi_handle, ADIS16362_XACCEL_OUT, &accel_x_raw) != 0) continue;
        if (read_register(spi_handle, ADIS16362_YACCEL_OUT, &accel_y_raw) != 0) continue;
        if (read_register(spi_handle, ADIS16362_ZACCEL_OUT, &accel_z_raw) != 0) continue;

        // Scale data
        scale_data(gyro_x_raw, &gyro_x);
        scale_data(gyro_y_raw, &gyro_y);
        scale_data(gyro_z_raw, &gyro_z);
        scale_data(accel_x_raw, &accel_x);
        scale_data(accel_y_raw, &accel_y);
        scale_data(accel_z_raw, &accel_z);

        // Log data
        if (log_data(log_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Close SPI device and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

