#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define GPIO_CHIP 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int sensor_value;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register SIGINT handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpio_status = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", GPIO_PIN, gpio_status);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %d\n", GPIO_PIN, sensor_value);
            gpioTerminate();
            return 1;
        }

        // Check if obstacle is detected (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

