#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    int result = gpioReadBulk(SENSOR_1_GPIO | SENSOR_2_GPIO);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor values: %d\n", result);
        return -1; // Indicate an error
    }

    *sensor1_value = (result & (1 << SENSOR_1_GPIO)) ? 1 : 0; // Active low
    *sensor2_value = (result & (1 << SENSOR_2_GPIO)) ? 1 : 0; // Active low

    return 0; // Indicate success
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           sensor1_value ? "Clear" : "Obstacle",
           sensor2_value ? "Clear" : "Obstacle");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    int sensor1_value, sensor2_value;

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            // Log sensor data
            log_sensor_data(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

