#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS_GPIO 8

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register from the ADIS16266
int16_t read_register(uint8_t address) {
    char tx_buf[3];
    char rx_buf[3];
    int16_t value;

    // Construct the transmit buffer: address (MSB first) + dummy byte
    tx_buf[0] = address | 0x80; // MSB = 1 for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transaction
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return 0; // Return 0 on failure
    }

    // Extract the 16-bit value from the receive buffer
    value = (rx_buf[1] << 8) | rx_buf[2];

    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set CS GPIO as output
    gpioSetMode(SPI_CS_GPIO, PI_OUTPUT);
    gpioWrite(SPI_CS_GPIO, 1); // Deactivate CS

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADIS16266 Gyroscope Data Reader\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t x_gyro = read_register(ADIS16266_XGYRO_OUT);
        int16_t y_gyro = read_register(ADIS16266_YGYRO_OUT);
        int16_t z_gyro = read_register(ADIS16266_ZGYRO_OUT);

        // Convert to degrees per second
        float x_rate = x_gyro * 0.02;
        float y_rate = y_gyro * 0.02;
        float z_rate = z_gyro * 0.02;

        // Log the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

