#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// WHO_AM_I register
#define WHO_AM_I 0x0F

// Expected WHO_AM_I value
#define WHO_AM_I_VALUE 0x69

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int i2c_handle)
{
    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_lsm6dsr(int i2c_handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buffer[12];

    // Read accelerometer and gyroscope data in one burst
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading accelerometer and gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%X, got 0x%X\n", WHO_AM_I_VALUE, who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        // Read accelerometer and gyroscope data
        if (read_lsm6dsr(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the data
            printf("Accel: %d %d %d, Gyro: %d %d %d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

