#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5
#define PAUSE_AFTER_WINDOW_S 1

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main(int argc, char *argv[]) {
    int threshold = -1;
    int i, high_count;
    int gpio_status;
    struct timespec ts;
    char timestamp[30];
    FILE *log_file;

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long parsed_threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || parsed_threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold. Please provide a positive integer.\n");
        return 1;
    }

    threshold = (int)parsed_threshold;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("sound_sensor_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,Status\n"); // CSV header

    while (!terminate) {
        high_count = 0;
        gpio_status = 0; // Reset status for each window

        // Sample the GPIO pin every 1 ms
        for (i = 0; i < (WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_MS); ++i) {
            int level = gpioRead(GPIO_PIN);
            if (level < 0) {
                fprintf(stderr, "Error reading GPIO pin!\n");
                gpio_status = -1; // Indicate error
                break;
            }
            if (level == 1) {
                high_count++;
            }
        }

        if (gpio_status == 0) {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Error getting timestamp!\n");
            } else {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                fprintf(log_file, "%s,ALERT\n", timestamp);
                fflush(log_file);
                printf("%s,ALERT\n", timestamp);
            }
        } else {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Error getting timestamp!\n");
            } else {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                fprintf(log_file, "%s,Status: High=%d,Low=%d\n", timestamp, high_count, (WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_MS) - high_count);
                fflush(log_file);
                printf("%s,Status: High=%d,Low=%d\n", timestamp, high_count, (WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_MS) - high_count);
            }
        }

        if (high_count > threshold) {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
