#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for Door A and Door B
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "access_log.txt"

// Define the minimum and maximum security code values
#define MIN_CODE 100000
#define MAX_CODE 999999

// Define the unlock duration (in seconds)
#define UNLOCK_DURATION 5

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int generate_code(int *code);
int read_code(int *user_code);
int validate_code(int code, int user_code);
int log_access(int code);
void unlock_doors();
void lock_doors();
void signal_handler(int signal);

int main() {
    int security_code, user_code;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Generate a random security code
    if (generate_code(&security_code) != 0) {
        fprintf(stderr, "Failed to generate security code. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Print the security code to stdout
    printf("Security Code: %d\n", security_code);

    // Main loop
    while (!terminate) {
        // Read the user's input
        if (read_code(&user_code) != 0) {
            fprintf(stderr, "Failed to read user code. Continuing.\n");
            continue;
        }

        // Validate the user's input
        if (validate_code(security_code, user_code) == 0) {
            // Log the access event
            if (log_access(security_code) != 0) {
                fprintf(stderr, "Failed to log access. Continuing.\n");
            }

            // Unlock the doors
            unlock_doors();

            // Wait for the unlock duration
            sleep(UNLOCK_DURATION);

            // Lock the doors
            lock_doors();
        } else {
            // Print an access denied message
            printf("Access denied.\n");
        }
    }

    // Clean up and exit
    lock_doors();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Ensure both doors are initially locked (LOW)
    lock_doors();

    return 0;
}

// Function to generate a random six-digit security code
int generate_code(int *code) {
    srand(time(NULL)); // Seed the random number generator
    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0;
}

// Function to read the user's input
int read_code(int *user_code) {
    char input[10]; // Buffer to hold user input
    int i;

    printf("Enter the security code: ");
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Error reading input.\n");
        return 1;
    }

    // Remove trailing newline character
    input[strcspn(input, "\n")] = 0;

    // Check if the input is numeric
    for (i = 0; input[i] != '\0'; i++) {
        if (!isdigit(input[i])) {
            fprintf(stderr, "Invalid input. Please enter a numeric code.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            return 1;
        }
    }

    // Convert the input to an integer
    *user_code = atoi(input);

    return 0;
}

// Function to validate the user's input against the generated code
int validate_code(int code, int user_code) {
    return (code == user_code);
}

// Function to log the access event to a file
int log_access(int code) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return 1;
    }

    // Write the log entry to the file
    fprintf(fp, "%s,%d\n", timestamp, code);

    // Close the file
    fclose(fp);

    return 0;
}

// Function to unlock the doors
void unlock_doors() {
    gpioWrite(DOOR_A_GPIO, 1); // Set GPIO HIGH to unlock Door A
    gpioWrite(DOOR_B_GPIO, 1); // Set GPIO HIGH to unlock Door B
}

// Function to lock the doors
void lock_doors() {
    gpioWrite(DOOR_A_GPIO, 0); // Set GPIO LOW to lock Door A
    gpioWrite(DOOR_B_GPIO, 0); // Set GPIO LOW to lock Door B
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
}

