#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_CONVERSION_TIME 180 // ms

int i2c_handle;
FILE *log_file;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error initializing BH1750: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the illuminance value from the sensor
float read_illuminance() {
    int raw_value = i2cReadWordData(i2c_handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading illuminance: %d\n", raw_value);
        return -1.0;
    }

    // Convert raw value to lux
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Function to log the timestamp and illuminance value to a file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_bh1750() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float lux = read_illuminance();
        if (lux >= 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

