#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000000
#define TCP_PORT 12345
#define AUTH_SECRET "MySecretKey"
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5

// Global variables
int i2c_handle;
int socket_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_data(int i2c_handle, unsigned char *touch_data);
int generate_frequency(unsigned char *touch_data);
int play_pwm_tone(int frequency);
int handle_tcp_connection(int client_fd);
void signal_handler(int signal);

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_SOFT_RESET 0x80

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR)
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0C) < 0) { // Enable electrodes 0-11
        fprintf(stderr, "Error: Failed to write to ECR\n");
        return -1;
    }

    // Configure Configuration Register 1 (CONFIG1)
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) { // Set touch and release thresholds
        fprintf(stderr, "Error: Failed to write to CONFIG1\n");
        return -1;
    }

    // Configure Configuration Register 1 (CONFIG1)
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x10) < 0) { // Set electrode sensitivity
        fprintf(stderr, "Error: Failed to write to CONFIG1\n");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int mpr121_read_touch_data(int i2c_handle, unsigned char *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    touch_data[0] = buf[1];
    touch_data[1] = buf[0];

    return 0;
}

// Function to generate a frequency based on touch data
int generate_frequency(unsigned char *touch_data) {
    int frequency = 440; // Base frequency (A4)
    int deviation = 200;  // Deviation from base frequency

    if (touch_data[0] & 0x01) {
        frequency += deviation;
    }
    if (touch_data[1] & 0x01) {
        frequency -= deviation;
    }

    return frequency;
}

// Function to play a PWM tone
int play_pwm_tone(int frequency) {
    if (frequency <= 0) return -1; // Invalid frequency

