#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MAG_ADDR_1 0x1E
#define MAG_ADDR_2 0x1D
#define MAG_ADDR_3 0x1C
#define MAG_CTRL_REG1_M 0x20
#define MAG_OUT_X_L_M 0x28
#define LED_GPIO 17
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle_1, i2c_handle_2, i2c_handle_3;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_magnetometer(int i2c_handle);
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(int magnitude);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize magnetometer
int init_magnetometer(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, MAG_CTRL_REG1_M, 0x70) < 0) { // Enable all axes, 50 Hz ODR
        log_error("Failed to initialize magnetometer");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, MAG_OUT_X_L_M, buffer, 6) < 0) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of the magnetic field vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Set LED brightness using PWM
void set_led_brightness(int magnitude) {
    int duty_cycle = (int)((magnitude / 100.0) * 255.0); // Scale magnitude to 0-255
    gpioPWM(LED_GPIO, duty_cycle);
}

// Log error message to file
void log_error(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "Error: %s\n", message);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C connections
    i2c_handle_1 = i2cOpen(I2C_BUS, MAG_ADDR_1, 0);
    i2c_handle_2 = i2cOpen(I2C_BUS, MAG_ADDR_2, 0);
    i2c_handle_3 = i2cOpen(I2C_BUS, MAG_ADDR_3, 0);

    if (i2c_handle_1 < 0 || i2c_handle_2 < 0 || i2c_handle_3 < 0) {
        log_error("Failed to open I2C connection");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometers
    if (init_magnetometer(i2c_handle_1) < 0 || init_magnetometer(i2c_handle_2) < 0 || init_magnetometer(i2c_handle_3) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer(s)\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        i2cClose(i2c_handle_3);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LED_GPIO, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x1, y1, z1, x2, y2, z2, x3, y3, z3;
    float magnitude1, magnitude2, magnitude3;

    // Main loop
    while (!terminate) {
        // Read data from magnetometers
        if (read_magnetometer_data(i2c_handle_1, &x1, &y1, &z1) < 0) continue;
        if (read_magnetometer_data(i2c_handle_2, &x2, &y2, &z2) < 0) continue;
        if (read_magnetometer_data(i2c_handle_3, &x3, &y3, &z3) < 0) continue;

        // Calculate magnitudes
        magnitude1 = calculate_magnitude(x1, y1, z1);
        magnitude2 = calculate_magnitude(x2, y2, z2);
        magnitude3 = calculate_magnitude(x3, y3, z3);

        // Calculate average magnitude
        float avg_magnitude = (magnitude1 + magnitude2 + magnitude3) / 3.0;

        // Set LED brightness
        set_led_brightness((int)avg_magnitude);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    i2cClose(i2c_handle_3);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

