        magnitude2 = calculate_magnitude(x2, y2, z2);
        magnitude3 = calculate_magnitude(x3, y3, z3);

        // Calculate average magnitude
        float avg_magnitude = (magnitude1 + magnitude2 + magnitude3) / 3.0;

        // Set LED brightness
        set_led_brightness((int)avg_magnitude);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    i2cClose(i2c_handle_3);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

