    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize offset buffer
    for (int i = 0; i < 100; i++) {
        x_buffer[i] = 0.0;
        y_buffer[i] = 0.0;
        z_buffer[i] = 0.0;
    }

    // Main loop
    while (!terminate) {
        int16_t x, y, z;

        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Update running average
            update_buffer((float)x, (float)y, (float)z);

            // Calculate running average
            float x_avg = calculate_average(x_buffer, 100);
            float y_avg = calculate_average(y_buffer, 100);
            float z_avg = calculate_average(z_buffer, 100);

            // Update hard-iron offsets
            x_offset = x_avg - (float)x;
            y_offset = y_avg - (float)y;
            z_offset = z_avg - (float)z;

            // Apply offsets
            apply_offsets(x, y, z, &x_offset, &y_offset, &z_offset);

            // Print corrected data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

