#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D Registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DUR 0x33
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define WHO_AM_I 0x0F

// GPIO pin for INT1
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Sensitivity (mg/LSB)
#define SENSITIVITY 0.061

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;

// Circular buffer
int16_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int verify_device_id();
int read_register(uint8_t reg, uint8_t *value);
int write_register(uint8_t reg, uint8_t value);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(int16_t x, int16_t y, int16_t z);
void dump_buffer();
void interrupt_handler(int signum);
void signal_handler(int signum);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, INT1_GPIO);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input_line(gpio_line, "lsm303d_mon") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to verify device ID
int verify_device_id() {
    uint8_t who_am_i;
    if (read_register(WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x49) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    printf("Device ID verified: 0x%02X\n", who_am_i);
    return 0;
}

// Function to read a register
int read_register(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to write a register
int write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (read_register(OUT_X_L_A, &x_l) != 0) return -1;
    if (read_register(OUT_X_H_A, &x_h) != 0) return -1;
    if (read_register(OUT_Y_L_A, &y_l) != 0) return -1;
    if (read_register(OUT_Y_H_A, &y_h) != 0) return -1;
    if (read_register(OUT_Z_L_A, &z_l) != 0) return -1;
    if (read_register(OUT_Z_H_A, &z_h) != 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    buffer[buffer_index] = x;
    buffer[buffer_index + 1] = y;
    buffer[buffer_index + 2] = z;
    buffer_index = (buffer_index + 3) % BUFFER_SIZE;
}

// Function to dump the buffer to the console
void dump_buffer() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    printf("%s ", buf);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        int16_t x = buffer[index];
        int16_t y = buffer[index + 1];
        int16_t z = buffer[index + 2];
        printf("%d,%d,%d ", x, y, z);
    }
    printf("\n");
}

// Interrupt handler function
void interrupt_handler(int signum) {
    int16_t x, y, z;
    if (read_acceleration(&x, &y, &z) == 0) {
        add_to_buffer(x, y, z);
        dump_buffer();
    } else {
        fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
    }
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        cleanup();
        exit(0);
    }
}

// Cleanup function
void cleanup() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        fprintf(stderr, "Device ID verification failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure INT1 pin as input
    if (gpiod_line_request_input_line(gpio_line, "lsm303d_mon") < 0) {
        perror("Error requesting GPIO line as input");
        cleanup();
        return 1;
    }

    // Configure INT1 interrupt
    if (write_register(INT1_CFG, 0x80) != 0) { // Enable INT1, set threshold to 2000mg, zero duration
        fprintf(stderr, "Error configuring INT1 interrupt\n");
        cleanup();
        return 1;
    }

    // Configure accelerometer
    if (write_register(CTRL_REG1_A, 0x57) != 0) { // Enable all axes, 50Hz data rate
        fprintf(stderr, "Error configuring accelerometer\n");
        cleanup();
        return 1;
    }
    if (write_register(CTRL_REG4_A, 0x00) != 0) { // +/- 2g full scale
        fprintf(stderr, "Error configuring accelerometer full scale\n");
        cleanup();
        return 1;
    }

    // Set up interrupt handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
sa.sa_handler = interrupt_handler;
if (sigaction(SIGIO, &sa, NULL) == -1) {
    perror("sigaction");
    cleanup();
    return 1;
}

    // Main loop
    while (1) {
        // Read acceleration data
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        // Wait for 10ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

