#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27

// Define UART ports
#define UART_PORT_1 "/dev/serial0"
#define UART_PORT_2 "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables for UART file descriptors and pigpio handles
int uart_fd1 = -1;
int uart_fd2 = -1;
int pigpio_handle1 = -1;
int pigpio_handle2 = -1;

// Function prototypes
int initialize_uart(const char *port, int baud_rate);
int read_code(int fd, char *buffer, int buffer_size, int timeout_seconds);
int validate_code(const char *code, const char *expected_code);
void control_relay(int relay_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);

    // Deactivate relays
    control_relay(RELAY1_PIN, 0);
    control_relay(RELAY2_PIN, 0);

    // Close UART ports
    if (uart_fd1 != -1) {
        close(uart_fd1);
    }
    if (uart_fd2 != -1) {
        close(uart_fd2);
    }

    // Terminate pigpio
    if (pigpio_handle1 != -1) {
        gpioTerminate();
    }
    if (pigpio_handle2 != -1) {
        gpioTerminate();
    }

    exit(0);
}

// Function to initialize UART port
int initialize_uart(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s\n", port);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for UART port %s\n", port);
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for UART port %s\n", port);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a code from a UART port
int read_code(int fd, char *buffer, int buffer_size, int timeout_seconds) {
    int bytes_read = 0;
    struct timeval start_time, current_time;
    gettimeofday(&start_time, NULL);

    while (bytes_read < buffer_size) {
        int c = read(fd, &buffer[bytes_read], 1);
        if (c == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Timeout occurred
                gettimeofday(&current_time, NULL);
                double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_usec - start_time.tv_usec) / 1000000.0;
                if (elapsed_time >= timeout_seconds) {
                    fprintf(stderr, "Read timeout on UART port %s\n", (fd == fd1) ? UART_PORT_1 : UART_PORT_2);
                    return -1; // Timeout
                }
            } else {
                fprintf(stderr, "Error reading from UART port %s\n", (fd == fd1) ? UART_PORT_1 : UART_PORT_2);
                return -1; // Error
            }
        } else if (c > 0) {
            if (c > 0 && c < 0x1000) {
                buffer[bytes_read] = (char)c;
                bytes_read++;
            } else {
                fprintf(stderr, "Invalid character received on UART port %s\n", (fd == fd1) ? UART_PORT_1 : UART_PORT_2);
                buffer[0] = '\0'; // Reset buffer on invalid character
                return -1;
            }
        } else {
            // No data available
            usleep(10000); // Sleep for 10ms
        }
        gettimeofday(&current_time, NULL);
    }

    buffer[bytes_read] = '\0'; // Null-terminate the buffer
    return bytes_read;
}

// Function to validate a code
int validate_code(const char *code, const char *expected_code) {
    if (strlen(code) != strlen(expected_code)) {
        fprintf(stderr, "Invalid code length. Expected %d, received %d\n", strlen(expected_code), strlen(code));
        return 0;
    }

    int result = 1;
    for (int i = 0; i < strlen(code); i++) {
        if (code[i] != expected_code[i]) {
            fprintf(stderr, "Code mismatch at position %d\n", i);
            result = 0;
            break;
        }
    }

    return result;
}

// Function to control a relay
void control_relay(int relay_pin, int state) {
    gpioWrite(relay_pin, state);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART ports
    uart_fd1 = initialize_uart(UART_PORT_1, BAUD_RATE);
    if (uart_fd1 == -1) {
        gpioTerminate();
        return 1;
    }

    uart_fd2 = initialize_uart(UART_PORT_2, BAUD_RATE);
    if (uart_fd2 == -1) {
        close(uart_fd1);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);

    char code1[7]; // Buffer for code 1 (6 digits + null terminator)
    char code2[7]; // Buffer for code 2 (6 digits + null terminator)
    int code1_received = 0;
    int code2_received = 0;

    // Main loop
    while (1) {
        // Read code from UART port 1
        if (!code1_received) {
            int bytes_read = read_code(uart_fd1, code1, 7, TIMEOUT_DURATION);
            if (bytes_read > 0) {
                code1_received = 1;
                fprintf(stderr, "Received code 1: %s\n", code1);
            } else {
                fprintf(stderr, "Failed to read code 1\n");
            }
        }

        // Read code from UART port 2
        if (!code2_received) {
            int bytes_read = read_code(uart_fd2, code2, 7, TIMEOUT_DURATION);
            if (bytes_read > 0) {
                code2_received = 1;
                fprintf(stderr, "Received code 2: %s\n", code2);
            } else {
                fprintf(stderr, "Failed to read code 2\n");
            }
        }

        // Validate codes
        if (code1_received && code2_received) {
            if (validate_code(code1, EXPECTED_CODE) && validate_code(code2, EXPECTED_CODE)) {
                // Activate relays
                control_relay(RELAY1_PIN, 1);
                control_relay(RELAY2_PIN, 1);
                sleep(2);
                control_relay(RELAY1_PIN, 0);
                control_relay(RELAY2_PIN, 0);
                fprintf(stderr, "Doors unlocked!\n");
            } else {
                fprintf(stderr, "Code validation failed\n");
            }
        }

        usleep(100000); // Delay to avoid busy-waiting
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    close(uart_fd1);
    close(uart_fd2);
    gpioTerminate();
    return 0;
}

