            int bytes_read = read_code(uart_fd1, code1, 7, TIMEOUT_DURATION);
            if (bytes_read > 0) {
                code1_received = 1;
                fprintf(stderr, "Received code 1: %s\n", code1);
            } else {
                fprintf(stderr, "Failed to read code 1\n");
            }
        }

        // Read code from UART port 2
        if (!code2_received) {
            int bytes_read = read_code(uart_fd2, code2, 7, TIMEOUT_DURATION);
            if (bytes_read > 0) {
                code2_received = 1;
                fprintf(stderr, "Received code 2: %s\n", code2);
            } else {
                fprintf(stderr, "Failed to read code 2\n");
            }
        }

        // Validate codes
        if (code1_received && code2_received) {
            if (validate_code(code1, EXPECTED_CODE) && validate_code(code2, EXPECTED_CODE)) {
                // Activate relays
                control_relay(RELAY1_PIN, 1);
                control_relay(RELAY2_PIN, 1);
                sleep(2);
                control_relay(RELAY1_PIN, 0);
                control_relay(RELAY2_PIN, 0);
                fprintf(stderr, "Doors unlocked!\n");
            } else {
                fprintf(stderr, "Code validation failed\n");
            }
        }

        usleep(100000); // Delay to avoid busy-waiting
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    close(uart_fd1);
    close(uart_fd2);
    gpioTerminate();
    return 0;
}

