#define RELAY_ON_TIME 1000 // milliseconds
#define FAILSAFE_TIMEOUT 10000 // milliseconds (10 seconds)
#define POLL_INTERVAL 50 // milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned long motion_start_time = 0;
static volatile int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
void log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

