    int pir_value = gpioRead(PIR_PIN);
    if (pir_value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor");
        return -1;
    }
    return pir_value;
}

// Control the relay
int control_relay(int state) {
    if (state != 0 && state != 1) {
        syslog(LOG_ERR, "Invalid relay state");
        return -1;
    }

    gpioWrite(RELAY_PIN, state);
    relay_state = state; // Update global relay state

    if (state == 1) {
        syslog(LOG_INFO, "Relay ON");
    } else {
        syslog(LOG_INFO, "Relay OFF");
    }

    return 0;
}

