        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Motion detector started");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            // Error reading PIR sensor, but continue running
            gpioDelay(POLL_INTERVAL);
            continue;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = gpioTick(); // Record the start time
            }

            // Check if motion has been continuous for FAILSAFE_TIMEOUT
            if (gpioTick() - motion_start_time > FAILSAFE_TIMEOUT) {
                syslog(LOG_WARNING, "PIR sensor continuously HIGH for too long, triggering failsafe");
                log_event(LOG_WARNING, "PIR sensor continuously HIGH for too long, triggering failsafe");
                control_relay(0); // De-energize the relay
                log_event(LOG_INFO, "System shutdown initiated");
                cleanup();
                exit(1); // Exit the program after shutdown
            }
        } else {
            motion_start_time = 0; // Reset motion start time
        }

        gpioDelay(POLL_INTERVAL); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

