// Define the duration for each irrigation cycle (in seconds)
#define IRRIGATION_DURATION 300

// Define the duration of the pause between cycles (in seconds)
#define PAUSE_DURATION 60

// Define the total duration of the irrigation cycle (irrigation + pause)
#define CYCLE_DURATION (IRRIGATION_DURATION + PAUSE_DURATION)

// Define the number of relays
#define NUM_RELAYS 4

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_states[NUM_RELAYS] = {1, 1, 1, 1}; // Initialize all relays to OFF (HIGH)

// Function prototypes
void signal_handler(int signal);
void activate_relay(int gpio_pin);
void deactivate_relay(int gpio_pin);
void irrigation_cycle();
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        program_running = 0;
    }
}

// Function to activate a relay
void activate_relay(int gpio_pin) {
    int result = gpioWrite(gpio_pin, 0); // Set GPIO LOW to activate relay
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Error activating relay on GPIO %d: %d", gpio_pin, result);
        log_message(LOG_ERR, message);
    } else {
        char message[100];
        snprintf(message, sizeof(message), "Activated relay on GPIO %d", gpio_pin);
        log_message(LOG_INFO, message);
    }
}

// Function to deactivate a relay
void deactivate_relay(int gpio_pin) {
    int result = gpioWrite(gpio_pin, 1); // Set GPIO HIGH to deactivate relay
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Error deactivating relay on GPIO %d: %d", gpio_pin, result);
        log_message(LOG_ERR, message);
    } else {
        char message[100];
        snprintf(message, sizeof(message), "Deactivated relay on GPIO %d", gpio_pin);
        log_message(LOG_INFO, message);
    }
}

// Function to run the irrigation cycle
void irrigation_cycle() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        activate_relay(RELAY_GPIO_ARRAY[i]);
        gpioDelay(IRRIGATION_DURATION * 1000); // Delay for irrigation duration (in milliseconds)
        deactivate_relay(RELAY_GPIO_ARRAY[i]);
        gpioDelay(PAUSE_DURATION * 1000); // Delay for pause duration (in milliseconds)
    }
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize relay states to HIGH (OFF)
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_states[i] = 1; // Set initial state to HIGH
        gpioWrite(RELAY_GPIO_ARRAY[i], 1); // Ensure relay is initially OFF
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        irrigation_cycle();
    }

    // Clean up and exit
    log_message(LOG_INFO, "Cleaning up and exiting...");

    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(RELAY_GPIO_ARRAY[i], 1); // Set HIGH to deactivate
    }

    gpioTerminate(); // Terminate pigpio
    closelog();
    return 0;
}

