#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
int16_t accel_buffer[BUFFER_SIZE][3];
int buffer_index = 0;
int running = 1;

// Signal handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    running = 0;
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050
    if (wiringPiI2CWriteReg8(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the MPU6050
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    *x = (int16_t)((wiringPiI2CReadReg8(i2c_fd, ACCEL_XOUT_H) << 8) | wiringPiI2CReadReg8(i2c_fd, ACCEL_XOUT_H + 1));
    *y = (int16_t)((wiringPiI2CReadReg8(i2c_fd, ACCEL_YOUT_H) << 8) | wiringPiI2CReadReg8(i2c_fd, ACCEL_YOUT_H + 1));
    *z = (int16_t)((wiringPiI2CReadReg8(i2c_fd, ACCEL_ZOUT_H) << 8) | wiringPiI2CReadReg8(i2c_fd, ACCEL_ZOUT_H + 1));
    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    accel_buffer[buffer_index][0] = x;
    accel_buffer[buffer_index][1] = y;
    accel_buffer[buffer_index][2] = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the latest data from the circular buffer
int16_t get_latest_data(int axis) {
    return accel_buffer[(buffer_index + BUFFER_SIZE - 1) % BUFFER_SIZE][axis];
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() == -1) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        close(i2c_fd);
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    server_addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        close(sockfd);
        close(i2c_fd);
        return 1;
    }

    // Listen for connections
    if (listen(sockfd, 5) < 0) {
        perror("Error listening on socket");
        close(sockfd);
        close(i2c_fd);
        return 1;
    }

    printf("Listening on port 8080...\n");

    // Main loop
    while (running) {
        int client_sockfd;
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int16_t x, y, z;

        // Accept connection
        client_sockfd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (client_sockfd < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(x, y, z);

            // Get latest data
            int16_t latest_x = get_latest_data(0);
            int16_t latest_y = get_latest_data(1);
            int16_t latest_z = get_latest_data(2);

            // Send data to client
            char buffer[256];
            snprintf(buffer, sizeof(buffer), "X: %d, Y: %d, Z: %d\n", latest_x, latest_y, latest_z);
            send(client_sockfd, buffer, strlen(buffer), 0);
        } else {
            fprintf(stderr, "Error reading acceleration data.\n");
        }

        close(client_sockfd);
    }

    // Clean up
    close(sockfd);
    close(i2c_fd);

    return 0;
}

