#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the base interval for the relays (in seconds)
#define BASE_INTERVAL 2

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to toggle a relay
void toggle_relay(int gpio_pin)
{
    int current_state = gpioRead(gpio_pin);
    int new_state = !current_state;
    gpioWrite(gpio_pin, new_state);
    printf("Relay on GPIO %d toggled to %d\n", gpio_pin, new_state);
}

// Function to calculate the next toggle time for a relay
long calculate_next_toggle_time(int base_interval, int prime_number, struct timespec last_toggle_time)
{
    long next_toggle_time_ns = (long)(last_toggle_time.tv_sec * 1000000000L + last_toggle_time.tv_nsec);
    long prime_interval_ns = (long)base_interval * 1000000000L * prime_number;
    long next_toggle_time = next_toggle_time_ns + prime_interval_ns;

    // Ensure the next toggle time is in the future
    if (next_toggle_time < (long)(time(NULL) * 1000000000L)) {
        next_toggle_time += 1000000000L; // Add a 1-second delay to avoid negative times
    }

    return next_toggle_time;
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial relay states to OFF
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Install signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize last toggle times for each relay
    struct timespec last_toggle_time_relay1 = {0, 0};
    struct timespec last_toggle_time_relay2 = {0, 0};
    struct timespec last_toggle_time_relay3 = {0, 0};
    struct timespec last_toggle_time_relay4 = {0, 0};

    // Main loop
    while (program_running)
    {
        // Calculate the next toggle time for each relay
        long next_toggle_time_relay1 = calculate_next_toggle_time(BASE_INTERVAL, 2, last_toggle_time_relay1);
        long next_toggle_time_relay2 = calculate_next_toggle_time(BASE_INTERVAL, 3, last_toggle_time_relay2);
        long next_toggle_time_relay3 = calculate_next_toggle_time(BASE_INTERVAL, 5, last_toggle_time_relay3);
        long next_toggle_time_relay4 = calculate_next_toggle_time(BASE_INTERVAL, 7, last_toggle_time_relay4);

        // Determine the relay with the earliest next toggle time
        int earliest_relay = -1;
        long earliest_next_toggle_time = 0;

        if (next_toggle_time_relay1 > earliest_next_toggle_time) {
            earliest_relay = 1;
            earliest_next_toggle_time = next_toggle_time_relay1;
        }
        if (next_toggle_time_relay2 > earliest_next_toggle_time) {
            earliest_relay = 2;
            earliest_next_toggle_time = next_toggle_time_relay2;
        }
        if (next_toggle_time_relay3 > earliest_next_toggle_time) {
            earliest_relay = 3;
            earliest_next_toggle_time = next_toggle_time_relay3;
        }
        if (next_toggle_time_relay4 > earliest_next_toggle_time) {
            earliest_relay = 4;
            earliest_next_toggle_time = next_toggle_time_relay4;
        }

        // Toggle the relay with the earliest next toggle time
        if (earliest_relay != -1)
        {
            struct timespec sleep_time;
            sleep_time.tv_sec = (earliest_next_toggle_time / 1000000000L) - time(NULL);
            sleep_time.tv_nsec = (long)earliest_next_toggle_time % 1000000000L;
            if (sleep_time.tv_nsec < 0) {
                sleep_time.tv_nsec += 1000000000L;
                sleep_time.tv_sec--;
            }

            nanosleep(&sleep_time, NULL);

            toggle_relay(earliest_relay);

            // Update the last toggle time for the toggled relay
            if (earliest_relay == 1) {
                clock_gettime(CLOCK_MONOTONIC, &last_toggle_time_relay1);
            } else if (earliest_relay == 2) {
                clock_gettime(CLOCK_MONOTONIC, &last_toggle_time_relay2);
            } else if (earliest_relay == 3) {
                clock_gettime(CLOCK_MONOTONIC, &last_toggle_time_relay3);
            } else {
                clock_gettime(CLOCK_MONOTONIC, &last_toggle_time_relay4);
            }
        }
    }

    // Turn off all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

