#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define RELAY_ACTIVATION_DURATION 3000 // milliseconds
#define DEBOUNCE_DELAY 500 // milliseconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned long last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm_event();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    log_alarm_event();
    gpioDelay(RELAY_ACTIVATION_DURATION);
    gpioWrite(RELAY_PIN, 0); // Turn relay off
}

// Log alarm event to file
void log_alarm_event() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Alarm triggered\n", s);
    fclose(fp);
}

// Cleanup function
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            unsigned long current_time = gpioTick();
            if (current_time - last_activation_time > DEBOUNCE_DELAY * 1000) {
                activate_relay();
                last_activation_time = current_time;
            }
        }

        gpioDelay(POLLING_INTERVAL);
    }

    return 0;
}

