// Read MH-Z19B CO2 sensor function
int read_mh_z19b(int uart_fd, int *co2_ppm) {
    unsigned char command[CO2_COMMAND_SIZE] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    unsigned char response[CO2_RESPONSE_SIZE];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        if (uart_write_data(uart_fd, command, CO2_COMMAND_SIZE) < 0) {
            log_error("Failed to write CO2 command");
            return -1;
        }

        gpioDelay(10); // Small delay after writing command

        bytes_read = uart_read_data(uart_fd, response, CO2_RESPONSE_SIZE);
        if (bytes_read < 0) {
            log_error("Failed to read CO2 response");
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (bytes_read == CO2_RESPONSE_SIZE) {
            // Basic checksum validation (replace with actual checksum calculation)
            // For example, sum of bytes should equal a certain value
            unsigned char checksum = 0;
            for (int i = 0; i < CO2_RESPONSE_SIZE - 1; i++) {
                checksum += response[i];
            }
            if (checksum != response[CO2_RESPONSE_SIZE - 1]) {
                log_error("CO2 checksum mismatch");
                retries++;
