            *als_lux = (response[0] << 8) | response[1]; // Example: ALS value in the first two bytes
            return 0; // Success
        } else {
            log_error("Incomplete ALS response");
            retries++;
            gpioDelay(100);
        }
    }

    log_error("ALS read failed after multiple retries");
    return -1; // Failure
}

// Process sensor data function
int process_sensor_data(int co2_ppm, int als_lux, sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data->timestamp_us = (long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
    data->co2_ppm = co2_ppm;
    data->als_lux = als_lux;
    data->error_flag = 0; // Assume no error for now
    return 0;
}

// Log data function
int log_data(const sensor_data_t *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized\n");
        return -1;
    }

    fprintf(log_file, "{\"timestamp_us\":%ld,\"co2_ppm\":%d,\"als_lux\":%d,\"error_flag\":%d}\n",
            data->timestamp_us, data->co2_ppm, data->als_lux, data->error_flag);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Log error function
int log_error(const char *message) {
    if (error_file == NULL) {
        fprintf(stderr, "Error log file not initialized\n");
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(error_file, "%ld: %s\n", (long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000, message);
    fflush(error_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART
    uart_fd = uart_init(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        uart_close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Open log files
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        uart_close(uart_fd);
        gpioTerminate();
        return 1;
    }

    error_file = fopen("co2_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", strerror(errno));
        fclose(log_file);
        i2c_close(i2c_fd);
        uart_close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int co2_ppm = 0;
        int als_lux = 0;
        sensor_data_t sensor_data;

        // Read CO2 sensor
        if (read_mh_z19b(uart_fd, &co2_ppm) == 0) {
            // Read ALS sensor
            if (read_als_sensor(i2c_fd, &als_lux) == 0) {
                // Process sensor data
                if (process_sensor_data(co2_ppm, als_lux, &sensor_data) == 0) {
                    // Log data
                    if (log_data(&sensor_data) != 0) {
                        log_error("Failed to log data");
                    }
                    printf("CO2: %d ppm, ALS: %d lux\n", co2_ppm, als_lux);
                } else {
                    log_error("Failed to process sensor data");
                }
            } else {
                log_error("Failed to read ALS sensor");
            }
        } else {
            log_error("Failed to read CO2 sensor");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Clean up
    fclose(log_file);
    fclose(error_file);
    i2c_close(i2c_fd);
    uart_close(uart_fd);
    gpioTerminate();

    return 0;
}

