#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define OUTPUT_PIN 17

// Target heading (degrees)
#define TARGET_HEADING 90.0

// Hard-iron offsets
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET -50

// Circular buffer size
#define BUFFER_SIZE 100

// I2C handle
int i2c_handle;

// Circular buffer
int heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to compensate for hard iron offsets
void compensate_hard_iron(int16_t x, int16_t y, int16_t z, int16_t *compensated_x, int16_t *compensated_y, int16_t *compensated_z) {
    *compensated_x = x - HARD_IRON_X_OFFSET;
    *compensated_y = y - HARD_IRON_Y_OFFSET;
    *compensated_z = z; // No Z offset compensation
}

// Function to calculate heading in degrees
double calculate_heading(int16_t x, int16_t y) {
    double heading_rad = atan2((double)y, (double)x);
    double heading_deg = heading_rad * 180.0 / M_PI;

    // Normalize to 0-360 degrees
    if (heading_deg < 0) {
        heading_deg += 360.0;
    }

    return heading_deg;
}

// Function to update the circular buffer
void update_circular_buffer(double heading) {
    heading_buffer[buffer_index] = (int)heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to control the output pin
void control_output(double heading) {
    double deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(OUTPUT_PIN, 1); // HIGH
    } else {
        gpioWrite(OUTPUT_PIN, 0); // LOW
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(OUTPUT_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double heading;
    int16_t compensated_x, compensated_y, compensated_z;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Compensate for hard iron offsets
            compensate_hard_iron(x, y, z, &compensated_x, &compensated_y, &compensated_z);

            // Calculate heading
            heading = calculate_heading(compensated_x, compensated_y);

            // Update circular buffer
            update_circular_buffer(heading);

            // Control output pin
            control_output(heading);

            printf("Heading: %.2f degrees\n", heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(OUTPUT_PIN, 0); // Ensure output is low on exit
    gpioTerminate();

    return 0;
}

