#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB lamps
#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22

// Define I2C bus and address
#define I2C_BUS   1
#define BH1750_ADDR 0x23

// Global variables for signal handling
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio();
int init_i2c();
int read_lux(int i2c_handle);
void control_relays(int lux_value);
void log_data(int lux_value, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int red_pin;
    int green_pin;
    int blue_pin;
} gpio_config_t;

// Structure to hold sensor and logging configurations
typedef struct {
    int i2c_bus;
    int bh1750_address;
    char *log_file_name;
} sensor_config_t;

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize relays to OFF state
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    return 0;
}

// Initialize I2C communication
int init_i2c() {
    int handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read lux value from BH1750 sensor
int read_lux(int i2c_handle) {
    char config[1] = {0x10}; // Continuous high-resolution mode
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(120); // Wait for conversion (at least 120ms)

    char buffer[2];
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (int)(raw_value / 1.2); // Convert to lux
}

// Control RGB lamps based on lux value
void control_relays(int lux_value) {
    if (lux_value < 50) {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux_value >= 50 && lux_value < 150) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux_value >= 150 && lux_value < 300) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 1);
    } else {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 1);
    }
}

// Log data to file
void log_data(int lux_value, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %d, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux_value, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off all relays
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Configuration
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .bh1750_address = BH1750_ADDR,
        .log_file_name = "lighting_log.txt"
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int lux_value = read_lux(i2c_handle);
        if (lux_value >= 0) {
            control_relays(lux_value);
            log_data(lux_value, gpioRead(RED_PIN), gpioRead(GREEN_PIN), gpioRead(BLUE_PIN));
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

