        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (int)(raw_value / 1.2); // Convert to lux
}

// Control RGB lamps based on lux value
void control_relays(int lux_value) {
    if (lux_value < 50) {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux_value >= 50 && lux_value < 150) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 0);
    } else if (lux_value >= 150 && lux_value < 300) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 1);
    } else {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 1);
    }
}

// Log data to file
void log_data(int lux_value, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %d, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux_value, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off all relays
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Configuration
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .bh1750_address = BH1750_ADDR,
        .log_file_name = "lighting_log.txt"
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int lux_value = read_lux(i2c_handle);
        if (lux_value >= 0) {
            control_relays(lux_value);
            log_data(lux_value, gpioRead(RED_PIN), gpioRead(GREEN_PIN), gpioRead(BLUE_PIN));
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

