// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Distance thresholds
#define FORWARD_THRESHOLD 50
#define BACKWARD_THRESHOLD 50

// Global variables for distance readings
int distance_a;
int distance_b;

// Function prototypes
int initialize_gpio();
void stop_motors();
void cleanup_gpio();
void signal_handler(int signal);
int map_distance_to_duty_cycle(int distance);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_motors();
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor A IN1 and IN2 as outputs
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set MOTOR_A_IN1 as output\n");
        return 1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set MOTOR_A_IN2 as output\n");
        return 1;
    }

    // Set motor B IN3 and IN4 as outputs
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set MOTOR_B_IN3 as output\n");
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set MOTOR_B_IN4 as output\n");
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for MOTOR_A_IN2\n");
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for MOTOR_B_IN4\n");
        return 1;
    }

    return 0;
}

// Stop both motors
void stop_motors() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    stop_motors();
    gpioTerminate();
}

// Map distance to duty cycle (0-255)
int map_distance_to_duty_cycle(int distance) {
    int duty_cycle;

    if (distance < FORWARD_THRESHOLD) {
        duty_cycle = 255;
    } else if (distance > BACKWARD_THRESHOLD) {
        duty_cycle = 0;
    } else {
        duty_cycle = (int)(((float)(distance - FORWARD_THRESHOLD) / (BACKWARD_THRESHOLD - FORWARD_THRESHOLD)) * 255.0);
    }

    return duty_cycle;
}

int main(int argc, char *argv[]) {
    // Check for correct number of arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse distance values
    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    // Validate distance values
    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Distance values must be between 10 and 100 cm\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1) {
        // Map distances to duty cycles
        int duty_cycle_a = map_distance_to_duty_cycle(distance_a);
        int duty_cycle_b = map_distance_to_duty_cycle(distance_b);

        // Set motor directions and PWM duty cycles
        gpioWrite(MOTOR_A_IN1, 1);
        gpioWrite(MOTOR_A_IN2, 0);
        gpioPWM(MOTOR_A_IN2, duty_cycle_a);

        gpioWrite(MOTOR_B_IN3, 1);
        gpioWrite(MOTOR_B_IN4, 0);
        gpioPWM(MOTOR_B_IN4, duty_cycle_b);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

