#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Servo control PWM channel
#define PWM_CHANNEL 0

// Servo control PWM chip
#define PWM_CHIP 2

// Servo control PWM period (1000000 ns = 1 ms)
#define PWM_PERIOD 1000000

// Servo control PWM duty cycle (50% for 90 degrees)
#define PWM_DUTY_CYCLE 500000

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int pwm_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int fd, int angle);
int log_data(FILE *fp, float pitch, float roll, int servo_angle);
void signal_handler(int signal);
int initialize_i2c(int addr);
int initialize_pwm(int chip, int channel, int period, int duty_cycle);
int cleanup_resources(int i2c_fd, int pwm_fd, FILE *log_file);

// I2C read function with exponential backoff
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 5;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, len %d)\n", reg, len);
    return -1; // Failure
}

// I2C write function with exponential backoff
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 5;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = write(fd, &value, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Failure
}

// Read MPU-6050 data
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[14];

    if (i2c_read_bytes(fd, ACCEL_XOUT_H, data, 14) != 0) {
        return -1;
    }

    *accel_x = (int16_t)((data[0] << 8) | data[1]);
    *accel_y = (int16_t)((data[2] << 8) | data[3]);
    *accel_z = (int16_t)((data[4] << 8) | data[5]);
    *gyro_x  = (int16_t)((data[8] << 8) | data[9]);
