#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (in seconds)
#define FADE_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Global variables
static volatile int running = 1;
static int relay_states[4] = {0, 0, 0, 0}; // Initial states for the relays

// Function prototypes
int read_schedule(const char *filename, int *relay_numbers, int *states, int *current_time);
int fade_relay(int relay_number, int target_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;

        // Turn off all relays
        gpioWrite(RELAY1_PIN, 0);
        gpioWrite(RELAY2_PIN, 0);
        gpioWrite(RELAY3_PIN, 0);
        gpioWrite(RELAY4_PIN, 0);

        // Release GPIO resources
        gpioTerminate();

        exit(0);
    }
}

// Function to read the schedule file
int read_schedule(const char *filename, int *relay_numbers, int *states, int *current_time) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int relay_index;
    char *token;
    int time_hour, time_minute, time_second;

    // Read the first line to get the current time
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    if (sscanf(line, "%d:%d:%d", &time_hour, &time_minute, &time_second) != 3) {
        fclose(fp);
        return -1;
    }
    *current_time = time_hour * 3600 + time_minute * 60 + time_second;

    // Read the rest of the lines
    while (fgets(line, sizeof(line), fp) != NULL) {
        token = strtok(line, ",");
        if (token != NULL) {
            relay_index = atoi(token) - 1; // Convert to 0-3 index
            if (relay_index >= 0 && relay_index < 4) {
                token = strtok(NULL, ",");
                if (token != NULL) {
                    if (strcmp(token, "on") == 0) {
                        states[relay_index] = 1;
                    } else if (strcmp(token, "off") == 0) {
                        states[relay_index] = 0;
                    } else {
                        fprintf(stderr, "Invalid state in schedule file: %s\n", token);
                        fclose(fp);
                        return -1;
                    }
                } else {
                    fprintf(stderr, "Missing state in schedule file: %s\n", line);
                    fclose(fp);
                    return -1;
                }
            } else {
                fprintf(stderr, "Invalid relay number in schedule file: %s\n", line);
                fclose(fp);
                return -1;
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to fade a relay
int fade_relay(int relay_number, int target_state) {
    int current_state = relay_states[relay_number];
    int duty_cycle;
    int i;

    if (target_state != current_state) {
        // Calculate the duty cycle
        duty_cycle = (int)(((float)(target_state - current_state) / 2.0) * 100.0);

        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        // Perform the fade
        for (i = 0; i < FADE_DURATION; i++) {
            if (i < duty_cycle) {
                gpioPWM(relay_number, 100); // Full brightness
            } else {
                gpioPWM(relay_number, 0);  // No brightness
            }
            gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1 second (1000000 us / 100 Hz)
        }

        // Update the relay state
        relay_states[relay_number] = target_state;
    }

    return 0;
}

int main() {
    int relay_numbers[4] = {4, 17, 27, 22}; // BCM pin numbers
    int states[4] = {0, 0, 0, 0}; // Initial states
    int current_time = 0; // Initial time

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RELAY1_PIN, 255);
    gpioSetPWMrange(RELAY2_PIN, 255);
    gpioSetPWMrange(RELAY3_PIN, 255);
    gpioSetPWMrange(RELAY4_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read the schedule
        if (read_schedule(SCHEDULE_FILE, relay_numbers, states, &current_time) == 0) {
            // Check for time transitions
            if (current_time != 0) {
                // Check each relay's schedule
                for (int i = 0; i < 4; i++) {
