#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Function to set the color of the RGB LED using PWM
void set_rgb_color(float red, float green, float blue)
{
    // Clamp the color values to the range [0.0, 1.0]
    red = fmax(0.0, fmin(red, 1.0));
    green = fmax(0.0, fmin(green, 1.0));
    blue = fmax(0.0, fmin(blue, 1.0));

    // Convert color values to PWM duty cycle (0-255)
    int red_duty = (int)(red * 255.0);
    int green_duty = (int)(green * 255.0);
    int blue_duty = (int)(blue * 255.0);

    // Set the PWM duty cycle for each color channel
    gpioPWM(RED_PIN, red_duty);
    gpioPWM(GREEN_PIN, green_duty);
    gpioPWM(BLUE_PIN, blue_duty);
}

// Function to generate a sine wave for the proximity value
float generate_proximity_value(float time)
{
    return 0.5 * (1.0 + sin(time * M_PI));
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for each pin
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        // Generate a sine wave for the proximity value
        float time = (float)gpioTick() / 1000000.0; // Time in seconds
        float proximity = generate_proximity_value(time);

        // Set the RGB color based on the proximity value
        set_rgb_color(proximity, proximity, proximity);

        // Delay for a short period
        usleep(10000); // 10 milliseconds
    }

    // Turn off the LED and release PWM resources before exiting
    set_rgb_color(0.0, 0.0, 0.0);
    gpioTerminate();

    return 0;
}

