#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for gyroscope
#define GYRO_SCALE 131.0

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);
int log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw gyroscope data to degrees per second
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x / GYRO_SCALE;
    *gyro_y_dps = (float)gyro_y / GYRO_SCALE;
    *gyro_z_dps = (float)gyro_z / GYRO_SCALE;
}

// Log data to file
