#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 440

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define melody lookup table
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523}; // C4, D4, E4, F4, G4, A4, B4, C5
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Define debounce variables
volatile int last_interrupt_time = 0;
volatile int melody_playing = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Interrupt service routine for button press
void button_isr(int gpio, int level, uint32_t tick, void *user)
{
    int current_time = gpioTick();

    // Debounce the button
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000)
    {
        last_interrupt_time = current_time;

        if (melody_playing == 0)
        {
            play_melody();
            melody_playing = 1;
        }
        else
        {
            stop_melody();
            melody_playing = 0;
        }
    }
}

// Function to play the melody
void play_melody()
{
    int i;
    for (i = 0; i < melody_length; i++)
    {
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);
        gpioDelay(1000000 / melody[i]); // Delay for note duration (1ms = 1000us)
    }
}

// Function to stop the melody
void stop_melody()
{
    gpioPWM(BUZZER_PIN, 0); // Stop PWM output
}

// Signal handler for clean shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM frequency for buzzer
    gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);

    // Set up interrupt service routine for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        if (melody_playing == 1)
        {
            gpioDelay(100000); // Check every 0.1 seconds
        }
        else
        {
            gpioDelay(1000000); // Check every 1 second
        }
    }

    return 0;
}

