#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define ISO8601_FORMAT "%Y-%m-%dT%H:%M:%SZ"

// Structure to hold the sliding window of events
typedef struct {
    int events[WINDOW_SIZE];
    int head;
    int count;
} EventWindow;

// Global variables
volatile sig_atomic_t terminate = 0;
int poll_timeout_ms = 1000;

// Function prototypes
int read_vibration_sensor();
void log_event(int value);
void handle_edge(int value);
void check_earthquake_alert(EventWindow *window);
void signal_handler(int signal);
void initialize_event_window(EventWindow *window);
void add_event_to_window(EventWindow *window, int value);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the event window
void initialize_event_window(EventWindow *window) {
    window->head = 0;
    window->count = 0;
    memset(window->events, 0, sizeof(window->events));
}

// Add an event to the sliding window
void add_event_to_window(EventWindow *window, int value) {
    window->events[window->head] = value;
    window->head = (window->head + 1) % WINDOW_SIZE;
    if (window->count < WINDOW_SIZE) {
        window->count++;
    }
}

// Read the vibration sensor value
int read_vibration_sensor() {
    return gpioRead(GPIO_PIN);
}

// Log the event to the file
void log_event(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char timestamp[ISO8601_FORMAT];
    strftime(timestamp, sizeof(timestamp), ISO8601_FORMAT, tstruct);

    fprintf(fp, "%s, %d\n", timestamp, value);
    if (fwrite(timestamp, 1, strlen(timestamp), fp) < strlen(timestamp)) {
        fprintf(stderr, "Error writing timestamp to log file: %s\n", strerror(errno));
    }
    if (fwrite(", %d\n", 1, value, fp) < value) {
        fprintf(stderr, "Error writing value to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    fsync(fileno(fp)); // Ensure data is written to disk
}

// Handle the edge event
void handle_edge(int value) {
    log_event(value);
    add_event_to_window(event_window, value);
    check_earthquake_alert(event_window);
}

// Check for earthquake alert
void check_earthquake_alert(EventWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->events[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        printf("EARTHQUAKE ALERT\n");
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: 1000ms\n");
            poll_timeout_ms = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize event window
    EventWindow event_window;
    initialize_event_window(&event_window);

    // Main loop
    int last_value = 0;
    int current_value;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = poll_timeout_ms * 1000000; // Convert milliseconds to nanoseconds

    while (!terminate) {
        current_value = read_vibration_sensor();

        if (current_value != last_value) {
            handle_edge(current_value);
            last_value = current_value;
            nanosleep(&sleep_time, NULL);
        } else {
            nanosleep(&sleep_time, NULL);
        }
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

