        return -1;
    }

    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the magnetometer
int init_magnetometer() {
    // Set continuous mode and 15 Hz data rate
    if (i2cWriteByteData(i2c_handle, LSM303_CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }

    // Set full-scale range to +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, LSM303_CTRL_REG3_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG3_M: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

