magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t raw_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        raw_data.x = 0; // Set to zero to avoid using uninitialized data
        raw_data.y = 0;
        raw_data.z = 0;
        return raw_data;
    }

    raw_data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return raw_data;
