#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Callback function for touch sensor interrupt
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce logic
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        if (level == 1) { // Rising edge (touch detected)
            relay_state = !relay_state; // Toggle relay state
            gpioWrite(RELAY_PIN, relay_state);

            // Log relay state change
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
            fflush(log_file); // Ensure data is written to file immediately

            last_touch_time = current_time;
        }
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN); // Enable pull-down resistor
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    // Set up interrupt on touch sensor pin
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running)
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

