#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Global variable to store the seed for the random number generator
static unsigned int seed = 0;

// Function prototypes
int initialize_gpio();
int generate_moisture_level();
int activate_relay(int gpio_pin, int duration_seconds, int gap_seconds);
int deactivate_relay(int gpio_pin);
int log_irrigation_event(int relay_number, int moisture_level);
void cleanup_gpio();
void signal_handler(int signal);

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Seed the random number generator
    srand(seed);

    // Main loop
    while (1) {
        // Generate a simulated soil moisture level
        int moisture_level = generate_moisture_level();

        // Check if irrigation is needed
        if (moisture_level < 30) {
            // Activate relays sequentially
            activate_relay(RELAY1_PIN, 5, 1);
            activate_relay(RELAY2_PIN, 5, 1);
            activate_relay(RELAY3_PIN, 5, 1);
            activate_relay(RELAY4_PIN, 5, 1);

            // Log the irrigation event
            log_irrigation_event(1, moisture_level);
            log_irrigation_event(2, moisture_level);
            log_irrigation_event(3, moisture_level);
            log_irrigation_event(4, moisture_level);
        }

        // Wait for 10 seconds
        gpioDelay(10000000); // 10 seconds in microseconds
    }

    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to generate a simulated soil moisture level
int generate_moisture_level() {
    // Seed the random number generator with the current time
    seed = time(NULL);

    // Generate a random number between 0 and 100
    return rand() % 101;
}

// Function to activate a relay for a specified duration
int activate_relay(int gpio_pin, int duration_seconds, int gap_seconds) {
    // Set the GPIO pin to 0 (active)
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", gpio_pin);
        return 1;
    }

    // Wait for the specified duration
    gpioDelay(duration_seconds * 1000000); // Convert seconds to microseconds

    // Set the GPIO pin to 1 (inactive)
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", gpio_pin);
        return 1;
    }

    // Wait for the specified gap
    gpioDelay(gap_seconds * 1000000); // Convert seconds to microseconds

    return 0;
}

// Function to deactivate a relay
