            nozzle_angle = angle;
            return ERROR_NONE;
        } else {
            fprintf(stderr, "Failed to set nozzle angle, retrying...\n");
            gpioDelay(RETRY_DELAY);
            retries++;
        }
    }
    fprintf(stderr, "Failed to set nozzle angle after %d retries\n", MAX_RETRIES);
    return ERROR_GPIO_SERVO;
}

// Water the plant
int water_plant() {
    printf("Watering plant...\n");
    if (simulate_soil_moisture() < 50) {
        printf("Soil moisture is low (%d), opening valve...\n", simulate_soil_moisture());
        if (open_valve() != ERROR_NONE) {
            fprintf(stderr, "Failed to open valve, aborting watering cycle\n");
            return ERROR_GPIO_SERVO;
        }
        gpioDelay(VALVE_OPEN_TIME * 1000); // Delay in milliseconds

        printf("Sweeping nozzle...\n");
        for (int i = 0; i < 5; i++) {
            int angle = (i * 45) + 0;
            if (set_nozzle_angle(angle) != ERROR_NONE) {
                fprintf(stderr, "Failed to set nozzle angle, continuing...\n");
            }
            gpioDelay(SPRAY_DURATION * 1000); // Delay in milliseconds
        }

        printf("Closing valve...\n");
        if (close_valve() != ERROR_NONE) {
            fprintf(stderr, "Failed to close valve, aborting watering cycle\n");
            return ERROR_GPIO_SERVO;
        }
        gpioDelay(VALVE_CLOSE_TIME * 1000); // Delay in milliseconds
    } else {
        printf("Soil moisture is sufficient (%d), skipping watering cycle\n", simulate_soil_moisture());
    }
    return ERROR_NONE;
}

// Simulate soil moisture
int simulate_soil_moisture() {
    static int moisture = 20;
    moisture = (moisture + 20) % 100;
    return moisture;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != ERROR_NONE) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    printf("Plant watering system started\n");

    // Main loop
    while (!terminate) {
        water_plant();
        gpioDelay(CYCLE_DELAY * 1000); // Delay in milliseconds
    }

    // Cleanup GPIO
    printf("Cleaning up GPIO...\n");
    gpioTerminate();

    printf("Plant watering system stopped\n");
    return 0;
}

