// Global variables
volatile sig_atomic_t terminate = 0;
volatile sig_atomic_t valve_open = 0;
volatile sig_atomic_t nozzle_angle = 0;

// Function prototypes
int initialize_gpio();
int open_valve();
int close_valve();
int set_nozzle_angle(int angle);
int water_plant();
int simulate_soil_moisture();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return ERROR_GPIO_INIT;
    }

    if (gpioSetMode(VALVE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set VALVE_PIN as output\n");
        return ERROR_GPIO_SET_MODE;
    }

    if (gpioSetMode(NOZZLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set NOZZLE_PIN as output\n");
        return ERROR_GPIO_SET_MODE;
    }

    if (gpioSetPWMrange(VALVE_PIN, 2000) != 0) {
        fprintf(stderr, "Failed to set PWM range for VALVE_PIN\n");
        return ERROR_GPIO_SET_PWM_RANGE;
    }

    if (gpioSetPWMrange(NOZZLE_PIN, 2000) != 0) {
        fprintf(stderr, "Failed to set PWM range for NOZZLE_PIN\n");
        return ERROR_GPIO_SET_PWM_RANGE;
    }

    if (gpioSetPWMpolarity(VALVE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set PWM polarity for VALVE_PIN\n");
        return ERROR_GPIO_SET_PWM_POLARITY;
    }

    if (gpioSetPWMpolarity(NOZZLE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set PWM polarity for NOZZLE_PIN\n");
        return ERROR_GPIO_SET_PWM_POLARITY;
    }

    if (gpioSetPWMrepeat(VALVE_PIN, 1000000) != 0) {
        fprintf(stderr, "Failed to set PWM repeat for VALVE_PIN\n");
        return ERROR_GPIO_SET_PWM_REPEAT_MODE;
    }

    if (gpioSetPWMrepeat(NOZZLE_PIN, 1000000) != 0) {
        fprintf(stderr, "Failed to set PWM repeat for NOZZLE_PIN\n");
        return ERROR_GPIO_SET_PWM_REPEAT_MODE;
    }

    return ERROR_NONE;
}

// Open the valve
int open_valve() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpioPWM(VALVE_PIN, VALVE_OPEN_PULSE) == 0) {
            valve_open = 1;
            return ERROR_NONE;
        } else {
            fprintf(stderr, "Failed to open valve, retrying...\n");
            gpioDelay(RETRY_DELAY);
            retries++;
        }
    }
    fprintf(stderr, "Failed to open valve after %d retries\n", MAX_RETRIES);
    return ERROR_GPIO_SERVO;
}

// Close the valve
int close_valve() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpioPWM(VALVE_PIN, VALVE_CLOSED_PULSE) == 0) {
            valve_open = 0;
            return ERROR_NONE;
        } else {
            fprintf(stderr, "Failed to close valve, retrying...\n");
            gpioDelay(RETRY_DELAY);
            retries++;
        }
    }
    fprintf(stderr, "Failed to close valve after %d retries\n", MAX_RETRIES);
    return ERROR_GPIO_SERVO;
}

// Set the nozzle angle
int set_nozzle_angle(int angle) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpioPWM(NOZZLE_PIN, angle) == 0) {
            nozzle_angle = angle;
            return ERROR_NONE;
        } else {
            fprintf(stderr, "Failed to set nozzle angle, retrying...\n");
            gpioDelay(RETRY_DELAY);
            retries++;
        }
    }
    fprintf(stderr, "Failed to set nozzle angle after %d retries\n", MAX_RETRIES);
    return ERROR_GPIO_SERVO;
}

// Water the plant
int water_plant() {
    printf("Watering plant...\n");
    if (simulate_soil_moisture() < 50) {
        printf("Soil moisture is low (%d), opening valve...\n", simulate_soil_moisture());
        if (open_valve() != ERROR_NONE) {
            fprintf(stderr, "Failed to open valve, aborting watering cycle\n");
            return ERROR_GPIO_SERVO;
        }
        gpioDelay(VALVE_OPEN_TIME * 1000); // Delay in milliseconds

        printf("Sweeping nozzle...\n");
        for (int i = 0; i < 5; i++) {
            int angle = (i * 45) + 0;
            if (set_nozzle_angle(angle) != ERROR_NONE) {
                fprintf(stderr, "Failed to set nozzle angle, continuing...\n");
            }
            gpioDelay(SPRAY_DURATION * 1000); // Delay in milliseconds
        }

        printf("Closing valve...\n");
        if (close_valve() != ERROR_NONE) {
            fprintf(stderr, "Failed to close valve, aborting watering cycle\n");
            return ERROR_GPIO_SERVO;
        }
        gpioDelay(VALVE_CLOSE_TIME * 1000); // Delay in milliseconds
    } else {
        printf("Soil moisture is sufficient (%d), skipping watering cycle\n", simulate_soil_moisture());
    }
    return ERROR_NONE;
}

// Simulate soil moisture
int simulate_soil_moisture() {
    static int moisture = 20;
    moisture = (moisture + 20) % 100;
    return moisture;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != ERROR_NONE) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    printf("Plant watering system started\n");

    // Main loop
    while (!terminate) {
        water_plant();
        gpioDelay(CYCLE_DELAY * 1000); // Delay in milliseconds
    }

    // Cleanup GPIO
    printf("Cleaning up GPIO...\n");
    gpioTerminate();

    printf("Plant watering system stopped\n");
    return 0;
}

