    gpioWrite(IN4, 0);
}

// Callback function for button press
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == LOCK_BUTTON && level == 0) { // Button pressed (active low)
        lock_door();
    } else if (gpio == UNLOCK_BUTTON && level == 0) { // Button pressed (active low)
        unlock_door();
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    stop_motor();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    // Enable pull-up resistors on buttons
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Set initial state of IN1-IN4 to LOW
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    // Register callback functions for button presses
    gpioSetAlertFuncEx(LOCK_BUTTON, button_callback, NULL);
    gpioSetAlertFuncEx(UNLOCK_BUTTON, button_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door control program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Keep the program running
    }

    return 0;
}

