#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_PIN 18
#define DISTANCE_THRESHOLD 50 // cm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Add initialization code here, if needed
    // For example, writing configuration registers
    // This might involve writing specific values to the sensor's registers
    // to set the operating mode, timing, etc.
    // Refer to the VL53L1X datasheet for the correct initialization sequence.
    // For now, we'll just return success.
    (void)VL53L1X_ADDR; // Suppress unused parameter warning
    return 0; // Success
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Command to trigger a measurement
    char buffer[2];        // Buffer to store the distance data
    int result;

    // Write the command to trigger a measurement
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1; // Indicate failure
    }

    // Wait for a short time for the measurement to complete
    gpioDelay(10000); // 10 ms delay

    // Read the distance data from the sensor
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1; // Indicate failure
    }

    // Combine the two bytes into a 16-bit distance value
    *distance = (buffer[0] << 8) | buffer[1];

    return 0; // Success
}

// Control the relay based on distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_PIN, 1); // Set relay HIGH
    } else {
        gpioWrite(RELAY_PIN, 0); // Set relay LOW
    }
}

int main() {
    int distance;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Control relay based on distance
            control_relay(distance);

            // Print distance to stdout
            printf("Distance: %d cm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait 100 ms
        gpioDelay(100000);
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, 0); // Set relay LOW
    gpioTerminate();

    return 0;
}

