#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];

    // Read 6 bytes of data starting from GYRO_XOUT_H
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes to form 16-bit values
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print gyroscope values
            printf("Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

