#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_cycle_start();
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to control the watering system
    while (program_running) {
        // Activate each relay sequentially
        activate_relay(RELAY1_PIN);
        gpioDelay(5000000); // 5 seconds
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        gpioDelay(5000000); // 5 seconds
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        gpioDelay(5000000); // 5 seconds
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        gpioDelay(5000000); // 5 seconds
        deactivate_relay(RELAY4_PIN);

        // Log the start of a new watering cycle
        log_cycle_start();

        // Wait for 86400 seconds (24 hours)
        gpioDelay(86400000000); // 86400 seconds * 1000000 microseconds/second
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs with active-low logic
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to the inactive state (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to activate a relay by setting the corresponding GPIO pin LOW
void activate_relay(int pin) {
    gpioWrite(pin, 0);
}

// Function to deactivate a relay by setting the corresponding GPIO pin HIGH
void deactivate_relay(int pin) {
    gpioWrite(pin, 1);
}

// Function to log the start time of a watering cycle to a file
void log_cycle_start() {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening watering_log.txt for writing!\n");
        return;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
}

