#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler_int(int signal) {
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void signal_handler_term(int signal) {
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_relay_intensity(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to clean up GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Turn off all relays
    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);

    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler_int);
    signal(SIGTERM, signal_handler_term);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Program started");

    // Sunrise effect loop
    for (int i = 0; i <= 255 && program_running; i++) {
        // Set relay intensities
        set_relay_intensity(RELAY1_PIN, i);
        set_relay_intensity(RELAY2_PIN, i);
        set_relay_intensity(RELAY3_PIN, i);
        set_relay_intensity(RELAY4_PIN, i);

        // Log the event
        char message[100];
        snprintf(message, sizeof(message), "Relay intensities set to %d", i);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    // Turn off all relays after sunrise
    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);

    log_event("Sunrise effect complete");

    // Clean up GPIO
    cleanup_gpio();

    log_event("Program terminated");

    return 0;
}

