#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 register addresses
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    struct timespec timestamp;
    int16_t x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(gyro_data_t data);
gyro_data_t get_from_buffer(int index);
int check_threshold(int16_t x, int16_t y, int16_t z);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get data from the circular buffer
gyro_data_t get_from_buffer(int index) {
    return gyro_buffer[index];
}

// Function to check if the absolute value of any axis exceeds the threshold
int check_threshold(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        return 1;
    } else {
        return 0;
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    gyro_data_t gyro_data;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Store data in gyro_data struct
            gyro_data.timestamp = ts;
            gyro_data.x = x;
            gyro_data.y = y;
            gyro_data.z = z;

            // Add data to buffer
            add_to_buffer(gyro_data);

            // Check threshold and control LED
            int led_state = check_threshold(x, y, z);
            control_led(led_state);

            // Print data (optional)
            //printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() < 0) {
                fprintf(stderr, "I2C re-initialization failed, exiting...\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Wait for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

