#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Sensitivity scale factor for accelerometer
#define ACCEL_SCALE 16384.0f

// GPIO pin for LED
#define LED_PIN 21

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void control_led(float roll, float pitch);
void log_data(float roll, float pitch);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting.\n");
        running = false;
        digitalWrite(LED_PIN, LOW); // Turn off LED
        close(i2c_fd); // Close I2C handle
        fclose(log_file); // Close log file
        exit(0);
    }
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050. Error code: %d\n", errno);
        return -1;
    }
    return 0;
}

// Read raw accelerometer data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    int16_t x, y, z;

    x = wiringPiI2CReadReg16(i2c_fd, ACCEL_XOUT_H);
    if (x < 0) {
        fprintf(stderr, "Error reading ACCEL_XOUT_H: %s\n", strerror(errno));
        return -1;
    }
    *accel_x = x;

    y = wiringPiI2CReadReg16(i2c_fd, ACCEL_YOUT_H);
    if (y < 0) {
        fprintf(stderr, "Error reading ACCEL_YOUT_H: %s\n", strerror(errno));
        return -1;
    }
    *accel_y = y;

    z = wiringPiI2CReadReg16(i2c_fd, ACCEL_ZOUT_H);
    if (z < 0) {
        fprintf(stderr, "Error reading ACCEL_ZOUT_H: %s\n", strerror(errno));
        return -1;
    }
    *accel_z = z;

    return 0;
}

// Process raw data and calculate roll and pitch
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    // Convert raw data to g's
    float ax = (float)accel_x / ACCEL_SCALE;
    float ay = (float)accel_y / ACCEL_SCALE;
    float az = (float)accel_z / ACCEL_SCALE;

    // Calculate roll and pitch
    *roll = atan2(ay, az) * 180.0f / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180.0f / M_PI;
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0f || fabs(pitch) > 45.0f) {
        digitalWrite(LED_PIN, HIGH); // Turn on LED
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn off LED
    }
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Could not initialize wiringPi.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Could not initialize I2C. Error code: %d\n", errno);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() == -1) {
        fprintf(stderr, "Error: Could not initialize MPU-6050.\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially turn off LED

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    float roll, pitch;

    // Main loop
    while (running) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z) == -1) {
            fprintf(stderr, "Error reading raw data. Continuing...\n");
            continue; // Continue to the next iteration
        }

        // Process data
        process_data(accel_x, accel_y, accel_z, &roll, &pitch);

        // Control LED
        control_led(roll, pitch);

        // Log data
        log_data(roll, pitch);

        // Print data to console
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        // Delay
        delay(100);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(i2c_fd); // Close I2C handle
    fclose(log_file); // Close log file

    return 0;
}

