#define PROXIMITY_REG 0x24
#define LED_GPIO 17
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *ambient_light, int *proximity);
int log_data(int ambient_light, int proximity);
void control_led(int proximity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int ambient_light;
    int proximity;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.ambient_light, &sensor_data.proximity) == 0) {
            // Log data
            if (log_data(sensor_data.ambient_light, sensor_data.proximity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Control LED
            control_led(sensor_data.proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *ambient_light, int *proximity) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Read ambient light
        if (i2cReadI2CBlockData(i2c_fd, AMBIENT_LIGHT_REG, buf, 2) == 2) {
            *ambient_light = (buf[1] << 8) | buf[0];
            // Read proximity
            if (i2cReadI2CBlockData(i2c_fd, PROXIMITY_REG, buf, 2) == 2) {
                *proximity = (buf[1] << 8) | buf[0];
                return 0; // Success
            } else {
                fprintf(stderr, "Failed to read proximity data, retry %d\n", retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        } else {
            fprintf(stderr, "Failed to read ambient light data, retry %d\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return 1; // Failure
}

// Log data to file
int log_data(int ambient_light, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control LED based on proximity
void control_led(int proximity) {
    if (proximity > 100) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

