#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CE 0 // CE0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define SAMPLE_DELAY_MS 10
#define SAMPLE_RATE_HZ 100
#define DATA_FILE "gyro_data.csv"

// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP 0x04
#define ADXRS290_REG_DIAG 0x06
#define ADXRS290_REG_STATUS 0x08
#define ADXRS290_REG_SENSITIVITY 0x0A
#define ADXRS290_REG_FILTER 0x0C
#define ADXRS290_REG_POWER_CTL 0x0E
#define ADXRS290_REG_RESET 0x10
#define ADXRS290_REG_TEST 0x12
#define ADXRS290_REG_FIRMWARE 0x14
#define ADXRS290_REG_ID 0x16

// Global variables
int spi_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int spi_read_register(uint8_t reg_addr, int16_t *data);
int spi_write_register(uint8_t reg_addr, uint8_t data);
int16_t read_gyro_axis(uint8_t axis_reg);
void log_data(struct timespec ts, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Structure to hold gyro data
typedef struct {
    struct timespec timestamp;
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// SPI Initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI Read Register function
int spi_read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    *data = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    return 0;
}

// SPI Write Register function
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    return 0;
}

// Read Gyro Axis function
int16_t read_gyro_axis(uint8_t axis_reg) {
    int16_t data;
    if (spi_read_register(axis_reg, &data) != 0) {
        fprintf(stderr, "Error reading gyro axis\n");
        return 0; // Return 0 on error
    }
    return data;
}

// Log Data function
void log_data(struct timespec ts, int16_t x_rate, int16_t y_rate) {
    fprintf(data_file, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate);
    fflush(data_file); // Ensure data is written to disk immediately
}

// Signal Handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "w");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(data_file, "timestamp,x_rate,y_rate\n");

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    struct timespec ts;
    int16_t x_rate, y_rate;
    int retries = 0;

    while (!terminate) {
        // Read gyro data
        x_rate = read_gyro_axis(ADXRS290_REG_X_RATE);
        y_rate = read_gyro_axis(ADXRS290_REG_Y_RATE);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            fprintf(stderr, "Error getting timestamp\n");
            break;
        }

        // Log data
        log_data(ts, x_rate, y_rate);

        // Delay
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Convert ms to us

        retries++;
        if (retries > 3) {
            fprintf(stderr, "Too many SPI initialization failures. Exiting.\n");
            break;
        }
    }

    // Cleanup
    fclose(data_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

