#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17

// Define alert duration (in seconds)
#define ALERT_DURATION 2

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, uint32_t tick, void *user_data);
void sensor2_callback(int gpio, int level, uint32_t tick, void *user_data);
void trigger_alert();
void log_event();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates current_states = {0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register callbacks
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    printf("Monitoring tilt sensors. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Set pull-down resistors (optional, depends on sensor wiring)
    // gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN);
    // gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN);

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)user_data; // Suppress unused parameter warning
    if (gpio == SENSOR1_GPIO) {
        current_states.sensor1_state = level;
        if (level == 1) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        }
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)user_data; // Suppress unused parameter warning
    if (gpio == SENSOR2_GPIO) {
        current_states.sensor2_state = level;
        if (level == 1) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        }
    }
}

// Trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set HIGH
    gpioDelay(ALERT_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(ALERT_GPIO, 0); // Set LOW
}

// Log the event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;

    // Disable callbacks
