#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <wiringPi.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CE0_PIN 8          // GPIO8 (BCM)
#define SCLK_PIN 11         // GPIO11 (BCM)
#define MOSI_PIN 10         // GPIO10 (BCM)
#define MISO_PIN 9          // GPIO9 (BCM)
#define LED_PIN 17          // GPIO17 (BCM)
#define THRESHOLD 20.0      // Degrees per second
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define BUFFER_SIZE 100

// ADXRS290 Register Addresses
#define ADXRS290_REG_XGYRO_OUT 0x04
#define ADXRS290_REG_STATUS 0x06

// Global Variables
static volatile int keep_running = 1;
static int spi_fd;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float rate_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function Prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(float *x_rate);
void add_to_buffer(float rate);
float get_average_rate(void);
void control_led(float rate);
void send_data_to_server(float rate);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error getting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

// Read Gyro Data
int read_gyro_data(float *x_rate) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    int16_t raw_data;

    // Construct the read address (MSB = 1 for read)
    tx_buf[0] = 0x80 | ADXRS290_REG_XGYRO_OUT; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for X-axis read.\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit raw data
    raw_data = (rx_buf[0] << 8) | rx_buf[1];

    // Convert raw data to degrees per second (DPS).  The ADXRS290 provides a sensitivity of 0.017 DPS/LSB.
    *x_rate = (float)raw_data * 0.017;

    return 0;
}

// Add to Circular Buffer
void add_to_buffer(float rate) {
    pthread_mutex_lock(&buffer_mutex);
    rate_buffer[buffer_index] = rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Get Average Rate
float get_average_rate(void) {
    float sum = 0.0;
    int count = buffer_count;
    pthread_mutex_lock(&buffer_mutex);
    if (count > 0) {
        for (int i = 0; i < count; i++) {
            sum += rate_buffer[i];
        }
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / count;
}

// Control LED
void control_led(float rate) {
    if (rate > THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Send Data to Server
void send_data_to_server(float rate) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[50];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    snprintf(buffer, sizeof(buffer), "Rate: %.2f deg/s", rate);

    if (sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Cleanup
void cleanup(void) {
    printf("Cleaning up...\n");
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(spi_fd);
    pthread_mutex_destroy(&buffer_mutex);
    exit(0);
}

int main(void) {
    float x_rate;
    float avg_rate;

    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed.\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially turn off the LED

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Read gyro data
        if (read_gyro_data(&x_rate) == 0) {
            // Add to buffer
            add_to_buffer(x_rate);

            // Get average rate
            avg_rate = get_average_rate();

            // Control LED
            control_led(avg_rate);

            // Send data to server
            send_data_to_server(avg_rate);

            printf("X-axis rate: %.2f deg/s, Average rate: %.2f deg/s\n", x_rate, avg_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        delay(100); // Delay for 100ms
    }

    cleanup();
    return 0;
}

