#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 255

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_lamp_brightness(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to fade a lamp from 100% to 0% brightness
void fade_lamp(int gpio_pin, int duration_seconds) {
    int i;
    int num_steps = duration_seconds * 10; // 10 steps per second
    int duty_cycle;

    for (i = 0; i < num_steps; i++) {
        duty_cycle = 255 - (i * 255 / num_steps); // Linear fade-out
        if (set_lamp_brightness(gpio_pin, duty_cycle) != 0) {
            fprintf(stderr, "Error fading lamp on GPIO %d\n", gpio_pin);
            return;
        }
        gpioDelay(10000); // 10ms delay (100Hz frequency)
    }

    // Ensure lamp is off after fading
    if (set_lamp_brightness(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error turning off lamp on GPIO %d\n", gpio_pin);
    }
}

int main(int argc, char *argv[]) {
    int duration_seconds;

    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
    }

    duration_seconds = atoi(argv[1]);

    // Validate duration
    if (duration_seconds <= 0 || duration_seconds > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_PIN, PI_OUTPUT);
    gpioSetMode(LAMP2_PIN, PI_OUTPUT);
    gpioSetMode(LAMP3_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_PIN, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade each lamp sequentially
