#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY_MS 100
#define TOGGLE_DELAY_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
void relay_toggle(int gpio_pin);
void log_error(const char *message);
void signal_handler(int signal);

// Structure for MPR121 configuration
typedef struct {
    uint8_t electrode_config;
    uint8_t touch_threshold;
    uint8_t release_threshold;
} mpr121_config_t;

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        log_error("Failed to set MPR121 to stop mode.");
        return -1;
    }

    // Configure electrode 0 for touch sensing
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) {
        log_error("Failed to configure electrode 0.");
        return -1;
    }

    // Configure touch and release thresholds for all electrodes
    if (i2cWriteByteData(i2c_handle, 0x41, 0x0F) < 0) {
        log_error("Failed to set touch threshold.");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, 0x0A) < 0) {
        log_error("Failed to set release threshold.");
        return -1;
    }

    // Start the MPR121 in run mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        log_error("Failed to set MPR121 to run mode.");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int i2c_handle) {
    int touch_status = i2cReadByteData(i2c_handle, 0x00);
    if (touch_status < 0) {
        log_error("Failed to read touch status.");
        return -1;
    }
    return touch_status;
}

// Function to toggle the relay
void relay_toggle(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
}

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize to LOW

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        log_error("MPR121 initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int last_touch_state = 0; // 0: not touched, 1: touched
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            log_error("Failed to read touch status in main loop.");
            break;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            if (last_touch_state == 0) {
                relay_toggle(GPIO_RELAY);
                last_touch_state = 1;
                gpioDelay(TOGGLE_DELAY_MS * 1000); // Delay for 50ms
            }
        } else {
            last_touch_state = 0;
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

