#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Global variables
FILE *log_file = NULL;
int flame_detected = 0;

// Function prototypes
int read_flame_sensor();
void log_flame_detection();
void activate_buzzer_and_led();
void deactivate_buzzer_and_led();
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log flame detection to a file
void log_flame_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Flame Detected\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer and LED
void activate_buzzer_and_led() {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error writing to buzzer pin.\n");
    }
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error writing to LED pin.\n");
    }
}

// Function to deactivate the buzzer and LED
void deactivate_buzzer_and_led() {
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error writing to buzzer pin.\n");
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error writing to LED pin.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate buzzer and LED
    deactivate_buzzer_and_led();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flame_count = 0;
    int last_flame_state = 1; // Assume no flame initially

    // Main loop
    while (1) {
        int flame_state = read_flame_sensor();
        if (flame_state < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
