#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense interval (in milliseconds)
#define DISPENSE_INTERVAL_MS 1000

// Define dispense durations (in milliseconds)
#define SOLENOID_1_DURATION_MS 500
#define SOLENOID_2_DURATION_MS 500

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense_cycle(int solenoid_pin1, int solenoid_pin2, int duration1_ms, int duration2_ms);
int log_dispense_event(int solenoid_pin1, int solenoid_pin2, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0; // Set the flag to exit the main loop

        // Deactivate both solenoids
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);

        // Terminate the pigpio library
        gpioTerminate();

        // Exit the program
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to perform a single dispense cycle
int dispense_cycle(int solenoid_pin1, int solenoid_pin2, int duration1_ms, int duration2_ms) {
    // Activate solenoid 1
    gpioWrite(solenoid_pin1, 1);
    gpioDelay(duration1_ms * 1000); // Convert ms to microseconds

    // Deactivate solenoid 1
    gpioWrite(solenoid_pin1, 0);

    // Activate solenoid 2
    gpioWrite(solenoid_pin2, 1);
    gpioDelay(duration2_ms * 1000); // Convert ms to microseconds

    // Deactivate solenoid 2
    gpioWrite(solenoid_pin2, 0);

    return 0;
}

// Function to log dispense events to a file
int log_dispense_event(int solenoid_pin1, int solenoid_pin2, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt for writing\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Solenoid 1: GPIO%d, Solenoid 2: GPIO%d, Duration: %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            solenoid_pin1, solenoid_pin2, duration_ms);

    fclose(fp);
    return 0; // Indicate success
}

