    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Perform the dispense cycle
        if (dispense_cycle(SOLENOID_1_PIN, SOLENOID_2_PIN, SOLENOID_1_DURATION_MS, SOLENOID_2_DURATION_MS) != 0) {
            fprintf(stderr, "Error during dispense cycle\n");
        }

        // Log the dispense event
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_INTERVAL_MS) != 0) {
            fprintf(stderr, "Error logging dispense event\n");
        }

        // Wait for the next dispense interval
        gpioDelay(DISPENSE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // This point is reached only when program_running is set to 0 by the signal handler
    gpioTerminate(); // Terminate pigpio
    return 0;
}

