#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Motor GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA_PIN 24
#define ENB_PIN 25

// PID gains
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// Log file name
#define LOG_FILE "balance_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void signal_handler(int signal);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
float generate_tilt_error();
float generate_distance();
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void stop_motors();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, stopping motors and exiting.\n");
        running = 0;
        stop_motors();
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Logs data to the log file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Generates a random tilt error between -10.0 and 10.0
float generate_tilt_error() {
    return (float)(rand() % 21 - 10) / 10.0;
}

// Generates a random distance between 2.0 and 400.0
float generate_distance() {
    return (float)(rand() % 399 + 2) / 100.0;
}

// Sets the motor speeds using PWM
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Clamp motor speeds to ±255
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA_PIN, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENA_PIN, -motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA_PIN, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB_PIN, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENB_PIN, -motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB_PIN, 0);
    }
}

// Stops both motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENA_PIN, 0);
    gpioPWM(ENB_PIN, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA_PIN, PI_OUTPUT);
    gpioSetMode(ENB_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(ENA_PIN, 255);
    gpioSetPWMrange(ENB_PIN, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Generate sensor data
        float tilt_error = generate_tilt_error();
        float distance = generate_distance();

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            // Reverse both motors at 50% speed
            int motor_a_speed = -127; // 50% of 255
            int motor_b_speed = -127;
            set_motor_speed(motor_a_speed, motor_b_speed);
        } else {
            // Calculate PID output
            float error = tilt_error;
            float integral = 0.0;
            float derivative = 0.0;
            float last_error = 0.0;

            // Calculate integral term
            integral += error;

            // Calculate derivative term
            derivative = error - last_error;

            // Calculate PID output
            float output = KP * error + KI * integral + KD * derivative;

            // Calculate motor speeds
            int motor_a_speed = (int)output;
            int motor_b_speed = (int)output;

            // Set motor speeds
            set_motor_speed(motor_a_speed, motor_b_speed);
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Stop motors and close log file before exiting
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

