    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Generate sensor data
        float tilt_error = generate_tilt_error();
        float distance = generate_distance();

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            // Reverse both motors at 50% speed
            int motor_a_speed = -127; // 50% of 255
            int motor_b_speed = -127;
            set_motor_speed(motor_a_speed, motor_b_speed);
        } else {
            // Calculate PID output
            float error = tilt_error;
            float integral = 0.0;
            float derivative = 0.0;
            float last_error = 0.0;

            // Calculate integral term
            integral += error;

            // Calculate derivative term
            derivative = error - last_error;

            // Calculate PID output
            float output = KP * error + KI * integral + KD * derivative;

            // Calculate motor speeds
            int motor_a_speed = (int)output;
            int motor_b_speed = (int)output;

            // Set motor speeds
            set_motor_speed(motor_a_speed, motor_b_speed);
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Stop motors and close log file before exiting
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

