#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_relay(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set touch sensor pin as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN as input\n");
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on TOUCH_SENSOR_PIN\n");
        return 1;
    }

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        return 1;
    }

    return 0; // Indicate success
}

// Read the touch sensor state
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to read TOUCH_SENSOR_PIN\n");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Control the relay state
void control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
    }
    relay_state = state; // Update global relay state
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_touch_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            cleanup_gpio();
            return 1;
        }

        if (sensor_value == 1) {
            // Touch detected, toggle relay state
            control_relay(!relay_state);
            printf("Touch detected, relay toggled to %d\n", relay_state);

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to us
        }

        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    return 0; // This line will not be reached due to the infinite loop
}

