#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Configuration
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_CHANNELS 1
#define DEFAULT_FORMAT SND_PCM_FORMAT_S16_LE
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0
#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // PWM range for pigpio
#define ALSA_DEVICE "default"

// Global variables (minimize usage)
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static double sensitivity = DEFAULT_SENSITIVITY;

// Structure to hold ALSA configuration
typedef struct {
    unsigned int sample_rate;
    unsigned int channels;
    snd_pcm_format_t format;
    unsigned int period_size;
} alsa_config_t;

// Structure to hold LED configuration
typedef struct {
    int red_gpio;
    int green_gpio;
    int blue_gpio;
} led_config_t;

// Function prototypes
int init_alsa(alsa_config_t *config);
int init_led(led_config_t *led_config);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames);
double calculate_rms(const short *buffer, int frames);
void map_amplitude_to_color(double amplitude, double *red, double *green, double *blue);
void set_led_color(int red_gpio, int green_gpio, int blue_gpio, double red_value, double green_value, double blue_value);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

// Initialize ALSA
int init_alsa(alsa_config_t *config) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, config->format)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, config->channels)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = config->sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Initialize LED
int init_led(led_config_t *led_config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(led_config->red_gpio, PI_OUTPUT);
    gpioSetMode(led_config->green_gpio, PI_OUTPUT);
    gpioSetMode(led_config->blue_gpio, PI_OUTPUT);

    return 0;
}

// Capture audio
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / frames);
}

// Map amplitude to color
void map_amplitude_to_color(double amplitude, double *red, double *green, double *blue) {
    // Non-linear mapping (e.g., logarithmic)
    double scaled_amplitude = amplitude / 32768.0; // Normalize to 0-1 range
    *red = 1.0 - exp(-scaled_amplitude * 5.0); // Example mapping
    *green = exp(-scaled_amplitude * 3.0);
    *blue = exp(-scaled_amplitude * 2.0);

    // Clamp values to 0-1 range
    if (*red < 0.0) *red = 0.0;
    if (*red > 1.0) *red = 1.0;
    if (*green < 0.0) *green = 0.0;
    if (*green > 1.0) *green = 1.0;
    if (*blue < 0.0) *blue = 0.0;
    if (*blue > 1.0) *blue = 1.0;
}

// Set LED color using PWM
void set_led_color(int red_gpio, int green_gpio, int blue_gpio, double red_value, double green_value, double blue_value) {
    int red_pwm = (int)(red_value * PWM_RANGE);
    int green_pwm = (int)(green_value * PWM_RANGE);
    int blue_pwm = (int)(blue_value * PWM_RANGE);

    gpioPWM(red_gpio, red_pwm);
    gpioPWM(green_gpio, green_pwm);
    gpioPWM(blue_gpio, blue_pwm);
}

int main(int argc, char *argv[]) {
    alsa_config_t alsa_config = {
        .sample_rate = DEFAULT_SAMPLE_RATE,
        .channels = DEFAULT_CHANNELS,
        .format = DEFAULT_FORMAT,
        .period_size = DEFAULT_PERIOD_SIZE
    };
    led_config_t led_config = {
        .red_gpio = RED_GPIO,
        .green_gpio = GREEN_GPIO,
        .blue_gpio = BLUE_GPIO
    };
    short *audio_buffer = NULL;
    int buffer_frames = DEFAULT_PERIOD_SIZE;
    struct timeval tv;
    long usecs;
    double rms_amplitude;
    double red, green, blue;
    int err;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtod(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0.0) {
            fprintf(stderr, "Invalid sensitivity argument. Using default value.\n");
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize ALSA
    if (init_alsa(&alsa_config) != 0) {
        fprintf(stderr, "ALSA initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize LED
    if (init_led(&led_config) != 0) {
        fprintf(stderr, "LED initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Allocate audio buffer
    audio_buffer = (short *)malloc(buffer_frames * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Capture audio
        if (capture_audio(pcm_handle, audio_buffer, buffer_frames) != 0) {
            fprintf(stderr, "Audio capture failed. Re-initializing ALSA.\n");
            snd_pcm_prepare(pcm_handle);
            continue;
        }

        // Calculate RMS amplitude
        rms_amplitude = calculate_rms(audio_buffer, buffer_frames);

        // Map amplitude to color
        map_amplitude_to_color(rms_amplitude, &red, &green, &blue);

        // Set LED color
        set_led_color(led_config.red_gpio, led_config.green_gpio, led_config.blue_gpio, red, green, blue);

        // Wait for 10ms
        gettimeofday(&tv, NULL);
        usecs = (tv.tv_sec * 1000000) + (tv.tv_usec);
        usleep(10000); // 10ms

        // Check for suspended state (ESTRPIPE)
        if (snd_pcm_status(pcm_handle) == SND_PCM_STATUS_XRUN) {
            fprintf(stderr, "Suspended state detected. Resuming.\n");
            snd_pcm_prepare(pcm_handle);
        }
    }

    // Cleanup
    free(audio_buffer);
    cleanup();

    return 0;
}

