    audio_buffer = (short *)malloc(buffer_frames * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Capture audio
        if (capture_audio(pcm_handle, audio_buffer, buffer_frames) != 0) {
            fprintf(stderr, "Audio capture failed. Re-initializing ALSA.\n");
            snd_pcm_prepare(pcm_handle);
            continue;
        }

        // Calculate RMS amplitude
        rms_amplitude = calculate_rms(audio_buffer, buffer_frames);

        // Map amplitude to color
        map_amplitude_to_color(rms_amplitude, &red, &green, &blue);

        // Set LED color
        set_led_color(led_config.red_gpio, led_config.green_gpio, led_config.blue_gpio, red, green, blue);

        // Wait for 10ms
        gettimeofday(&tv, NULL);
        usecs = (tv.tv_sec * 1000000) + (tv.tv_usec);
        usleep(10000); // 10ms

        // Check for suspended state (ESTRPIPE)
        if (snd_pcm_status(pcm_handle) == SND_PCM_STATUS_XRUN) {
            fprintf(stderr, "Suspended state detected. Resuming.\n");
            snd_pcm_prepare(pcm_handle);
        }
    }

    // Cleanup
    free(audio_buffer);
    cleanup();

    return 0;
}

