#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD9) < 0) { // 154ms integration time
        fprintf(stderr, "Error writing to TCS34725_ATIME\n");
        return -1;
    }

    // Set gain (AGAIN) - default is 4x
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error writing to TCS34725_CONTROL\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;

    result = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading CDATA\n");
        *clear = 0;
    } else {
        *clear = (uint16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading RDATA\n");
        *red = 0;
    } else {
        *red = (uint16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading GDATA\n");
        *green = 0;
    } else {
        *green = (uint16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading BDATA\n");
        *blue = 0;
    } else {
        *blue = (uint16_t)result;
    }

    return 0;
}

// Function to log data to a CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t clear, red, green, blue;
    while (!terminate) {
        // Read color data
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            // Log data
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading color data, logging zeros\n");
            log_data(0, 0, 0, 0);
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

