#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 3600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 86400

// Global variable to track the current phase
static int current_phase = 0;

// Function prototypes
void signal_handler(int signal);
void sunrise_phase();
void daytime_phase();
void sunset_phase();
void nighttime_phase();
void set_relay_duty_cycle(int relay_pin, int duty_cycle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Sunrise phase function
void sunrise_phase() {
    printf("Sunrise phase starting...\n");
    for (int i = 0; i <= 100; i += 10) {
        set_relay_duty_cycle(RELAY1_PIN, i);
        set_relay_duty_cycle(RELAY2_PIN, i);
        set_relay_duty_cycle(RELAY3_PIN, i);
        set_relay_duty_cycle(RELAY4_PIN, i);
        gpioDelay(SUNRISE_DURATION / 10); // Delay for 360 seconds
    }
    current_phase = 1; // Update current phase to Daytime
}

// Daytime phase function
void daytime_phase() {
    printf("Daytime phase starting...\n");
    for (int i = 0; i <= 100; i += 10) {
        set_relay_duty_cycle(RELAY1_PIN, 100 - i);
        set_relay_duty_cycle(RELAY2_PIN, 100 - i);
        set_relay_duty_cycle(RELAY3_PIN, 100 - i);
        set_relay_duty_cycle(RELAY4_PIN, 100 - i);
        gpioDelay(DAYTIME_DURATION / 10); // Delay for 360 seconds
    }
    current_phase = 2; // Update current phase to Sunset
}

// Sunset phase function
void sunset_phase() {
    printf("Sunset phase starting...\n");
    for (int i = 100; i >= 0; i -= 10) {
        set_relay_duty_cycle(RELAY1_PIN, i);
        set_relay_duty_cycle(RELAY2_PIN, i);
        set_relay_duty_cycle(RELAY3_PIN, i);
        set_relay_duty_cycle(RELAY4_PIN, i);
        gpioDelay(SUNSET_DURATION / 10); // Delay for 360 seconds
    }
    current_phase = 3; // Update current phase to Nighttime
}

// Nighttime phase function
void nighttime_phase() {
    printf("Nighttime phase starting...\n");
    for (int i = 0; i <= 100; i += 10) {
        set_relay_duty_cycle(RELAY1_PIN, 100 - i);
        set_relay_duty_cycle(RELAY2_PIN, 100 - i);
        set_relay_duty_cycle(RELAY3_PIN, 100 - i);
        set_relay_duty_cycle(RELAY4_PIN, 100 - i);
        gpioDelay(NIGHTTIME_DURATION / 10); // Delay for 8640 seconds
    }
    current_phase = 0; // Update current phase to Sunrise
}

// Function to set the duty cycle of a relay using PWM
void set_relay_duty_cycle(int relay_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Duty cycle must be between 0 and 100\n");
        gpioTerminate();
        exit(1);
    }

    // Calculate the on and off times for the PWM signal
    int on_time = (int)((float)duty_cycle / 100.0 * 1000000.0); // Convert percentage to microseconds
    int off_time = 1000000 - on_time; // Calculate off time

    // Set the PWM frequency to 1 kHz
    gpioSetPWMfrequency(relay_pin, 1000);

    // Set the PWM range (maximum duty cycle value)
    gpioSetPWMrange(relay_pin, 1000000); // Set range to 1000000 for microsecond precision

    // Set the PWM duty cycle (on time)
    gpioPWM(relay_pin, on_time);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        switch (current_phase) {
            case 0:
                sunrise_phase();
                break;
            case 1:
                daytime_phase();
                break;
            case 2:
                sunset_phase();
                break;
            case 3:
                nighttime_phase();
                break;
        }
    }

    return 0;
}

