#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to generate a filename based on the current timestamp
char* generate_filename() {
    char *filename = (char*)malloc(30 * sizeof(char));
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        return NULL;
    }
    sprintf(filename, "%s%s.h264", VIDEO_DIR, timestamp);
    free(timestamp);
    return filename;
}

// Function to capture video using raspivid
int capture_video(const char* filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_SEC * 1000); // Convert seconds to milliseconds
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid");
        return -1;
    }
    return 0;
}

// Function to log the motion event to a file
int log_motion(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        // Check for motion (LOW signal)
        if (sensor_value == 0) {
