static volatile unsigned long last_trigger_time = 0;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to generate a filename based on the current timestamp
char* generate_filename() {
    char *filename = (char*)malloc(30 * sizeof(char));
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        return NULL;
    }
    sprintf(filename, "%s%s.h264", VIDEO_DIR, timestamp);
    free(timestamp);
    return filename;
}

// Function to capture video using raspivid
int capture_video(const char* filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_SEC * 1000); // Convert seconds to milliseconds
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid");
        return -1;
    }
    return 0;
