#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor (±250°/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *deg_per_sec_x, float *deg_per_sec_y, float *deg_per_sec_z);
int log_data(long long timestamp, float deg_per_sec_x, float deg_per_sec_y, float deg_per_sec_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (set sleep bit to 0)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyro data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Process raw gyroscope data
void process_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *deg_per_sec_x, float *deg_per_sec_y, float *deg_per_sec_z) {
    *deg_per_sec_x = (float)gyro_x / GYRO_SCALE;
    *deg_per_sec_y = (float)gyro_y / GYRO_SCALE;
    *deg_per_sec_z = (float)gyro_z / GYRO_SCALE;
}

// Log data to file
int log_data(long long timestamp, float deg_per_sec_x, float deg_per_sec_y, float deg_per_sec_z) {
    if (fprintf(log_file, "%lld,%.6f,%.6f,%.6f\n", timestamp, deg_per_sec_x, deg_per_sec_y, deg_per_sec_z) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t gyro_x, gyro_y, gyro_z;
    float deg_per_sec_x, deg_per_sec_y, deg_per_sec_z;
    struct timespec ts;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process gyroscope data
            process_gyro_data(gyro_x, gyro_y, gyro_z, &deg_per_sec_x, &deg_per_sec_y, &deg_per_sec_z);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                long long timestamp = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

                // Log data
                if (log_data(timestamp, deg_per_sec_x, deg_per_sec_y, deg_per_sec_z) != 0) {
                    fprintf(stderr, "Error: Failed to log data, but continuing...\n");
                }
            } else {
                fprintf(stderr, "Error: Could not get timestamp\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data, but continuing...\n");
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

