#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define ZONE1_PIN 4
#define ZONE2_PIN 17
#define ZONE3_PIN 27
#define ZONE4_PIN 22

// Define moisture thresholds
#define DRY_THRESHOLD 30
#define WET_THRESHOLD 60

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int zone, int state);
void log_data(int moisture, int zone1_state, int zone2_state, int zone3_state, int zone4_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Deactivate all relays
    control_relay(1, 1);
    control_relay(2, 1);
    control_relay(3, 1);
    control_relay(4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(ZONE1_PIN, PI_OUTPUT);
    gpioSetMode(ZONE2_PIN, PI_OUTPUT);
    gpioSetMode(ZONE3_PIN, PI_OUTPUT);
    gpioSetMode(ZONE4_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read the simulated moisture sensor
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random moisture level between 0 and 100
    int moisture = rand() % 101;

    return moisture;
}

// Control the relay state
void control_relay(int zone, int state) {
    int pin;

    switch (zone) {
        case 1:
            pin = ZONE1_PIN;
            break;
        case 2:
            pin = ZONE2_PIN;
            break;
        case 3:
            pin = ZONE3_PIN;
            break;
        case 4:
            pin = ZONE4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return;
    }

    gpioWrite(pin, state); // Active-low relays
}

// Log data to file
void log_data(int moisture, int zone1_state, int zone2_state, int zone3_state, int zone4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Zone 1: %s, Zone 2: %s, Zone 3: %s, Zone 4: %s\n",
            timestamp, moisture, zone1_state ? "ON" : "OFF", zone2_state ? "ON" : "OFF",
            zone3_state ? "ON" : "OFF", zone4_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System\n");

    // Main loop
    while (program_running) {
        // Read moisture sensor
        int moisture = read_moisture_sensor();

        // Control relays based on moisture level
        int zone1_state = (moisture < DRY_THRESHOLD) ? 0 : 1;
        int zone2_state = (moisture < DRY_THRESHOLD) ? 0 : 1;
        int zone3_state = (moisture < DRY_THRESHOLD) ? 0 : 1;
        int zone4_state = (moisture < DRY_THRESHOLD) ? 0 : 1;

        // Activate relays if moisture is below threshold
        control_relay(1, zone1_state);
        control_relay(2, zone2_state);
        control_relay(3, zone3_state);
        control_relay(4, zone4_state);

        // Log data
        log_data(moisture, zone1_state, zone2_state, zone3_state, zone4_state);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // This point is reached only when program_running is set to 0 by the signal handler
    fclose(log_file);
    gpioTerminate();

    return 0;
}

