#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <math.h>

// Constants
#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_RANGE_CM 400.0 // 4 meters
#define TIMEOUT_MS 100
#define MAX_PULSE_WIDTH_US 23200 // 23.2 ms
#define LOG_FILE "distance_log.txt"
#define MAX_TICKS 2147483647 // Maximum value for 32-bit integer

// Global variables
volatile unsigned long last_tick = 0;
volatile unsigned long pulse_width = 0;
volatile int timeout_flag = 0;
int i2c_fd;
FILE *log_file = NULL;
pthread_mutex_t log_mutex;

// Function prototypes
void trigger_sensor();
void echo_rising_edge();
void echo_falling_edge();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    pinMode(TRIG_PIN, OUTPUT);
    pinMode(ECHO_PIN, INPUT);

    // Initialize I2C for BME280
    i2c_fd = wiringPiI2CSetup(0x76); // BME280 I2C address
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&log_mutex, NULL) != 0) {
        fprintf(stderr, "Error initializing mutex: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    digitalWrite(TRIG_PIN, HIGH);
    delayMicroseconds(10);
    digitalWrite(TRIG_PIN, LOW);
}

// Interrupt handler for rising edge of echo pulse
void echo_rising_edge() {
    unsigned long current_tick = micros();
    if (current_tick > last_tick) {
        pulse_width = current_tick - last_tick;
        last_tick = current_tick;
    }
}

// Interrupt handler for falling edge of echo pulse
void echo_falling_edge() {
    unsigned long current_tick = micros();
    if (current_tick > last_tick) {
        pulse_width = current_tick - last_tick;
        last_tick = current_tick;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to cleanup resources
void cleanup() {
    // Disable interrupts
    wiringPiISR(ECHO_PIN, INT_EDGE_RISING, NULL);
    wiringPiISR(ECHO_PIN, INT_EDGE_FALLING, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&log_mutex);

    // Terminate wiringPi
    wiringPiSetup(); // Reinitialize to disable interrupts

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Ultrasonic sensor and BME280 logger started. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_sensor();

        // Wait for echo or timeout
        timeout_flag = 0; // Reset timeout flag
        unsigned long start_time = micros();
        while (micros() - start_time < TIMEOUT_MS && !timeout_flag) {
            if (pulse_width > MAX_PULSE_WIDTH_US) {
                timeout_flag = 1;
                break;
            }
            delayMicroseconds(1); // Small delay to avoid busy-waiting
        }

        if (timeout_flag) {
            fprintf(stderr, "Timeout error: No echo received within %d ms\n", TIMEOUT_MS);
            flock(fileno(log_file), LOCK_UN); // Release lock if held
            fprintf(log_file, "Timeout error: No echo received within %d ms\n", TIMEOUT_MS);
            fflush(log_file);
            flock(fileno(log_file), LOCK_NB); // Reacquire lock
            continue; // Skip to the next iteration
        }

        // Validate pulse width
        if (pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width);
            flock(fileno(log_file), LOCK_UN); // Release lock if held
            fprintf(log_file, "Invalid pulse width: %d us\n", pulse_width);
            fflush(log_file);
            flock(fileno(log_file), LOCK_NB); // Reacquire lock
            continue; // Skip to the next iteration
        }

        // Calculate distance in centimeters
        float distance_cm = (pulse_width / 2.0) * 0.0343;

        // Get timestamp with nanosecond precision
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        unsigned long timestamp_ns = (unsigned long)ts.tv_sec * 1000000000 + ts.tv_nsec;

        // Log data to file
        pthread_mutex_lock(&log_mutex);
        fprintf(log_file, "%lu,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file);
        pthread_mutex_unlock(&log_mutex);

        printf("Timestamp: %lu ns, Distance: %.2f cm\n", timestamp_ns, distance_cm);

        // Wait 200 ms before next trigger
        delay(200);
    }

    return 0;
}

