#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Number of steps per revolution for 28BYJ-48 (64 gear ratio)
#define STEPS_PER_REVOLUTION 2048

// Steps per side of the square
#define SIDE_STEPS 100

// Delay between steps (in microseconds)
#define STEP_DELAY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Stopping motors and cleaning up...\n");
        program_running = 0;
    }
}

// Function to set the GPIO pins for a specific step
void set_motor_pins(int motor, int step) {
    int in1, in2, in3, in4;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    switch (step) {
        case 0:
            gpioWrite(in1, 1);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 1:
            gpioWrite(in1, 0);
            gpioWrite(in2, 1);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 2:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 1);
            gpioWrite(in4, 0);
            break;
        case 3:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 1);
            break;
        default:
            fprintf(stderr, "Error: Invalid step number: %d\n", step);
            break;
    }
}

// Function to move a motor a specified number of steps
void move_motor(int motor, int steps, int direction) {
    int step_sequence[4] = {0, 1, 2, 3};
    int i;

    if (direction == 1) { // Clockwise
        for (i = 0; i < steps && program_running; i++) {
            set_motor_pins(motor, step_sequence[i % 4]);
            gpioDelay(STEP_DELAY);
        }
    } else if (direction == -1) { // Counter-clockwise
        for (i = 0; i < steps && program_running; i++) {
            set_motor_pins(motor, step_sequence[(3 - (i % 4)) % 4]);
            gpioDelay(STEP_DELAY);
        }
    } else {
        fprintf(stderr, "Error: Invalid direction: %d\n", direction);
    }
}

// Function to move both motors to a specific position
void move_to_position(int x_steps, int y_steps) {
    move_motor(1, abs(x_steps), (x_steps > 0) ? 1 : -1);
    move_motor(2, abs(y_steps), (y_steps > 0) ? 1 : -1);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    int pins[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4, MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Move to the starting position (0,0)
    move_to_position(0, 0);

    // Main loop: Move in a square pattern
    while (program_running) {
        move_to_position(SIDE_STEPS, 0);
        move_to_position(0, SIDE_STEPS);
        move_to_position(-SIDE_STEPS, 0);
        move_to_position(0, -SIDE_STEPS);
    }

    // Stop motors and release resources before exiting
    set_motor_pins(1, 0); // Stop Motor 1
    set_motor_pins(2, 0); // Stop Motor 2
    gpioDelay(1000); // Allow time for motors to stop

    // Set all GPIO pins low
    int pins_to_low[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4, MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < sizeof(pins_to_low) / sizeof(pins_to_low[0]); i++) {
        gpioWrite(pins_to_low[i], 0);
    }

    gpioTerminate();
    printf("Program terminated successfully.\n");
    return 0;
}

