#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer structure
typedef struct {
    SensorReadings buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer sensor_buffer;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void add_to_buffer(CircularBuffer *cb, SensorReadings data);
SensorReadings get_latest_reading(CircularBuffer *cb);
int check_line_status(CircularBuffer *cb);
void control_robot(int line_status);
void activate_alert();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to add data to the circular buffer
void add_to_buffer(CircularBuffer *cb, SensorReadings data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to get the latest reading from the circular buffer
SensorReadings get_latest_reading(CircularBuffer *cb) {
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[index];
}

// Function to check line status
int check_line_status(CircularBuffer *cb) {
    SensorReadings latest = get_latest_reading(cb);
    if (latest.center == 0) {
        return 0; // Line detected
    } else if (latest.center == 1) {
        return 1; // No line detected
    } else {
        fprintf(stderr, "Invalid sensor reading: center=%d\n", latest.center);
        return -1; // Error
    }
}

// Function to control the robot
void control_robot(int line_status) {
    if (line_status == 0) {
        // Move forward
        printf("Moving forward\n");
    } else if (line_status == 1) {
        // Turn left
        printf("Turning left\n");
    } else if (line_status == 2) {
        // Turn right
        printf("Turning right\n");
    } else {
        // Stop
        printf("Stopping\n");
    }
}

// Function to activate the alert
void activate_alert() {
    gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
    printf("Alert activated for 2 seconds\n");
    gpioDelay(2000);          // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
    printf("Alert deactivated\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize circular buffer
    sensor_buffer.head = 0;
    sensor_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Autonomous line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Check for errors during sensor reading
        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        // Add sensor readings to the circular buffer
        SensorReadings readings = {left_value, center_value, right_value};
        add_to_buffer(&sensor_buffer, readings);

        // Check line status
        int line_status = check_line_status(&sensor_buffer);

        // Control the robot based on line status
        if (line_status == 0) {
            control_robot(line_status);
        } else if (line_status == 1) {
            // Check if center sensor has been no-line for 5 consecutive readings
            if (sensor_buffer.count == 5) {
                if (get_latest_reading(&sensor_buffer).center == 1) {
                    activate_alert();
                }
            }
        } else if (line_status == 2) {
            control_robot(line_status);
        } else {
            control_robot(line_status);
        }

        // Delay for 10 ms
        gpioDelay(10);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

