#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define MAGNETIC_THRESHOLD 5.0 // mT
#define POLL_ATTEMPTS 50
#define POLL_DELAY_MS 100
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *field_strength);
int control_relay(int state);
int log_event(const char *event_type, float field_strength, int relay_state);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float field_strength;
    int relay_state;
} sensor_data_t;

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the magnetic field data from the Si7210
int read_magnetic_field(float *field_strength) {
    char buf[2];
    int result;
    int attempts = 0;

    while (attempts < POLL_ATTEMPTS) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            short raw_value = (buf[0] << 8) | buf[1];

            // Convert the raw value to milliTesla (mT).  Adjust the scaling factor as needed.
            *field_strength = (float)raw_value * 0.1; // Example scaling factor
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempts + 1, result);
            attempts++;
            gpioDelay(POLL_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Timeout: Failed to read magnetic field after %d attempts.\n", POLL_ATTEMPTS);
    return -1; // Failure
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, float field_strength, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s - %s - Field: %.2f mT, Relay: %s\n", timestamp, event_type, field_strength, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    float field_strength;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int previous_relay_state = -1; // Initialize to an invalid state

    // Main loop
    while (!terminate) {
        // Read magnetic field
        if (read_magnetic_field(&field_strength) == 0) {
            // Control relay based on threshold
            if (field_strength > MAGNETIC_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn relay ON
                relay_state = 1;
                log_event("THRESHOLD_TRIGGERED", field_strength, relay_state);
            } else if (field_strength <= MAGNETIC_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn relay OFF
                relay_state = 0;
                log_event("THRESHOLD_CLEARED", field_strength, relay_state);
            }

            // Log the current state
            log_event("READING", field_strength, relay_state);
        } else {
            fprintf(stderr, "Failed to read magnetic field. Deactivating relay.\n");
            control_relay(0); // Deactivate relay on error
            log_event("ERROR", 0.0, relay_state);
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is OFF
    gpioTerminate();

    return 0;
}

