#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define CLOSE_TIME 5000 // 5 seconds
#define DEBOUNCE_DELAY 600 // 600 ms
#define POLL_INTERVAL 200 // 200 ms

// Global variables
volatile sig_atomic_t program_running = 1;
int debounce_counter = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void start_motor_close();
void stop_motor();
void handle_signal(int signal);
void log_event(int priority, const char *message);

