void handle_signal(int signal) {
    program_running = 0;
    log_event(LOG_INFO, "Received signal, shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    log_event(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_event(LOG_ERR, "Failed to read rain sensor");
        return -1;
    }
    return sensor_value;
}

// Start motor to close window
void start_motor_close() {
    gpioWrite(MOTOR_ENA_PIN, 1);
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    log_event(LOG_INFO, "Motor started to close window");
}

// Stop motor
void stop_motor() {
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    log_event(LOG_INFO, "Motor stopped");
}

// Log events to syslog
void log_event(int priority, const char *message) {
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event(LOG_INFO, "Program started");

    // Main loop
    while (program_running) {
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) {
            // Error already logged in read_rain_sensor()
            usleep(POLL_INTERVAL * 1000); // Sleep for poll interval
            continue;
        }

        if (sensor_value == 0) { // Rain detected (DO is low)
            debounce_counter++;
            if (debounce_counter >= (DEBOUNCE_DELAY / POLL_INTERVAL)) {
                start_motor_close();
                usleep(CLOSE_TIME * 1000000); // Sleep for close time
                stop_motor();
                debounce_counter = 0; // Reset debounce counter
            }
        } else { // Dry
            debounce_counter = 0; // Reset debounce counter
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for poll interval
    }

    return 0;
}

