#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width values
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track servo state
static volatile int servo_state = 0; // 0: unlocked, 1: locked

// Function prototypes
int lock_door();
int unlock_door();
void shutdown_servo();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received shutdown signal. Shutting down servo.\n");
        shutdown_servo();
        exit(0);
    }
}

// Lock door function
int lock_door() {
    if (gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width for locking.\n");
        return -1;
    }
    servo_state = 1; // Update servo state to locked
    printf("Door locked.\n");
    return 0;
}

// Unlock door function
int unlock_door() {
    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width for unlocking.\n");
        return -1;
    }
    servo_state = 0; // Update servo state to unlocked
    printf("Door unlocked.\n");
    return 0;
}

// Shutdown servo function
void shutdown_servo() {
    gpioServo(SERVO_PIN, 0); // Set servo to 0 to stop it
    printf("Servo stopped.\n");
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == LOCK_BUTTON_PIN && level == 0) { // Button pressed (LOW)
        // Debounce delay
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to us

        if (gpioRead(LOCK_BUTTON_PIN) == 0) { // Button still pressed
            if (lock_door() != 0) {
                fprintf(stderr, "Error: Failed to lock door.\n");
            }
        }
    } else if (gpio == UNLOCK_BUTTON_PIN && level == 0) { // Button pressed (LOW)
        // Debounce delay
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to us

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) { // Button still pressed
            if (unlock_door() != 0) {
                fprintf(stderr, "Error: Failed to unlock door.\n");
            }
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo position (unlocked)
    gpioServo(SERVO_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handlers for button presses
    gpioSetAlertFuncEx(LOCK_BUTTON_PIN, button_callback, NULL);
    gpioSetAlertFuncEx(UNLOCK_BUTTON_PIN, button_callback, NULL);

    // Main loop
    while (1) {
        // Small delay to reduce CPU usage
        usleep(10000); // 10 ms
    }

    // The program should never reach here, but include cleanup code just in case
    gpioTerminate();
    return 0;
}

