#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_TIME 60 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_led(int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
        control_led(0); // Turn off LED
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Initialize GPIO using wiringPi
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(PIR_PIN, INPUT);
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Ensure LED is off initially

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return digitalRead(PIR_PIN);
}

// Control LED state
void control_led(int state) {
    digitalWrite(LED_PIN, state);
}

// Log events to file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", event_type, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened. Event: %s, Message: %s\n", event_type, message);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    int last_pir_state = 0; // Store the last PIR sensor state

    // Main loop
    while (program_running) {
        int pir_state = read_pir_sensor();

        if (pir_state == 1 && last_pir_state == 0) {
            // Motion detected
            printf("Motion detected!\n");
            log_event("Motion Detected", "Motion detected by PIR sensor.");
            control_led(1); // Turn on LED
            delay(LED_ON_TIME * 1000); // Keep LED on for 60 seconds
            control_led(0); // Turn off LED
            log_event("Motion Deactivated", "Motion deactivated. LED turned off.");
        }

        last_pir_state = pir_state;
        delay(POLLING_INTERVAL); // Poll every 100ms
    }

    // Ensure LED is off before exiting
    control_led(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

