#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// GPIO pin for the relay
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
int i2c_fd;
bool relay_state = false; // false = OFF, true = ON
bool running = true;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void relay_control(int state);
void signal_handler(int signal);

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_FFI_R 0x2F
#define MPR121_SFI_R 0x30
#define MPR121_CDT_R 0x31
#define MPR121_ECR_R 0x5E
#define MPR121_SOFT_RESET 0x80

// Function to write a register value to the MPR121
int mpr121_write_register(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a register value from the MPR121
int mpr121_read_register(int reg) {
    int value = wiringPiI2CReadReg8(i2c_fd, reg);
    if (value == -1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Soft Reset
    if (mpr121_write_register(MPR121_SOFT_RESET, 0x63) == -1) return -1;
    delay(100); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR)
    if (mpr121_write_register(MPR121_ECR, 0x0C) == -1) return -1; // Enable electrodes 0-11

    // Configure Baseline Filtering Registers
    if (mpr121_write_register(MPR121_MHD_R, 0x01) == -1) return -1;
    if (mpr121_write_register(MPR121_NHD_R, 0x01) == -1) return -1;
    if (mpr121_write_register(MPR121_NCL_R, 0x01) == -1) return -1;
    if (mpr121_write_register(MPR121_FDL_R, 0x01) == -1) return -1;

    // Configure FFI, SFI and CDT Registers
    if (mpr121_write_register(MPR121_FFI_R, 0x01) == -1) return -1;
    if (mpr121_write_register(MPR121_SFI_R, 0x01) == -1) return -1;
    if (mpr121_write_register(MPR121_CDT_R, 0x01) == -1) return -1;

    // Configure Debounce
    if (mpr121_write_register(MPR121_ECR, 0x01) == -1) return -1; // Enable electrode debounce

    // Enable Auto Configuration
    if (mpr121_write_register(MPR121_ECR, 0x10) == -1) return -1; // Enable auto config

    // Enable Electrode 0
    if (mpr121_write_register(MPR121_ECR, 0x01) == -1) return -1; // Enable electrode 0

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    int low = mpr121_read_register(MPR121_TOUCHSTATUS_L);
    int high = mpr121_read_register(MPR121_TOUCHSTATUS_H);

    if (low == -1 || high == -1) {
        return -1; // Indicate an error
    }

    *touch_status = (high << 8) | low;
    return 0;
}

// Function to control the relay
void relay_control(int state) {
    digitalWrite(RELAY_PIN, state);
    relay_state = state;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
    relay_control(LOW); // Turn off the relay
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error initializing MPR121.\n");
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    relay_control(LOW); // Ensure relay is initially OFF

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    int last_touch_state = 0; // 0 = not touched, 1 = touched
    time_t last_touch_time = 0;

    printf("MPR121 Relay Control Program\n");

    while (running) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status & (1 << 0)) { // Check if electrode 0 is touched
                time_t current_time = time(NULL);
                if (last_touch_state == 0) { // Only toggle if not already touched
                    relay_control(HIGH); // Turn on the relay
                    last_touch_state = 1;
                    last_touch_time = current_time;
                    printf("Relay ON\n");
                } else {
                    // Debounce check
                    if (difftime(current_time, last_touch_time) >= (double)DEBOUNCE_TIME / 1000.0) {
                        relay_control(HIGH); // Turn on the relay
                        last_touch_state = 1;
                        last_touch_time = current_time;
                        printf("Relay ON (debounced)\n");
                    }
                }
            } else {
                last_touch_state = 0; // Reset state if not touched
                relay_control(LOW); // Turn off the relay
                printf("Relay OFF\n");
            }
        } else {
            fprintf(stderr, "Error reading touch status.\n");
        }

        delay(50); // Small delay to avoid busy-waiting
    }

    return 0;
}

