#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <stdarg.h>

// Configuration
#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 2000000 // pigpio PWM range
#define LOG_FILE "security.log"

// Global variables
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_socket();
void handle_client(int client_socket);
int parse_command(char *command, int *angle);
int set_servo_angle(int angle);
int read_pir_sensor();
int log_event(const char *format, ...);
void signal_handler(int signum);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_event("GPIO initialization failed. Exiting.");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN); // Pull-down resistor

    return 0;
}

// Function to initialize the socket
int init_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_event("Socket creation failed");
        perror("socket failed");
        return -1;
    }

