#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <getopt.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_POLLING_DURATION 500

// Global variables
volatile sig_atomic_t program_running = 1;
double scale_factor = DEFAULT_SCALE_FACTOR;
int threshold = DEFAULT_THRESHOLD;
int polling_duration = DEFAULT_POLLING_DURATION;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double scale_factor);
int check_threshold(double weight, int threshold);
void activate_solenoid(int duration_ms);
int tare_load_cell(int num_readings);
void signal_handler(int signal);
void cleanup();

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Wait for DOUT to go LOW
    int timeout_counter = 0;
    while (gpioRead(HX711_DOUT) == 1 && timeout_counter < 1000) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= 1000) {
        syslog(LOG_ERR, "HX711 timeout error: DOUT did not go LOW within 1 second.");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse to select Channel A and gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight in grams
double calculate_weight(int raw_value, double scale_factor) {
    return (double)raw_value / scale_factor;
}

// Function to check if weight exceeds threshold
int check_threshold(double weight, int threshold) {
    return (weight > threshold) ? 1 : 0;
}

// Function to activate the solenoid lock
void activate_solenoid(int duration_ms) {
    gpioWrite(SOLENOID_PIN, 1); // Set HIGH
    gpioDelay(duration_ms);
    gpioWrite(SOLENOID_PIN, 0); // Set LOW
}

// Function to perform tare
int tare_load_cell(int num_readings) {
