#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_KEEPALIVE 60
#define GPIO_PIN 17
#define GPIO_INIT_DELAY 5

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to initialize the GPIO driver and configure the relay pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    syslog(LOG_INFO, "GPIO initialized and relay set to OFF");
    return 0;
}

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(GPIO_PIN, state);
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
}

// Function to handle MQTT messages
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            set_relay_state(1);
        } else if (strcmp(payload, "OFF") == 0) {
            set_relay_state(0);
        } else {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Function to handle MQTT connection events
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

// Function to handle MQTT disconnection events
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Function to handle MQTT error events
void on_error(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_ERR, "MQTT error: %s", mosquitto_strerror(rc));
}

// Function to handle MQTT loop events
void on_loop(struct mosquitto *mosq, void *userdata) {
    // This function is called by the mosquitto_loop function.
    // It's typically used for periodic tasks, but we don't need that here.
    // Just keep the loop running.
}

// Signal handler function
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, stopping...");
    running = 0;
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_error_callback_set(mosq, on_error);
    mosquitto_loop_callback_set(mosq, on_loop);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 for blocking, 1 for max 1 message processed
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Clean up
    syslog(LOG_INFO, "Disconnecting from MQTT broker");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    syslog(LOG_INFO, "Disconnecting from GPIO");
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    syslog(LOG_INFO, "Exiting");
    closelog();
    return 0;
}

