#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_GPIO 7
#define SERVO2_GPIO 8
#define SERVO3_GPIO 9
#define SERVO4_GPIO 10
#define SERVO5_GPIO 11

#define PWM_FREQUENCY 50
#define PWM_PERIOD 20000 // 20 ms

#define MIN_PULSE_WIDTH 500 // µs
#define MAX_PULSE_WIDTH 2500 // µs

#define TARGET_1 1000
#define TARGET_2 1500
#define TARGET_3 2000
#define TARGET_4 500
#define TARGET_5 2500

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

int set_servo_pulse_width(int gpio, int pulse_width_us) {
    if (pulse_width_us < MIN_PULSE_WIDTH || pulse_width_us > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Pulse width out of range: %d us\n", pulse_width_us);
        return 1; // Indicate failure
    }

    int dutycycle = (int)(((float)pulse_width_us / 1000.0) * PWM_PERIOD);
    gpioPWM(gpio, dutycycle);
    return 0; // Indicate success
}

int stop_servo(int gpio) {
    gpioPWM(gpio, 0); // Stop PWM signal
    return 0;
}

int cleanup_gpio() {
    gpioTerminate();
    return 0;
}

int main() {
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set GPIO modes to output
    gpioSetMode(SERVO1_GPIO, PI_OUTPUT);
    gpioSetMode(SERVO2_GPIO, PI_OUTPUT);
    gpioSetMode(SERVO3_GPIO, PI_OUTPUT);
    gpioSetMode(SERVO4_GPIO, PI_OUTPUT);
    gpioSetMode(SERVO5_GPIO, PI_OUTPUT);

    // Set PWM frequency and period
    gpioSetPWMfrequency(SERVO1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO1_GPIO, PWM_PERIOD); // Set range to PWM period
    gpioSetPWMrange(SERVO2_GPIO, PWM_PERIOD);
    gpioSetPWMrange(SERVO3_GPIO, PWM_PERIOD);
    gpioSetPWMrange(SERVO4_GPIO, PWM_PERIOD);
    gpioSetPWMrange(SERVO5_GPIO, PWM_PERIOD);

    // Set initial pulse widths (0)
    set_servo_pulse_width(SERVO1_GPIO, 0);
    set_servo_pulse_width(SERVO2_GPIO, 0);
    set_servo_pulse_width(SERVO3_GPIO, 0);
    set_servo_pulse_width(SERVO4_GPIO, 0);
    set_servo_pulse_width(SERVO5_GPIO, 0);

    // Move servos to target positions
    set_servo_pulse_width(SERVO1_GPIO, TARGET_1);
    set_servo_pulse_width(SERVO2_GPIO, TARGET_2);
    set_servo_pulse_width(SERVO3_GPIO, TARGET_3);
    set_servo_pulse_width(SERVO4_GPIO, TARGET_4);
    set_servo_pulse_width(SERVO5_GPIO, TARGET_5);

    sleep(3); // Hold for 3 seconds

    // Stop servos
    stop_servo(SERVO1_GPIO);
    stop_servo(SERVO2_GPIO);
    stop_servo(SERVO3_GPIO);
    stop_servo(SERVO4_GPIO);
    stop_servo(SERVO5_GPIO);

    if (cleanup_gpio() != 0) {
        return 1; // Exit if cleanup fails
    }

    return 0;
}

