#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PI Controller
#define KP 1.0
#define KI 0.01
#define TARGET_RPM 50.0

// Anti-windup
#define INTEGRATOR_MAX 100
#define INTEGRATOR_MIN -100

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
double integral_a = 0.0;
double integral_b = 0.0;
int running = 1;

// Function prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double pi_control(double error, double *integral);
void set_motor_speed(int motor, int pwm_duty_cycle);
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    encoder_a_ticks++;
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    encoder_b_ticks++;
}

// Calculate RPM from encoder ticks
double calculate_rpm(int ticks) {
    return (double)ticks / 64.0 * 60.0;
}

// PI control loop
double pi_control(double error, double *integral) {
    *integral += error;
    if (*integral > INTEGRATOR_MAX) *integral = INTEGRATOR_MAX;
    if (*integral < INTEGRATOR_MIN) *integral = INTEGRATOR_MIN;
    double output = KP * error + KI * (*integral);
    return output;
}

// Set motor speed using PWM
void set_motor_speed(int motor, int pwm_duty_cycle) {
    if (motor == 0) {
        gpioPWM(MOTOR_A_PWM, pwm_duty_cycle);
        gpioWrite(MOTOR_A_DIR, 1); // Forward
    } else if (motor == 1) {
        gpioPWM(MOTOR_B_PWM, pwm_duty_cycle);
        gpioWrite(MOTOR_B_DIR, 1); // Forward
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Stopping motors and cleaning up...\n");
    running = 0;
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, 10000); // 10 kHz
    gpioSetPWMfrequency(MOTOR_B_PWM, 10000); // 10 kHz

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Set ISRs
    gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    while (running) {
        // Read encoder ticks
        int current_a_ticks = encoder_a_ticks;
        int current_b_ticks = encoder_b_ticks;

        // Calculate RPM
        double rpm_a = calculate_rpm(current_a_ticks - encoder_a_ticks);
        double rpm_b = calculate_rpm(current_b_ticks - encoder_b_ticks);

        // Calculate error
        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        // PI control
        double control_a = pi_control(error_a, &integral_a);
        double control_b = pi_control(error_b, &integral_b);

        // Set motor speeds
        set_motor_speed(0, (int)control_a);
        set_motor_speed(1, (int)control_b);

        // Print RPM and PWM duty cycle
        printf("Motor A: RPM = %.2f, PWM = %d\n", rpm_a, (int)control_a);
        printf("Motor B: RPM = %.2f, PWM = %d\n", rpm_b, (int)control_b);

        // Stall detection
        if (current_a_ticks == 0) {
            time_t start_time = time(NULL);
            while (current_a_ticks == 0 && running) {
                time_t current_time = time(NULL);
                if ((current_time - start_time) > 2) {
                    fprintf(stderr, "WARNING: Motor A stalled for more than 2 seconds!\n");
                    running = 0; // Stop the motors
                }
                nanosleep(&sleep_time, NULL);
            }
        }
        if (current_b_ticks == 0) {
            time_t start_time = time(NULL);
            while (current_b_ticks == 0 && running) {
                time_t current_time = time(NULL);
                if ((current_time - start_time) > 2) {
                    fprintf(stderr, "WARNING: Motor B stalled for more than 2 seconds!\n");
                    running = 0; // Stop the motors
                }
                nanosleep(&sleep_time, NULL);
            }
        }

        // Reset tick counters
        encoder_a_ticks = current_a_ticks;
        encoder_b_ticks = current_b_ticks;

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
    gpioTerminate();

    return 0;
}

