#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS_DELAY 180 // milliseconds
#define POLLING_INTERVAL 5   // seconds
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_lux();
int control_relay(int state);
int log_data(int lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
int read_lux() {
    char config[1] = {0x10}; // Continuous high-resolution mode
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(200); // Wait for measurement (at least 180ms)

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (int)(raw_value / 1.2);
}

// Control relay state
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Log data to file
int log_data(int lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Turn off relay on exit
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for relay
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0; // 0 = OFF, 1 = ON
    int lux_value;
    int dusk_active = 0;
    int dawn_active = 0;

    printf("Chicken coop lighting system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        lux_value = read_lux();
        if (lux_value < 0) {
            fprintf(stderr, "Error reading lux value, turning off relay and logging error.\n");
            control_relay(0);
            log_data(-1, 0); // Log error
        } else {
            log_data(lux_value, relay_state);

            if (lux_value < LUX_THRESHOLD_DUSK && !dusk_active) {
                control_relay(1);
                relay_state = 1;
                dusk_active = 1;
                printf("Dusk mode activated (Lux: %d)\n", lux_value);
            } else if (lux_value > LUX_THRESHOLD_DAWN && dawn_active) {
                control_relay(0);
                relay_state = 0;
                dawn_active = 0;
                printf("Dawn mode deactivated (Lux: %d)\n", lux_value);
            }
        }

        gpioDelay(POLLING_INTERVAL * 1000); // Delay for polling interval
    }

    cleanup();
    return 0;
}

