#include <pigpio.h>
#include <unistd.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME_US 1000 // 1 second in microseconds
#define SAMPLE_INTERVAL_S 1

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
double total_liters = 0.0;
double lpm = 0.0;
int solenoid_state = 1; // 1 = open, 0 = closed
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm();
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Calculate LPM based on pulse count
double calculate_lpm() {
    (void)total_liters; // unused
    return lpm;
}

// Control solenoid based on LPM
void control_solenoid(double lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        solenoid_state = 0;
        printf("Solenoid closed (LPM: %.2f)\n", lpm);
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        solenoid_state = 1;
        printf("Solenoid opened (LPM: %.2f)\n", lpm);
    }
}

// Log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Close solenoid
    gpioWrite(SOLENOID_GPIO, 1); // Open solenoid

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Cleanup pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Set solenoid to open state
    gpioWrite(SOLENOID_GPIO, 1);

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Sample every second

        // Debounce and calculate pulse count
        int local_pulse_count = 0;
        pthread_mutex_lock(&pulse_mutex);
        local_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count after reading
        pthread_mutex_unlock(&pulse_mutex);

        double liters = (double)local_pulse_count / PULSES_PER_LITER;
        total_liters += liters;
        lpm = liters / SAMPLE_INTERVAL_S; // LPM = liters/second

        // Calculate and log LPM
        double calculated_lpm = calculate_lpm();
        if (calculated_lpm != 0.0) {
            lpm = calculated_lpm;
        }

        log_data(lpm, solenoid_state);

        // Control solenoid
        control_solenoid(lpm);
    }

    return 0;
}

