// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(23, PI_INPUT);
    gpioSetMode(24, PI_OUTPUT);

    gpioWrite(24, 0);

    // Wait for DOUT to go low
    int timeout = 0;
    while (gpioRead(23) == 1 && timeout < 1000) {
        gpioDelay(1); // 1 us delay
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(24, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(23)) {
            data++;
        }
        gpioWrite(24, 0);
        gpioDelay(1); // 1 us delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(24, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(24, 0);
    gpioDelay(1); // 1 us delay

    data = data ^ 0x800000; // Convert to signed 2's complement

    return data;
}

// Servo control function
int control_servo(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
