#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
}

int main() {
    int angle = 90;
    int pulse_width;
    char input;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended for clean PWM)
    gpioSetPWMrange(SERVO_PIN, 1000000); // Full resolution

    // Set initial angle (90 degrees)
    pulse_width = (int)(1500.0 / 20.0 * 1000.0); // 1500 us pulse width at 50Hz
    gpioPWM(SERVO_PIN, pulse_width);

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read input
        input = getchar();

        // Check for 'q'
        if (input == 'q') {
            running = 0;
            continue;
        }

        // Check for '+'
        if (input == '+') {
            angle += 10;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
        }

        // Check for '-'
        if (input == '-') {
            angle -= 10;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
        }

        // Calculate pulse width
        pulse_width = (int)(MIN_PULSE_WIDTH + (float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) * 1000.0);

        // Set PWM duty cycle
        gpioPWM(SERVO_PIN, pulse_width);

        // Print current angle
        printf("Angle: %d\n", angle);

        // Small delay
        usleep(10000); // 10ms
    }

    // Stop PWM
    gpioPWM(SERVO_PIN, 0);

    // Restore terminal settings (optional, but good practice)
    // This part is not strictly necessary with pigpio, but included for completeness
    // In a real-world scenario, you might need to reset the terminal to its original state
    // after the program exits.

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

