#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

static volatile int running = 1;
static int pulse_count = 0;
static struct timespec last_pulse_time;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the GPIO pin with debouncing
int read_gpio_with_debounce() {
    int current_state = gpioRead(GPIO_PIN);
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    long time_diff_ms = (now.tv_sec - last_pulse_time.tv_sec) * 1000 + (now.tv_nsec - last_pulse_time.tv_nsec) / 1000000;

    if (time_diff_ms < DEBOUNCE_MS) {
        return current_state; // Return the current state if within debounce window
    }

    last_pulse_time = now;
    return current_state; // Return the current state after debounce
}

// Function to count pulses
void count_pulse() {
    pulse_count++;
}

// Function to calculate RPM
double calculate_rpm() {
    struct timespec start, end;
    long elapsed_time_ns;
    double elapsed_time_s;
    double rpm;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        elapsed_time_s = (double)elapsed_time_ns / 1000000000.0;

        if (elapsed_time_s >= 5.0) {
            break;
        }
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    rpm = (double)pulse_count / elapsed_time_s * 60.0;
    pulse_count = 0; // Reset pulse count after calculating RPM
    return rpm;
}

// Function to log RPM to a file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // ISO 8601 timestamp format: YYYY-MM-DDTHH:MM:SS.mmmZ

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize last pulse time
    clock_gettime(CLOCK_MONOTONIC, &last_pulse_time);

    fprintf(stderr, "RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        double rpm = calculate_rpm();
        log_rpm(rpm);
        print_rpm(rpm);
        sleep(5);
    }

    // Cleanup
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "RPM monitoring stopped.\n");

    return 0;
}

