#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define TOGGLE_DELAY_MS 50
#define CONTINUOUS_HIGH_TIMEOUT_S 10

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_relay(int state);
void handle_timeout();
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    int relay_state = 0; // 0 = OFF, 1 = ON
    time_t start_time = 0;
    int continuous_high_count = 0;

    while (!terminate) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // If touch is detected (HIGH)
        if (touch_detected) {
            // Toggle relay state
            relay_state = !relay_state;
            control_relay(relay_state);

            // Reset timeout counter
            continuous_high_count = 0;
        }

        // Increment timeout counter
        continuous_high_count++;

        // Check for timeout condition
        if (continuous_high_count > (CONTINUOUS_HIGH_TIMEOUT_S * 1000)) {
            handle_timeout();
        }

        // Delay
        gpioDelay(TOGGLE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to output mode\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    control_relay(0);

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control relay state
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Handle timeout condition
void handle_timeout() {
    printf("Timeout condition reached. Turning relay OFF.\n");
    control_relay(0); // Turn relay OFF
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up and exiting.\n");
    control_relay(0); // Ensure relay is OFF
    gpioTerminate();
}

