#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define I2C address for MCP3008
#define MCP3008_ADDR 0x04

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Define flow sensor calibration factor (pulses/L/min)
#define FLOW_SENSOR_CALIBRATION 7.5

// Global variables
volatile int flow_count = 0;
volatile unsigned long last_flow_count_time = 0;
int mcp3008_fd;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
void flow_sensor_isr();
float read_flow_rate();
int set_valve_position(int position);
int validate_target_flow_rate(float target_flow_rate);
void log_data(float flow_rate, int valve_position);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(VALVE_PWM_PIN, PWM_OUTPUT);
    pinMode(VALVE_ENABLE_PIN, OUTPUT);
    pinMode(FLOW_SENSOR_PIN, INPUT);

    // Set PWM frequency and range
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock for desired frequency (approximately 1000 Hz)
    pwmSetRange(PWM_RANGE);

    // Enable valve
    digitalWrite(VALVE_ENABLE_PIN, HIGH);

    return 0;
}

// Function to initialize I2C communication with MCP3008
int initialize_i2c() {
    mcp3008_fd = wiringPiI2CSetup(MCP3008_ADDR);
    if (mcp3008_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Interrupt service routine for flow sensor
void flow_sensor_isr() {
    flow_count++;
    last_flow_count_time = millis();
}

// Function to read flow rate from MCP3008 ADC
float read_flow_rate() {
    int adc_value = 0;

    // Read ADC value from MCP3008 channel 0
    wiringPiI2CWrite(mcp3008_fd, 0x00); // Start bit
    adc_value = wiringPiI2CReadReg16(mcp3008_fd, 0x00); // Read 12-bit ADC value

    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value * (3.3 / 4095.0);

    // Calculate flow rate in L/min
    float flow_rate = (float)flow_count / FLOW_SENSOR_CALIBRATION * (1.0 / (1.0 + voltage / 3.3)); // Assuming voltage is proportional to flow

    // Reset flow count
    flow_count = 0;

    return flow_rate;
}

// Function to set valve position using PWM
int set_valve_position(int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid valve position (0-%d)\n", PWM_RANGE);
        return -1;
    }

    pwmWrite(VALVE_PWM_PIN, position);
    return 0;
}

// Function to validate target flow rate
int validate_target_flow_rate(float target_flow_rate) {
    if (target_flow_rate < 0.0 || target_flow_rate > 10.0) {
        fprintf(stderr, "Error: Invalid target flow rate. Must be between 0.0 and 10.0 L/min.\n");
        return -1;
    }
    return 0;
}

// Function to log data to CSV file
void log_data(float flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);

    // Disable valve
    set_valve_position(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate wiringPi
    wiringPiSetup(); // Reinitialize to allow cleanup

    exit(0);
}

int main(int argc, char *argv[]) {
    float target_flow_rate = 0.0;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        target_flow_rate = strtof(argv[1], &endptr);

        if (*endptr != '\0' || errno == ERANGE) {
            fprintf(stderr, "Error: Invalid target flow rate. Must be a floating-point number.\n");
            return 1;
        }

        if (validate_target_flow_rate(target_flow_rate) != 0) {
            return 1;
        }
    } else {
        fprintf(stderr, "Error: Target flow rate must be provided as a command-line argument.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Set up interrupt for flow sensor
    if (wiringPiISR(FLOW_SENSOR_PIN, INT_EDGE_RISING, flow_sensor_isr) < 0) {
        fprintf(stderr, "Error setting up ISR: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read flow rate
        float flow_rate = read_flow_rate();

        // Calculate error
        float error = target_flow_rate - flow_rate;

        // Calculate proportional gain
        float kp = 1.0;
        float correction = kp * error;

        // Clamp correction to 0-255 range
        int valve_position = (int)correction;
        if (valve_position < 0) {
            valve_position = 0;
        } else if (valve_position > PWM_RANGE) {
            valve_position = PWM_RANGE;
        }

        // Set valve position
        if (set_valve_position(valve_position) != 0) {
            return 1;
        }

        // Log data
        log_data(flow_rate, valve_position);

        // Wait 100 ms
        delay(100);
    }

    return 0;
}

