#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 100000

// Define RFID tag value
#define RFID_TAG "1234567890"

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define lock disengage time in seconds
#define LOCK_DISENGAGE_TIME 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(int spi_handle, char *tag);
int verify_tag(const char *tag);
int read_button_state(int button_pin);
void disengage_locks(int lock1_pin, int lock2_pin, int duration_seconds);
void engage_locks(int lock1_pin, int lock2_pin);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid_tag(int spi_handle, char *tag) {
    int retries = 0;
    int bytes_read;
    char buffer[10];

    while (retries < 3) {
        bytes_read = spiRead(spi_handle, buffer, 10);
        if (bytes_read == 10) {
            // Check for all zero bytes
            if (buffer[0] == 0 && buffer[1] == 0 && buffer[2] == 0 && buffer[3] == 0 &&
                buffer[4] == 0 && buffer[5] == 0 && buffer[6] == 0 && buffer[7] == 0 && buffer[8] == 0 && buffer[9] == 0) {
                strcpy(tag, "No tag present");
                return 0; // No tag
            } else {
                strcpy(tag, (char*)buffer);
                return 1; // Tag read
            }
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    log_event("RFID read failed after multiple retries.");
    return -1; // Failure
}

// Function to verify RFID tag
int verify_tag(const char *tag) {
    return (strcmp(tag, RFID_TAG) == 0);
}

// Function to read button state with debouncing
int read_button_state(int button_pin) {
    int i;
    int state = 1; // Assume button is not pressed (active low)

    for (i = 0; i < 10; i++) {
        if (gpioRead(button_pin) == 0) {
            state = 0;
            break;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return state;
}

// Function to disengage locks
void disengage_locks(int lock1_pin, int lock2_pin, int duration_seconds) {
    gpioWrite(lock1_pin, 0);
    gpioWrite(lock2_pin, 0);
    gpioDelay(duration_seconds * 1000000); // Convert seconds to microseconds
    engage_locks(lock1_pin, lock2_pin);
}

// Function to engage locks
void engage_locks(int lock1_pin, int lock2_pin) {
    gpioWrite(lock1_pin, 1);
    gpioWrite(lock2_pin, 1);
}

// Function to log events
void log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[30];

    time(&now);
    timeinfo = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");

    // Disengage locks
    engage_locks(LOCK1_PIN, LOCK2_PIN);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Call RFID read API
    spiRead(spi_handle, NULL, 0); // Dummy call to flush the buffer

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    char tag[11]; // 10 bytes + null terminator
    int button_pressed;
    int button_state;
    int last_button_state = 1; // Initialize to not pressed (active low)

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started.");

    // Main loop
    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag(spi_handle, tag) == 1) {
            // Verify tag
            if (verify_tag(tag)) {
                log_event("Tag verified, button press required.");

                // Read button state
                button_state = read_button_state(BUTTON_PIN);

                // Debounce button press
                if (button_state == 0 && last_button_state == 1) {
                    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
                    button_state = read_button_state(BUTTON_PIN); // Re-read after debounce

                    if (button_state == 0) {
                        log_event("Button pressed, disengaging locks.");
                        disengage_locks(LOCK1_PIN, LOCK2_PIN, LOCK_DISENGAGE_TIME);
                        log_event("Locks disengaged.");
                        gpioDelay(1000000); // Wait 1 second before re-engaging
                        engage_locks(LOCK1_PIN, LOCK2_PIN);
                        log_event("Locks engaged.");
                    }
                }
            } else {
                log_event("Invalid tag.");
            }
        } else {
            log_event("RFID read failed.");
        }

        last_button_state = button_state;
        gpioDelay(100000); // Check every 0.1 seconds
    }

    return 0;
}

