#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR_1_ENA 23
#define MOTOR_1_IN1 24
#define MOTOR_1_IN2 25
#define MOTOR_1_A 5
#define MOTOR_1_B 6

// Motor 2
#define MOTOR_2_ENB 12
#define MOTOR_2_IN3 16
#define MOTOR_2_IN4 20
#define MOTOR_2_A 26
#define MOTOR_2_B 19

#define PWM_FREQUENCY 100
#define SAMPLE_TIME_MS 100
#define TARGET_SPEED 60.0 // RPM

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
volatile int motor1_count = 0;
volatile int motor2_count = 0;
double motor1_speed = 0.0;
double motor2_speed = 0.0;
double motor1_integral = 0.0;
double motor2_integral = 0.0;
double motor1_previous_error = 0.0;
double motor2_previous_error = 0.0;
FILE *log_file = NULL;
int running = 1;

// Mutexes
pthread_mutex_t motor1_mutex;
pthread_mutex_t motor2_mutex;

// Function Prototypes
void *encoder_thread(void *arg);
double pid_control(double target_speed, double motor_speed, double *integral, double *previous_error);
void set_motor_speed(int motor_number, double duty_cycle);
void log_data(double motor1_speed, double motor1_integral, double motor1_previous_error, double motor2_speed, double motor2_integral, double motor2_previous_error);
void signal_handler(int signal);

// Function to set motor speed using PWM
void set_motor_speed(int motor_number, double duty_cycle) {
    int in1, in2, ena;

    if (motor_number == 1) {
        in1 = MOTOR_1_IN1;
        in2 = MOTOR_1_IN2;
        ena = MOTOR_1_ENA;
    } else if (motor_number == 2) {
        in1 = MOTOR_2_IN3;
        in2 = MOTOR_2_IN4;
        ena = MOTOR_2_ENB;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_number);
        return;
    }

    if (duty_cycle > 0) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
        gpioPWM(ena, (int)(duty_cycle * 255)); // pigpio PWM range is 0-255
    } else if (duty_cycle < 0) {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
        gpioPWM(ena, (int)(-duty_cycle * 255)); // pigpio PWM range is 0-255
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
        gpioPWM(ena, 0); // Stop the motor
    }
}

// Function to calculate PID output
double pid_control(double target_speed, double motor_speed, double *integral, double *previous_error) {
    double error = target_speed - motor_speed;
    *integral += error * SAMPLE_TIME_MS;
    double derivative = (error - *previous_error) / SAMPLE_TIME_MS;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Encoder thread function
void *encoder_thread(void *arg) {
    while (running) {
        int motor_number;
        if (pthread_mutex_lock(&motor1_mutex) == 0) {
            motor_number = 1;
        } else {
            fprintf(stderr, "Error: Could not lock motor1 mutex\n");
            continue;
        }

        if (gpioRead(MOTOR_1_A) != gpioRead(MOTOR_1_B)) {
            motor1_count++;
        }

        if (pthread_mutex_unlock(&motor1_mutex) == 0) {
            // Mutex unlocked successfully
        } else {
            fprintf(stderr, "Error: Could not unlock motor1 mutex\n");
        }

        if (pthread_mutex_lock(&motor2_mutex) == 0) {
            motor_number = 2;
        } else {
            fprintf(stderr, "Error: Could not lock motor2 mutex\n");
            continue;
        }

        if (gpioRead(MOTOR_2_A) != gpioRead(MOTOR_2_B)) {
            motor2_count++;
        }

        if (pthread_mutex_unlock(&motor2_mutex) == 0) {
            // Mutex unlocked successfully
        } else {
            fprintf(stderr, "Error: Could not unlock motor2 mutex\n");
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    return NULL;
}

// Function to log data to file
void log_data(double motor1_speed, double motor1_integral, double motor1_previous_error, double motor2_speed, double motor2_integral, double motor2_previous_error) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, motor1_speed, motor1_integral, motor1_previous_error, motor2_speed, motor2_integral, motor2_previous_error);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    running = 0;
    set_motor_speed(1, 0.0); // Stop Motor 1
    set_motor_speed(2, 0.0); // Stop Motor 2
    gpioPWM(MOTOR_1_ENA, 0); // Stop Motor 1 PWM
    gpioPWM(MOTOR_2_ENB, 0); // Stop Motor 2 PWM
    gpioWrite(MOTOR_1_IN1, 0);
    gpioWrite(MOTOR_1_IN2, 0);
    gpioWrite(MOTOR_2_IN3, 0);
    gpioWrite(MOTOR_2_IN4, 0);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR_2_IN3, PI_OUTPUT);
