        gpioTerminate();
        return 1;
    }
    if (pthread_mutex_init(&motor2_mutex, NULL) != 0) {
        fprintf(stderr, "Error: Could not initialize motor2 mutex\n");
        pthread_mutex_destroy(&motor1_mutex);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        pthread_mutex_destroy(&motor1_mutex);
        pthread_mutex_destroy(&motor2_mutex);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Motor1_Speed(RPM),Motor1_Integral,Motor1_Previous_Error,Motor2_Speed(RPM),Motor2_Integral,Motor2_Previous_Error\n");
    fflush(log_file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
