        pthread_mutex_destroy(&motor2_mutex);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&motor2_thread, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Error: Could not create motor2 thread\n");
        pthread_cancel(motor1_thread);
        fclose(log_file);
        pthread_mutex_destroy(&motor1_mutex);
        pthread_mutex_destroy(&motor2_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Calculate PID output
        double pid_output_1 = pid_control(TARGET_SPEED, motor1_speed, &motor1_integral, &motor1_previous_error);
        double pid_output_2 = pid_control(TARGET_SPEED, motor2_speed, &motor2_integral, &motor2_previous_error);

