#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// Relay GPIO pin
#define RELAY_PIN 17

// I2C bus
#define I2C_BUS 1

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure filtering parameters
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to write CONFIG1\n");
        return -1;
    }

    // Set touch and release thresholds for each electrode
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to enable run mode\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Function to log relay state to file
void log_relay_state(int state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d Relay: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            state ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            int any_touched = 0;
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    any_touched = 1;
                    break;
                }
            }

            if (any_touched && !relay_state) {
                control_relay(1);
                relay_state = 1;
                log_relay_state(relay_state);
            } else if (!any_touched && relay_state) {
                control_relay(0);
                relay_state = 0;
                log_relay_state(relay_state);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    control_relay(0); // Turn off relay
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

