#include <pigpio.h>

// Define GPIO pins for the valves
#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio_pin, int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE_1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE_2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn the valve ON
    gpioDelay(duration_ms);  // Wait for the specified duration
    gpioWrite(gpio_pin, 0); // Turn the valve OFF
}

// Function to log an event to the log file with an ISO 8601 timestamp
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
