void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }
    gpioDelay(100000); // 100 ms delay

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_set_touch_release_threshold(i, 40, 20) < 0) {
            fprintf(stderr, "Error: Failed to set touch/release thresholds for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (mpr121_set_filter_config(0x10) < 0) {
        fprintf(stderr, "Error: Failed to set filter configuration.\n");
        return -1;
    }

    // Configure electrode current
    if (mpr121_set_electrode_current(0x10) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current.\n");
        return -1;
    }

    return 0;
}

// MPR121 set touch/release threshold function
int mpr121_set_touch_release_threshold(int electrode, int touch_threshold, int release_threshold) {
    if (i2cWriteByteData(i2c_handle, 0x41 + (electrode * 2), touch_threshold) < 0) {
        fprintf(stderr, "Error: Failed to write touch threshold for electrode %d.\n", electrode);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42 + (electrode * 2), release_threshold) < 0) {
        fprintf(stderr, "Error: Failed to write release threshold for electrode %d.\n", electrode);
        return -1;
    }
    return 0;
}

// MPR121 set filter configuration function
int mpr121_set_filter_config(int filter_config) {
    if (i2cWriteByteData(i2c_handle, 0x2B, filter_config) < 0) {
        fprintf(stderr, "Error: Failed to write filter configuration.\n");
        return -1;
    }
    return 0;
}

// MPR121 set charge time function
int mpr121_set_charge_time(int charge_time) {
    if (i2cWriteByteData(i2c_handle, 0x2C, charge_time) < 0) {
        fprintf(stderr, "Error: Failed to write charge time.\n");
        return -1;
    }
    return 0;
}

// MPR121 set electrode current function
int mpr121_set_electrode_current(int electrode_current) {
    if (i2cWriteByteData(i2c_handle, 0x2D, electrode_current) < 0) {
        fprintf(stderr, "Error: Failed to write electrode current.\n");
        return -1;
    }
    return 0;
}

// MPR121 set run mode function
int mpr121_set_run_mode() {
    if (i2cWriteByteData(i2c_handle, 0x80, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode.\n");
        return -1;
    }
    gpioDelay(100000); // 100 ms delay
    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status() {
    int touch_status = i2cReadByteData(i2c_handle, 0x00);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    return touch_status;
}

// Toggle relay function
void toggle_relay() {
    int current_relay_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_relay_state);
    printf("Relay toggled to state: %d\n", !current_relay_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to off state

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status, exiting.\n");
            break;
        }

        if (touch_status > 0) {
            toggle_relay();
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

