#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLLING_INTERVAL_MS 50

// Global variables
FILE *log_file = NULL;
int rate_limit_start_time = 0;
int rate_limit_active = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int state);
void log_event(const char *event_type, int duration_ms);
void rate_limit_handler();
void signal_handler(int signal);
void cleanup();

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int last_pir_state = 0; // Store the last known state of the PIR sensor

    // Main loop
    while (1) {
        // Read PIR sensor
        int pir_state = read_pir_sensor();

        // Check for rising edge
        if (pir_state == 1 && last_pir_state == 0) {
            // Motion detected
            log_event("Motion Detected", 0);

            // Control relay
            control_relay(1); // Unlock
            gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
            control_relay(0); // Lock

            // Rate limiting
            rate_limit_handler();
        }

        // Update last PIR state
        last_pir_state = pir_state;

        // Delay for polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000);
    }

    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off
    return 0;
}

// Read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Log event
void log_event(const char *event_type, int duration_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld.%03ld: %s\n", ts.tv_sec, milliseconds, event_type);
    fflush(log_file); // Ensure data is written to file immediately
}

// Rate limiting handler
void rate_limit_handler() {
    rate_limit_active = 1;
    rate_limit_start_time = time_time();
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting.\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    // Disable relay
    gpioWrite(RELAY_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

