#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the motors
#define MOTOR_1_GPIO 17
#define MOTOR_2_GPIO 27

// Define the number of steps in a pattern
#define PATTERN_LENGTH_MIN 5
#define PATTERN_LENGTH_MAX 15

// Define the minimum and maximum step duration
#define STEP_DURATION_MIN 50 // milliseconds
#define STEP_DURATION_MAX 200 // milliseconds

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define the PWM range
#define PWM_RANGE 255

// Global variables
volatile sig_atomic_t shutdown_flag = 0;

// Function prototypes
void signal_handler(int signal);
int generate_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int *step_duration, int *pattern_length);
void play_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int step_duration, int pattern_length);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        shutdown_flag = 1;
    }
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int *step_duration, int *pattern_length) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate random values for each parameter
    *motor1_duty_cycle = rand() % PWM_RANGE;
    *motor2_duty_cycle = rand() % PWM_RANGE;
    *step_duration = rand() % (STEP_DURATION_MAX - STEP_DURATION_MIN + 1) + STEP_DURATION_MIN;
    *pattern_length = rand() % (PATTERN_LENGTH_MAX - PATTERN_LENGTH_MIN + 1) + PATTERN_LENGTH_MIN;

    return 0; // Indicate success
}

// Function to play a haptic feedback pattern
void play_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int step_duration, int pattern_length) {
    // Calculate the number of steps per second
    float steps_per_second = (float)pattern_length / step_duration;

    // Calculate the delay between steps in microseconds
    float delay_between_steps = (1000000.0 / steps_per_second) / 2.0; // Divide by 2 because we have two motors

    // Loop through the pattern length
    for (int i = 0; i < pattern_length; i++) {
        // Set the PWM duty cycle for both motors
        gpioPWM(MOTOR_1_GPIO, *motor1_duty_cycle);
