#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define DEFAULT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_TIMEOUT_MS 500

// Global variables
double scale_factor = DEFAULT_SCALE;
double offset = DEFAULT_OFFSET;
double threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double scale, double offset);
int check_threshold(double weight, double threshold);
void control_solenoid(int lock_state);
int load_calibration_data();
int save_calibration_data();
void log_data(int raw_value, double weight);
void signal_handler(int signal);
int startup_calibration();

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < READ_TIMEOUT_MS) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= READ_TIMEOUT_MS) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value, double scale, double offset) {
    return (double)(raw_value - offset) / scale;
}

// Function to check if weight exceeds threshold
int check_threshold(double weight, double threshold) {
    return (weight > threshold) ? 1 : 0;
}

// Function to control the solenoid lock
void control_solenoid(int lock_state) {
    gpioWrite(SOLENOID_PIN, lock_state);
}

// Function to load calibration data from file
int load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file. Using default values.\n");
        return -1; // Indicate failure to open file
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Could not read calibration data from file. Using default values.\n");
        fclose(fp);
        return -1; // Indicate failure to read data
    }

    fclose(fp);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1; // Indicate failure to open file
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    return 0; // Indicate success
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to perform startup calibration
int startup_calibration() {
    double sum = 0.0;
    int i;
    int raw_value;

    printf("Performing startup calibration...\n");
    for (i = 0; i < 100; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 timeout during startup calibration.\n");
            return -1; // Indicate failure
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = sum / 100.0;
    printf("Startup calibration complete. Offset: %.2f\n", offset);
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (load_calibration_data() != 0) {
        // Use default values if loading fails
        scale_factor = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
    }

    // Perform startup calibration
    if (startup_calibration() != 0) {
        fprintf(stderr, "Error: Startup calibration failed. Using default offset.\n");
        offset = DEFAULT_OFFSET;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, scale_factor, offset);
            log_data(raw_value, weight);

            if (check_threshold(weight, threshold)) {
                control_solenoid(1); // Lock the solenoid
                printf("Weight exceeds threshold. Solenoid locked.\n");
            } else {
                control_solenoid(0); // Unlock the solenoid
                printf("Weight below threshold. Solenoid unlocked.\n");
            }
        } else {
            fprintf(stderr, "Error: HX711 read failed.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up and exit
    control_solenoid(0); // Unlock solenoid on exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

