#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define DEBOUNCE_DELAY_MS 50
#define RAIN_THRESHOLD 3
#define RAIN_DURATION_SEC 5
#define CHECK_INTERVAL_SEC 60
#define POST_CLOSE_DELAY_SEC 60

// Global variables
static volatile int running = 1;
static int pwm_enabled = 0;

// Function prototypes
int read_rain_sensor();
int debounce_read(int pin, int num_reads, int delay_ms);
int control_motor(int in1_pin, int in2_pin, int pwm_pin, int direction, int duty_cycle);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < 5; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

// Function to control the DC motor
int control_motor(int in1_pin, int in2_pin, int pwm_pin, int direction, int duty_cycle) {
    if (direction == 1) { // Close window
        if (!pwm_enabled) {
            if (gpioInitialise() < 0) {
                log_event("Error: pigpio initialisation failed");
                return -1;
            }
            gpioSetMode(pwm_pin, PI_OUTPUT);
            gpioPWM(pwm_pin, duty_cycle);
            pwm_enabled = 1;
        }
        if (gpioWrite(in1_pin, 1) != 0 || gpioWrite(in2_pin, 0) != 0) {
            log_event("Error: Failed to set motor direction");
            return -1;
        }
    } else { // Stop motor
        if (pwm_enabled) {
            gpioPWM(pwm_pin, 0);
            pwm_enabled = 0;
        }
        if (gpioWrite(in1_pin, 0) != 0 || gpioWrite(in2_pin, 0) != 0) {
            log_event("Error: Failed to stop motor");
            return -1;
        }
    }
    return 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    // Stop the motor
    if (pwm_enabled) {
        gpioPWM(MOTOR_PWM_PIN, 0);
        pwm_enabled = 0;
    }
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    // Release GPIO resources
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Main loop
    while (running) {
        // Read rain sensor
        int rain_detected = read_rain_sensor();

        // Log rain detection
        if (rain_detected) {
            log_event("Rain detected!");

            // Control motor
            if (control_motor(MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_PWM_PIN, 1, PWM_DUTY_CYCLE) != 0) {
                log_event("Error: Failed to control motor");
            }

            // Log motor action
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Motor started for %d seconds", RAIN_DURATION_SEC);
            log_event(log_message);

            // Wait for motor to complete
            gpioDelay(RAIN_DURATION_SEC * 1000000); // Delay in microseconds

            // Stop motor
            if (control_motor(MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_PWM_PIN, 0, 0) != 0) {
                log_event("Error: Failed to stop motor");
            }

            // Log motor stop
            log_event("Motor stopped.");

            // Wait before next check
            gpioDelay(CHECK_INTERVAL_SEC * 1000000); // Delay in microseconds
        } else {
            // Wait before next check
