int running = 1;

// Function prototypes
int read_hx711();
float convert_to_grams(int raw_value);
void activate_solenoid();
void deactivate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for the data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DT) == 1 && timeout_counter < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_DURATION) {
        log_event("Error: HX711 data line stuck high.");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to grams
float convert_to_grams(int raw_value) {
    // Calibration factor (adjust this value based on your setup)
    // This is a placeholder; you'll need to calibrate your load cell.
    float calibration_factor = 1.0; // Example: 1 raw unit = 1 gram
    return (float)raw_value / calibration_factor;
}

// Function to activate the solenoid
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set GPIO HIGH
    log_event("Solenoid activated.");
    gpioDelay(SOLENOID_DURATION * 1000000); // Delay for solenoid duration (in microseconds)
    deactivate_solenoid();
}

// Function to deactivate the solenoid
void deactivate_solenoid() {
    gpioWrite(SOLENOID_PIN, 0); // Set GPIO LOW
    log_event("Solenoid deactivated.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
