        if (raw_value != -1) {
            float weight_grams = convert_to_grams(raw_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight_grams);
            log_event(log_message);

            if (weight_grams < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating solenoid.");
                activate_solenoid();
            }
        } else {
            log_event("Error reading HX711.");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

