#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_DURATION 5  // seconds
#define SAMPLE_INTERVAL 1       // seconds
#define TIMEOUT_DURATION 100    // milliseconds
#define WEIGHT_THRESHOLD 5.0    // kg
#define SOLENOID_DURATION 5     // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;
static double calibration_factor = 0.0;

// Function prototypes
int initialize_gpio();
long read_hx711();
double calibrate_sensor();
double convert_to_weight(long raw_value);
void control_solenoid(double weight);
void log_data(double weight);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw data from HX711
long read_hx711() {
    long value = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for the data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) && timeout < TIMEOUT_DURATION) {
        gpioDelay(1); // 1 us delay
        timeout++;
    }

    if (timeout >= TIMEOUT_DURATION) {
        fprintf(stderr, "HX711 timeout error\n");
        return 0; // Indicate timeout
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to calibrate the sensor
double calibrate_sensor() {
    double known_weight;
    long raw_value;
    double sum = 0.0;
    int i;

    printf("Place a known weight (in kg) on the load cell:\n");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return -1.0;
    }

    printf("Reading sensor value...\n");
    for (i = 0; i < 10; i++) {
        raw_value = read_hx711();
        if (raw_value == 0) {
            fprintf(stderr, "Calibration failed: Timeout error.\n");
            return -1.0;
        }
        sum += raw_value;
        gpioDelay(1000); // 1 second delay
    }

    calibration_factor = (sum / 10.0) / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    return calibration_factor;
}

