void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        printf("Weight threshold exceeded. Activating solenoid.\n");
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        gpioDelay(SOLENOID_DURATION * 1000000); // 5 seconds
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        printf("Solenoid deactivated.\n");
    }
}

// Function to log data to file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open calibration file
    calibration_file = fopen("calibration.txt", "r");
    if (calibration_file == NULL) {
        calibration_file = fopen("calibration.txt", "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Error opening calibration file!\n");
            cleanup();
            return 1;
        }
        if (calibrate_sensor() != 0) {
            fprintf(stderr, "Calibration failed!\n");
            cleanup();
            return 1;
        }
        calibration_factor = atof(fgets(calibration_file, 100, calibration_file));
        fclose(calibration_file);
    } else {
        fseek(calibration_file, -1, SEEK_END);
        long last_char = fgetc(calibration_file);
        if (last_char == '\n') {
            fseek(calibration_file, 0, SEEK_SET);
            calibration_factor = atof(fgets(calibration_file, 100, calibration_file));
        } else {
            calibration_factor = atof(fgets(calibration_file, 100, calibration_file));
        }
        fclose(calibration_file);
    }

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        long raw_value = read_hx711();
        if (raw_value != 0) {
            double weight = convert_to_weight(raw_value);
            printf("Raw: %ld, Weight: %.2f kg\n", raw_value, weight);
            control_solenoid(weight);
            log_data(weight);
        }
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Sample every second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

