        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("GPIO resources cleaned up.\n");
}

