#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

static volatile sig_atomic_t terminate = 0;

// Function to parse the configuration file
int parse_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL) {
        fprintf(stderr, "Malformed config file: No key-value pair found\n");
        return -1;
    }

    char *value = strtok(NULL, "=");
    if (value == NULL) {
        fprintf(stderr, "Malformed config file: No value found\n");
        return -1;
    }

    if (strcmp(token, "duration") == 0) {
        char *endptr;
        long parsed_duration = strtol(value, &endptr, 10);

        if (*endptr != '\0' && *endptr != '\n') {
            fprintf(stderr, "Malformed config file: Invalid duration value\n");
            return -1;
        }

        if (parsed_duration < MIN_DURATION || parsed_duration > MAX_DURATION) {
            fprintf(stderr, "Malformed config file: Duration out of range (%ld seconds)\n", parsed_duration);
            return -1;
        }

        *duration = (int)parsed_duration;
        return 0;
    } else {
        fprintf(stderr, "Malformed config file: Unknown key '%s'\n", token);
        return -1;
    }
}

// Function to initialize the GPIO pin
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    gpioWrite(pin, 0); // Set initial state to LOW (valve off)
    return 0;
}

// Function to activate the valve
int activate_valve(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating valve: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to deactivate the valve
int deactivate_valve(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating valve: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to wait for the specified duration
int wait_duration(int duration) {
    if (duration <= 0) {
        fprintf(stderr, "Invalid duration: %d seconds\n", duration);
        return -1;
    }

    struct timespec ts;
    ts.tv_sec = duration;
    ts.tv_nsec = 0;

    if (nanosleep(&ts, NULL) != 0) {
        if (errno == EINTR) {
            fprintf(stderr, "Wait interrupted by signal\n");
        } else {
            fprintf(stderr, "Error during nanosleep: %s\n", strerror(errno));
        }
        return -1;
    }

    return 0;
}

// Function to log the watering event
void log_event(int duration) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Watering for %d seconds\n", timestamp, duration);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    int duration = 0;
    int gpio_pin = GPIO_PIN;

    // Parse configuration file
    if (parse_config(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to parse configuration file. Exiting.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pin
    if (initialize_gpio(gpio_pin) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    log_event(duration);
    if (activate_valve(gpio_pin) != 0) {
        fprintf(stderr, "Valve activation failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (wait_duration(duration) != 0) {
        fprintf(stderr, "Wait duration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (deactivate_valve(gpio_pin) != 0) {
        fprintf(stderr, "Valve deactivation failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    log_event(duration);

    // Release GPIO and terminate pigpio
    gpioTerminate();

    return 0;
}

