    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on lock and unlock buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_position(LOCK_POSITION);
    gpioDelay(500); // Debounce delay
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_position(UNLOCK_POSITION);
    gpioDelay(500); // Debounce delay
}

// Function to set the servo position
void set_servo_position(int position) {
    if (position < MIN_PULSE_WIDTH || position > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Servo position out of range (%d)\n", position);
        return;
    }

    gpioServo(SERVO_PIN, position);
    servo_position = position; // Update global servo position
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            gpioDelay(100); // Short delay to prevent repeated triggering
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            gpioDelay(100); // Short delay to prevent repeated triggering
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0; // This line will never be reached due to the infinite loop
}

