#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"
#define ALARM_DURATION_SEC 1

// Global variables (to be minimized, used for signal handling)
static int zmq_socket_fd = -1;
static int zmq_context_id = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(int gpio_pin, int mode);
int zmq_init(int port);
int zmq_connect(int socket_fd, const char *address, int port);
int zmq_subscribe(int socket_fd, const char *topic);
int zmq_send_message(int socket_fd, const char *message);
int zmq_receive_message(int socket_fd, char *buffer, size_t buffer_size);
void alarm_led_on(int gpio_pin);
void alarm_led_off(int gpio_pin);
void publish_alert(int zmq_socket_fd, const char *topic);
void signal_handler(int signal);

// GPIO Initialization
int gpio_init(int gpio_pin, int mode) {
    if (gpioSetMode(gpio_pin, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode to %d: %s\n", gpio_pin, mode, strerror(errno));
        return -1;
    }
    return 0;
}

// ZeroMQ Initialization
int zmq_init(int port) {
    zmq_context_t *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Error creating ZeroMQ context: %s\n", zmq_strerror(errno));
        return -1;
    }
    zmq_context_id = (int)context; // Store context ID for cleanup

    int socket_fd = zmq_socket(context, ZMQ_PUB);
    if (!socket_fd) {
        fprintf(stderr, "Error creating ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    if (zmq_bind(socket_fd, "tcp://*:0") < 0) {
        fprintf(stderr, "Error binding ZeroMQ socket to port: %s\n", zmq_strerror(errno));
        zmq_close(socket_fd);
        zmq_ctx_destroy(context);
        return -1;
    }

    int local_port = 0;
    socklen_t len = sizeof(local_port);
    if (getsockname(socket_fd, (struct sockaddr *)&local_port, &len) < 0) {
        fprintf(stderr, "Error getting socket name: %s\n", strerror(errno));
        zmq_close(socket_fd);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("ZeroMQ listening on port %d\n", local_port);
    return socket_fd;
}

// ZeroMQ Connect
int zmq_connect(int socket_fd, const char *address, int port) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, address, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", address);
        return -1;
    }

    if (zmq_connect(socket_fd, (const char *) &server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error connecting to ZeroMQ server: %s\n", zmq_strerror(errno));
        return -1;
    }

    return 0;
}

// ZeroMQ Subscribe
int zmq_subscribe(int socket_fd, const char *topic) {
    char topic_str[256];
    snprintf(topic_str, sizeof(topic_str), "%s", topic);
    if (zmq_setsockopt(socket_fd, ZMQ_SUBSCRIBE, topic_str, strlen(topic_str)) < 0) {
        fprintf(stderr, "Error subscribing to ZeroMQ topic: %s\n", zmq_strerror(errno));
        return -1;
    }
    return 0;
}

// ZeroMQ Send Message
int zmq_send_message(int socket_fd, const char *message) {
    zmq_msg_t msg;
    zmq_msg_init_size(&msg, strlen(message));
    memcpy(zmq_msg_data(&msg), message, strlen(message));

    if (zmq_msg_send(&msg, socket_fd, 0) < 0) {
        fprintf(stderr, "Error sending ZeroMQ message: %s\n", zmq_strerror(errno));
        zmq_msg_close(&msg);
        return -1;
    }

    zmq_msg_close(&msg);
    return 0;
}

// ZeroMQ Receive Message
int zmq_receive_message(int socket_fd, char *buffer, size_t buffer_size) {
    zmq_msg_t msg;
    zmq_msg_init(&msg);

    if (zmq_msg_recv(&msg, socket_fd, 0) < 0) {
        fprintf(stderr, "Error receiving ZeroMQ message: %s\n", zmq_strerror(errno));
        zmq_msg_close(&msg);
        return -1;
    }

    size_t msg_size = zmq_msg_size(&msg);
    if (msg_size > buffer_size) {
        fprintf(stderr, "Error: Message size (%zu) exceeds buffer size (%zu)\n", msg_size, buffer_size);
        zmq_msg_close(&msg);
        return -1;
    }

    memcpy(buffer, zmq_msg_data(&msg), msg_size);

    zmq_msg_close(&msg);
    return 0;
}

// Alarm LED Control
void alarm_led_on(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
}

void alarm_led_off(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Publish Alert
void publish_alert(int zmq_socket_fd, const char *topic) {
    char message[256];
    snprintf(message, sizeof(message), "%s", topic);
    if (zmq_send_message(zmq_socket_fd, message) != 0) {
        fprintf(stderr, "Error publishing alert\n");
    }
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int mode = 0; // Default mode

    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "sound_sensor") == 0) {
            mode = 0;
        } else if (strcmp(argv[1], "alarm_node") == 0) {
            mode = 1;
        } else {
            fprintf(stderr, "Invalid mode specified. Using default (sound_sensor).\n");
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pins
    if (gpio_init(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        gpioTerminate();
        return 1;
    }
    if (gpio_init(ALARM_LED_GPIO, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ZeroMQ
    zmq_socket_fd = zmq_init(ZMQ_PORT);
    if (zmq_socket_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ZeroMQ context ID for cleanup
    zmq_context_id = (int)zmq_ctx_new();

    // Initialize ZeroMQ socket for subscription
    if (mode == 1) {
        if (zmq_connect(zmq_socket_fd, "localhost", ZMQ_PORT) != 0) {
            gpioTerminate();
            zmq_close(zmq_socket_fd);
            zmq_ctx_destroy(zmq_ctx_new());
            return 1;
        }
        if (zmq_subscribe(zmq_socket_fd, ZMQ_TOPIC) != 0) {
            gpioTerminate();
            zmq_close(zmq_socket_fd);
            zmq_ctx_destroy(zmq_ctx_new());
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (mode == 0) { // Sound sensor mode
            int sound_detected = gpioRead(SOUND_SENSOR_GPIO);
            if (sound_detected == 0) { // Active low
                publish_alert(zmq_socket_fd, ZMQ_TOPIC);
                alarm_led_on(ALARM_LED_GPIO);
                gpioDelay(10000); // 10ms delay
                alarm_led_off(ALARM_LED_GPIO);
            }
        } else if (mode == 1) { // Alarm node mode
            char buffer[256];
            if (zmq_receive_message(zmq_socket_fd, buffer, sizeof(buffer)) == 0) {
                if (strstr(buffer, ZMQ_TOPIC) != NULL) {
                    alarm_led_on(ALARM_LED_GPIO);
                    gpioDelay(ALARM_DURATION_SEC * 1000000); // 1 second delay
                    alarm_led_off(ALARM_LED_GPIO);
                }
            }
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (mode == 1) {
        zmq_close(zmq_socket_fd);
    }
    gpioTerminate();
    if (zmq_context_id != -1) {
        zmq_ctx_destroy(zmq_ctx_new());
    }

    return 0;
}

