#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_remote_decoder"
#define MQTT_KEEPALIVE 60
#define PULSE_BUFFER_SIZE 100

// NEC Protocol Constants
#define NEC_HEADER_MARK 9000  // 9ms
#define NEC_HEADER_SPACE 4500 // 4.5ms
#define NEC_BIT_MARK 560     // 560us
#define NEC_ONE_SPACE 1690   // 1690us
#define NEC_ZERO_SPACE 560   // 560us
#define NEC_MAX_PULSES 32

// Global Variables
static volatile int pulse_count = 0;
static volatile uint32_t pulse_times[PULSE_BUFFER_SIZE];
static volatile int pulse_index = 0;
static volatile int nec_frame_complete = 0;
static volatile uint32_t nec_command = 0;
static volatile int nec_checksum_valid = 0;
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function Prototypes
void alert_func(int gpio, int level, uint32_t tick, void *user);
int decode_nec(uint32_t *pulse_times, int pulse_count, uint32_t *command, int *checksum_valid);
int publish_mqtt(uint32_t command);
void signal_handler(int signal);
int init_mqtt();
void cleanup();

// Alert Function
void alert_func(int gpio, int level, uint32_t tick, void *user)
{
    if (level == FALLING_EDGE)
    {
        pulse_times[pulse_index++] = tick;
        if (pulse_index >= PULSE_BUFFER_SIZE)
        {
            pulse_index = 0; // Wrap around
            nec_frame_complete = 0; // Reset frame completion
        }
        if (pulse_count < PULSE_BUFFER_SIZE)
        {
            pulse_count++;
        }
    }
}

// NEC Decoding Function
int decode_nec(uint32_t *pulse_times, int pulse_count, uint32_t *command, int *checksum_valid)
{
    if (pulse_count < NEC_MAX_PULSES)
    {
        syslog(LOG_ERR, "Incomplete NEC frame received.");
        return -1;
    }

    *command = 0;
    *checksum_valid = 0;

    // Verify header
    if ((pulse_times[0] - pulse_times[1]) > NEC_HEADER_MARK * 0.9 || (pulse_times[0] - pulse_times[1]) < NEC_HEADER_MARK * 0.1)
    {
        syslog(LOG_ERR, "NEC header mark invalid.");
        return -1;
    }
    if ((pulse_times[2] - pulse_times[3]) > NEC_HEADER_SPACE * 0.9 || (pulse_times[2] - pulse_times[3]) < NEC_HEADER_SPACE * 0.1)
    {
        syslog(LOG_ERR, "NEC header space invalid.");
        return -1;
    }

    // Decode address and inverted address
    uint32_t address = 0;
    uint32_t inverted_address = 0;

    for (int i = 0; i < 8; i++)
    {
        if ((pulse_times[4 + (i * 2)] - pulse_times[5 + (i * 2)]) > NEC_BIT_MARK * 0.9)
        {
            if ((pulse_times[6 + (i * 2)] - pulse_times[7 + (i * 2)]) > NEC_ONE_SPACE * 0.9)
            {
                address |= (1 << i);
            }
            else
            {
                address &= ~(1 << i);
            }
        }
        else
        {
            syslog(LOG_ERR, "NEC bit mark invalid.");
            return -1;
        }
    }

    for (int i = 0; i < 8; i++)
    {
        if ((pulse_times[12 + (i * 2)] - pulse_times[13 + (i * 2)]) > NEC_BIT_MARK * 0.9)
        {
            if ((pulse_times[14 + (i * 2)] - pulse_times[15 + (i * 2)]) > NEC_ONE_SPACE * 0.9)
            {
                inverted_address |= (1 << i);
            }
            else
            {
                inverted_address &= ~(1 << i);
            }
        }
        else
        {
            syslog(LOG_ERR, "NEC inverted bit mark invalid.");
            return -1;
        }
    }

    // Decode command
    uint32_t command_data = 0;
    for (int i = 0; i < 8; i++)
    {
        if ((pulse_times[16 + (i * 2)] - pulse_times[17 + (i * 2)]) > NEC_BIT_MARK * 0.9)
        {
            if ((pulse_times[18 + (i * 2)] - pulse_times[19 + (i * 2)]) > NEC_ONE_SPACE * 0.9)
            {
                command_data |= (1 << i);
            }
            else
            {
                command_data &= ~(1 << i);
            }
        }
        else
        {
            syslog(LOG_ERR, "NEC command bit mark invalid.");
            return -1;
        }
    }

    // Checksum validation
    uint32_t checksum = (address << 16) | (inverted_address << 8) | command_data;
    uint32_t inverted_checksum = ~checksum;

    if (checksum == inverted_checksum)
    {
        *command = (address << 16) | (inverted_address << 8) | command_data;
        *checksum_valid = 1;
    }
    else
    {
        syslog(LOG_ERR, "NEC checksum invalid.");
        *checksum_valid = 0;
    }

    return 0;
}

// MQTT Publishing Function
int publish_mqtt(uint32_t command)
{
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"command\": %u}", command);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }

    syslog(LOG_INFO, "Published to MQTT: %s", payload);
    return 0;
}

// Signal Handler
void signal_handler(int signal)
{
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT Initialization Function
int init_mqtt()
{
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq)
    {
        syslog(LOG_ERR, "Failed to create MQTT client instance.");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_subscribe_callback_set(mosq, NULL);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Cleanup Function
void cleanup()
{
    syslog(LOG_INFO, "Cleaning up resources...");

    if (mosq)
    {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();

    gpioTerminate();
    closelog();
}

int main()
{
    // Initialize syslog
    openlog("ir_remote_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(IR_GPIO, PI_INPUT);

    // Set alert function
    gpioSetAlertFuncEx(IR_GPIO, alert_func, NULL);

    // Initialize MQTT
    if (init_mqtt() != 0)
    {
        syslog(LOG_ERR, "MQTT initialization failed");
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR remote decoder started");

    // Main loop
    while (running)
    {
        if (nec_frame_complete)
        {
            uint32_t decoded_command;
            int checksum_valid;

            if (decode_nec(pulse_times, pulse_count, &decoded_command, &checksum_valid) == 0)
            {
                if (checksum_valid)
                {
                    if (publish_mqtt(decoded_command) != 0)
                    {
                        syslog(LOG_ERR, "Failed to publish MQTT message");
                    }
                }
                else
                {
                    syslog(LOG_WARNING, "NEC checksum invalid, not publishing.");
                }
            }
            else
            {
                syslog(LOG_ERR, "NEC decoding failed");
            }

            // Reset for next frame
            pulse_count = 0;
            nec_frame_complete = 0;
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

