#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define START_CONVERSION_COMMAND 0x10
#define MEASUREMENT_DELAY_MS 180
#define SLEEP_SECONDS 1

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fds[NUM_SENSORS];
int udp_socket;

// Function prototypes
int i2c_setup(int address);
float read_lux(int fd);
char* format_data(float lux_values[], int sensor_ids[], int num_sensors);
int send_udp_packet(const char* data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read lux value from a sensor
float read_lux(int fd) {
    unsigned char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &START_CONVERSION_COMMAND, 1) != 1) {
            perror("Error writing to I2C device");
            return NAN;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

        if (read(fd, buf, 2) == 2) {
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            return (float)raw_value / 1.2;
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait before retrying
        }
    }

    return NAN; // Return NaN if all retries fail
}

// Function to format sensor data into a string
char* format_data(float lux_values[], int sensor_ids[], int num_sensors) {
    char* data = (char*)malloc(256 * num_sensors + 1); // Allocate memory for the string
    if (data == NULL) {
        perror("Error allocating memory");
        return NULL;
    }

    data[0] = '\0'; // Initialize as an empty string

    for (int i = 0; i < num_sensors; i++) {
        char temp[64];
        snprintf(temp, sizeof(temp), "%d,%.2f", sensor_ids[i], lux_values[i]);
        strcat(data, temp);
        if (i < num_sensors - 1) {
            strcat(data, ";");
        }
    }

    return data;
}

// Function to send UDP packet
int send_udp_packet(const char* data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

