#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_REG 0x00
#define LOG_FILE "airflow_log.txt"

int i2c_handle;
FILE *log_file;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read airflow data from the sensor
float read_airflow() {
    unsigned char buffer[2];
    int result;
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buffer, 2);
        if (result == 2) {
            // Combine the two bytes into a 14-bit value
            int raw_flow = (buffer[0] << 8) | buffer[1];

            // Mask the 14-bit value to get the 12-bit flow rate
            int flow_rate = raw_flow & 0x3FFF; // Mask to 12 bits

            // Convert the flow rate to SLPM (standard liters per minute)
            float slpm = (float)flow_rate / 100.0; // AWM7300V datasheet

            return slpm;
        } else {
            fprintf(stderr, "I2C read failed (error %d), retrying...\n", result);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1.0; // Indicate an error
}

// Function to log airflow data to a file
void log_airflow(float slpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, slpm);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float slpm = read_airflow();
        if (slpm >= 0) {
            log_airflow(slpm);
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }
        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

