#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_ID 0x00
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0x8E
#define AS7341_F1_DATA 0x94

// SMUX Configuration
#define SMUX_CONFIG 0x03 // F1, F2, F3, F4, F5, F6, F7, Clear, NIR

// Enable Spectral Measurement
#define ENABLE_SPECTRAL 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int as7341_init();
int read_spectral_data(unsigned short *spectral_data);
float calculate_lux(unsigned short *spectral_data);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the AS7341 sensor
int as7341_init() {
    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0x40) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Power on the sensor
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }

    // Configure SMUX
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, SMUX_CONFIG) < 0) {
        fprintf(stderr, "Error configuring SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, ENABLE_SPECTRAL) < 0) {
        fprintf(stderr, "Error enabling spectral measurement\n");
        return -1;
    }

    return 0;
}

// Read spectral data from the sensor
int read_spectral_data(unsigned short *spectral_data) {
    char buffer[20]; // Buffer to hold all spectral data (2 bytes per channel * 10 channels)
    int result = i2cReadI2CBlockData(i2c_handle, AS7341_F1_DATA, buffer, 20);

    if (result < 0) {
        fprintf(stderr, "Error reading spectral data: %d\n", result);
        return -1;
    }

    // Extract spectral data from the buffer
    spectral_data[0] = (unsigned short)buffer[0] | ((unsigned short)buffer[1] << 8);
    spectral_data[1] = (unsigned short)buffer[2] | ((unsigned short)buffer[3] << 8);
    spectral_data[2] = (unsigned short)buffer[4] | ((unsigned short)buffer[5] << 8);
    spectral_data[3] = (unsigned short)buffer[6] | ((unsigned short)buffer[7] << 8);
    spectral_data[4] = (unsigned short)buffer[8] | ((unsigned short)buffer[9] << 8);
    spectral_data[5] = (unsigned short)buffer[10] | ((unsigned short)buffer[11] << 8);
    spectral_data[6] = (unsigned short)buffer[12] | ((unsigned short)buffer[13] << 8);
    spectral_data[7] = (unsigned short)buffer[14] | ((unsigned short)buffer[15] << 8);
    spectral_data[8] = (unsigned short)buffer[16] | ((unsigned short)buffer[17] << 8);
    spectral_data[9] = (unsigned short)buffer[18] | ((unsigned short)buffer[19] << 8);

    return 0;
}

// Calculate a simplified lux approximation from spectral data
float calculate_lux(unsigned short *spectral_data) {
    // This is a placeholder.  A real implementation would use a more sophisticated algorithm.
    // For example, it could use calibration data to convert spectral data to lux.
    // For now, we'll just return a value based on the sum of the spectral data.
    float sum = 0.0;
    for (int i = 0; i < 10; i++) {
        sum += spectral_data[i];
    }
    return sum / 10.0; // Scale the sum to get a lux value
}

// Log data to a CSV file
int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (as7341_init() < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Lux\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned short spectral_data[10];
    float lux;

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(spectral_data) == 0) {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            log_data(lux);

            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read spectral data. Retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

