#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x4C
#define DEFAULT_SAMPLING_INTERVAL 1.0
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_BACKOFF_MS 10

// Omron D7S Register Addresses (Example, adjust as needed)
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
double sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *output_filename = DEFAULT_OUTPUT_FILENAME;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int handle, float *x, float *y, float *z);
int log_data(const char *filename, time_t timestamp, float x, float y, float z);
int log_error(const char *filename, const char *message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor_data(int handle, float *x, float *y, float *z) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, REG_X_LSB, buf, 6);
        if (result == 6) {
            // Combine LSB and MSB, convert to g
            int16_t raw_x = (buf[1] << 8) | buf[0];
            int16_t raw_y = (buf[3] << 8) | buf[2];
            int16_t raw_z = (buf[5] << 8) | buf[4];

            *x = (float)raw_x / 1000.0; // Example scaling, adjust as needed
            *y = (float)raw_y / 1000.0;
            *z = (float)raw_z / 1000.0;

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            log_error("seismic_error.log", "I2C read error");
            gpioDelay(RETRY_BACKOFF_MS * (1000 * (MAX_RETRIES - retries))); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    log_error("seismic_error.log", "Failed to read sensor data after multiple retries.");
    return -1; // Failure
}

// Log data to CSV file
int log_data(const char *filename, time_t timestamp, float x, float y, float z) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return -1;
    }

    char timestamp_str[30];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp_str, x, y, z);
    fclose(fp);
    return 0;
}

// Log error messages to file
int log_error(const char *filename, const char *message) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for error logging\n", filename);
        return -1;
    }

    time_t now = time(NULL);
    char timestamp_str[30];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(fp, "%s: %s\n", timestamp_str, message);
    fclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtod(optarg, NULL);
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    time_t start_time = time(NULL);
    while (!terminate) {
        float x, y, z;
        time_t current_time = time(NULL);

        if (read_sensor_data(i2c_handle, &x, &y, &z) == 0) {
            if (log_data(output_filename, current_time, x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay((int)(sampling_interval * 1000000)); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

