#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to configure the BH1750 sensor
int config_bh1750() {
    int result = i2cWriteByteData(i2c_fd, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Error configuring BH1750: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the raw light value from the BH1750
int read_raw_value(unsigned short *raw_value) {
    int bytes_read = i2cReadI2CBlockData(i2c_fd, 0x00, (char *)raw_value, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading raw value: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert the raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to create and configure the UDP socket
int create_udp_socket() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set the Time-To-Live (TTL) for multicast packets
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        return -1;
    }

    // Configure the destination address
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    dest_addr.sin_port = htons(MULTICAST_PORT);

    // Connect the socket to the destination address
    if (connect(udp_socket, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("Error connecting socket");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Function to send the lux value via UDP multicast
int send_lux_value(float lux_value) {
    char buffer[32]; // Buffer to hold the string representation of the lux value
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("Error sending data");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure BH1750 sensor
    if (config_bh1750() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    if (create_udp_socket() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    unsigned short raw_value;
    float lux_value;

    // Main loop
    while (1) {
        // Read raw light value
        if (read_raw_value(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Send lux value via UDP multicast
            if (send_lux_value(lux_value) != 0) {
                fprintf(stderr, "Error sending lux value\n");
            }
        } else {
            fprintf(stderr, "Error reading raw value, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(udp_socket);
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

