int validate_magic_word(const unsigned char *buffer, int size) {
    if (size != 16) {
        fprintf(stderr, "Invalid frame size: %d\n", size);
        return 0;
    }

    unsigned short word1 = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
