    unsigned short word3 = (buffer[8] << 24) | (buffer[9] << 16) | (buffer[10] << 8) | buffer[11];
    unsigned short word4 = (buffer[12] << 24) | (buffer[13] << 16) | (buffer[14] << 8) | buffer[15];

    if (word1 != MAGIC_WORD_1 || word2 != MAGIC_WORD_2 || word3 != MAGIC_WORD_1 || word4 != MAGIC_WORD_2) {
        fprintf(stderr, "Invalid magic word values\n");
        return 0;
    }

    return 1;
}

// Parse TLV payload function
int parse_tlv_payload(const unsigned char *buffer, int size, RadarData *radar_data, int *num_objects) {
    int index = 0;
    *num_objects = 0;

    while (index < size - 8) { // Ensure enough bytes for type and length
        unsigned short type = (buffer[index + 4] << 8) | buffer[index + 5];
