                float velocity = *((float *)(buffer + index + 8 + 4));

                radar_data[*num_objects].timestamp = time(NULL);
                radar_data[*num_objects].object_index = (*num_objects) + 1;
                radar_data[*num_objects].range_m = range;
                radar_data[*num_objects].velocity_mps = velocity;
