#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/file.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUFFER_SIZE 256
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC (TIMEOUT_SEC * 1000000)

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

int setup_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;
    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        fprintf(stderr, "Timeout reading from UART.\n");
        return 0;
    } else {
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

int parse_data(const char *line, float *range) {
    char *token;
    char *str = strdup(line);
    if (str == NULL) {
        fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(str, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp\n");
        free(str);
        return -1;
    }

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range\n");
        free(str);
        return -1;
    }

    char *endptr;
    *range = strtof(token, &endptr);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error converting range to float\n");
        free(str);
        return -1;
    }

    free(str);
    return 0;
}

int log_data(const char *timestamp, float range) {
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    char line_buffer[LINE_BUFFER_SIZE];
    ssize_t bytes_read;
    float range;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, line_buffer, sizeof(line_buffer));
        if (bytes_read > 0) {
            if (parse_data(line_buffer, &range) == 0) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                log_data(timestamp, range);
            }
        }
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

