int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        fprintf(stderr, "Timeout reading from UART.\n");
        return 0;
    } else {
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

int parse_data(const char *line, float *range) {
    char *token;
    char *str = strdup(line);
    if (str == NULL) {
        fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(str, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp\n");
        free(str);
        return -1;
    }

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range\n");
        free(str);
        return -1;
    }

    char *endptr;
    *range = strtof(token, &endptr);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error converting range to float\n");
        free(str);
        return -1;
    }

    free(str);
    return 0;
}

int log_data(const char *timestamp, float range) {
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    char line_buffer[LINE_BUFFER_SIZE];
    ssize_t bytes_read;
    float range;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, line_buffer, sizeof(line_buffer));
        if (bytes_read > 0) {
            if (parse_data(line_buffer, &range) == 0) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                log_data(timestamp, range);
            }
        }
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

