#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device
#define UART_DEVICE "/dev/ttyAMA0"

// Define baud rate
#define BAUD_RATE 115200

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void log_sensor_data(int left, int middle, int right);
void check_emergency_stop(int left, int middle, int right);
int send_uart_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to check for an emergency stop condition
void check_emergency_stop(int left, int middle, int right) {
    if (left == 0 && middle == 0 && right == 0) {
        printf("EMERGENCY STOP!\n");
        if (send_uart_message("EMERGENCY STOP!\n") != 0) {
            fprintf(stderr, "Error sending UART message.\n");
        }
    }
}

// Function to send a message over the UART
int send_uart_message(const char *message) {
    int uart_fd;
    struct termios tty;

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART device");
        return 1; // Indicate failure
    }

    // Get the current attributes of the UART
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(uart_fd);
        return 1; // Indicate failure
    }

    // Configure the UART for 8N1
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    // Set the baud rate
    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    // Apply the configuration
    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(uart_fd);
        return 1; // Indicate failure
    }

    // Send the message
    if (write(uart_fd, message, strlen(message)) == -1) {
        perror("Error writing to UART");
        close(uart_fd);
        return 1; // Indicate failure
    }

    // Close the UART device
    close(uart_fd);
    return 0; // Indicate success
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    printf("Sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_sensor, middle_sensor, right_sensor);

        // Check for emergency stop
        check_emergency_stop(left_sensor, middle_sensor, right_sensor);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

